  // A runway between nine and twelve months, and a raise priced at the rate the company asks.
  cases["unit:nimbus-runway-under-twelve"] = {...nimbus, desk: {...nimbus.desk!, balance: {...nimbus.desk!.balance, cash: "20000000"}}};
