  else if (relevant.some((r) => r.decision === "raise" && r.state === "awaiting_series")) result = "pending_confirmation";
  else if (missingYears.length === 0 && relevant.every((r) => r.state === "corroborated")) result = "not_fired";
  else result = "incomplete";
