    id: frontmatter.id,
    version: frontmatter.version,
    maturity: frontmatter.maturity,
    title: {pt: frontmatter.title_pt, en: frontmatter.title_en},
    role: frontmatter.role,
    blueprintStage: frontmatter.blueprint_stage,
