    return "material";
  }
  const informational = manifest.kind === "answer" && blocks.length > 0 && blocks.every((block) => (
    (block.kind === "section" || block.kind === "paragraph") && block.claims.length === 0 && !contentCarriesNumber(block.content as unknown as JsonValue)
  ));
  return informational ? "informational" : "without_substance";
}

// Material change ----------------------------------------------------------------------------

export type RevisionChange = "identical" | "cosmetic" | "material";
export type MaterialChangeReason =
  | "claim_set" | "claim_value" | "source_versions" | "method_release" | "execution" | "institutional_result" | "audience"
  | "block_content" | "claim_support" | "manifest_context" | "unverified_bytes" | "invalid_snapshot";

function claimIndex(blocks: readonly ArtifactBlock[]): Map<string, string> {
  const index = new Map<string, string>();
  for (const block of blocks) {
    for (const claim of block.claims) index.set(claim.claimId, stable({kind: claim.kind, value: claim.value, unit: claim.unit, period: claim.period}));
  }
  return index;
}

function sameBlocks(previous: readonly ArtifactBlock[], next: readonly ArtifactBlock[]): boolean {
  const a = [...previous].sort((x, y) => x.blockNo - y.blockNo);
  const b = [...next].sort((x, y) => x.blockNo - y.blockNo);
  return a.length === b.length && a.every((block, index) => {
    const other = b[index];
    return other !== undefined && block.blockKey === other.blockKey && block.contentFingerprint === other.contentFingerprint
      && block.kind === other.kind && stable(block.content) === stable(other.content)
      && stable(block.claims) === stable(other.claims);
  });
}

function sameManifest(previous: RevisionSnapshot["revision"], next: RevisionSnapshot["revision"]): boolean {
  if ("manifestFingerprint" in previous && "manifestFingerprint" in next && previous.manifestFingerprint !== next.manifestFingerprint) return false;
  return stable(previous.manifest) === stable(next.manifest);
}

/**
 * Material when any claim id, claim value, source version, method release, execution,
 * institutional result or audience differs. Arbitrary content changes are material, even when
 * claims stay equal. Only block order and the typed template reference may be cosmetic;
 * fingerprints alone never override divergent content. Stage 20 requires a new approval act on
 * a material change.
 */
export type RevisionChangeReport = {readonly outcome: RevisionChange; readonly reasons: readonly MaterialChangeReason[]};

export function describeRevisionChange(previous: RevisionSnapshot, next: RevisionSnapshot): RevisionChangeReport {
  const duplicateIdentity = [previous, next].some((snapshot) =>
    duplicates(snapshot.blocks.map((block) => block.blockKey))
    || duplicates(snapshot.blocks.flatMap((block) => block.claims.map((claim) => claim.claimId))));
  if (duplicateIdentity) return freezeArtifactValue({outcome: "material", reasons: ["invalid_snapshot"]});
  if (sameManifest(previous.revision, next.revision) && sameBlocks(previous.blocks, next.blocks)
    && previous.revision.contentSha256 === next.revision.contentSha256
    && previous.revision.byteLength === next.revision.byteLength
    && previous.revision.audience === next.revision.audience) {
    const identical: RevisionChangeReport = {outcome: "identical", reasons: []};
    return freezeArtifactValue(identical);
  }
  const reasons: MaterialChangeReason[] = [];
  const before = claimIndex(previous.blocks);
  const after = claimIndex(next.blocks);
  if (before.size !== after.size || [...before.keys()].some((claimId) => !after.has(claimId))) reasons.push("claim_set");
  if ([...before].some(([claimId, value]) => after.has(claimId) && after.get(claimId) !== value)) reasons.push("claim_value");
  const semanticBlocks = (blocks: readonly ArtifactBlock[]) => stable([...blocks]
    .sort((a, b) => a.blockKey.localeCompare(b.blockKey))
    .map((block) => ({key: block.blockKey, kind: block.kind, content: block.content})));
  if (semanticBlocks(previous.blocks) !== semanticBlocks(next.blocks)) reasons.push("block_content");
  const supports = (blocks: readonly ArtifactBlock[]) => stable([...blocks]
    .sort((a, b) => a.blockKey.localeCompare(b.blockKey))
    .map((block) => ({key: block.blockKey, claims: block.claims.map((claim) => ({id: claim.claimId, supportIds: [...claim.supportIds].sort()}))})));
  if (supports(previous.blocks) !== supports(next.blocks)) reasons.push("claim_support");
  const previousManifest = previous.revision.manifest;
  const nextManifest = next.revision.manifest;
  const sourceKey = (manifest: ArtifactManifest) => stable([...manifest.sources].map((source) => `${source.sourceVersionId}:${source.rightsVersionId ?? ""}`).sort());
  if (sourceKey(previousManifest) !== sourceKey(nextManifest)) reasons.push("source_versions");
  if (stable(previousManifest.method) !== stable(nextManifest.method)) reasons.push("method_release");
  if (stable(previousManifest.execution) !== stable(nextManifest.execution)) reasons.push("execution");
  if (stable(previousManifest.institutionalResult) !== stable(nextManifest.institutionalResult)) reasons.push("institutional_result");
  if (previous.revision.audience !== next.revision.audience) reasons.push("audience");
  const context = (manifest: ArtifactManifest) => ({kind: manifest.kind, format: manifest.format,
    inputSnapshot: manifest.inputSnapshot, traces: manifest.traces, provenance: manifest.provenance,
    legacy: manifest.legacy, claims: [...manifest.claims].sort((a, b) => a.blockKey.localeCompare(b.blockKey))});
  if (stable(context(previousManifest)) !== stable(context(nextManifest))) reasons.push("manifest_context");
  // Until a pinned renderer proves byte equivalence, a byte change is not a layout claim.
  if (stable(previousManifest.bytes) !== stable(nextManifest.bytes)
    || previous.revision.contentSha256 !== next.revision.contentSha256
    || previous.revision.byteLength !== next.revision.byteLength) reasons.push("unverified_bytes");
  const report: RevisionChangeReport = {outcome: reasons.length > 0 ? "material" : "cosmetic", reasons};
  return freezeArtifactValue(report);
}

export function compareRevisions(previous: RevisionSnapshot, next: RevisionSnapshot): RevisionChange {
  return describeRevisionChange(previous, next).outcome;
}

// Freshness ----------------------------------------------------------------------------------

export type Freshness = "current" | "stale" | "unknown";

/** Head facts the reader collects: the live head of each linked lineage and the latest version of each linked source. */
export type LineageHeads = {
  readonly executions: ReadonlyMap<string, string>;
  readonly institutionalResults: ReadonlyMap<string, string>;
  readonly sourceVersions: ReadonlyMap<string, string>;
};

/**
 * Stale when a linked execution or institutional result is no longer the head of its lineage or
 * a linked source has a newer version; unknown when any head is missing. Stale wins over unknown,
 * and an incomplete graph is never current. Stale is not revoked: the revision stays readable.
 */
export function freshness(links: readonly ArtifactDependencyLink[], heads: LineageHeads): Freshness {
  let incomplete = false;
  for (const link of links) {
    const pair = link.kind === "execution" ? [link.executionId, heads.executions.get(link.executionId)]
      : link.kind === "institutional_result" ? [link.resultId, heads.institutionalResults.get(link.resultId)]
        : link.kind === "source_version" ? [link.sourceVersionId, heads.sourceVersions.get(link.sourceVersionId)]
          : null;
    if (pair === null) continue;
    const [linked, head] = pair;
    if (head === undefined) incomplete = true;
    else if (head !== linked) return "stale";
  }
  return incomplete ? "unknown" : "current";
}

// Release ------------------------------------------------------------------------------------

export type ReleaseState = "internal" | "released" | "blocked";

/** Historical approval facts. Execution receipts attest computation and never approve content. */
export type ApprovalFact =
  | {readonly kind: "artifact_decision"; readonly decision: "confirm" | "request_changes"; readonly artifactFingerprint: string}
  | {readonly kind: "package_review"; readonly status: string; readonly materialFingerprint: string}
  /** Established already includes the adoption of a recomputed result (`institutional_result_established_v1`). */
  | {readonly kind: "institutional_result"; readonly resultId: string; readonly established: boolean}
  /** Retained for callers carrying computation evidence; ignored for approval. */
  | {readonly kind: "execution_receipt"; readonly executionId: string; readonly resultFingerprint: string};

/**
 * Facts supplied by an authorized resolver for this exact revision. This pure contract cannot
 * discover source rights, indirect execution links or persisted institutional bindings. A
 * missing/incomplete context never establishes historical fallback. The resolver must traverse
 * all ancestry and supply complete review history, including revocations and reaffirmation bases.
 * This projection is evidence for domain evaluation, not a token that grants database access.
 * ArtifactRevision carries no organization/work: ownership of those two target fields must be
 * verified by that resolver, while this contract binds the human act to its supplied target.
 */
export type ReleaseContext = {
  readonly target: ExactReviewTarget;
  readonly sourceReadAccess: boolean;
  readonly ancestry: {
    readonly complete: boolean;
    readonly hasExecution: boolean;
    readonly institutional: "none" | "native" | "historical_counterpart" | "missing_native";
  };
  readonly reviews: readonly ArtifactReview[];
};

export type ReleaseInput = {
  readonly workReadAccess: boolean;
  readonly facts: readonly ApprovalFact[];
  readonly context: ReleaseContext;
};

/** The fingerprints under which an approval may name this exact revision. */
export function revisionFingerprints(revision: ArtifactRevision): ReadonlySet<string> {
  const fingerprints = new Set<string>([revision.manifestFingerprint]);
  if (revision.contentSha256 !== null) fingerprints.add(revision.contentSha256);
  if (revision.legacyRef !== null) fingerprints.add(revision.legacyRef.fingerprint);
  return fingerprints;
}

function factCoversRevision(revision: ArtifactRevision, fact: ApprovalFact): boolean {
  const fingerprints = revisionFingerprints(revision);
  switch (fact.kind) {
    case "artifact_decision": return fact.decision === "confirm" && fingerprints.has(fact.artifactFingerprint);
    case "package_review": return fact.status === "approved" && fingerprints.has(fact.materialFingerprint);
    case "institutional_result": return fact.established && revision.manifest.institutionalResult?.id === fact.resultId;
    case "execution_receipt": return false;
  }
}

/**
 * Every audience requires current work and inherited source access plus complete lineage facts.
 * Execution and institutional native content require their own exact active human act. Historical
 * alternatives of native bindings are blocked. Only a proved ordinary historical lineage may
 * use the legacy approval facts. This is a pure domain evaluation; runtime readers use the
 * database's authorized projection, not this function. No purpose parameter changes the result.
 */
export function releaseState(revision: ArtifactRevision, input: ReleaseInput): ReleaseState {
  if (input.workReadAccess !== true) return "blocked";
  const context = input.context;
  if (!context || context.sourceReadAccess !== true || context.ancestry?.complete !== true
    || typeof context.ancestry.hasExecution !== "boolean"
    || !["none", "native", "historical_counterpart", "missing_native"].includes(context.ancestry.institutional)
    || !uuid.safeParse(context.target?.organizationId).success || !uuid.safeParse(context.target?.workId).success
    || !Array.isArray(context.reviews)
    || context.target.artifactId !== revision.artifactId || context.target.revisionId !== revision.id
    || context.target.manifestFingerprint !== revision.manifestFingerprint || context.target.audience !== revision.audience) return "blocked";
  const binding = context.ancestry.institutional;
  if (binding === "missing_native") return "blocked";
  // Native binding takes precedence, as in SQL; its ancestor cannot become an alternative route.
  if (binding === "historical_counterpart") return "blocked";
  const humanReviewRequired = binding === "native" || context.ancestry.hasExecution || revision.manifest.execution !== null;
  const approved = humanReviewRequired
    ? context.reviews.some((review) => approvalCoversRevision(context.target, review, context.reviews))
    : input.facts.some((fact) => factCoversRevision(revision, fact));
  if (revision.audience === "external") return approved ? "released" : "blocked";
  return approved ? "released" : "internal";
}

// Exact revision resolution ------------------------------------------------------------------

export type ResolvedRevision =
  | {readonly ok: true; readonly revision: ArtifactRevision}
  | {readonly ok: false; readonly error: "revision_not_found" | "artifact_head_missing"};

/** A requested id resolves to that revision or fails; without one, the head pointer decides, never the newest by date. */
export function resolveRevision(artifact: Artifact, revisions: readonly ArtifactRevision[], requestedRevisionId?: string | null): ResolvedRevision {
  const own = revisions.filter((revision) => revision.artifactId === artifact.id);
  if (requestedRevisionId !== undefined && requestedRevisionId !== null) {
    const revision = own.find((candidate) => candidate.id === requestedRevisionId);
    return revision ? {ok: true, revision} : {ok: false, error: "revision_not_found"};
  }
  const head = artifact.headRevisionId === null ? undefined : own.find((candidate) => candidate.id === artifact.headRevisionId);
  return head ? {ok: true, revision: head} : {ok: false, error: "artifact_head_missing"};
}

// Adapters -----------------------------------------------------------------------------------
//
// `case-understanding` and `financial-model` both depend on `reconciliation`, which depends on
// this package, so importing their schemas here would create a cycle. The four external adapters
// are therefore typed against the structural shape of each contract (only the fields they read)
// and tested on fixtures copied from the real shapes. `documentWorkProductSchema` lives in this
// package and is imported directly.

export type ManifestContext = {
  readonly audience: ArtifactAudience;
  readonly provenance: ManifestProvenance;
  /** Source versions the producer resolved in the graph. No contract below carries rights versions. */
  readonly sources?: readonly ManifestSource[];
};

/** Resolved licenses refine an unpinned reference; distinct fixed licenses never replace each other. */
function mergedSources(context: ManifestContext, own: readonly ManifestSource[] = []): ManifestSource[] {
  const merged = new Map<string, Map<string | null, ManifestSource>>();
  for (const source of [...own, ...(context.sources ?? [])]) {
    const licenses = merged.get(source.sourceVersionId) ?? new Map<string | null, ManifestSource>();
    licenses.set(source.rightsVersionId, source);
    if (licenses.size > 1) licenses.delete(null);
    merged.set(source.sourceVersionId, licenses);
  }
  return [...merged.values()].flatMap(licenses => [...licenses.values()]);
}

function unique(values: readonly string[]): string[] {
  return [...new Set(values)];
}

function finish(manifest: unknown): ArtifactManifest {
  return freezeArtifactValue(artifactManifestSchema.parse(manifest));
}

const emptyManifestParts = {method: null, execution: null, inputSnapshot: null, institutionalResult: null, template: null, legacy: null, bytes: null} as const;

export type DecisionArtifactContractLike = {
  readonly schemaVersion: "2026.09.07-v1";
  readonly caseId: string;
  readonly snapshotFingerprint: string;
  readonly contractFingerprint: string;
  readonly claims: ReadonlyArray<{
    readonly id: string;
    readonly object: {readonly id: string; readonly type: string; readonly fingerprint: string; readonly path: string};
  }>;
  readonly views: ReadonlyArray<{
    readonly surface: "conversation" | "workbook" | "presentation";
    readonly blocks: ReadonlyArray<{readonly id: string; readonly claimIds: readonly string[]}>;
  }>;
};

/** The decision contract is a governed work product; its case snapshot is the input snapshot and its signed objects are the traces. */
export function manifestFromDecisionArtifactContract(contract: DecisionArtifactContractLike, context: ManifestContext): ArtifactManifest {
  return finish({
    ...emptyManifestParts,
    schemaVersion: artifactManifestSchemaVersion,
    kind: "work_product",
    audience: context.audience,
    format: "json",
    inputSnapshot: {fingerprint: contract.snapshotFingerprint},
    sources: mergedSources(context),
    claims: contract.views.flatMap((view) => view.blocks
      .filter((block) => block.claimIds.length > 0)
      .map((block) => ({blockKey: `${view.surface}:${block.id}`, claimIds: [...block.claimIds]}))),
    traces: unique([
      `decision-contract:${contract.contractFingerprint}`,
      ...contract.claims.map((claim) => `signed-object:${claim.object.type}:${claim.object.id}:${claim.object.fingerprint}`),
    ]),
    provenance: context.provenance,
  });
}

export type RenderedMaterialManifestLike = {
  readonly schemaVersion: "2026.09.07-v1";
  readonly id: string;
  readonly decisionContractFingerprint: string;
  readonly surface: "workbook" | "presentation" | "supporting_document";
  readonly format: "xlsx" | "pptx" | "docx";
  readonly byteLength: number;
  readonly contentSha256: string;
  readonly renderer: {readonly id: string; readonly version: string};
  /** versionId names the stored template version the file was rendered with; absent or null for the house template. */
  readonly template: {readonly id: string; readonly version: string; readonly fingerprint: string; readonly origin: "offroad_house" | "client_supplied"; readonly versionId?: string | null | undefined};
  readonly storage: {readonly bucket: string; readonly objectPath: string; readonly state: "pending_upload" | "stored"; readonly etag: string | null};
  readonly claimIds: readonly string[];
  readonly manifestFingerprint: string;
};

const surfaceKind = {workbook: "workbook", presentation: "presentation", supporting_document: "document"} as const;

/** A stored file becomes a revision with storage bytes; a receipt whose object is not stored yet is refused. */
export function manifestFromRenderedMaterialManifest(material: RenderedMaterialManifestLike, context: ManifestContext): ArtifactManifest {
  if (material.storage.state !== "stored") throw new Error("artifact_adapter_material_not_stored");
  return finish({
    ...emptyManifestParts,
    schemaVersion: artifactManifestSchemaVersion,
    kind: surfaceKind[material.surface],
    audience: context.audience,
    format: material.format,
    bytes: {sha256: material.contentSha256, byteLength: material.byteLength, storage: {bucket: material.storage.bucket, path: material.storage.objectPath}},
    inputSnapshot: {fingerprint: material.decisionContractFingerprint},
    sources: mergedSources(context),
    claims: material.claimIds.length > 0 ? [{blockKey: material.surface, claimIds: [...material.claimIds]}] : [],
    traces: unique([`rendered-material:${material.manifestFingerprint}`, `renderer:${material.renderer.id}@${material.renderer.version}`]),
    // The stored template version when the file was rendered with one; the house template, which is
    // not stored, is named by the receipt's id and version.
    template: {templateVersionId: material.template.versionId ?? `${material.template.id}@${material.template.version}`, fingerprint: material.template.fingerprint},
    provenance: context.provenance,
  });
}

/** The fields of a decision contract claim the material block reads. */
export type DecisionClaimLike = {
  readonly id: string;
  readonly value: string | number | boolean | null;
  readonly unit: string | null;
  readonly evidenceState: "observed_public" | "observed_private" | "calculated" | "assumption" | "mixed" | "not_computable";
  readonly sourceIds: readonly string[];
  readonly assumptionIds: readonly string[];
  readonly gapIds: readonly string[];
};

/** A value computed from observed and assumed inputs is still a calculation; its assumptions stay in supportIds. */
const decisionClaimKind = {
  observed_public: "public_source", observed_private: "fact", calculated: "calculation", mixed: "calculation", not_computable: "calculation", assumption: "judgment",
} as const satisfies Record<DecisionClaimLike["evidenceState"], ArtifactClaim["kind"]>;

/**
 * The one block of a stored file, keyed by its surface as the manifest summary is: every claim the
 * renderer placed in the file, in the receipt's order, with the value, unit and support the
 * decision contract gives it. A claim the contract does not carry is refused, never invented.
 */
export function renderedMaterialBlocks(material: RenderedMaterialManifestLike, claims: readonly DecisionClaimLike[]): readonly ArtifactBlockDraft[] {
  const byId = new Map(claims.map((claim) => [claim.id, claim]));
  const draft = {
    blockKey: material.surface,
    kind: "section",
    content: {surface: material.surface, format: material.format, renderer: `${material.renderer.id}@${material.renderer.version}`},
    claims: material.claimIds.map((claimId) => {
      const claim = byId.get(claimId);
      if (!claim) throw new Error("artifact_adapter_claim_missing");
      return {claimId, kind: decisionClaimKind[claim.evidenceState], value: claim.value, unit: claim.unit, period: null,
        supportIds: unique([...claim.sourceIds, ...claim.assumptionIds, ...claim.gapIds])};
    }),
  };
  return freezeArtifactValue([artifactBlockDraftSchema.parse(draft)]);
}

export type InstitutionalWorkbookArtifactLike = {
  readonly modelKind: "institutional";
  readonly version: string;
  readonly fingerprint: string;
  readonly workbooks: {readonly pt: {readonly sha256: string; readonly byteSize: number}; readonly en: {readonly sha256: string; readonly byteSize: number}};
  readonly renderAudits: {readonly pt: {readonly rendererVersion: string}; readonly en: {readonly rendererVersion: string}};
  readonly institutional: {
    readonly schemaVersion: "institutional-workbook-artifact.v1";
    readonly activeScenarioId: string;
    readonly sourceManifestFingerprint: string;
    readonly scenarios: ReadonlyArray<{
      readonly configurationId: string;
      readonly configurationFingerprint: string;
      readonly inputFingerprint: string;
      readonly outputFingerprint: string;
    }>;
  };
};

export type InstitutionalManifestContext = ManifestContext & {
  /** The `institutional_model_results` row this artifact belongs to; the artifact does not carry it. */
  readonly resultId: string;
  readonly locale: "pt" | "en";
};

/** One locale of the deterministic workbook, pinned to the established result and its active scenario. */
export function manifestFromInstitutionalWorkbookArtifact(artifact: InstitutionalWorkbookArtifactLike, context: InstitutionalManifestContext): ArtifactManifest {
  const active = artifact.institutional.scenarios.find((scenario) => scenario.configurationId === artifact.institutional.activeScenarioId);
  if (!active) throw new Error("artifact_adapter_active_scenario_missing");
  const workbook = artifact.workbooks[context.locale];
  return finish({
    ...emptyManifestParts,
    schemaVersion: artifactManifestSchemaVersion,
    kind: "model_result",
    audience: context.audience,
    format: "xlsx",
    bytes: {
      sha256: workbook.sha256,
      byteLength: workbook.byteSize,
      rendered: {
        renderer: artifact.version,
        rendererVersion: artifact.renderAudits[context.locale].rendererVersion,
        deterministicInputs: {locale: context.locale, artifactFingerprint: artifact.fingerprint, sourceManifestFingerprint: artifact.institutional.sourceManifestFingerprint},
      },
    },
    inputSnapshot: {fingerprint: active.inputFingerprint},
    institutionalResult: {id: context.resultId, configurationFingerprint: active.configurationFingerprint},
    sources: mergedSources(context),
    claims: [],
    traces: unique([`institutional-workbook:${artifact.fingerprint}`, ...artifact.institutional.scenarios.map((scenario) => `institutional-output:${scenario.outputFingerprint}`)]),
    provenance: context.provenance,
  });
}

/** A documentary work product cites passages, not source versions; the producer resolves those in the graph. */
export function manifestFromDocumentWorkProduct(product: DocumentWorkProduct, context: ManifestContext): ArtifactManifest {
  const parsed = documentWorkProductSchema.parse(product);
  return finish({
    ...emptyManifestParts,
    schemaVersion: artifactManifestSchemaVersion,
    kind: "work_product",
    audience: context.audience,
    format: "json",
    inputSnapshot: {fingerprint: parsed.inputFingerprint},
    sources: mergedSources(context),
    claims: [],
    traces: unique([`document-work-product:${parsed.fingerprint}`, `approved-request:${parsed.requestFingerprint}`]),
    provenance: context.provenance,
  });
}

// The execution result ------------------------------------------------------------------------
//
// One mapping of the `capital-procedure-packet.v2` result into blocks, mirrored key for key by the
// SQL producer the execution commit calls (`private.execution_result_blocks_v1`): the same block
// keys, kinds, content and claims, in the same order. Nothing here computes a number the packet
// does not carry. The decisive number of each chart piece is selected with the rule of
// `deriveCapitalChartSeries` (per alternative with calculated rows and per question, the first row
// with the lowest value, so a tie resolves to the earliest period) and copied verbatim. The MD test
// is not a block: it is evaluated by the one TypeScript evaluator over the committed packet and the
// gate receipt, and the manifest pins that receipt among its traces.

type PacketProjectionLike = {
  readonly currency: string;
  readonly basisFingerprint: string;
  readonly calculationFingerprint: string;
  readonly rows: ReadonlyArray<{readonly periodId: string; readonly closingAvailable: string; readonly netFinancingAvailable: string}> | null;
  readonly summary: unknown;
};

export type CapitalProcedurePacketLike = {
  readonly schemaVersion: "capital-procedure-packet.v2";
  readonly status: "framed" | "partial" | "prepared_for_human_review";
  readonly decision: {
    readonly procedureId: string;
    readonly workId: string;
    readonly question: string;
    readonly asOf: string;
    readonly fingerprint: string;
    readonly alternatives: ReadonlyArray<{readonly id: string; readonly label: string; readonly kind: string; readonly projection: PacketProjectionLike}>;
    readonly ratios: ReadonlyArray<{
      readonly id: string; readonly alternativeId: string; readonly ratioId: string; readonly definitionKind: string;
      readonly measurementDate: string; readonly displayedRatio: string | null; readonly fingerprint: string;
    }>;
    readonly recommendation: {readonly alternativeId: string; readonly basisDecisionIds: readonly string[]} | null;
    readonly informationGaps: ReadonlyArray<{readonly subjectId: string | null; readonly code: string; readonly reason: string}>;
    readonly nextRequirements: readonly string[];
    readonly provenance: {readonly financialCoreVersion: string; readonly contributionIds: readonly string[]};
  };
  readonly contractualGaps: ReadonlyArray<{readonly subjectId: string; readonly code: string}>;
  readonly contractSourceVersionIds: readonly string[];
  readonly inputFingerprint: string;
  readonly fingerprint: string;
};

/** The questions of the chart series, in its order, with the row field each one reads. */
export const executionResultDecisiveQuestions = [
  {questionCode: "lowest_available_cash_by_period", field: "closingAvailable"},
  {questionCode: "largest_net_financing_outflow_by_period", field: "netFinancingAvailable"},
] as const;

const decimalText = /^-?\d+(?:\.\d+)?$/;

/** Exact order of two decimal texts (-1, 0 or 1), without floating point. */
export function compareDecimalText(a: string, b: string): number {
  const parse = (value: string) => {
    if (typeof value !== "string" || !decimalText.test(value)) throw new Error("artifact_adapter_decimal_invalid");
    const negative = value.startsWith("-");
    const [whole = "", fraction = ""] = (negative ? value.slice(1) : value).split(".");
    const integer = whole.replace(/^0+(?=\d)/, "");
    const decimals = fraction.replace(/0+$/, "");
    return {sign: integer === "0" && decimals === "" ? 0 : negative ? -1 : 1, integer, decimals};
  };
  const x = parse(a);
  const y = parse(b);
  if (x.sign !== y.sign) return x.sign < y.sign ? -1 : 1;
  if (x.sign === 0) return 0;
  const width = Math.max(x.decimals.length, y.decimals.length);
  const left = x.integer.padStart(y.integer.length, "0") + x.decimals.padEnd(width, "0");
  const right = y.integer.padStart(x.integer.length, "0") + y.decimals.padEnd(width, "0");
  if (left === right) return 0;
  return (left < right ? -1 : 1) * x.sign;
}

/**
 * The blocks of an execution result: the framing, the alternatives (a claim each), the ratios (a
 * claim each, when there are ratios), the recommendation (one claim, when there is one), the
 * information and contractual gaps, the next requirements, and one number block per decisive number
 * with its claim and supportIds. Throws when the packet cannot be mapped; the SQL producer then
 * records no revision and the commit goes on.
 */
export function capitalProcedurePacketBlocks(packet: CapitalProcedurePacketLike): readonly ArtifactBlockDraft[] {
  const decision = packet.decision;
  const drafts: unknown[] = [
    {blockKey: "framing", kind: "section", claims: [],
      content: {status: packet.status, question: decision.question, asOf: decision.asOf, contributionCount: decision.provenance.contributionIds.length}},
    {blockKey: "alternatives", kind: "table",
      content: {rows: decision.alternatives.map((alternative) => ({
        id: alternative.id, label: alternative.label, kind: alternative.kind, calculated: alternative.projection.summary !== null,
      }))},
      claims: decision.alternatives.map((alternative) => ({
        claimId: alternative.id, kind: "judgment", value: alternative.label, unit: null, period: null,
        supportIds: [alternative.projection.basisFingerprint, alternative.projection.calculationFingerprint],
      }))},
  ];
  if (decision.ratios.length > 0) {
    drafts.push({blockKey: "ratios", kind: "table",
      content: {rows: decision.ratios.map((ratio) => ({
        id: ratio.id, alternativeId: ratio.alternativeId, ratioId: ratio.ratioId, definitionKind: ratio.definitionKind,
        measurementDate: ratio.measurementDate, displayedRatio: ratio.displayedRatio,
      }))},
      claims: decision.ratios.map((ratio) => ({
        claimId: ratio.id, kind: "calculation", value: ratio.displayedRatio, unit: "ratio", period: ratio.measurementDate, supportIds: [ratio.fingerprint],
      }))});
  }
  if (decision.recommendation) {
    drafts.push({blockKey: "recommendation", kind: "section", content: {alternativeId: decision.recommendation.alternativeId},
      claims: [{claimId: "recommendation", kind: "judgment", value: decision.recommendation.alternativeId, unit: null, period: null,
        supportIds: [...decision.recommendation.basisDecisionIds]}]});
  }
  drafts.push(
    {blockKey: "information-gaps", kind: "table", claims: [],
      content: {rows: decision.informationGaps.map((gap) => ({subjectId: gap.subjectId, code: gap.code, reason: gap.reason}))}},
    {blockKey: "contractual-gaps", kind: "table", claims: [],
      content: {rows: packet.contractualGaps.map((gap) => ({subjectId: gap.subjectId, code: gap.code}))}},
    {blockKey: "next-requirements", kind: "section", claims: [], content: {items: [...decision.nextRequirements]}},
  );
  decision.alternatives.forEach((alternative, index) => {
    const projection = alternative.projection;
    const rows = projection.rows;
    if (rows === null || rows.length === 0) return;
    for (const {questionCode, field} of executionResultDecisiveQuestions) {
      let lowest = 0;
      rows.forEach((row, rowIndex) => {
        if (compareDecimalText(row[field], rows[lowest]![field]) < 0) lowest = rowIndex;
      });
      const row = rows[lowest]!;
      drafts.push({blockKey: `decisive:${questionCode}:${index}`, kind: "number",
        content: {questionCode, alternativeId: alternative.id, unit: projection.currency, value: row[field], periodLabel: row.periodId,
          path: `decision.alternatives[${index}].projection.rows[${lowest}].${field}`},
        claims: [{claimId: `${questionCode}:${alternative.id}`, kind: "calculation", value: row[field], unit: projection.currency, period: row.periodId,
          supportIds: [projection.basisFingerprint, projection.calculationFingerprint]}]});
    }
  });
  const blocks = drafts.map((draft) => artifactBlockDraftSchema.parse(draft));
  if (duplicates(blocks.map((block) => block.blockKey))) throw new Error("duplicate_block_key");
  if (duplicates(blocks.flatMap((block) => block.claims.map((claim) => claim.claimId)))) throw new Error("duplicate_claim_id");
  return freezeArtifactValue(blocks);
}

export type PacketManifestContext = ManifestContext & {
  /** From the execution result receipt: its canonical result fingerprint is not the packet's own JSON fingerprint. */
  readonly execution: {readonly executionId: string; readonly resultFingerprint: string; readonly inputFingerprint: string};
  /** From the execution input snapshot, when the producer has it. */
  readonly inputSnapshot?: {readonly fingerprint: string} | null;
  /**
   * The release the execution ran, when the producer has it. The procedure defaults to the one the
   * packet names; the SQL producer takes it from the pinned release, which is the same procedure.
   */
  readonly method?: {readonly procedureId?: string; readonly platformReleaseId: string; readonly houseReleaseId: string | null; readonly version: string} | null;
  /** The gate receipt the MD test is evaluated over, when the execution carried one. */
  readonly gatesFingerprint?: string | null;
};

/** The execution result as an artifact: the claims summary is the one of `capitalProcedurePacketBlocks`. */
export function manifestFromCapitalProcedurePacket(packet: CapitalProcedurePacketLike, context: PacketManifestContext): ArtifactManifest {
  const method = context.method;
  return finish({
    ...emptyManifestParts,
    schemaVersion: artifactManifestSchemaVersion,
    kind: "execution_result",
    audience: context.audience,
    format: "json",
    method: method ? {procedureId: method.procedureId ?? packet.decision.procedureId, platformReleaseId: method.platformReleaseId,
      houseReleaseId: method.houseReleaseId, version: method.version} : null,
    execution: context.execution,
    inputSnapshot: context.inputSnapshot ?? null,
    sources: mergedSources(context, packet.contractSourceVersionIds.map((sourceVersionId) => ({sourceVersionId, rightsVersionId: null}))),
    claims: blockDraftsClaimsSummary(capitalProcedurePacketBlocks(packet)),
    traces: unique([
      `capital-procedure-packet:${packet.fingerprint}`,
      `capital-decision-delivery:${packet.decision.fingerprint}`,
      `financial-core:${packet.decision.provenance.financialCoreVersion}`,
      ...packet.decision.ratios.map((ratio) => `ratio:${ratio.id}:${ratio.fingerprint}`),
      ...(context.gatesFingerprint ? [`execution-gates:${context.gatesFingerprint}`] : []),
    ]),
    provenance: context.provenance,
  });
}

/** An execution result as a reader takes it back from its blocks: what the blocks carry, nothing recomputed. */
export type ExecutionResultBlocksView = {
  readonly framing: {readonly status: "framed" | "partial" | "prepared_for_human_review"; readonly question: string; readonly asOf: string; readonly contributionCount: number};
  readonly alternatives: ReadonlyArray<{readonly id: string; readonly label: string; readonly kind: string; readonly calculated: boolean}>;
  readonly ratios: ReadonlyArray<{
    readonly id: string; readonly alternativeId: string; readonly ratioId: string; readonly definitionKind: string;
    readonly measurementDate: string; readonly displayedRatio: string | null;
  }>;
  readonly recommendation: {readonly alternativeId: string} | null;
  readonly informationGaps: ReadonlyArray<{readonly subjectId: string | null; readonly code: string; readonly reason: string}>;
  readonly contractualGaps: ReadonlyArray<{readonly subjectId: string; readonly code: string}>;
  readonly nextRequirements: readonly string[];
  readonly decisiveNumbers: ReadonlyArray<{
    readonly pieceId: string; readonly questionCode: (typeof executionResultDecisiveQuestions)[number]["questionCode"];
    readonly alternativeId: string; readonly unit: string; readonly value: string; readonly periodLabel: string;
  }>;
};

const noClaims = z.array(z.never()).length(0);
const framingBlock = z.strictObject({blockKey: z.literal("framing"), kind: z.literal("section"), claims: noClaims,
  content: z.strictObject({status: z.enum(["framed", "partial", "prepared_for_human_review"]), question: z.string(), asOf: z.string(), contributionCount: z.number().int().nonnegative()})});
const alternativesBlock = z.strictObject({blockKey: z.literal("alternatives"), kind: z.literal("table"), claims: z.array(artifactClaimSchema),
  content: z.strictObject({rows: z.array(z.strictObject({id: z.string(), label: z.string(), kind: z.string(), calculated: z.boolean()}))})});
const ratiosBlock = z.strictObject({blockKey: z.literal("ratios"), kind: z.literal("table"), claims: z.array(artifactClaimSchema),
  content: z.strictObject({rows: z.array(z.strictObject({id: z.string(), alternativeId: z.string(), ratioId: z.string(), definitionKind: z.string(),
    measurementDate: z.string(), displayedRatio: z.string().nullable()}))})});
const recommendationBlock = z.strictObject({blockKey: z.literal("recommendation"), kind: z.literal("section"), claims: z.array(artifactClaimSchema).length(1),
  content: z.strictObject({alternativeId: z.string()})});
const informationGapsBlock = z.strictObject({blockKey: z.literal("information-gaps"), kind: z.literal("table"), claims: noClaims,
  content: z.strictObject({rows: z.array(z.strictObject({subjectId: z.string().nullable(), code: z.string(), reason: z.string()}))})});
const contractualGapsBlock = z.strictObject({blockKey: z.literal("contractual-gaps"), kind: z.literal("table"), claims: noClaims,
  content: z.strictObject({rows: z.array(z.strictObject({subjectId: z.string(), code: z.string()}))})});
const requirementsBlock = z.strictObject({blockKey: z.literal("next-requirements"), kind: z.literal("section"), claims: noClaims,
  content: z.strictObject({items: z.array(z.string())})});
const decisiveBlock = z.strictObject({blockKey: z.string().regex(/^decisive:[a-z_]+:\d+$/), kind: z.literal("number"), claims: z.array(artifactClaimSchema).length(1),
  content: z.strictObject({questionCode: z.enum(executionResultDecisiveQuestions.map((question) => question.questionCode) as ["lowest_available_cash_by_period", "largest_net_financing_outflow_by_period"]),
    alternativeId: z.string(), unit: z.string(), value: z.string().regex(decimalText), periodLabel: z.string(), path: z.string()})});

/**
 * The reader of `capitalProcedurePacketBlocks`: the blocks of an execution result revision back into
 * the fields they carry. Every block the mapping writes must be there once and consistent with its
 * claims (alternative and ratio claims name their rows, the recommendation claim names the
 * alternative, each number claim repeats its block's value, unit and period); an unknown key, a
 * missing block or an inconsistent claim gives null, and the reader then shows nothing from it.
 */
export function readCapitalProcedurePacketBlocks(blocks: ReadonlyArray<{readonly blockKey: string; readonly kind: string; readonly content: unknown; readonly claims: unknown}>): ExecutionResultBlocksView | null {
  const byKey = new Map<string, {blockKey: string; kind: string; content: unknown; claims: unknown}>();
  for (const block of blocks) {
    if (byKey.has(block.blockKey)) return null;
    byKey.set(block.blockKey, {blockKey: block.blockKey, kind: block.kind, content: block.content, claims: block.claims});
  }
  const take = <T>(key: string, schema: z.ZodType<T>, optional = false): T | null | undefined => {
    const block = byKey.get(key);
    byKey.delete(key);
    if (block === undefined) return optional ? null : undefined;
    const parsed = schema.safeParse(block);
    return parsed.success ? parsed.data : undefined;
  };
  const framing = take("framing", framingBlock);
  const alternatives = take("alternatives", alternativesBlock);
  const ratios = take("ratios", ratiosBlock, true);
  const recommendation = take("recommendation", recommendationBlock, true);
  const informationGaps = take("information-gaps", informationGapsBlock);
  const contractualGaps = take("contractual-gaps", contractualGapsBlock);
  const requirements = take("next-requirements", requirementsBlock);
  if (!framing || !alternatives || ratios === undefined || recommendation === undefined || !informationGaps || !contractualGaps || !requirements) return null;
  const rowsNamedByClaims = (rows: ReadonlyArray<{id: string}>, claims: ReadonlyArray<{claimId: string}>) => (
    rows.length === claims.length && rows.every((row, index) => claims[index]?.claimId === row.id));
  if (!rowsNamedByClaims(alternatives.content.rows, alternatives.claims) || (ratios !== null && !rowsNamedByClaims(ratios.content.rows, ratios.claims))) return null;
  if (recommendation !== null && (recommendation.claims[0]!.claimId !== "recommendation" || recommendation.claims[0]!.value !== recommendation.content.alternativeId)) return null;
  const decisiveNumbers: Array<ExecutionResultBlocksView["decisiveNumbers"][number]> = [];
  for (const block of blocks) {
    if (!block.blockKey.startsWith("decisive:")) continue;
    const parsed = decisiveBlock.safeParse(byKey.get(block.blockKey));
    byKey.delete(block.blockKey);
    if (!parsed.success) return null;
    const {content, claims} = parsed.data;
    const claim = claims[0]!;
    if (!parsed.data.blockKey.startsWith(`decisive:${content.questionCode}:`) || claim.claimId !== `${content.questionCode}:${content.alternativeId}`
      || claim.value !== content.value || claim.unit !== content.unit || claim.period !== content.periodLabel) return null;
    decisiveNumbers.push({pieceId: claim.claimId, questionCode: content.questionCode, alternativeId: content.alternativeId, unit: content.unit, value: content.value, periodLabel: content.periodLabel});
  }
  if (byKey.size > 0) return null;
  return freezeArtifactValue({
    framing: framing.content,
    alternatives: alternatives.content.rows,
    ratios: ratios?.content.rows ?? [],
    recommendation: recommendation ? {alternativeId: recommendation.content.alternativeId} : null,
    informationGaps: informationGaps.content.rows,
    contractualGaps: contractualGaps.content.rows,
    nextRequirements: requirements.content.items,
    decisiveNumbers,
  });
}

// Conversation citations ---------------------------------------------------------------------
//
// An answer of the conversation that cites the result of an execution names the execution and the
// exact revision it read, in `metadata.citations`; the interface links to that revision. The
// citation carries identifiers only, never the text or the numbers of the result.

export const executionResultCitationSchema = z.strictObject({kind: z.literal("execution_result"), executionId: uuid, revisionId: uuid});
export type ExecutionResultCitation = z.infer<typeof executionResultCitationSchema>;

/** The execution results a message's metadata cites; anything else in the metadata is ignored, and a malformed citation list cites nothing. */
export function executionResultCitations(metadata: unknown): readonly ExecutionResultCitation[] {
  if (metadata === null || typeof metadata !== "object" || Array.isArray(metadata)) return [];
  const parsed = z.array(executionResultCitationSchema).max(20).safeParse((metadata as Record<string, unknown>).citations);
  if (!parsed.success || duplicates(parsed.data.map((citation) => citation.revisionId))) return [];
  return freezeArtifactValue(parsed.data);
}

// Legacy labeling ----------------------------------------------------------------------------
//
// Four historical shapes become `legacy` revisions. Each keeps the row's own fingerprint verbatim
// in `legacyRef`, lists only what the row carries as evidence and never fills a method, an
// execution, an input snapshot or a source link the row does not have. The historical
// `input_fingerprint` columns are evidence, not input snapshots: no historical table carries one.

const workbookHashes = z.object({sha256: hex64, byteSize: z.number().int().positive()});

export const legacyCapitalProjectArtifactRowSchema = z.object({
  id: uuid, organization_id: uuid, capital_project_id: uuid, plan_id: uuid, task_run_id: uuid, processing_job_id: uuid,
  artifact_type: text(80), schema_version: text(80), artifact_version: z.number().int().positive(), status: text(40),
  input_fingerprint: hex64, artifact_fingerprint: hex64, created_by_kind: z.enum(["worker", "user"]), created_at: timestamp,
  evidence_refs: z.array(z.unknown()).default([]), dependencies: z.array(z.unknown()).default([]),
});

export const legacyCaseArtifactManifestRowSchema = z.object({
  id: uuid, organization_id: uuid, intake_session_id: uuid, processing_run_id: uuid.nullable(), schema_version: text(80),
  locale: z.enum(["pt-BR", "en-US"]), input_fingerprint: hex64, manifest_fingerprint: hex64, created_by: uuid, created_at: timestamp,
  manifest: z.object({
    runId: z.string().optional(),
    outputs: z.array(z.object({artifactId: z.string(), kind: z.string(), sha256: hex64})).default([]),
    sources: z.array(z.object({documentId: z.string(), versionId: z.string(), sha256: hex64.nullable()})).default([]),
  }),
});

export const legacyInstitutionalModelResultRowSchema = z.object({
  id: uuid, organization_id: uuid, capital_project_id: uuid, intake_session_id: uuid, configuration_id: uuid,
  configuration_fingerprint: hex64, source_manifest_fingerprint: hex64, status: z.enum(["queued", "completed", "blocked"]), created_at: timestamp,
  artifact: z.object({
    fingerprint: hex64, version: z.string(), workbooks: z.object({pt: workbookHashes, en: workbookHashes}),
    institutional: z.object({
      activeScenarioId: uuid,
      scenarios: z.array(z.object({configurationId: uuid, configurationFingerprint: hex64, outputFingerprint: hex64, sourceBindings: z.array(z.unknown()).default([])})),
    }),
