export const receivablesAgingBuckets = [
  "not_due",
  "past_due_1_15",
  "past_due_16_30",
  "past_due_31_60",
  "past_due_61_90",
  "past_due_91_180",
  "past_due_over_180",
] as const;
export type ReceivablesAgingBucket = typeof receivablesAgingBuckets[number];

export type EligibilityScope =
  | "receivable"
  | "obligor"
  | "economic_group"
  | "portfolio"
  | "cedent"
  | "vehicle"
  | "class"
  | "operational_legal"
  | "live_mandate";

export type EligibilityDenominator =
  | "receivable_face_value"
  | "portfolio_open_value"
  | "cedent_portfolio_value"
  | "fund_net_asset_value"
  | "class_net_asset_value"
  | "committed_capacity"
  | "not_applicable";

export type BuyerFitStatus =
  | "technically_eligible"
  | "policy_fit_confirmed"
  | "live_appetite_confirmed"
  | "conditionally_eligible"
  | "not_evaluated"
  | "ineligible";

export type EligibilityCriterion = {
  id: string;
  version: string;
  scope: EligibilityScope;
  denominator: EligibilityDenominator;
  description: string;
  provenance: CitedProvenance;
};

export type BuyerFitResult = {
  buyerId: string;
  status: BuyerFitStatus;
  evaluatedAt: IsoDate;
  criterionResults: readonly {
    criterionId: string;
    status: "pass" | "fail" | "condition" | "not_evaluated";
    reason: string;
    provenance?: AssertionProvenance;
  }[];
};

export function agingBucketForDaysPastDue(daysPastDue: number): ReceivablesAgingBucket {
  if (!Number.isInteger(daysPastDue)) throw new RangeError("days past due must be an integer");
  if (daysPastDue <= 0) return "not_due";
  if (daysPastDue <= 15) return "past_due_1_15";
  if (daysPastDue <= 30) return "past_due_16_30";
  if (daysPastDue <= 60) return "past_due_31_60";
  if (daysPastDue <= 90) return "past_due_61_90";
  if (daysPastDue <= 180) return "past_due_91_180";
  return "past_due_over_180";
}

export function assertHardEligibilityProvenance(result: BuyerFitResult): void {
  if (result.status === "not_evaluated") return;
  for (const criterion of result.criterionResults) {
    if (criterion.status === "not_evaluated") continue;
    if (!criterion.provenance) throw new Error(`criterion ${criterion.criterionId} requires provenance`);
    if (criterion.provenance.kind === "estimated") {
      throw new Error(`criterion ${criterion.criterionId} cannot use estimated provenance for a hard decision`);
    }
  }
}

import Decimal from "decimal.js";

import {
  agingBucketForDaysPastDue,
  receivablesAgingBuckets,
  type DilutionEvent,
  type IsoDate,
  type ReceivableTitle,
  type ReceivablesAgingBucket,
  type ReceivablesUniverse,
  type RepurchaseEvent,
  type SettlementEvent,
} from "./contracts";
import {
  canonicalMetricValue,
  collectReceivablesSourceAnchors,
  measuredReceivablesMetric,
  notEvaluableReceivablesMetric,
  receivablesDaysBetween,
  receivablesMetricsFormulaVersion,
  receivablesUtcDate,
  shiftReceivablesDays,
  type MeasuredMetric,
  type MetricPeriod,
  validateReceivablesUniverse,
} from "./static-metrics";

const ZERO = new Decimal(0);
const DILUTION_REASONS: readonly DilutionEvent["reason"][] = ["return", "rebate", "discount", "credit_note", "glosa", "other"];

export const receivablesVintageHorizons = [30, 60, 90, 120, 180, 360] as const;
export type ReceivablesVintageHorizon = typeof receivablesVintageHorizons[number];
export const receivablesRollDestinations = [...receivablesAgingBuckets, "resolved"] as const;
export type ReceivablesRollDestination = typeof receivablesRollDestinations[number];

export type RollTransition = {
  amount: string;
  rate: MeasuredMetric;
};

export type RollRateRow = {
  sourceExposure: string;
  transitions: Record<ReceivablesRollDestination, RollTransition>;
};

export type MonthlyRollRate = {
  fromDate: IsoDate;
  toDate: IsoDate;
  rows: Record<ReceivablesAgingBucket, RollRateRow>;
};

export type VintageHorizonMetric = {
  unresolvedAmount: string | null;
  unresolvedShare: MeasuredMetric;
};

export type ReceivablesVintage = {
  cohortMonth: string;
  titleCount: number;
  faceValue: string;
  horizons: Record<ReceivablesVintageHorizon, VintageHorizonMetric>;
};

export type DynamicReceivablesMetrics = {
  version: typeof receivablesMetricsFormulaVersion;
  universeId: string;
  rollRates: {
    status: "measured" | "not_evaluable";
    basis: "original_due_date";
    periods: readonly MonthlyRollRate[];
    warnings: readonly string[];
  };
  vintages: {
