    if (lowerNpv.mul(midpointNpv).lte(0)) {
      upper = midpoint;
      upperNpv = midpointNpv;
    } else {
      lower = midpoint;
      lowerNpv = midpointNpv;
    }
  }
  return lower.plus(upper).div(2);
}

