      recommendation: optional(p + "recommendation", "text", "text"), options: optional(p + "options", "text", "list")};
  });
  const appendix = keys(new RegExp(`^appendix\\.(${k})$`), "order.appendix").map((id) => ({id, reading: select(`appendix.${id}`, "identity", "list")}));
  const questions = keys(new RegExp(`^question\\.(${k})\\.`), "order.questions").map((id) => ({id, question: select(`question.${id}.question`, "text", "text"), answer: select(`question.${id}.answer`, "text", "text")}));
  const omissions = keys(new RegExp(`^omission\\.(${k})$`), "order.omissions").map((id) => ({id, reading: select(`omission.${id}`, "identity", "list")}));
  const informed = keys(new RegExp(`^informed\\.(${k})$`), "order.informed").map((id) => ({id, reading: select(`informed.${id}`, "identity", "list")}));
  const discussion = {envelope: input.discussion.envelope, scope: input.discussion.scope, entityId: d.entityId!, perimeter: d.perimeter!, currency: d.currency!,
    openingDate: d.periodStart!, endDate: d.periodEnd!, numericInterpretations: [], analysisId, scenario: sc,
    meeting: {date: select("meeting.date", "date", "date"), askedOn: select("meeting.askedOn", "date", "date"), leadDays: select("meeting.leadDays", "days", "number"),
      minutesPerPage: select("meeting.minutesPerPage", "minutes", "number"), agendaMinutes: optional("meeting.agendaMinutes", "minutes", "number"),
      nextMeetingDate: optional("meeting.nextMeetingDate", "date", "date"), template: optional("meeting.template", "text", "text"), outlineConfirmed: select("meeting.outlineConfirmed", "convention", "boolean")},
    sources, topics, deliberations, figures, materialFigureIds: select("figures.material", "identity", "list"), indicative, pages,
    summary: {opening: select("summary.opening", "text", "text"), closing: select("summary.closing", "text", "text")}, appendix, questions, omissions, informed};
  // A missing operand carries the lowest resolved definition so the reference is stable; the executor ignores it.
  const borrowed = [...definitions].sort((a, b) => a.definitionVersionId < b.definitionVersionId ? -1 : 1)[0];
  if (borrowed) for (const m of missing) {m.definitionVersionId = borrowed.definitionVersionId; m.definitionKind = borrowed.definitionKind;}
  // The stored results, verbatim and in the order the basis names them.
  const byId = new Map(input.sources.map((s) => [s.id, s.result]));
  if (byId.size !== input.sources.length || input.sources.some((s) => !sources.some((x) => x.id === s.id))) throw new Error("board_capital_source_not_named");
  const packets = sources.map((s) => {const packet = byId.get(s.id); if (!packet) throw new Error(`board_capital_source_missing:${s.id}`); return {id: s.id, packet};});
  return boardCapitalDiscussionPacketInputSchema.parse({schemaVersion: "board-capital-discussion-packet-input.v1", question: input.question, analysis: {sources: packets, discussion}});
}

import {z} from "zod";
import {methodDataContractFromJsonSchema} from "@offroad/credit-playbook";
import {boardCapitalDiscussionPacketInputSchema, boardCapitalDiscussionPacketOutputSchema, boardCapitalDiscussionPacketVersion} from "./board-capital-discussion-packet";

/** Build-owned contract publication, kept apart from the executor so the released artifact
 * bundles only the calculation and its schemas. */
export function boardCapitalDiscussionPacketExecutorContracts() {
  const options = {reused: "inline", cycles: "throw", unrepresentable: "throw"} as const;
  const inputSchema = z.toJSONSchema(boardCapitalDiscussionPacketInputSchema, {...options, io: "input"});
  const outputSchema = z.toJSONSchema(boardCapitalDiscussionPacketOutputSchema, options);
  return {schemaVersion: "method-executor-contracts.v1",
    executor: {module: "@offroad/financial-model", exportName: "prepareBoardCapitalDiscussionPacket", version: boardCapitalDiscussionPacketVersion},
    inputs: methodDataContractFromJsonSchema("board-capital-discussion-packet-input", boardCapitalDiscussionPacketVersion, inputSchema),
    outputs: methodDataContractFromJsonSchema("board-capital-discussion-packet-output", boardCapitalDiscussionPacketVersion, outputSchema),
    validationSchemas: {input: inputSchema, output: outputSchema}};
}

import {createHash} from "node:crypto";
import {z} from "zod";
import {financialCoreVersion} from "@offroad/financial-core";
import {boardCapitalDiscussionAnalysesSchema, calculateAdoptedBoardCapitalDiscussion} from "./adopted-board-capital-discussion";
import {adoptedBoardCapitalDiscussionOutputSchema} from "./board-capital-discussion-results";
import {boardCanonicalJson, boardVersionFingerprint} from "./board-capital-discussion";

export const boardCapitalDiscussionPacketVersion = "2026.10.27-v1";
const text = z.string().trim().min(1).max(4000), key = z.string().trim().min(1).max(160), hash = z.string().regex(/^[a-f0-9]{64}$/);

/** One request to prepare a board discussion of a capital decision, over the reviewed results the work already holds. */
export const boardCapitalDiscussionPacketInputSchema = z.strictObject({
  schemaVersion: z.literal("board-capital-discussion-packet-input.v1"),
  question: text,
  analysis: boardCapitalDiscussionAnalysesSchema,
});
export type BoardCapitalDiscussionPacketInput = z.infer<typeof boardCapitalDiscussionPacketInputSchema>;
const packetExclusions = ["recalculation", "presentation_delivery", "template_import", "third_party_distribution", "credit_approval"] as const;

export const boardCapitalDiscussionPacketOutputSchema = z.strictObject({
  schemaVersion: z.literal("board-capital-discussion-packet.v1"), executorVersion: z.literal(boardCapitalDiscussionPacketVersion), financialCoreVersion: key,
  question: text, basisFingerprint: hash, scope: boardCapitalDiscussionAnalysesSchema.shape.discussion.shape.scope, entityId: z.uuid(), currency: z.string().regex(/^[A-Z]{3}$/),
  result: adoptedBoardCapitalDiscussionOutputSchema,
  /** What the answer says, in order: before the material, the outline and the questions that change it;
   * with the material, what was checked, what is pending and, after an omission request, what stays. */
  readings: z.strictObject({
    stage: z.enum(["outline_proposed", "material_prepared"]),
    /** Material withheld because there is time to align the outline first. */
    materialWithheld: z.boolean(),
    deliberations: z.array(z.strictObject({id: key, number: z.number().int(), title: text, text, deadlines: z.array(z.iso.date()).max(4)})).min(1).max(12),
    questionsBeforeMaterial: z.array(z.strictObject({code: key, topicId: key.nullable()})).max(16),
    material: z.strictObject({version: z.number().int(), fingerprint: hash, mainPages: z.number().int(), appendixPages: z.number().int(),
      titles: z.array(z.strictObject({pageId: key, number: z.number().int(), placement: z.enum(["main", "appendix"]), title: text})).max(40),
      fitsAgenda: z.boolean().nullable(), questions: z.number().int(), figuresChecked: z.number().int(), allFiguresMatch: z.literal(true),
      /** Every material fact of the rule is shown in the final text of this version; allFiguresMatch holds only because every number of that text was verified against its marker. */
      materialFacts: z.number().int(), materialFactsShown: z.literal(true), verifiedNumbers: z.number().int(),
      priorVersionFingerprint: hash.nullable()}).nullable(),
    pending: z.strictObject({indicative: z.array(key).max(24), sources: z.array(key).max(16), authority: z.array(key).max(12), template: z.enum(["not_supplied", "supplied_not_applied"])}),
    omissions: z.array(z.strictObject({id: key, outcome: z.enum(["applied", "refused"]), reason: text, keptFigureIds: z.array(key).max(160)})).max(12),
    priorVersionsKept: z.literal(true), sentToThirdParties: z.literal(false), presented: z.literal(false),
  }).nullable(),
  gaps: z.array(z.strictObject({operand: text, reason: text})).max(1024),
  status: z.enum(["framed", "partial", "prepared_for_human_review"]),
  exclusions: z.array(z.enum(packetExclusions)).length(5).refine((v) => v.join("|") === packetExclusions.join("|"), "Exact exclusion ledger required"),
  grantsExecution: z.literal(false), grantsPublication: z.literal(false), fingerprint: hash,
});
export type BoardCapitalDiscussionPacket = z.infer<typeof boardCapitalDiscussionPacketOutputSchema>;

/** Prepares the board discussion of a capital decision from reviewed results, without recalculating them:
 * the deliberations with deadline and authority in urgency order; the outline before any material when there
 * is time to align it, asking only what changes the material; then the pages, each title a conclusion with the
 * number behind it, every number read from a reviewed result by method, version and path and checked against
 * the stated one; the summary for prior reading, the appendix, the likely questions with answers and numbers,
 * the declared pending items, the order conditioned on what the board has seen, and the omission rule: a
 * recommendation may be withdrawn, a material fact is kept, and each version is kept. Deterministic; it never
 * presents, applies an imported template or sends anything to a third party. */
export function prepareBoardCapitalDiscussionPacket(raw: unknown): BoardCapitalDiscussionPacket {
  const input = boardCapitalDiscussionPacketInputSchema.parse(raw);
  const result = adoptedBoardCapitalDiscussionOutputSchema.parse(calculateAdoptedBoardCapitalDiscussion(input.analysis));
  const d = result.discussion;
  const current = d?.versions.at(-1) ?? null;
  const readings = d ? {
    stage: d.stage === "material" ? "material_prepared" as const : "outline_proposed" as const,
    materialWithheld: d.stage === "outline",
    deliberations: (current?.deliberations ?? d.outline.deliberations).map((x) => ({id: x.id, number: x.number, title: x.title, text: x.text, deadlines: x.deadlines.map((t) => t.date)})),
    questionsBeforeMaterial: d.stage === "outline" ? d.outline.questions.map((q) => ({code: q.code, topicId: q.topicId})) : [],
    material: current ? {version: current.version, fingerprint: current.fingerprint, mainPages: current.agenda.mainPages, appendixPages: current.pages.length - current.agenda.mainPages,
      titles: current.pages.map((p) => ({pageId: p.id, number: p.number, placement: p.placement, title: p.title})), fitsAgenda: current.agenda.fits,
      questions: current.questions.length, figuresChecked: d.identity.length, allFiguresMatch: true as const,
      materialFacts: d.materialFacts.figures.length + d.materialFacts.deadlines.length, materialFactsShown: true as const, verifiedNumbers: current.verifiedNumbers,
      priorVersionFingerprint: d.versions.length > 1 ? d.versions[0]!.fingerprint : null} : null,
    pending: {indicative: d.pending.indicative.map((x) => x.figureId), sources: d.pending.sources.map((s) => s.sourceId), authority: d.pending.authority, template: d.pending.template},
    omissions: d.omissions.map((o) => ({id: o.id, outcome: o.outcome, reason: o.reason, keptFigureIds: o.keptFigureIds})),
    priorVersionsKept: true as const, sentToThirdParties: false as const, presented: false as const,
  } : null;
  const gaps = [...result.gaps, ...(d?.gaps ?? []).map((g) => ({operand: `board_capital.${result.analysisId}.${g.item}`, reason: g.reason}))];
  const status = !d || d.stage === "outline" ? "framed" as const : gaps.length ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "board-capital-discussion-packet.v1" as const, executorVersion: boardCapitalDiscussionPacketVersion, financialCoreVersion,
    question: input.question, basisFingerprint: result.basisFingerprint, scope: result.scope, entityId: result.entityId, currency: result.currency,
    result, readings, gaps, status, exclusions: packetExclusions, grantsExecution: false as const, grantsPublication: false as const};
  const packet = boardCapitalDiscussionPacketOutputSchema.parse({...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")});
  // Every version's fingerprint recomputed canonically on the object the schema validated: it must reproduce.
  const {fingerprint: resultFingerprint, ...resultBody} = packet.result;
  if (createHash("sha256").update(boardCanonicalJson(resultBody)).digest("hex") !== resultFingerprint) throw new Error("board_capital_result_fingerprint_mismatch");
  for (const v of packet.result.discussion?.versions ?? []) if (boardVersionFingerprint(v) !== v.fingerprint) throw new Error(`board_capital_version_fingerprint_mismatch:${v.version}`);
  return packet;
}

import {z} from "zod";
import {capacityUuid} from "./debt-capacity-premises";
import type {ProposedHypothesis} from "./investment-premises";
import {boardAuthorities, boardOmissionTargets, boardPageRoles} from "./board-capital-discussion";
import {boardSourceMethodIds} from "./board-capital-discussion-sources";
import {boardInformedAuthors, boardThemeOfRefs, boardThemes} from "./board-capital-discussion-templates";

const text = z.string().trim().min(1).max(2000);
const key = z.string().regex(/^[a-z0-9][a-z0-9-]{0,39}$/);
const hash = z.string().regex(/^[a-f0-9]{64}$/);
const origins = ["document", "informed", "house", "estimate", "analysis"] as const;
const originLabel: Record<(typeof origins)[number], string> = {document: "documento", informed: "informado", house: "premissa da casa", estimate: "estimativa", analysis: "análise revisada"};
/** A value and where it came from; the source names the document, the message, the reviewed result or the house rule. */
const fact = <T extends z.ZodType>(value: T) => z.strictObject({value, origin: z.enum(origins), source: text});
type Origin = {origin: (typeof origins)[number]; source: string};

/** [source, path, decimals or date format, stated]: the unit, scale and periodicity come from the field registry of the source's method. */
const reading = z.tuple([key, z.string().min(1).max(400), z.enum(["0", "1", "2", "-", "day_month", "day_long", "month_year", "month_long", "year"])])
  .rest(z.string().regex(/^(?:\d{4}-\d{2}-\d{2}|-?\d{1,24}(?:\.\d{1,8})?)$/));
const figure = z.discriminatedUnion("kind", [
  z.strictObject({id: key, kind: z.literal("reading"), reading: reading.refine((r) => r.length === (r[2] === "-" ? 3 : 4), {message: "A number or a date states its value; a label or a yes-no reading does not"})}),
  z.strictObject({id: key, kind: z.literal("pending"), reading: z.tuple([key, text, text])})]);
const deliberation = z.strictObject({id: key, topicId: key.nullable(), title: text, subject: text, recommendation: text.nullable(), authority: z.enum(boardAuthorities), authorityBasis: text.nullable(),
  deadlines: z.array(z.strictObject({id: key, date: z.iso.date(), action: text})).max(4)});
const page = z.strictObject({id: key, role: z.enum(boardPageRoles), topicId: key.nullable(), title: text, lines: z.array(text).max(12), recommendation: text.nullable(), options: z.array(text).max(6)});

/** The facts of one board discussion, each with its origin. The reviewed results are named by method and packet
 * fingerprint and travel beside the basis; nothing of them is restated here. Nothing is adopted until a person
 * confirms the set; every number on the material is a reading of a named result. */
export const boardCapitalDiscussionFactsSchema = z.strictObject({
  discussionId: z.uuid(), entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/), definitionVersionId: z.uuid(),
  askedOn: fact(z.iso.date()), meetingDate: fact(z.iso.date()), leadDays: fact(z.string().regex(/^\d{1,3}$/)), minutesPerPage: fact(z.string().regex(/^[1-9]\d?$/)),
  agendaMinutes: fact(z.string().regex(/^[1-9]\d{0,2}$/)).nullable(), nextMeetingDate: fact(z.iso.date()).nullable(), template: fact(text).nullable(), outlineConfirmed: fact(z.boolean()),
  /** Each reviewed result with the money scale its basis was adopted in (the producer checks it against the stored basis). */
  sources: z.array(fact(z.strictObject({id: key, methodId: z.enum(boardSourceMethodIds), packetFingerprint: hash, moneyScale: z.enum(["reais", "millions"])}))).min(1).max(16),
  topics: z.array(fact(z.strictObject({id: key, label: text, seen: z.boolean().nullable()}))).max(12),
  deliberations: z.array(fact(deliberation)).min(1).max(12),
  figures: z.array(fact(figure)).max(160),
  materialFigureIds: fact(z.array(key).max(160)),
  indicative: z.array(fact(z.strictObject({figureId: key, reason: text}))).max(24),
  pages: z.array(fact(page)).min(1).max(40),
  summary: fact(z.strictObject({opening: text, closing: text})),
  appendix: z.array(fact(z.strictObject({id: key, label: text, sourceIds: z.array(key).min(1).max(16)}))).max(16),
  questions: z.array(fact(z.strictObject({id: key, question: text, answer: text}))).max(24),
  omissions: z.array(fact(z.strictObject({id: key, target: z.enum(boardOmissionTargets), targetId: z.string().regex(/^[a-z0-9][a-z0-9.-]{0,80}$/), requestedBy: text}))).max(12),
  /** Facts informed in the conversation, with the person who stated them; the origin travels into the basis. */
  informed: z.array(fact(z.strictObject({id: key, author: z.enum(boardInformedAuthors), code: z.string().regex(/^[a-z][a-z_]{0,59}$/)}))).max(12).default([]),
}).superRefine((f, ctx) => {
  const fail = (message: string) => ctx.addIssue({code: "custom", message});
  if (f.meetingDate.value < f.askedOn.value) fail("The meeting must not precede the request");
  const unique = (xs: string[], what: string) => {if (new Set(xs).size !== xs.length) fail(`Duplicate ${what}`);};
  unique(f.sources.map((s) => s.value.id), "source"); unique(f.topics.map((t) => t.value.id), "topic"); unique(f.deliberations.map((d) => d.value.id), "deliberation");
  unique(f.figures.map((x) => x.value.id), "figure"); unique(f.pages.map((p) => p.value.id), "page"); unique(f.questions.map((q) => q.value.id), "question");
  unique(f.appendix.map((a) => a.value.id), "appendix item"); unique(f.omissions.map((o) => o.value.id), "omission"); unique(f.informed.map((x) => x.value.id), "informed fact");
  const sources = new Set(f.sources.map((s) => s.value.id)), figures = new Set(f.figures.map((x) => x.value.id)), topics = new Set(f.topics.map((t) => t.value.id));
  for (const {value: x} of f.figures) if (x.kind === "reading" && !sources.has(x.reading[0])) fail(`Figure ${x.id} reads a result the discussion does not name`);
  for (const id of [...f.materialFigureIds.value, ...f.indicative.map((x) => x.value.figureId)]) if (!figures.has(id)) fail(`Unknown figure ${id}`);
  for (const {value: a} of f.appendix) if (!a.sourceIds.every((s) => sources.has(s))) fail(`Appendix item ${a.id} cites a result the discussion does not name`);
  // Themes are the library's closed set; the theme each text derives is checked against its templates downstream.
  // The theme is derived from the templates and never adopted: a fact's topic must be the theme of its own texts.
  for (const {value: t} of f.topics) if (!(boardThemes as readonly string[]).includes(t.id)) fail(`Unknown topic ${t.id}`);
  void topics;
  const check = (id: string, topicId: string | null, refs: string[]) => {
    const theme = boardThemeOfRefs(refs);
    if (theme === null) fail(`Texts of ${id} mix themes`);
    else if (topicId === null) fail(`Topic of ${id} missing; its texts are of theme ${theme}`);
    else if (topicId !== theme) fail(`Topic ${topicId} of ${id} is not the theme of its texts (${theme})`);
  };
  for (const {value: x} of f.pages) check(`page ${x.id}`, x.topicId, [x.title, ...x.lines, ...x.recommendation ? [x.recommendation] : [], ...x.options]);
  for (const {value: x} of f.deliberations) check(`deliberation ${x.id}`, x.topicId, [x.title, x.subject, ...x.recommendation ? [x.recommendation] : [], ...x.deadlines.map((t) => t.action)]);
});
export type BoardCapitalDiscussionFacts = z.infer<typeof boardCapitalDiscussionFactsSchema>;

export const boardCapitalDiscussionAnalysisId = (discussionId: string) => capacityUuid(`offroad:board-capital-discussion:${discussionId}:analysis`);
/** The size of one working basis. */
export const maxBoardCapitalDiscussionHypotheses = 256;

/** The hypotheses one confirmation adopts for the discussion: the meeting, the named results, each deliberation,
 * figure, page, question and request, plus the structure the reader receives as given (the topic of a page or a
 * deliberation and the order of everything), so the packet is composed from the basis alone. Nothing is calculated. */
export function proposeBoardCapitalDiscussionHypotheses(raw: unknown): ProposedHypothesis[] {
  const f = boardCapitalDiscussionFactsSchema.parse(raw);
  const out: ProposedHypothesis[] = [], prefix = `board_capital.${boardCapitalDiscussionAnalysisId(f.discussionId)}.`;
  const why = (x: Origin) => `Origem: ${originLabel[x.origin]}. ${x.source}`;
  const house = (source: string) => `Origem: premissa da casa. ${source}`;
  const add = (path: string, unit: string, value: ProposedHypothesis["value"], reason: string) => out.push({fieldPath: prefix + path,
    dimensions: {entityId: f.entityId, perimeter: f.perimeter, periodStart: f.askedOn.value, periodEnd: f.meetingDate.value, currency: f.currency, unit, scale: "1", scenario: "base", definitionVersionId: f.definitionVersionId},
    value, reason});
  const txt = (path: string, value: string, reason: string, unit = "text") => add(path, unit, {type: "text", value}, reason);
  const list = (path: string, value: string[], reason: string, unit = "identity") => add(path, unit, {type: "list", value}, reason);
  const date = (path: string, value: string, reason: string) => add(path, "date", {type: "date", value}, reason);
  const flag = (path: string, value: boolean, reason: string) => add(path, "convention", {type: "boolean", value}, reason);

  date("meeting.date", f.meetingDate.value, why(f.meetingDate)); date("meeting.askedOn", f.askedOn.value, why(f.askedOn));
  add("meeting.leadDays", "days", {type: "number", value: f.leadDays.value}, why(f.leadDays));
  add("meeting.minutesPerPage", "minutes", {type: "number", value: f.minutesPerPage.value}, why(f.minutesPerPage));
  if (f.agendaMinutes) add("meeting.agendaMinutes", "minutes", {type: "number", value: f.agendaMinutes.value}, why(f.agendaMinutes));
  if (f.nextMeetingDate) date("meeting.nextMeetingDate", f.nextMeetingDate.value, why(f.nextMeetingDate));
  if (f.template) txt("meeting.template", f.template.value, why(f.template));
  flag("meeting.outlineConfirmed", f.outlineConfirmed.value, why(f.outlineConfirmed));
  for (const s of f.sources) list(`source.${s.value.id}`, [s.value.methodId, s.value.packetFingerprint, s.value.moneyScale], why(s));
  for (const t of f.topics) {txt(`topic.${t.value.id}.label`, t.value.label, why(t)); if (t.value.seen !== null) flag(`topic.${t.value.id}.seen`, t.value.seen, why(t));}
  for (const d of f.deliberations) {
    const v = d.value, p = `deliberation.${v.id}.`, r = why(d);
    txt(p + "title", v.title, r); txt(p + "subject", v.subject, r); if (v.recommendation !== null) txt(p + "recommendation", v.recommendation, r);
    list(p + "authority", v.authorityBasis === null ? [v.authority] : [v.authority, v.authorityBasis], r);
    for (const x of v.deadlines) list(`${p}deadline.${x.id}`, [x.date, x.action], r);
    if (v.deadlines.length) list(p + "order.deadlines", v.deadlines.map((x) => x.id), house("Ordem dos prazos como informada"));
  }
  for (const x of f.figures) list(`figure.${x.value.id}.${x.value.kind}`, [...x.value.reading], why(x));
  list("figures.material", f.materialFigureIds.value, why(f.materialFigureIds));
  for (const x of f.indicative) txt(`figure.${x.value.figureId}.indicative`, x.value.reason, why(x));
  for (const pg of f.pages) {
    const v = pg.value, p = `page.${v.id}.`, r = why(pg);
    txt(p + "role", v.role, r, "convention"); txt(p + "title", v.title, r); list(p + "lines", v.lines, r, "text");
    if (v.recommendation !== null) txt(p + "recommendation", v.recommendation, r);
    if (v.options.length) list(p + "options", v.options, r, "text");
  }
  txt("summary.opening", f.summary.value.opening, why(f.summary)); txt("summary.closing", f.summary.value.closing, why(f.summary));
  for (const a of f.appendix) list(`appendix.${a.value.id}`, [a.value.label, ...a.value.sourceIds], why(a));
  for (const q of f.questions) {txt(`question.${q.value.id}.question`, q.value.question, why(q)); txt(`question.${q.value.id}.answer`, q.value.answer, why(q));}
  for (const o of f.omissions) list(`omission.${o.value.id}`, [o.value.target, o.value.targetId, o.value.requestedBy], why(o));
  for (const x of f.informed) list(`informed.${x.value.id}`, [x.origin, x.value.author, x.value.code], why(x));
  const order = (name: string, ids: string[], what: string) => {if (ids.length) list(`order.${name}`, ids, house(`Ordem ${what} como informada`));};
  order("sources", f.sources.map((s) => s.value.id), "dos resultados"); order("topics", f.topics.map((t) => t.value.id), "dos temas");
  order("deliberations", f.deliberations.map((d) => d.value.id), "das deliberações"); order("figures", f.figures.map((x) => x.value.id), "dos números");
  order("indicative", f.indicative.map((x) => x.value.figureId), "das condições indicativas");
  order("pages", f.pages.map((p) => p.value.id), "das páginas"); order("appendix", f.appendix.map((a) => a.value.id), "do apêndice");
  order("questions", f.questions.map((q) => q.value.id), "das perguntas"); order("omissions", f.omissions.map((o) => o.value.id), "dos pedidos");
  order("informed", f.informed.map((x) => x.value.id), "dos fatos informados");
  // A working basis holds at most 256 premises; a set larger than that is refused here, not at confirmation.
  if (out.length > maxBoardCapitalDiscussionHypotheses) throw new Error("board_capital_premises_exceed_basis");
  return out;
}

