export function boardPacketViaPremises(turn: BoardTurn = 2, edit: (c: CaseData) => void = () => undefined, question = boardQuestion,
  factsEdit: (f: ReturnType<typeof auroraBoardFacts>) => void = () => undefined) {
  let n = 9800;
