  const basis = auroraReceivablesFundingBasis({...k, items: k.items.map((i) => i.id === "rede-a" || (variant.thirdProgram && i.id === "rede-e") ? {...i, anchorProgram: "active" as const, ...i.id === "rede-a" && variant.contractA ? {contract: variant.contractA} : {}} : i),
