        reference: {code: "zero", value: referenceValue},
        decisiveNumber: {path: decisive.path, value: decisive.value},
        conclusion: {
          code: position < 0 ? "minimum_below_reference" : position === 0 ? "minimum_at_reference" : "minimum_above_reference",
          values: {
