  const m = i.analysis.measurements.find((x) => x.id === i.headlineMeasurementId);
  if (!m || m.role !== "test") ctx.addIssue({code: "custom", message: "The headline must be a test measurement of the analysis"});
});
export type CovenantHeadroomPacketInput = z.infer<typeof covenantHeadroomPacketInputSchema>;

export const covenantHeadroomPacketOutputSchema = z.strictObject({
  schemaVersion: z.literal("covenant-headroom-packet.v1"), executorVersion: z.literal(covenantHeadroomPacketVersion), financialCoreVersion: key,
  question: text, basisFingerprint: hash, scope: adoptedCovenantHeadroomInputSchema.shape.scope, entityId: z.uuid(), currency: z.string().regex(/^[A-Z]{3}$/),
  result: adoptedCovenantHeadroomOutputSchema,
  /** What the answer must say, in order. */
  readings: z.strictObject({
    headline: z.strictObject({measurementId: key, date: z.iso.date(), ratio: decimal.nullable(), tightestLimitId: key.nullable(),
      byLimit: z.array(z.strictObject({limitId: key, kind: z.enum(["contractual", "board_policy"]), ebitdaHeadroom: decimal, netDebtHeadroom: decimal,
        unrealizedEbitdaLossToLimit: decimal.nullable(), breached: z.boolean()})).max(6)}),
    policyBindsFirst: z.boolean(),
    worst: z.strictObject({measurementId: key, limitId: key, ebitdaHeadroom: decimal}).nullable(),
    anyBreach: z.boolean(),
    contrasts: z.array(key).max(12),
    openQuestions: z.array(key).max(6),
  }).nullable(),
  gaps: z.array(z.strictObject({operand: text, reason: text})).max(1024),
  status: z.enum(["framed", "partial", "prepared_for_human_review"]),
  exclusions: z.array(z.enum(["projection", "waiver_negotiation", "credit_approval", "method_release"])).length(4)
    .refine((v) => v.join("|") === "projection|waiver_negotiation|credit_approval|method_release", "Exact exclusion ledger required"),
  grantsExecution: z.literal(false), grantsPublication: z.literal(false), fingerprint: hash,
});
export type CovenantHeadroomPacket = z.infer<typeof covenantHeadroomPacketOutputSchema>;

/** Where the company stands against its covenants: the ratio at the test date by the written
 * definition; headroom in EBITDA and in net debt against the contract and against the board's
 * own policy, whichever binds first; how much of the period still ahead can be lost; the adverse
 * case, the season at the test date and later dates; readings that are not the test, named as such;
 * what a breach triggers; and the question only the company can answer. Deterministic. */
export function prepareCovenantHeadroomPacket(raw: unknown): CovenantHeadroomPacket {
  const input = covenantHeadroomPacketInputSchema.parse(raw);
  const result = adoptedCovenantHeadroomOutputSchema.parse(calculateAdoptedCovenantHeadroom(input.analysis));
  const h = result.headroom;
  const readings = h ? (() => {
    const m = h.measurements.find((x) => x.id === input.headlineMeasurementId)!;
    const tightest = m.tests.find((t) => t.limitId === m.tightestLimitId);
    return {headline: {measurementId: m.id, date: m.date, ratio: m.ratio, tightestLimitId: m.tightestLimitId,
      byLimit: m.tests.map((t) => ({limitId: t.limitId, kind: t.kind, ebitdaHeadroom: t.ebitdaHeadroom, netDebtHeadroom: t.netDebtHeadroom,
        unrealizedEbitdaLossToLimit: t.unrealizedEbitdaLossToLimit, breached: t.breached}))},
      // Whether the board's policy binds before the contract on the headline date, across every test of that date
      // (the policy may be measured on its own definition in a measurement of its own).
      policyBindsFirst: (() => {
        const sameDate = h.measurements.filter((x) => x.role === "test" && x.date === m.date).flatMap((x) => x.tests);
        const least = (kind: string) => sameDate.filter((t) => t.kind === kind).reduce<Decimal | null>((v, t) => v === null || new Exact(t.ebitdaHeadroom).lt(v) ? new Exact(t.ebitdaHeadroom) : v, null);
        const policy = least("board_policy"), contract = least("contractual");
        return policy !== null && contract !== null && policy.lt(contract);
      })(),
      worst: h.worst, anyBreach: h.anyBreach,
      contrasts: h.measurements.filter((x) => x.role === "contrast").map((x) => x.id),
      openQuestions: result.openQuestions.map((q) => q.limitId)};
  })() : null;
  const gaps = result.gaps;
  const status = !h ? "framed" as const : gaps.length || result.openQuestions.length ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "covenant-headroom-packet.v1" as const, executorVersion: covenantHeadroomPacketVersion, financialCoreVersion,
    question: input.question, basisFingerprint: result.basisFingerprint, scope: result.scope, entityId: result.entityId, currency: result.currency,
    result, readings, gaps, status,
    exclusions: ["projection", "waiver_negotiation", "credit_approval", "method_release"] as const,
    grantsExecution: false as const, grantsPublication: false as const};
  return covenantHeadroomPacketOutputSchema.parse({...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")});
}

import Decimal from "decimal.js";
import {z} from "zod";
import {capacityUuid} from "./debt-capacity-premises";
import type {ProposedHypothesis} from "./investment-premises";

const text = z.string().trim().min(1).max(2000);
/** Ids travel inside field paths, so they never carry a dot; 40 characters keep claim ids built from them short. */
const key = z.string().regex(/^[a-z0-9][a-z0-9-]{0,39}$/);
const scenarioKey = z.string().regex(/^[a-z0-9][a-z0-9_-]{0,59}$/);
/** Money carries at most eight decimals, as the adopted numeric representation reads it. */
const money = z.string().regex(/^-?\d{1,24}(?:\.\d{1,8})?$/);
const unsignedMoney = z.string().regex(/^\d{1,24}(?:\.\d{1,8})?$/);
const ratio = z.string().regex(/^\d{1,4}(?:\.\d{1,20})?$/);
const origins = ["document", "informed", "house", "estimate"] as const;
type Origin = {origin: (typeof origins)[number]; source: string};
const originLabel: Record<(typeof origins)[number], string> = {document: "documento", informed: "informado", house: "premissa da casa", estimate: "estimativa"};
/** A value and where it came from; the source names the document, the message or the house rule. */
const fact = <T extends z.ZodType>(value: T) => z.strictObject({value, origin: z.enum(origins), source: text});

/** The terms of one limit. The fact's source is the clause or minute the limit is read from. */
const limitTerm = z.strictObject({
  id: key, kind: z.enum(["contractual", "board_policy"]), status: z.enum(["in_force", "superseded"]),
  label: text, maximumRatio: ratio, testDates: z.array(z.iso.date()).max(24),
});
/** One reading of net debt over EBITDA at one date in one scenario; a contrast is not the test. */
const measurement = z.strictObject({
  id: key, label: text, role: z.enum(["test", "contrast"]), scenario: scenarioKey, limitIds: z.array(key).max(6), date: z.iso.date(),
  debt: unsignedMoney, cash: money, reportedEbitda: money,
  adjustments: z.array(z.strictObject({id: key, label: text, amount: money})).max(8),
  /** The part of the definition's EBITDA still ahead of the reading date; null when all is realized. */
  unrealizedEbitda: money.nullable(),
});

/** The facts of one covenant headroom question, each with its origin. Nothing here is adopted until a
 * person confirms the set; every number the method reads comes from the adopted basis. */
export const covenantHeadroomFactsSchema = z.strictObject({
  headroomId: z.uuid(), entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/), definitionVersionId: z.uuid(),
  /** The reading date opens the basis period; the basis ends at the last date read. */
  readingDate: z.iso.date(), endDate: z.iso.date(), scenario: scenarioKey,
  /** The test measurement the answer leads with. */
  headline: fact(key),
  limits: z.array(z.strictObject({term: fact(limitTerm),
    /** The EBITDA definition the limit is measured on; null when unwritten, and the source says where it was looked for. */
    definition: fact(text.nullable())})).min(1).max(6),
  measurements: z.array(fact(measurement)).min(1).max(12),
  effects: z.array(fact(z.strictObject({id: key, label: text, measurementId: key, withoutEffectMeasurementId: key}))).max(4),
  /** What a breach triggers, as the contract states it; absent, it stays a named gap. */
  consequence: z.strictObject({acceleration: fact(z.enum(["automatic", "non_automatic"])).nullable(), process: fact(text).nullable(), crossDefault: fact(text).nullable()}),
}).superRefine((f, ctx) => {
  const fail = (message: string) => ctx.addIssue({code: "custom", message});
  if (f.endDate <= f.readingDate) fail("The end date must follow the reading date");
  const limits = new Map(f.limits.map((l) => [l.term.value.id, l.term.value]));
  if (limits.size !== f.limits.length) fail("Duplicate limit");
  for (const l of limits.values()) {
    if (l.status === "in_force" && !l.testDates.length) fail(`Limit ${l.id} in force needs its test dates`);
    if (!new Decimal(l.maximumRatio).gt(0)) fail(`Limit ${l.id} must be positive`);
  }
  const ms = f.measurements.map((m) => m.value);
  if (new Set(ms.map((m) => m.id)).size !== ms.length) fail("Duplicate measurement");
  for (const m of ms) {
    if (new Set(m.adjustments.map((a) => a.id)).size !== m.adjustments.length) fail(`Measurement ${m.id} repeats an adjustment`);
    if (new Set(m.limitIds).size !== m.limitIds.length || m.limitIds.some((id) => !limits.has(id))) fail(`Measurement ${m.id} names an unknown limit`);
    if (m.role === "test" && !m.limitIds.length) fail(`Test ${m.id} needs a limit`);
    // A test is a test only of a limit in force on a date the limit is tested; anything else is a contrast.
    if (m.role === "test" && m.limitIds.some((id) => limits.get(id)?.status === "superseded")) fail(`Test ${m.id} names a superseded limit`);
    if (m.role === "test" && m.limitIds.some((id) => limits.has(id) && !limits.get(id)!.testDates.includes(m.date))) fail(`Test ${m.id} is off its limits' test dates`);
    if (m.unrealizedEbitda !== null && m.date <= f.readingDate) fail(`Measurement ${m.id} has unrealized EBITDA but is not after the reading date`);
  }
  for (const l of limits.values()) if (l.status === "in_force" && !ms.some((m) => m.role === "test" && m.limitIds.includes(l.id))) fail(`Limit ${l.id} in force is never tested`);
  if (new Set(f.effects.map((e) => e.value.id)).size !== f.effects.length) fail("Duplicate effect");
  for (const {value: e} of f.effects) {
    const a = ms.find((m) => m.id === e.measurementId), b = ms.find((m) => m.id === e.withoutEffectMeasurementId);
    if (!a || !b || a === b) fail(`Effect ${e.id} must pair two measurements`);
    else if (a.date !== b.date) fail(`Effect ${e.id} pairs measurements of different dates`);
  }
  if (ms.find((m) => m.id === f.headline.value)?.role !== "test") fail("The headline must be a test measurement");
});
export type CovenantHeadroomFacts = z.infer<typeof covenantHeadroomFactsSchema>;

export const covenantHeadroomAnalysisId = (headroomId: string) => capacityUuid(`offroad:covenant-headroom:${headroomId}:analysis`);
/** The size of one working basis. */
export const maxCovenantHeadroomHypotheses = 256;

/** The hypotheses one confirmation adopts, at the paths, units and scenarios the adopted reader reads
 * (`covenant.<analysis>.`). The reader's structure (reading date, headline, measurement role, label,
 * scenario and limits, effect pairs, order) is adopted as extra hypotheses it ignores, so the packet is
 * composed from the basis alone. An unwritten definition adopts no definition and states why; an
 * absent consequence term adopts nothing. Every reason states the origin. Deterministic. */
export function proposeCovenantHeadroomHypotheses(raw: unknown): ProposedHypothesis[] {
  const f = covenantHeadroomFactsSchema.parse(raw);
  const out: ProposedHypothesis[] = [], prefix = `covenant.${covenantHeadroomAnalysisId(f.headroomId)}.`, top = f.scenario;
  const why = (x: Origin) => `Origem: ${originLabel[x.origin]}. ${x.source}`;
  const house = (source: string) => `Origem: premissa da casa. ${source}`;
  const add = (path: string, unit: string, value: ProposedHypothesis["value"], reason: string, scenario = top) => out.push({fieldPath: prefix + path,
    dimensions: {entityId: f.entityId, perimeter: f.perimeter, periodStart: f.readingDate, periodEnd: f.endDate, currency: f.currency, unit, scale: "1", scenario, definitionVersionId: f.definitionVersionId},
    value, reason});
  const txt = (path: string, unit: string, value: string, reason: string, scenario = top) => add(path, unit, {type: "text", value}, reason, scenario);
  const list = (path: string, unit: string, value: string[], reason: string, scenario = top) => add(path, unit, {type: "list", value}, reason, scenario);
  const num = (path: string, unit: string, value: string, reason: string, scenario = top) => add(path, unit, {type: "number", value}, reason, scenario);
  const date = (path: string, value: string, reason: string, scenario = top) => add(path, "date", {type: "date", value}, reason, scenario);
  // Structure the reader receives as plain fields.
  date("readingDate", f.readingDate, house("Data da leitura adotada"));
  txt("headlineMeasurementId", "identity", f.headline.value, why(f.headline));
  list("order.limits", "identity", f.limits.map((l) => l.term.value.id), house("Ordem de leitura dos limites"));
  list("order.measurements", "identity", f.measurements.map((m) => m.value.id), house("Ordem de leitura das medições"));
  list("order.effects", "identity", f.effects.map((e) => e.value.id), house("Ordem de leitura dos efeitos"));
  for (const {term, definition} of f.limits) {
    const l = term.value, p = `limit.${l.id}.`;
    txt(p + "kind", "convention", l.kind, why(term));
    txt(p + "status", "convention", l.status, why(term));
    list(p + "testDates", "date", l.testDates, why(term));
    txt(p + "label", "text", l.label, why(term));
    num(p + "maximumRatio", "ratio", l.maximumRatio, why(term));
    txt(p + "source", "text", term.source, why(term));
    // An unwritten definition is asked, never assumed: the reason it is missing is adopted instead.
    if (definition.value === null) txt(p + "definitionGap", "explanation", definition.source, why(definition));
    else txt(p + "definition", "text", definition.value, why(definition));
  }
  for (const m of f.measurements) {
    const v = m.value, p = `measurement.${v.id}.`, sc = v.scenario, r = why(m);
    txt(p + "role", "convention", v.role, r, sc);
    txt(p + "label", "explanation", v.label, r, sc);
    list(p + "limitIds", "identity", v.limitIds, r, sc);
    list(p + "adjustmentIds", "identity", v.adjustments.map((a) => a.id), r, sc);
    date(p + "date", v.date, r, sc);
    num(p + "debt", "currency", v.debt, r, sc);
    num(p + "cash", "currency", v.cash, r, sc);
    num(p + "reportedEbitda", "currency", v.reportedEbitda, r, sc);
    for (const a of v.adjustments) {
      txt(p + `adjustment.${a.id}.label`, "text", a.label, r, sc);
      num(p + `adjustment.${a.id}.amount`, "currency", a.amount, r, sc);
    }
    if (v.unrealizedEbitda !== null) num(p + "unrealizedEbitda", "currency", v.unrealizedEbitda, r, sc);
  }
  for (const e of f.effects) {
    const v = e.value, p = `effect.${v.id}.`;
    txt(p + "label", "explanation", v.label, why(e));
    txt(p + "measurementId", "identity", v.measurementId, why(e));
    txt(p + "withoutEffectMeasurementId", "identity", v.withoutEffectMeasurementId, why(e));
  }
  const c = f.consequence;
  if (c.acceleration) txt("consequence.acceleration", "convention", c.acceleration.value, why(c.acceleration));
  if (c.process) txt("consequence.process", "text", c.process.value, why(c.process));
  if (c.crossDefault) txt("consequence.crossDefault", "text", c.crossDefault.value, why(c.crossDefault));
  // A working basis holds at most 256 premises; a set larger than that is refused here, not at confirmation.
  if (out.length > maxCovenantHeadroomHypotheses) throw new Error("covenant_headroom_premises_exceed_basis");
  return out;
}

import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {deterministicRunEvidenceFingerprint, type DeterministicMethodRun, type DeterministicMethodRunCase} from "@offroad/credit-playbook";
import {covenantHeadroomPacketOutputSchema, prepareCovenantHeadroomPacket, type CovenantHeadroomPacketInput} from "./covenant-headroom-packet";
import {auroraCovenantBasis} from "./covenant-headroom.test-support";

// Evaluation-only module; not exported to application consumers. All cases are synthetic
// calibrations of ficha C12 (modelo_c12.py), never production parameters.
const fingerprint = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const D = Decimal.clone({precision: 60});
const r = (v: string | null | undefined, p = 2) => v == null ? null : new D(v).toDecimalPlaces(p).toNumber();
type Case = DeterministicMethodRunCase;
type Evidence = Omit<DeterministicMethodRun, "schemaVersion" | "humanApproval" | "run">;
type Packet = ReturnType<typeof prepareCovenantHeadroomPacket>;
export const covenantHeadroomMethodVersion = "2026.10.23-v1";
export const covenantHeadroomRunIds = {
  gold: "measure-covenant-headroom-2026-10-23-v1-gold",
  adversarial: "measure-covenant-headroom-2026-10-23-v1-adversarial",
  consistency: "measure-covenant-headroom-2026-10-23-v1-consistency",
} as const;
const question = "Como estamos contra os covenants?";
type Options = Parameters<typeof auroraCovenantBasis>[0];
type Basis = ReturnType<typeof auroraCovenantBasis>;
const packetInput = (o: Options = {}, edit: (f: Basis) => void = () => undefined): CovenantHeadroomPacketInput => {
  const f = auroraCovenantBasis(o); edit(f);
  return {schemaVersion: "covenant-headroom-packet-input.v1", question, headlineMeasurementId: "dez26-base", analysis: f.seal()} as CovenantHeadroomPacketInput;
};
function observe(id: string, input: CovenantHeadroomPacketInput, expected: unknown, select: (p: Packet) => unknown): Case {
  const result = prepareCovenantHeadroomPacket(input), observed = JSON.stringify(select(result)), expectation = JSON.stringify(expected);
  return {id, expectation, observed, inputFingerprint: fingerprint(input), outputFingerprint: fingerprint(result), passed: expectation === observed};
}
const at = (p: Packet, id: string) => p.result.headroom!.measurements.find((m) => m.id === id)!;
const test = (p: Packet, id: string, limit: string) => at(p, id).tests.find((t) => t.limitId === limit)!;

function goldCases(): Case[] {
  const base = () => packetInput(), packet = prepareCovenantHeadroomPacket(base());
  const reuse = (id: string, expected: unknown, select: (p: Packet) => unknown): Case => {
    const observed = JSON.stringify(select(packet)), expectation = JSON.stringify(expected);
    return {id, expectation, observed, inputFingerprint: fingerprint(base()), outputFingerprint: fingerprint(packet), passed: expectation === observed};
  };
  return [
    // Expectations come from the independent Python oracle (outputs/fichas-ensaio-2026-10/C12/resultados.json) and the ficha's answer key.
    reuse("december-by-the-indenture-definition", {netDebt: 113.2, ebitda: 51.5, ratio: 2.2},
      (p) => ({netDebt: r(at(p, "dez26-base").netDebt, 1), ebitda: r(at(p, "dez26-base").ebitda, 1), ratio: r(at(p, "dez26-base").ratio)})),
    reuse("headroom-in-ebitda-and-net-debt-to-the-covenant", {ebitda: 13.76, netDebt: 41.29},
      (p) => ({ebitda: r(test(p, "dez26-base", "aditamento").ebitdaHeadroom), netDebt: r(test(p, "dez26-base", "aditamento").netDebtHeadroom)})),
    reuse("reverse-test-on-the-unrealized-second-half", {covenant: 52.9, policy: 23.9},
      (p) => ({covenant: r(new D(test(p, "dez26-base", "aditamento").unrealizedEbitdaLossToLimit!).mul(100).toFixed(), 1),
        policy: r(new D(test(p, "dez26-base", "politica").unrealizedEbitdaLossToLimit!).mul(100).toFixed(), 1)})),
    reuse("board-policy-binds-first", {tightest: "politica", headroom: 6.22, policyBindsFirst: true},
      (p) => ({tightest: p.readings!.headline.tightestLimitId, headroom: r(test(p, "dez26-base", "politica").ebitdaHeadroom), policyBindsFirst: p.readings!.policyBindsFirst})),
    reuse("adverse-case-in-december", 2.32, (p) => r(at(p, "dez26-adverso").ratio)),
    reuse("a-larger-season-in-december", {ratio: 2.3, policyHeadroom: 4.2}, (p) => ({ratio: r(at(p, "dez26-safra-30").ratio), policyHeadroom: r(test(p, "dez26-safra-30", "politica").ebitdaHeadroom, 1)})),
    reuse("season-weighs-half-a-turn-at-the-test-date", 0.5, (p) => r(p.result.headroom!.effects[0]!.ratioEffect, 1)),
    reuse("december-2027-base-and-adverse", {base: 1.85, adverse: 2.37, policyHeadroom: 2.33, worst: ["dez27-adverso", "politica"]},
      (p) => ({base: r(at(p, "dez27-base").ratio), adverse: r(at(p, "dez27-adverso").ratio), policyHeadroom: r(test(p, "dez27-adverso", "politica").ebitdaHeadroom),
        worst: [p.readings!.worst!.measurementId, p.readings!.worst!.limitId]})),
    reuse("managerial-june-reading-is-a-contrast", {ratio: 1.73, role: "contrast"}, (p) => ({ratio: r(at(p, "junho-gerencial").ratio), role: at(p, "junho-gerencial").role})),
    reuse("original-indenture-limit-is-superseded", {headroom: 10.33, role: "contrast"},
      (p) => ({headroom: r(test(p, "dez26-escritura-original", "original").ebitdaHeadroom), role: at(p, "dez26-escritura-original").role})),
    reuse("breach-is-not-automatic-and-the-chain-is-named", {acceleration: "non_automatic", process: true, crossDefault: true},
      (p) => ({acceleration: p.result.consequence.acceleration, process: !!p.result.consequence.process, crossDefault: !!p.result.consequence.crossDefault})),
    reuse("unwritten-policy-definition-is-a-question", {open: ["politica"], status: "partial"}, (p) => ({open: p.readings!.openQuestions, status: p.status})),
    observe("turn-two-policy-on-managerial-ebitda", packetInput({policyDefinition: "EBITDA gerencial: CVM 156 com ajustes da gestão, sem descontar arrendamentos", policyOnManagerial: true}),
      {ratio: 2.04, policyHeadroom: 10.2, policyBindsFirst: true, status: "prepared_for_human_review"},
      (p) => ({ratio: r(at(p, "dez26-politica-gerencial").ratio), policyHeadroom: r(test(p, "dez26-politica-gerencial", "politica").ebitdaHeadroom, 1),
        policyBindsFirst: p.readings!.policyBindsFirst, status: p.status})),
    (() => {
      const i = packetInput({policyDefinition: "EBITDA da escritura"});
      const cash = i.analysis.measurements[0]!.cash as {decisionId: string | null; missingReason: string | null};
      i.analysis.measurements[0]!.cash = {...cash, decisionId: null, missingReason: "Caixa de dezembro não projetado"} as typeof i.analysis.measurements[0]["cash"];
      return observe("absent-cash-is-a-gap-not-a-default", i, {status: "framed", gap: true},
        (p) => ({status: p.status, gap: p.gaps.some((g) => g.reason === "Caixa de dezembro não projetado")}));
    })(),
  ];
}

function adversarialCases(): Case[] {
  const attempts: [string, () => unknown, string][] = [
    ["tampered-envelope", () => {const i = packetInput(); i.analysis.envelope = {...i.analysis.envelope, canonical: i.analysis.envelope.canonical.replace('"54.5"', '"64.5"')}; return i;}, "adoption_basis_integrity_mismatch"],
    ["free-result-in-request", () => ({...packetInput(), headroom: {ratio: "1"}}), "Unrecognized key"],
    ["fabricated-grant-in-result", () => ({forge: true}), "grantsExecution"],
    ["headline-is-a-contrast", () => ({...packetInput(), headlineMeasurementId: "junho-gerencial"}), "headline must be a test measurement"],
    ["measurement-names-unknown-limit", () => {const i = packetInput(); i.analysis.measurements[0] = {...i.analysis.measurements[0]!, limitIds: ["inventado"]}; return i;}, "covenant_unknown_limit"],
    ["effect-across-dates", () => {const i = packetInput(); i.analysis.effects[0] = {...i.analysis.effects[0]!, withoutEffectMeasurementId: "dez27-base"}; return i;}, "covenant_effect_on_other_date"],
    ["test-without-limit", () => {const i = packetInput(); i.analysis.measurements[1] = {...i.analysis.measurements[1]!, limitIds: []}; return i;}, "covenant_test_without_limit"],
    ["unrealized-after-the-test-date", () => ({...packetInput(), analysis: {...packetInput().analysis, readingDate: "2027-01-10"}}), "covenant_unrealized_after_test_date"],
    ["duplicate-measurement", () => {const i = packetInput(); i.analysis.measurements[1] = {...i.analysis.measurements[1]!, id: "dez26-base"}; return i;}, "Duplicate measurement"],
    ["managerial-june-promoted-to-a-test", () => {const i = packetInput(); i.analysis.measurements = i.analysis.measurements.map((m) => m.id === "junho-gerencial" ? {...m, role: "test" as const, limitIds: ["aditamento"]} : m); return i;}, "covenant_test_off_the_test_date"],
    ["superseded-limit-promoted-to-a-test", () => {const i = packetInput(); i.analysis.measurements = i.analysis.measurements.map((m) => m.id === "dez26-escritura-original" ? {...m, role: "test" as const} : m); return i;}, "covenant_superseded_limit_in_test"],
    ["policy-dropped-from-every-test", () => {const i = packetInput(); i.analysis.measurements = i.analysis.measurements.map((m) => ({...m, limitIds: m.limitIds.filter((id) => id !== "politica")})); return i;}, "covenant_limit_in_force_not_tested"],
    ["figure-read-in-another-scenario", () => packetInput({}, (f) => {f.entries.find((x) => x.fieldPath.endsWith("measurement.dez27-adverso.cash"))!.dimensions.scenario = "base_2028";}), "analysis_basis_context_mismatch"],
  ];
  return attempts.map(([id, build, message]) => {
    let observed: string, passed: boolean, input: unknown;
    try {
      input = build();
      if ((input as {forge?: boolean}).forge) covenantHeadroomPacketOutputSchema.parse({...prepareCovenantHeadroomPacket(packetInput()), grantsExecution: true});
      else prepareCovenantHeadroomPacket(input);
      observed = "accepted"; passed = false;
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      passed = detail.includes(message); observed = passed ? "rejected by expected boundary" : `unexpected error: ${detail.slice(0, 250)}`;
    }
    return {id, expectation: "rejected by expected boundary", observed, inputFingerprint: fingerprint(input ?? null), outputFingerprint: fingerprint({observed}), passed};
  });
}

function consistencyCases(): Case[] {
  return [packetInput(), packetInput({policyDefinition: "EBITDA gerencial", policyOnManagerial: true})].flatMap((input, fixtureIndex) => {
    const before = fingerprint(input), first = prepareCovenantHeadroomPacket(input);
    return Array.from({length: 3}, (_, repeat) => {
      const result = prepareCovenantHeadroomPacket(JSON.parse(JSON.stringify(input)));
      const passed = fingerprint(result) === fingerprint(first) && fingerprint(input) === before;
      return {id: `fixture-${fixtureIndex + 1}-repeat-${repeat + 1}`, expectation: "same inputs and versions reproduce all output bytes without mutation",
        observed: passed ? "same inputs and versions reproduce all output bytes without mutation" : "output or input changed", inputFingerprint: before, outputFingerprint: fingerprint(result), passed};
    });
  });
}

export function buildCovenantHeadroomRuns(): Evidence[] {
  return ([{kind: "gold", cases: goldCases()}, {kind: "adversarial", cases: adversarialCases()}, {kind: "consistency", cases: consistencyCases()}] as const).map(({kind, cases}) => {
    const evidence = {runId: covenantHeadroomRunIds[kind], kind, method: {id: "measure-covenant-headroom", version: covenantHeadroomMethodVersion},
      executor: {module: "@offroad/financial-model", exportName: "prepareCovenantHeadroomPacket"},
      harness: {module: "@offroad/financial-model/src/covenant-headroom-runs.test-support.ts", exportName: "buildCovenantHeadroomRuns"},
      modelCalls: 0 as const, cases, result: cases.every((c) => c.passed) ? "pass" as const : "fail" as const};
    return {...evidence, evidenceFingerprint: deterministicRunEvidenceFingerprint(evidence),
      notes: "Synthetic deterministic execution calibrated on ficha C12. Numerical expectations do not constitute independent review, content approval, live access verification or publication."};
  });
}

