    executor: {module: "@offroad/financial-model", exportName: "prepareDebtCapacityPacket", version: debtCapacityPacketVersion},
    inputs: methodDataContractFromJsonSchema("debt-capacity-packet-input", debtCapacityPacketVersion, inputSchema),
    outputs: methodDataContractFromJsonSchema("debt-capacity-packet-output", debtCapacityPacketVersion, outputSchema),
    validationSchemas: {input: inputSchema, output: outputSchema}};
}

import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {z} from "zod";
import {financialCoreVersion, projectDebtCapacityAmount, type DebtCapacityInput} from "@offroad/financial-core";
import {adoptedDebtCapacityInputSchema, calculateAdoptedDebtCapacity} from "./adopted-debt-capacity";

export const debtCapacityPacketVersion = "2026.10.19-v1";
const Exact = Decimal.clone({precision: 60, rounding: Decimal.ROUND_HALF_UP});
const text = z.string().trim().min(1).max(2000), key = z.string().trim().min(1).max(160);
const decimal = z.string().regex(/^-?\d{1,30}(?:\.\d{1,40})?$/), hash = z.string().regex(/^[a-f0-9]{64}$/);
const fmt = (v: Decimal) => v.toDecimalPlaces(20).toFixed();
const roles = ["informed", "alternative"] as const;

/** One capacity question over one adopted basis: the schedule as informed and its alternatives
 * (phasing, another structure), each a complete adopted analysis. Limits name the adopted rules
 * that make each restriction, so the binding one is identified; nothing here supplies a number. */
export const debtCapacityPacketInputSchema = z.strictObject({
  schemaVersion: z.literal("debt-capacity-packet-input.v1"),
  question: text,
  cases: z.array(z.strictObject({
    id: key, role: z.enum(roles), label: text, changes: z.array(text).max(20),
    analysis: adoptedDebtCapacityInputSchema,
    limits: z.array(z.strictObject({id: key, label: text, ruleIds: z.array(z.uuid()).min(1).max(12)})).min(1).max(8),
  })).min(1).max(6),
}).superRefine((input, ctx) => {
  const fail = (message: string) => ctx.addIssue({code: "custom", message});
  if (input.cases.filter((c) => c.role === "informed").length !== 1) fail("Exactly one informed case is required");
  if (new Set(input.cases.map((c) => c.id)).size !== input.cases.length) fail("Duplicate case identity");
  if (new Set(input.cases.map((c) => c.analysis.analysisId)).size !== input.cases.length) fail("Each case needs its own adopted analysis");
  const first = input.cases[0]!.analysis;
  for (const c of input.cases) {
    const a = c.analysis;
    if (a.envelope.fingerprint !== first.envelope.fingerprint || a.scope.versionId !== first.scope.versionId || a.entityId !== first.entityId || a.currency !== first.currency)
      fail("All cases must read the same adopted basis, entity and currency");
    if (c.role === "informed" && c.changes.length) fail("The informed case declares no changes");
    if (c.role !== "informed" && !c.changes.length) fail("An alternative must say what it changes");
    const rules = new Set(a.scenarios.flatMap((s) => s.rules.map((r) => r.id)));
    const named = c.limits.flatMap((l) => l.ruleIds);
    if (named.some((r) => !rules.has(r))) fail("A limit names a rule the analysis does not carry");
    if (new Set(named).size !== named.length || named.length !== rules.size) fail("Every adopted rule belongs to exactly one limit");
  }
});
export type DebtCapacityPacketInput = z.infer<typeof debtCapacityPacketInputSchema>;

const extreme = z.strictObject({value: decimal, date: z.iso.date()});
const scenarioReading = z.strictObject({scenarioId: z.uuid(), peakLeverage: extreme, minimumCash: extreme, minimumInterestCoverage: extreme.nullable()});
const caseOutput = z.strictObject({
  caseId: key, role: z.enum(roles), label: text, changes: z.array(text).max(20), resultStatus: z.enum(["missing_inputs", "partial_composition"]),
  limits: z.array(z.strictObject({id: key, label: text, capacity: decimal.nullable(), status: key.nullable()})).max(8),
  /** The joint capacity: the largest amount that satisfies every adopted rule at once, as the engine
   * intersects them (never the smallest of the per-limit maxima, which can overstate it). */
  capacity: decimal.nullable(), capacityStatus: z.enum(["calculated", "calibration_only", "no_feasible_amount"]).nullable(),
  /** What stops the next quantum: the limit, the date and the scenario of the first failing check. */
  binding: z.strictObject({limitId: key, date: z.iso.date(), scenarioId: z.uuid()}).nullable(), bindingLimitId: key.nullable(),
  boundedBySearchDomain: z.boolean().nullable(), calibrationOnly: z.boolean().nullable(),
  review: z.strictObject({amount: decimal, fits: z.boolean(), failingLimitIds: z.array(key).max(8), scenarios: z.array(scenarioReading).max(4)}).nullable(),
  plan: z.array(z.strictObject({date: z.iso.date(), scheduledExistingPrincipal: decimal, cashAfterInterest: decimal, paysWithoutRefinancing: z.boolean()})).max(240).nullable(),
  gaps: z.array(z.strictObject({operand: text, reason: text})).max(1024),
});
export const debtCapacityPacketOutputSchema = z.strictObject({
  schemaVersion: z.literal("debt-capacity-packet.v1"), executorVersion: z.literal(debtCapacityPacketVersion), financialCoreVersion: key,
  question: text, basisFingerprint: hash, scope: adoptedDebtCapacityInputSchema.shape.scope, entityId: z.uuid(), currency: z.string().regex(/^[A-Z]{3}$/),
  cases: z.array(caseOutput).min(1).max(6),
  comparison: z.strictObject({informedCaseId: key, requestedFitsIn: z.array(key).max(6), largestCapacityCaseId: key.nullable()}),
  status: z.enum(["framed", "partial", "prepared_for_human_review"]),
  exclusions: z.array(z.enum(["credit_approval", "nonlinear_pricing", "intraperiod_cash_certification", "investment_return", "method_release"])).length(5)
    .refine((v) => v.join("|") === "credit_approval|nonlinear_pricing|intraperiod_cash_certification|investment_return|method_release", "Exact exclusion ledger required"),
  grantsExecution: z.literal(false), grantsPublication: z.literal(false), fingerprint: hash,
});
export type DebtCapacityPacket = z.infer<typeof debtCapacityPacketOutputSchema>;

type Row = {date: string; ebitda: string; covenantEbitda: string; cashInterest: string; cfads: string; closingAvailableCash: string; closingDebt: string};
const pick = (rows: Row[], value: (r: Row) => Decimal | null, lowest: boolean) => rows.reduce<{value: Decimal; date: string} | null>((m, r) => {
  const v = value(r); if (v === null) return m;
  return m === null || (lowest ? v.lt(m.value) : v.gt(m.value)) ? {value: v, date: r.date} : m;
}, null);

/** How much new debt fits and with what profile: the largest amount under each adopted limit and
 * the one that binds, for the schedule as informed and its alternatives; the requested amount
 * reviewed on peak leverage, minimum cash and interest coverage by date in every scenario; and
 * whether the existing plan's scheduled principal is paid by cash after interest without
 * refinancing. Deterministic; the investment's own return is a separate method. */
export function prepareDebtCapacityPacket(raw: unknown): DebtCapacityPacket {
  const input = debtCapacityPacketInputSchema.parse(raw);
  const cases = input.cases.map((c) => {
    const full = calculateAdoptedDebtCapacity(c.analysis);
    const limits = c.limits.map((l) => {
      const subset = {...c.analysis, scenarios: c.analysis.scenarios.map((s) => ({...s, rules: s.rules.filter((r) => l.ruleIds.includes(r.id))})).filter((s) => s.rules.length)};
      const r = calculateAdoptedDebtCapacity(subset) as {capacity: {maximumFeasibleAmount: string | null; status: string} | null};
      return {id: l.id, label: l.label, capacity: r.capacity?.maximumFeasibleAmount ?? null, status: r.capacity?.status ?? null};
    });
    const joint = full.capacity as {status: "calculated" | "calibration_only" | "no_feasible_amount"; maximumFeasibleAmount: string | null; boundedBySearchDomain: boolean;
      followingChecks: {ruleId: string; passed: boolean; date: string; scenarioId: string}[] | null} | null;
    const stop = joint?.followingChecks?.find((x) => !x.passed) ?? null;
    const limitOf = (ruleId: string) => c.limits.find((l) => l.ruleIds.includes(ruleId))!.id;
    const binding = stop ? {limitId: limitOf(stop.ruleId), date: stop.date, scenarioId: stop.scenarioId} : null;
    const profile = full.profile as DebtCapacityInput | null;
    const fixed = full.fixedReview as {amount: string; checks: {ruleId: string; passed: boolean}[]; financialRows: {scenarioId: string; rows: Row[]}[]} | null;
    const review = fixed ? {amount: fixed.amount, fits: fixed.checks.every((x) => x.passed),
      failingLimitIds: c.limits.filter((l) => fixed.checks.some((x) => !x.passed && l.ruleIds.includes(x.ruleId))).map((l) => l.id),
      scenarios: fixed.financialRows.map((s) => {
        // Leverage nets cash under each scenario's adopted convention, as the kernel's covenant does.
        const nonnegative = profile?.scenarios.find((x) => x.id === s.scenarioId)?.cashNetting === "nonnegative_available";
        const leverage = pick(s.rows, (r) => new Exact(r.covenantEbitda).gt(0)
          ? new Exact(r.closingDebt).minus(nonnegative ? Exact.max(r.closingAvailableCash, 0) : new Exact(r.closingAvailableCash)).div(r.covenantEbitda) : null, false)!;
        const cash = pick(s.rows, (r) => new Exact(r.closingAvailableCash), true)!;
        const coverage = pick(s.rows, (r) => new Exact(r.cashInterest).gt(0) ? new Exact(r.ebitda).div(r.cashInterest) : null, true);
        return {scenarioId: s.scenarioId, peakLeverage: {value: fmt(leverage.value), date: leverage.date}, minimumCash: {value: fmt(cash.value), date: cash.date},
          minimumInterestCoverage: coverage ? {value: fmt(coverage.value), date: coverage.date} : null};
      })} : null;
    // The plan as it stands, with no new debt: scheduled principal against cash after interest in the first scenario.
    const plan = profile ? (() => {
      const zero = projectDebtCapacityAmount(profile, "0"), s = profile.scenarios[0]!, rows = zero.financialRows[0]!.rows as Row[];
      return s.periods.map((p, i) => {
        const after = new Exact(rows[i]!.cfads).minus(rows[i]!.cashInterest);
        return {date: p.endDate, scheduledExistingPrincipal: fmt(new Exact(p.existingCashPrincipalPaid)), cashAfterInterest: fmt(after), paysWithoutRefinancing: after.gte(p.existingCashPrincipalPaid)};
      });
    })() : null;
    return {caseId: c.id, role: c.role, label: c.label, changes: c.changes, resultStatus: full.status, limits,
      capacity: joint?.maximumFeasibleAmount ?? null, capacityStatus: joint?.status ?? null, binding, bindingLimitId: binding?.limitId ?? null,
      boundedBySearchDomain: joint ? joint.boundedBySearchDomain : null, calibrationOnly: joint ? joint.status === "calibration_only" : null, review, plan, gaps: full.gaps};
  });
  const informed = cases.find((c) => c.role === "informed")!;
  const first = input.cases[0]!.analysis;
  const withCapacity = cases.filter((c) => c.capacity !== null);
  const status = informed.capacityStatus === null ? "framed" as const : cases.some((c) => c.gaps.length) ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "debt-capacity-packet.v1" as const, executorVersion: debtCapacityPacketVersion, financialCoreVersion,
    question: input.question, basisFingerprint: first.envelope.fingerprint, scope: first.scope, entityId: first.entityId, currency: first.currency,
    cases, comparison: {informedCaseId: informed.caseId, requestedFitsIn: cases.filter((c) => c.review?.fits).map((c) => c.caseId),
      largestCapacityCaseId: withCapacity.length ? withCapacity.reduce((m, c) => (new Exact(c.capacity!).gt(m.capacity!) ? c : m)).caseId : null},
    status, exclusions: ["credit_approval", "nonlinear_pricing", "intraperiod_cash_certification", "investment_return", "method_release"] as const,
    grantsExecution: false as const, grantsPublication: false as const};
  return debtCapacityPacketOutputSchema.parse({...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")});
}

import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {z} from "zod";
import type {ProposedHypothesis} from "./investment-premises";

const Exact = Decimal.clone({precision: 80, rounding: Decimal.ROUND_HALF_UP});
const text = z.string().trim().min(1).max(2000);
const key = z.string().regex(/^[a-z0-9][a-z0-9-]{0,39}$/);
const amount = z.string().regex(/^\d{1,24}(?:\.\d{1,20})?$/);
const signed = z.string().regex(/^-?\d{1,24}(?:\.\d{1,20})?$/);
/** Money carries at most eight decimals, as the adopted numeric representation reads it. */
const money = z.string().regex(/^-?\d{1,24}(?:\.\d{1,8})?$/);
const ratio = z.string().regex(/^-?\d{1,4}(?:\.\d{1,20})?$/);
const share = z.string().regex(/^(?:0(?:\.\d{1,20})?|1(?:\.0{1,20})?)$/);
const origins = ["document", "informed", "house", "estimate"] as const;
const originLabel: Record<(typeof origins)[number], string> = {document: "documento", informed: "informado", house: "premissa da casa", estimate: "estimativa"};
/** A value and where it came from; the source names the document, the message or the house rule. */
const fact = <T extends z.ZodType>(value: T) => z.strictObject({value, origin: z.enum(origins), source: text});
const series = z.array(money).min(1).max(40);
const s20 = (v: Decimal) => v.toDecimalPlaces(20).toFixed();
const s8 = (v: Decimal) => v.toDecimalPlaces(8).toFixed();

/** One way of spending the use the new debt finances: when it is spent and what it brings. All
 * series are per period of the projection; the project's figures are its own, not the company's. */
const projectCase = z.strictObject({
  id: key, role: z.enum(["informed", "alternative"]), label: text, changes: z.array(text).max(20),
  capex: series, ebitda: series, depreciation: series, maintenanceCapex: series, workingCapitalInvestment: series,
});
const limit = z.strictObject({
  id: key, label: text, kind: z.enum(["maximum_net_debt_to_ebitda", "minimum_interest_coverage", "minimum_available_cash"]),
  /** The threshold in the company's case; in the adverse case only when the limit applies there too. */
  base: signed, adverse: signed.nullable(),
});

/** The facts of one capacity question, each with its origin. Nothing here is adopted until a person
 * confirms the set; every number the method reads comes from the adopted basis, not from this object.
 * Periods are the projection's (annual by default) and money is in the company's currency units. */
export const debtCapacityFactsSchema = z.strictObject({
  capacityId: z.uuid(), entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/), definitionVersionId: z.uuid(),
  openingDate: z.iso.date(), periodEnds: z.array(z.iso.date()).min(2).max(40),
  company: z.strictObject({
    openingAvailableCash: fact(money), ebitda: fact(series), leasePayments: fact(series), depreciation: fact(series),
    maintenanceCapex: fact(series), workingCapitalInvestment: fact(series), cashTaxRate: fact(share),
    /** The covenant's EBITDA excludes lease payments (pre-IFRS 16), as the indenture defines it. */
    covenantEbitdaExcludesLeases: fact(z.boolean()),
  }),
  /** The debt in place with its plan: closing balance as the covenant counts it, scheduled principal and cash interest. */
  existingDebt: fact(z.strictObject({closingDebt: series, principalPaid: series, cashInterest: series, finalPaymentDates: z.array(z.iso.date()).max(40)})),
  /** The informed use and at most one alternative: a working basis holds 256 premises and each schedule
   * carries a complete analysis in both scenarios. */
  cases: z.array(fact(projectCase)).min(1).max(2),
  /** The structure of the new debt: all-in annual rate per period, share of principal repaid at each period end, last payment. */
  structure: fact(z.strictObject({label: text, annualRate: z.array(ratio).min(1).max(40), amortizationShares: z.array(ratio).min(1).max(40), finalPaymentDate: z.iso.date()})),
  limits: z.array(fact(limit)).min(1).max(4),
  stress: z.strictObject({ebitdaShock: fact(share)}),
  /** The amount asked for, reviewed on every limit; absent, only the capacity is measured. */
  requestedAmount: fact(amount).nullable(),
  /** Search resolution of the capacity, in currency units. */
  monetaryQuantum: fact(amount),
}).superRefine((f, ctx) => {
  const n = f.periodEnds.length, fail = (message: string) => ctx.addIssue({code: "custom", message});
  if (f.periodEnds.some((d, i) => d <= (i ? f.periodEnds[i - 1]! : f.openingDate))) fail("Period ends must be increasing after the opening date");
  for (const k of ["ebitda", "leasePayments", "depreciation", "maintenanceCapex", "workingCapitalInvestment"] as const)
    if (f.company[k].value.length !== n) fail(`Company ${k} must have one value per period`);
  for (const k of ["closingDebt", "principalPaid", "cashInterest"] as const) if (f.existingDebt.value[k].length !== n) fail(`Existing debt ${k} must have one value per period`);
  const st = f.structure.value;
  if (st.annualRate.length !== n || st.amortizationShares.length !== n) fail("Structure must have one rate and one repayment share per period");
  // The shares repay the debt once, never more; a schedule that leaves principal after the horizon is a calibration window.
  if (st.amortizationShares.some((x) => new Exact(x).lt(0)) || st.amortizationShares.reduce((t, x) => t.plus(x), new Exact(0)).gt(1)) fail("Repayment shares must be non-negative and add up to at most one");
  if (new Set(f.cases.map((c) => c.value.id)).size !== f.cases.length || f.cases.filter((c) => c.value.role === "informed").length !== 1) fail("Exactly one informed case and unique case ids");
  for (const c of f.cases) {
    const v = c.value;
    for (const k of ["capex", "ebitda", "depreciation", "maintenanceCapex", "workingCapitalInvestment"] as const) if (v[k].length !== n) fail(`Case ${v.id} ${k} must have one value per period`);
    if (v.capex.some((x) => new Exact(x).lt(0)) || !v.capex.reduce((t, x) => t.plus(x), new Exact(0)).gt(0)) fail(`Case ${v.id} needs a positive use to finance`);
    if (v.role === "informed" && v.changes.length) fail("The informed case declares no changes");
    if (v.role === "alternative" && !v.changes.length) fail("An alternative must say what it changes");
  }
  if (new Set(f.limits.map((l) => l.value.id)).size !== f.limits.length) fail("Duplicate limit");
  // The adverse scenario is a scenario only when some limit applies there.
  if (f.limits.every((l) => l.value.adverse === null)) fail("At least one limit must apply in the adverse case");
});
export type DebtCapacityFacts = z.infer<typeof debtCapacityFactsSchema>;

/** RFC 4122 version 5 identity under the URL namespace, so a confirmation is reproducible. */
export function capacityUuid(name: string) {
  const ns = Buffer.from("6ba7b8119dad11d180b400c04fd430c8", "hex");
  const h = createHash("sha1").update(Buffer.concat([ns, Buffer.from(name, "utf8")])).digest();
  h[6] = (h[6]! & 0x0f) | 0x50; h[8] = (h[8]! & 0x3f) | 0x80;
  const x = h.subarray(0, 16).toString("hex");
  return `${x.slice(0, 8)}-${x.slice(8, 12)}-${x.slice(12, 16)}-${x.slice(16, 20)}-${x.slice(20)}`;
}
export const capacityAnalysisId = (capacityId: string, caseId: string) => capacityUuid(`offroad:capacity:${capacityId}:case:${caseId}`);
const ruleId = (capacityId: string, caseId: string, limitId: string, stressed: boolean) => capacityUuid(`offroad:capacity:${capacityId}:case:${caseId}:limit:${limitId}:${stressed ? "adverse" : "base"}`);
const scenarioId = (capacityId: string, caseId: string, stressed: boolean) => capacityUuid(`offroad:capacity:${capacityId}:case:${caseId}:scenario:${stressed ? "adverse" : "base"}`);

/** The hypotheses one confirmation adopts: for each case (as informed and each alternative) a
 * complete capacity analysis with the company's case and the adverse case, which changes only the
 * EBITDA the stress names. The new debt finances the case's use and is drawn as it is spent; its
 * interest uses the annual average-balance approximation the method declares. Every reason states
 * the origin of the number. Deterministic; nothing is calculated here. */
/** The size of one working basis. */
export const maxCapacityHypotheses = 256;
export function proposeDebtCapacityHypotheses(raw: unknown): ProposedHypothesis[] {
  const f = debtCapacityFactsSchema.parse(raw);
  const out: ProposedHypothesis[] = [], n = f.periodEnds.length, endDate = f.periodEnds[n - 1]!;
  const why = (x: {origin: (typeof origins)[number]; source: string}, extra = "") => `Origem: ${originLabel[x.origin]}. ${x.source}${extra ? ` ${extra}` : ""}`;
  const house = (source: string) => `Origem: premissa da casa. ${source}`;
  const cite = (parts: [string, {origin: (typeof origins)[number]; source: string}][]) => `Origem: ${parts.map(([name, x]) => `${name}, ${originLabel[x.origin]} (${x.source})`).join("; ")}.`;
  const co = f.company, debt = f.existingDebt, st = f.structure.value, keepFactor = new Exact(1).minus(f.stress.ebitdaShock.value);
  const D = (v: string) => new Exact(v);
  const lastPayment = [st.finalPaymentDate, ...debt.value.finalPaymentDates].sort().at(-1)!;
  // Full settlement only when the projection reaches the last payment and the debt in place ends it at zero;
  // a revolving line still open at the end leaves the capacity valid for the projected window.
  const horizonMode = endDate >= lastPayment && new Exact(debt.value.closingDebt[n - 1]!).isZero() ? "full_settlement" : "calibration_window";
  for (const c of f.cases) {
    const v = c.value, aid = capacityAnalysisId(f.capacityId, v.id), prefix = `debt_capacity.${aid}.`;
    const total = v.capex.reduce((t, x) => t.plus(x), new Exact(0));
    const perUnit = (xs: string[]) => xs.map((x) => s20(D(x).div(total)));
    const add = (path: string, unit: string, value: ProposedHypothesis["value"], reason: string, scenario: string) => out.push({fieldPath: prefix + path,
      dimensions: {entityId: f.entityId, perimeter: f.perimeter, periodStart: f.openingDate, periodEnd: endDate, currency: f.currency, unit, scale: "1", scenario, definitionVersionId: f.definitionVersionId},
      value, reason});
    const list = (path: string, unit: string, values: string[], reason: string, scenario: string) => add(path, unit, {type: "list", value: values}, reason, scenario);
    const num = (path: string, unit: string, value: string, reason: string, scenario: string) => add(path, unit, {type: "number", value}, reason, scenario);
    const txt = (path: string, unit: string, value: string, reason: string, scenario: string) => add(path, unit, {type: "text", value}, reason, scenario);
    const top = `${v.id}:base`;
    // The case: its role, label and what it changes, so the packet is composed from the basis alone.
    txt("case.role", "convention", v.role, why(c), top);
    txt("case.label", "explanation", v.label, why(c), top);
    list("case.changes", "explanation", v.changes, why(c), top);
    // The search: up to five times the use, at the adopted resolution.
    num("maximumAmount", "currency", s8(total.times(5)), house("Busca da capacidade até cinco vezes o uso a financiar"), top);
    num("monetaryQuantum", "currency", f.monetaryQuantum.value, why(f.monetaryQuantum), top);
    if (f.requestedAmount) num("fixedReviewAmount", "currency", f.requestedAmount.value, why(f.requestedAmount), top);
    txt("horizonMode", "convention", horizonMode, house(horizonMode === "full_settlement"
      ? "A projeção cobre o último pagamento de toda a dívida" : "A projeção termina com dívida em aberto; a capacidade vale para a janela projetada"), top);
    add("newDebtFinalPaymentDate", "date", {type: "date", value: st.finalPaymentDate}, why(f.structure), top);
    list("existingDebtFinalPaymentDates", "date", debt.value.finalPaymentDates, why(debt), top);
    // Each limit names the adopted rules that make it, so the binding one is identified.
    for (const l of f.limits) {
      txt(`limit.${l.value.id}.label`, "explanation", l.value.label, why(l), top);
      list(`limit.${l.value.id}.ruleIds`, "identity", [false, true].flatMap((stressed) => (stressed ? l.value.adverse : l.value.base) === null ? [] : [ruleId(f.capacityId, v.id, l.value.id, stressed)]), why(l), top);
    }
    for (const stressed of [false, true]) {
      const sid = scenarioId(f.capacityId, v.id, stressed), sc = `${v.id}:${stressed ? "adverse" : "base"}`, p = `scenario.${sid}.`;
      const keep = stressed ? keepFactor : new Exact(1);
      const shock = stressed ? ` ${cite([["choque do caso adverso", f.stress.ebitdaShock]])}` : "";
      list(p + "periodEnds", "date", f.periodEnds, house("Períodos da projeção adotada"), sc);
      num(p + "openingAvailableCash", "currency", co.openingAvailableCash.value, why(co.openingAvailableCash), sc);
      txt(p + "cashNetting", "convention", "signed_available", house("Caixa disponível descontado da dívida com o sinal que tiver"), sc);
      add(p + "includeNewAccruedInterestInDebt", "convention", {type: "boolean", value: false}, house("Juros da dívida nova pagos no período, sem acúmulo"), sc);
      const pair = (name: string, fixed: string[], unit: string[], reason: string) => {
        list(p + name + ".fixed", "currency", fixed, reason, sc);
        list(p + name + ".perUnitNewDebt", "ratio", unit, reason, sc);
      };
      const ebitda = co.ebitda.value.map((x) => s8(D(x).times(keep)));
      pair("ebitda", ebitda, v.ebitda.map((x) => s20(D(x).times(keep).div(total))), cite([["EBITDA da companhia", co.ebitda], ["EBITDA do projeto", c]]) + shock);
      pair("covenantEbitdaAdjustment", co.leasePayments.value.map((x) => co.covenantEbitdaExcludesLeases.value ? s8(D(x).neg()) : "0"), f.periodEnds.map(() => "0"),
        cite([["definição do EBITDA do covenant", co.covenantEbitdaExcludesLeases], ["arrendamentos pagos", co.leasePayments]]));
      pair("nonCashEbitdaBridge", f.periodEnds.map(() => "0"), f.periodEnds.map(() => "0"), house("Sem ajuste não caixa entre o EBITDA e o caixa operacional"));
      pair("cashLeasePayments", co.leasePayments.value, f.periodEnds.map(() => "0"), why(co.leasePayments));
      pair("changeInWorkingCapital", co.workingCapitalInvestment.value, perUnit(v.workingCapitalInvestment), cite([["capital de giro da companhia", co.workingCapitalInvestment], ["capital de giro do projeto", c]]));
      pair("maintenanceCapex", co.maintenanceCapex.value, perUnit(v.maintenanceCapex), cite([["manutenção da companhia", co.maintenanceCapex], ["manutenção do projeto", c]]));
      pair("growthCapex", f.periodEnds.map(() => "0"), perUnit(v.capex), cite([["uso a financiar", c]]));
      // Taxable base before the new debt's interest: EBITDA less depreciation, lease payments and existing interest.
      pair("taxableBaseBeforeNewDebtInterest",
        f.periodEnds.map((_, i) => s8(D(co.ebitda.value[i]!).times(keep).minus(co.depreciation.value[i]!).minus(co.leasePayments.value[i]!).minus(debt.value.cashInterest[i]!))),
        f.periodEnds.map((_, i) => s20(D(v.ebitda[i]!).times(keep).minus(v.depreciation[i]!).div(total))),
        cite([["EBITDA", co.ebitda], ["depreciação", co.depreciation], ["arrendamentos", co.leasePayments], ["juros da dívida vigente", debt], ["resultado do projeto", c]])
          + " Premissa da casa: base tributável antes dos juros da dívida nova." + shock);
      pair("otherExistingFinancingCashAvailable", f.periodEnds.map(() => "0"), f.periodEnds.map(() => "0"), house("Sem outra fonte de financiamento vigente além da informada"));
      pair("capitalCashAvailable", f.periodEnds.map(() => "0"), f.periodEnds.map(() => "0"), house("Sem aporte de capital no período"));
      list(p + "existingCashInterest", "currency", debt.value.cashInterest, why(debt), sc);
      list(p + "existingCashPrincipalPaid", "currency", debt.value.principalPaid, why(debt), sc);
      list(p + "existingDebtForRatio", "currency", debt.value.closingDebt, why(debt), sc);
      list(p + "cashTaxRate", "ratio", f.periodEnds.map(() => co.cashTaxRate.value), why(co.cashTaxRate), sc);
      list(p + "lossTaxTreatment", "convention", f.periodEnds.map(() => "no_cash_benefit"), house("Prejuízo fiscal sem benefício de caixa no período"), sc);
      list(p + "newDebtTaxDeduction", "convention", f.periodEnds.map(() => "paid_interest"), house("Juros da dívida nova dedutíveis quando pagos"), sc);
      list(p + "cfadsGrowthCapexTreatment", "convention", f.periodEnds.map(() => "exclude_growth_capex"), house("Caixa para o serviço da dívida antes do investimento financiado"), sc);
      list(p + "cfadsDefinitionAnchors", "reference_id", f.periodEnds.map(() => "caixa disponível para o serviço da dívida"), house("Definição de caixa disponível do método"), sc);
      const nf = (name: string, values: string[], reason: string) => list(p + "newFinancing." + name, "ratio", values, reason, sc);
      const rate = st.annualRate.map((x) => D(x));
      nf("drawAtStart", f.periodEnds.map(() => "0"), house("Desembolso ao fim de cada período, conforme o uso é gasto"));
      nf("drawAtEnd", perUnit(v.capex), cite([["uso a financiar", c]]));
      nf("principalPaidAtEnd", st.amortizationShares, why(f.structure));
      nf("interestFactorOnOpeningAndStartDraw", rate.map(s20), why(f.structure));
      nf("interestFactorOnEndDraw", rate.map((r) => s20(r.div(2))), why(f.structure, "Premissa da casa: saldo médio anual."));
      nf("interestFactorCreditOnEndAmortization", rate.map((r) => s20(r.div(2))), why(f.structure, "Premissa da casa: saldo médio anual."));
      nf("withheldCostPerUnitDraw", f.periodEnds.map(() => "0"), house("Custos de entrada fora da capacidade; medidos pela comparação de propostas"));
      list(p + "newFinancing.factorConvention", "convention", f.periodEnds.map(() => "adopted_annual_average_balance_approximation"), house("Aproximação anual por saldo médio declarada pelo método"), sc);
      list(p + "newFinancing.paysAccruedInterest", "convention", f.periodEnds.map(() => "true"), house("Juros pagos em cada período"), sc);
      list(p + "newFinancing.unpaidInterestBase", "convention", f.periodEnds.map(() => "principal_only"), house("Sem juros sobre juros"), sc);
      for (const l of f.limits) {
        const threshold = stressed ? l.value.adverse : l.value.base;
        if (threshold === null) continue;
        const rid = ruleId(f.capacityId, v.id, l.value.id, stressed);
        txt(p + `rule.${rid}.kind`, "convention", l.value.kind, why(l), sc);
        num(p + `rule.${rid}.threshold`, l.value.kind === "minimum_available_cash" ? "currency" : "ratio", threshold, why(l), sc);
      }
    }
  }
  // A working basis holds at most 256 premises; a set larger than that is refused here, not at confirmation.
  if (out.length > maxCapacityHypotheses) throw new Error("capacity_premises_exceed_basis");
  return out;
}

import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {deterministicRunEvidenceFingerprint, type DeterministicMethodRun, type DeterministicMethodRunCase} from "@offroad/credit-playbook";
import {debtCapacityPacketOutputSchema, prepareDebtCapacityPacket, type DebtCapacityPacketInput} from "./debt-capacity-packet";
import {calculateAdoptedDebtCapacity} from "./adopted-debt-capacity";
import {c04DisconnectedPacketInput, c04PacketInput} from "./debt-capacity.test-support";

// Evaluation-only module; not exported to application consumers. All cases are synthetic
// calibrations of ficha C04 (modelo_c04.py), never production parameters.
const fingerprint = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const D = Decimal.clone({precision: 60});
const r = (v: string, p = 1) => new D(v).toDecimalPlaces(p).toNumber();
type Case = DeterministicMethodRunCase;
type Evidence = Omit<DeterministicMethodRun, "schemaVersion" | "humanApproval" | "run">;
export const debtCapacityMethodVersion = "2026.10.19-v2";
export const debtCapacityRunIds = {
  gold: "assess-debt-capacity-2026-10-19-v2-gold",
  adversarial: "assess-debt-capacity-2026-10-19-v2-adversarial",
  consistency: "assess-debt-capacity-2026-10-19-v2-consistency",
} as const;
type Packet = ReturnType<typeof prepareDebtCapacityPacket>;
const sealed = (o: Parameters<typeof c04PacketInput>[0] = {}) => c04PacketInput(o).seal() as DebtCapacityPacketInput;
function observe(id: string, input: DebtCapacityPacketInput, expected: unknown, select: (p: Packet) => unknown): Case {
  const result = prepareDebtCapacityPacket(input), observed = JSON.stringify(select(result)), expectation = JSON.stringify(expected);
  return {id, expectation, observed, inputFingerprint: fingerprint(input), outputFingerprint: fingerprint(result), passed: expectation === observed};
}
const at = (p: Packet, id: string) => p.cases.find((c) => c.caseId === id)!;
const view = (p: Packet, id: string) => at(p, id).review!.scenarios.map((s) => [r(s.peakLeverage.value, 2), s.peakLeverage.date.slice(0, 4), r(s.minimumCash.value), r(s.minimumInterestCoverage!.value, 2)]);

function goldCases(): Case[] {
  const packet = prepareDebtCapacityPacket(sealed()), bndes = prepareDebtCapacityPacket(sealed({structure: "bndes"}));
  const reuse = (id: string, p: Packet, input: () => DebtCapacityPacketInput, expected: unknown, select: (p: Packet) => unknown): Case => {
    const observed = JSON.stringify(select(p)), expectation = JSON.stringify(expected);
    return {id, expectation, observed, inputFingerprint: fingerprint(input()), outputFingerprint: fingerprint(p), passed: expectation === observed};
  };
  const base = () => sealed(), withBndes = () => sealed({structure: "bndes"});
  return [
    // Expectations come from the independent Python oracle (outputs/fichas-ensaio-2026-10/C04/resultados.json).
    reuse("c04-capacity-by-limit-independent-oracle", packet, base, [["covenant", 54.8], ["market", 76.8], ["interest", 72]],
      (p) => at(p, "informed").limits.map((l) => [l.id, r(l.capacity!)])),
    reuse("phased-capacity-independent-oracle", packet, base, [["covenant", 79.5], ["market", 108.6], ["interest", 107.6]],
      (p) => at(p, "phased").limits.map((l) => [l.id, r(l.capacity!)])),
    reuse("covenant-with-headroom-binds", packet, base, {informed: ["covenant", "2028-12-31", "adverse"], phased: ["covenant", "2029-12-31", "adverse"]},
      (p) => Object.fromEntries(["informed", "phased"].map((id) => {const c = at(p, id), sc = c.review!.scenarios.findIndex((x) => x.scenarioId === c.binding!.scenarioId);
        return [id, [c.binding!.limitId, c.binding!.date, sc === 1 ? "adverse" : "base"]];}))),
    observe("joint-capacity-is-the-intersection-of-the-limits", c04DisconnectedPacketInput(), {perLimit: [["cash", 200], ["interest", 20]], joint: null, status: "no_feasible_amount"},
      (p) => ({perLimit: p.cases[0]!.limits.map((l) => [l.id, l.capacity === null ? null : r(l.capacity, 0)]), joint: p.cases[0]!.capacity, status: p.cases[0]!.capacityStatus})),
    reuse("sixty-breaks-the-covenant-in-the-adverse-case-as-informed", packet, base, {fits: false, failing: ["covenant"], view: [[2.42, "2028", 13.8, 2.65], [3.12, "2028", -22.3, 2.26]]},
      (p) => ({fits: at(p, "informed").review!.fits, failing: at(p, "informed").review!.failingLimitIds, view: view(p, "informed")})),
    reuse("phasing-makes-sixty-fit-in-size", packet, base, {fits: true, view: [[1.88, "2029", 13.5, 3.17], [2.58, "2029", -21.4, 2.7]]},
      (p) => ({fits: at(p, "phased").review!.fits, view: view(p, "phased")})),
    reuse("size-fits-but-a-five-year-profile-runs-out-of-cash-in-the-adverse-case", packet, base, {fits: true, adverseMinimumCashNegative: true},
      (p) => ({fits: at(p, "phased").review!.fits, adverseMinimumCashNegative: new D(at(p, "phased").review!.scenarios[1]!.minimumCash.value).lt(0)})),
    reuse("bndes-eight-years-keeps-cash-positive", bndes, withBndes, {informed: [[2.39, 25.2], [3.08, 2.4]], phased: [[1.85, 26.3], [2.55, 3.4]]},
      (p) => ({informed: view(p, "informed").map((v) => [v[0], v[2]]), phased: view(p, "phased").map((v) => [v[0], v[2]])})),
    reuse("plan-pays-scheduled-principal-without-refinancing", packet, base, {date: "2029-12-31", scheduled: 22.67, afterInterest: 23.56, pays: true},
      (p) => {const y = at(p, "informed").plan!.find((x) => x.date === "2029-12-31")!; return {date: y.date, scheduled: r(y.scheduledExistingPrincipal, 2), afterInterest: r(y.cashAfterInterest, 2), pays: y.paysWithoutRefinancing};}),
    reuse("window-ends-with-the-seasonal-line-open", packet, base, {calibrationOnly: true}, (p) => ({calibrationOnly: at(p, "informed").calibrationOnly})),
    (() => {
      // Under nonnegative netting, negative cash does not reduce debt: the leverage shown is the covenant's own.
      const g = c04PacketInput();
      // The independent review's reproduction: R$ 200 mi reviewed from zero opening cash, so cash turns negative.
      for (const e of g.basis.entries) {
        if (e.fieldPath.endsWith(".cashNetting")) e.value = {type: "text", value: "nonnegative_available"};
        if (e.fieldPath.endsWith(".openingAvailableCash")) e.value = {type: "number", value: "0"};
        if (e.fieldPath.endsWith(".fixedReviewAmount")) e.value = {type: "number", value: "200"};
      }
      const i = g.seal() as DebtCapacityPacketInput, informed = i.cases.find((c) => c.id === "informed")!;
      const covenant = new Set(informed.limits.find((l) => l.id === "covenant")!.ruleIds);
      const checks = (calculateAdoptedDebtCapacity(informed.analysis).fixedReview as {checks: {scenarioId: string; ruleId: string; metric: string | null}[]}).checks;
      const kernel = informed.analysis.scenarios.map((sc) => r(checks.filter((x) => x.scenarioId === sc.id && covenant.has(x.ruleId) && x.metric !== null)
        .reduce((m, x) => D.max(m, x.metric!), new D(-1e9)).toFixed(), 4));
      return observe("leverage-nets-cash-under-the-adopted-convention", i, {leverage: kernel, adverseMinimumCashNegative: true},
        (p) => ({leverage: at(p, "informed").review!.scenarios.map((x) => r(x.peakLeverage.value, 4)),
          adverseMinimumCashNegative: new D(at(p, "informed").review!.scenarios[1]!.minimumCash.value).lt(0)}));
    })(),
    (() => {
      const i = sealed(); const rule = i.cases[0]!.analysis.scenarios[0]!.rules[0]!;
      rule.threshold = {...rule.threshold, decisionId: null, missingReason: "Folga do covenant não adotada"};
      return observe("absent-threshold-is-a-gap-not-a-default", i, {status: "framed", covenant: null, gap: true},
        (p) => ({status: p.status, covenant: at(p, "informed").limits[0]!.capacity, gap: at(p, "informed").gaps.some((g) => g.reason === "Folga do covenant não adotada")}));
    })(),
  ];
}

function adversarialCases(): Case[] {
  const attempts: [string, () => unknown, string][] = [
    ["tampered-envelope", () => {const i = sealed(); for (const c of i.cases) c.analysis.envelope = {...c.analysis.envelope, canonical: c.analysis.envelope.canonical.replace('"56.6"', '"66.6"')}; return i;}, "adoption_basis_integrity_mismatch"],
    ["two-informed-cases", () => {const i = sealed(); (i.cases[1] as {role: string}).role = "informed"; i.cases[1]!.changes = []; return i;}, "Exactly one informed case is required"],
    ["silent-alternative", () => {const i = sealed(); i.cases[1]!.changes = []; return i;}, "must say what it changes"],
    ["same-analysis-twice", () => {const i = sealed(); i.cases[1] = {...i.cases[1]!, analysis: i.cases[0]!.analysis, limits: i.cases[0]!.limits}; return i;}, "own adopted analysis"],
    ["limit-names-unknown-rule", () => {const i = sealed(); i.cases[0]!.limits[1]!.ruleIds = ["ac400000-0000-4000-9000-000000099999"]; return i;}, "names a rule the analysis does not carry"],
    ["rule-in-two-limits", () => {const i = sealed(); i.cases[0]!.limits[1]!.ruleIds = [...i.cases[0]!.limits[1]!.ruleIds, i.cases[0]!.limits[0]!.ruleIds[0]!]; return i;}, "exactly one limit"],
    ["rule-left-out", () => {const i = sealed(); i.cases[0]!.limits = i.cases[0]!.limits.slice(0, 2); return i;}, "exactly one limit"],
    ["another-basis", () => {const i = sealed(); i.cases[1]!.analysis = {...i.cases[1]!.analysis, envelope: {...i.cases[1]!.analysis.envelope, fingerprint: "0".repeat(64)}}; return i;}, "same adopted basis"],
    ["free-result-in-request", () => ({...sealed(), capacity: "200"}), "Unrecognized key"],
    ["fabricated-grant-in-result", () => ({forge: true}), "grantsExecution"],
  ];
  return attempts.map(([id, build, message]) => {
    let observed: string, passed: boolean, input: unknown;
    try {
      input = build();
      if ((input as {forge?: boolean}).forge) debtCapacityPacketOutputSchema.parse({...prepareDebtCapacityPacket(sealed()), grantsExecution: true});
      else prepareDebtCapacityPacket(input);
      observed = "accepted"; passed = false;
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      passed = detail.includes(message); observed = passed ? "rejected by expected boundary" : `unexpected error: ${detail.slice(0, 250)}`;
    }
    return {id, expectation: "rejected by expected boundary", observed, inputFingerprint: fingerprint(input ?? null), outputFingerprint: fingerprint({observed}), passed};
  });
}

function consistencyCases(): Case[] {
  const informedOnly = () => {const i = sealed(); i.cases = [i.cases[0]!]; return i;};
  return [sealed(), informedOnly()].flatMap((input, fixtureIndex) => {
    const before = fingerprint(input), first = prepareDebtCapacityPacket(input);
    return Array.from({length: 3}, (_, repeat) => {
      const result = prepareDebtCapacityPacket(JSON.parse(JSON.stringify(input)));
      const passed = fingerprint(result) === fingerprint(first) && fingerprint(input) === before;
      return {id: `fixture-${fixtureIndex + 1}-repeat-${repeat + 1}`, expectation: "same inputs and versions reproduce all output bytes without mutation",
        observed: passed ? "same inputs and versions reproduce all output bytes without mutation" : "output or input changed", inputFingerprint: before, outputFingerprint: fingerprint(result), passed};
    });
  });
}

export function buildDebtCapacityRuns(): Evidence[] {
  return ([{kind: "gold", cases: goldCases()}, {kind: "adversarial", cases: adversarialCases()}, {kind: "consistency", cases: consistencyCases()}] as const).map(({kind, cases}) => {
    const evidence = {runId: debtCapacityRunIds[kind], kind, method: {id: "assess-debt-capacity", version: debtCapacityMethodVersion},
      executor: {module: "@offroad/financial-model", exportName: "prepareDebtCapacityPacket"},
      harness: {module: "@offroad/financial-model/src/debt-capacity-runs.test-support.ts", exportName: "buildDebtCapacityRuns"},
      modelCalls: 0 as const, cases, result: cases.every((c) => c.passed) ? "pass" as const : "fail" as const};
    return {...evidence, evidenceFingerprint: deterministicRunEvidenceFingerprint(evidence),
      notes: "Synthetic deterministic execution calibrated on ficha C04. Numerical expectations do not constitute independent review, content approval, live access verification or publication."};
  });
}

import Decimal from "decimal.js";
import type {AdoptedDebtCapacityInput} from "./adopted-debt-capacity";
import {analysisTestBasis, analysisTestId as id} from "./adopted-analysis.test-support";

// Synthetic adopted basis of ficha C04 (fictitious Aurora after the 2027 plan of C32), annual 2027
// to 2033, in R$ million. Drivers mirror the independent oracle modelo_c04.py so the engine can be
// checked against it; they are calibration hypotheses, never production parameters.
const D = Decimal.clone({precision: 60});
const years = [2027, 2028, 2029, 2030, 2031, 2032, 2033];
const CDI: Record<number, string> = {2027: "0.14", 2028: "0.1275", 2029: "0.12", 2030: "0.12", 2031: "0.12", 2032: "0.12", 2033: "0.12"};
const TLP = "0.079", LEASE = "3", MAINTENANCE = "8", WORKING_CAPITAL = "2.5", TAX = "0.34", DA = "12", OPENING_CASH = "15.3", SEASONAL_LINE = "20";
const EBITDA: Record<number, string> = {2027: "56.6", 2028: "58.8", 2029: "61.2", 2030: "63.6", 2031: "66.1", 2032: "68.7", 2033: "71.5"};
export const c04Schedules = {
  informed: {capex: {2027: "30", 2028: "30"} as Record<number, string>, projectEbitda: {2029: "6", 2030: "12", 2031: "12", 2032: "12", 2033: "12"} as Record<number, string>},
  phased: {capex: {2028: "30", 2029: "30"} as Record<number, string>, projectEbitda: {2030: "6", 2031: "12", 2032: "12", 2033: "12"} as Record<number, string>},
} as const;
/** Five years with grace to 2030 (the structure the size table uses) and BNDES over eight years. */
export const c04Structures = {
  fiveYears: {rate: (y: number) => new D(CDI[y]!).plus("0.025"), amortization: {2030: "1/3", 2031: "1/3", 2032: "1/3"} as Record<number, string>},
  bndes: {rate: () => new D(TLP).plus("0.03"), amortization: {2030: "1/6", 2031: "1/6", 2032: "1/6", 2033: "1/6"} as Record<number, string>},
} as const;
// Existing debt after the 2027 plan: debenture of 80 amortizing 16 a year from 2029, the older FINAME.
const debenture: Record<number, string> = {2026: "80", 2027: "80", 2028: "80", 2029: "64", 2030: "48", 2031: "32", 2032: "16", 2033: "0"};
const finame: Record<number, string> = {2026: "23.33", 2027: "16.66", 2028: "9.99", 2029: "3.32", 2030: "0", 2031: "0", 2032: "0", 2033: "0"};
const fraction = (v: string) => v.includes("/") ? new D(v.split("/")[0]!).div(v.split("/")[1]!) : new D(v);
const s = (v: Decimal) => v.toDecimalPlaces(20).toFixed();

/** One capacity analysis (one schedule and one structure) with the base and the adverse case
 * (EBITDA 15% lower) and the three limits of the ficha as separate adopted rules. */
export function c04Analysis(f: ReturnType<typeof analysisTestBasis>, o: {analysisId: string; label: string; schedule: keyof typeof c04Schedules; structure: keyof typeof c04Structures; review: string | null}) {
  const pfx = `debt_capacity.${o.analysisId}.`;
  const num = (p: string, unit: string, value: string, scenario: string) => f.contribute(pfx + p, unit, {type: "number", value}, scenario);
  const text = (p: string, value: string, scenario: string) => f.contribute(pfx + p, "convention", {type: "text", value}, scenario);
  const list = (p: string, unit: string, value: string[], scenario: string) => f.contribute(pfx + p, unit, {type: "list", value}, scenario);
  const sched = c04Schedules[o.schedule], st = c04Structures[o.structure];
  const scenario = (adverse: boolean, sid: string, rules: {id: string; kind: string; threshold: string}[]) => {
    const sc = `${o.label}:${adverse ? "adverse" : "base"}`, p = `scenario.${sid}.`, keep = adverse ? new D("0.85") : new D(1);
    const project = (y: number) => new D(sched.projectEbitda[y] ?? "0");
    const capexShare = (y: number) => new D(sched.capex[y] ?? "0").div(60);
    const interestExisting = (y: number) => new D(debenture[y - 1]!).plus(debenture[y]!).div(2).times(new D(CDI[y]!).plus("0.029"))
      .plus(new D(finame[y - 1]!).plus(finame[y]!).div(2).times(new D(TLP).plus("0.018"))).plus(new D(SEASONAL_LINE).times("0.5").times(new D(CDI[y]!).plus("0.02")));
    const projectDa = (y: number) => new D(y >= 2029 ? 6 : y === 2028 ? 3 : 0).div(60);
    const affine: Record<string, [string[], string[]]> = {
      ebitda: [years.map((y) => s(new D(EBITDA[y]!).times(keep))), years.map((y) => s(project(y).times(keep).div(60)))],
      covenantEbitdaAdjustment: [years.map(() => "-" + LEASE), years.map(() => "0")],
      nonCashEbitdaBridge: [years.map(() => "0"), years.map(() => "0")],
      cashLeasePayments: [years.map(() => LEASE), years.map(() => "0")],
      changeInWorkingCapital: [years.map(() => WORKING_CAPITAL), years.map((y) => s(project(y).minus(project(y - 1)).div(60)))],
      maintenanceCapex: [years.map(() => MAINTENANCE), years.map((y) => s(project(y).gt(0) ? new D("1.5").div(60) : new D(0)))],
      growthCapex: [years.map(() => "0"), years.map((y) => s(capexShare(y)))],
      taxableBaseBeforeNewDebtInterest: [years.map((y) => s(new D(EBITDA[y]!).times(keep).minus(DA).minus(LEASE).minus(interestExisting(y)))),
        years.map((y) => s(project(y).times(keep).div(60).minus(projectDa(y))))],
      otherExistingFinancingCashAvailable: [years.map(() => "0"), years.map(() => "0")],
