import {adoptedValueSelectionSchema} from "./adopted-debt-inputs";
import {inventoryModes} from "./document-folder-inventory";
import {documentFolderInventoryPacketInputSchema, type DocumentFolderInventoryPacketInput} from "./document-folder-inventory-packet";

const text = z.string().trim().min(1).max(2000);
const bound = z.strictObject({
  envelope: z.strictObject({canonical: z.string().min(2).max(4194304), fingerprint: z.string().regex(/^[a-f0-9]{64}$/)}),
  scope: z.strictObject({workId: z.uuid(), purpose: z.string().min(3).max(300), versionId: z.uuid()}),
});
/** The folder's basis and, in a later turn, the basis of what arrived. */
export const boundDocumentFolderInventoryInputSchema = z.strictObject({base: bound, update: bound.nullable().default(null), question: text, mode: z.enum(inventoryModes).default("organize")});
type Selection = z.infer<typeof adoptedValueSelectionSchema>;
const uuid = "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}";
const k = "[a-z0-9][a-z0-9-]{0,39}";
const keyOf = z.string().regex(new RegExp(`^${k}$`));

/** One basis, composed by field path: the single analysis it carries, each record selected by path,
 * scenario, unit and type in the analysis' own dimensions, listed in the adopted order first. An absent
 * record or one adopted twice for the same slot is declared missing with its reason. */
function composeOne(raw: z.input<typeof bound>, root: string, kinds: {kind: string; leaf: string; order: string}[]) {
  const input = bound.parse(raw);
  const basis = readContextualBasis(input.envelope, input.scope);
  const entries = [...basis.entries].sort((a, b) => a.decisionId < b.decisionId ? -1 : 1);
  const pattern = new RegExp(`^${root}\\.(${uuid})\\.`);
  const roles = entries.flatMap((e) => {const m = pattern.exec(e.fieldPath); return m ? [{analysisId: m[1]!, entry: e}] : [];});
  if (!roles.length) throw new Error("document_inventory_analysis_missing");
  if (new Set(roles.map((r) => r.analysisId)).size !== 1) throw new Error("document_inventory_analysis_ambiguous");
  const analysisId = roles[0]!.analysisId, prefix = `${root}.${analysisId}.`;
  const anchor = (roles.find((r) => r.entry.fieldPath.endsWith(".order.files")) ?? roles[0]!).entry, d = anchor.dimensions, sc = d.scenario!;
  const own = entries.filter((e) => e.fieldPath.startsWith(prefix) && e.dimensions.scenario === sc && e.dimensions.entityId === d.entityId && e.dimensions.perimeter === d.perimeter
    && e.dimensions.currency === d.currency && e.dimensions.periodStart === d.periodStart && e.dimensions.periodEnd === d.periodEnd);
  const definitions: Selection[] = [], missing: Selection[] = [];
  function select(p: string, type: AdoptionBasisEntry["value"]["type"]): Selection {
    const matches = own.filter((e) => e.fieldPath === prefix + p && e.value.type === type && e.dimensions.unit === "identity");
    if (matches.length === 1) {
      const e = matches[0]!, s = {decisionId: e.decisionId, definitionVersionId: e.dimensions.definitionVersionId!, definitionKind: e.definitionKind, missingReason: null};
      definitions.push(s); return s;
    }
    const s = {decisionId: null, definitionVersionId: anchor.dimensions.definitionVersionId!, definitionKind: anchor.definitionKind,
      missingReason: matches.length > 1 ? `${matches.length} contributions match ${p} for scenario ${sc}; keep one value per slot in the working basis` : `No contribution adopted for ${p} in scenario ${sc}`};
    missing.push(s); return s;
  }
  const ids = (kind: string, leaf: string, orderPath: string) => {
    const found = own.filter((e) => e.fieldPath === prefix + orderPath && e.value.type === "list");
    if (found.length > 1) throw new Error("document_inventory_order_ambiguous");
    const order = z.array(keyOf).parse(found[0]?.value.value ?? []);
    if (new Set(order).size !== order.length) throw new Error("document_inventory_order_ambiguous");
    const named = new RegExp(`^${kind}\\.(${k})\\.${leaf}$`);
    const seen = [...new Set(own.flatMap((e) => {const m = named.exec(e.fieldPath.slice(prefix.length)); return m ? [m[1]!] : [];}))].filter((x) => !order.includes(x)).sort();
    return [...order, ...seen];
  };
  const slots = Object.fromEntries(kinds.map(({kind, leaf, order}) => [kind, ids(kind, leaf, order).map((id) => ({id, value: select(`${kind}.${id}.${leaf}`, "text")}))]));
  const context = {envelope: input.envelope, scope: input.scope, entityId: d.entityId!, perimeter: d.perimeter!, currency: d.currency!,
    openingDate: d.periodStart!, endDate: d.periodEnd!, numericInterpretations: [], analysisId, scenario: sc};
  // A missing record carries the lowest resolved definition so the reference is stable; the reader ignores it.
  const borrowed = [...definitions].sort((a, b) => a.definitionVersionId < b.definitionVersionId ? -1 : 1)[0];
  return {context, slots, select, fix: () => {if (borrowed) for (const m of missing) {m.definitionVersionId = borrowed.definitionVersionId; m.definitionKind = borrowed.definitionKind;}}};
}

/** Composes the folder inventory packet input from the bases alone: the folder's basis and, in a later
 * turn, the basis of what arrived, which names the folder's basis by fingerprint. No record is supplied here. */
export function composeBoundDocumentFolderInventory(raw: unknown): DocumentFolderInventoryPacketInput {
  const input = boundDocumentFolderInventoryInputSchema.parse(raw);
  const b = composeOne(input.base, "document_folder_inventory", [{kind: "entity", leaf: "record", order: "order.entities"}, {kind: "decision", leaf: "record", order: "order.decisions"},
    {kind: "vault", leaf: "record", order: "order.vault"}, {kind: "file", leaf: "reading", order: "order.files"}]);
  const subjectEntityId = b.select("subject.entity", "text");
  b.fix();
  const base = {...b.context, subjectEntityId, entities: b.slots.entity!, decisions: b.slots.decision!, vault: b.slots.vault!, files: b.slots.file!};
  let update = null;
  if (input.update) {
    const u = composeOne(input.update, "document_folder_inventory_update", [{kind: "file", leaf: "reading", order: "order.files"}, {kind: "informed", leaf: "record", order: "order.informed"}]);
    const priorFingerprint = u.select("prior.fingerprint", "text");
    u.fix();
    update = {...u.context, priorFingerprint, files: u.slots.file!, informed: u.slots.informed!};
  }
  return documentFolderInventoryPacketInputSchema.parse({schemaVersion: "document-folder-inventory-packet-input.v1", question: input.question, mode: input.mode, analysis: {base, update}});
}

import {z} from "zod";
import {methodDataContractFromJsonSchema} from "@offroad/credit-playbook";
import {documentFolderInventoryPacketInputSchema, documentFolderInventoryPacketOutputSchema, documentFolderInventoryPacketVersion} from "./document-folder-inventory-packet";

/** Build-owned contract publication, kept apart from the executor so the released artifact
 * bundles only the organization and its schemas. */
export function documentFolderInventoryPacketExecutorContracts() {
  const options = {reused: "inline", cycles: "throw", unrepresentable: "throw"} as const;
  const inputSchema = z.toJSONSchema(documentFolderInventoryPacketInputSchema, {...options, io: "input"});
  const outputSchema = z.toJSONSchema(documentFolderInventoryPacketOutputSchema, options);
  return {schemaVersion: "method-executor-contracts.v1",
    executor: {module: "@offroad/financial-model", exportName: "prepareDocumentFolderInventoryPacket", version: documentFolderInventoryPacketVersion},
    inputs: methodDataContractFromJsonSchema("document-folder-inventory-packet-input", documentFolderInventoryPacketVersion, inputSchema),
    outputs: methodDataContractFromJsonSchema("document-folder-inventory-packet-output", documentFolderInventoryPacketVersion, outputSchema),
    validationSchemas: {input: inputSchema, output: outputSchema}};
}

import {createHash} from "node:crypto";
import {z} from "zod";
import {adoptedDocumentFolderInventoryOutputSchema, calculateAdoptedDocumentFolderInventory, documentFolderInventoryAnalysesSchema} from "./adopted-document-folder-inventory";
import {documentFolderInventoryLimits as L, inventoryModes} from "./document-folder-inventory";

export const documentFolderInventoryPacketVersion = "2026.10.27-v1";
// Limits from the kernel's one source; a statement of the method may name every line of a debt table.
const text = z.string().trim().min(1).max(L.text), key = z.string().trim().min(1).max(L.id), hash = z.string().regex(/^[a-f0-9]{64}$/);
const statement = z.string().trim().min(1).max(L.statement);
const decimal = z.string().regex(/^-?\d{1,30}(?:\.\d{1,20})?$/);
const source = z.strictObject({fileId: key, page: z.number().int().nullable(), section: text.nullable()});

/** One request to organize a folder. The mode is how the conversation framed it: organize (and say what
 * matters for the decisions in course), organize only (no analysis yet) or organize for the debt discussion. */
export const documentFolderInventoryPacketInputSchema = z.strictObject({
  schemaVersion: z.literal("document-folder-inventory-packet-input.v1"),
  question: text,
  mode: z.enum(inventoryModes).default("organize"),
  analysis: documentFolderInventoryAnalysesSchema,
});
export type DocumentFolderInventoryPacketInput = z.input<typeof documentFolderInventoryPacketInputSchema>;
const packetExclusions = ["ratio_calculation", "projection", "recommendation", "document_validation", "third_party_distribution"] as const;

export const documentFolderInventoryPacketOutputSchema = z.strictObject({
  schemaVersion: z.literal("document-folder-inventory-packet.v1"), executorVersion: z.literal(documentFolderInventoryPacketVersion),
  question: text, mode: z.enum(inventoryModes), basisFingerprint: hash, scope: adoptedDocumentFolderInventoryOutputSchema.shape.scope, entityId: z.uuid(),
  result: adoptedDocumentFolderInventoryOutputSchema,
  /** What the answer says, in order: the size and how it was organized, what matters for the decisions in course,
   * the versions, what was not read, what is missing by purpose, and at most two questions. */
  readings: z.strictObject({
    opening: z.strictObject({files: z.number().int(), groups: z.array(text).max(L.groupsOut), duplicates: z.number().int(), superseded: z.number().int(), inVault: z.number().int()}),
    decisionFindings: z.array(z.strictObject({rank: z.number().int(), statement, decisionIds: z.array(key).min(1), sources: z.array(source).min(1).max(L.sources)})).max(L.findings).nullable(),
    generalFindings: z.array(z.strictObject({rank: z.number().int(), statement})).max(L.findings).nullable(),
    versions: z.array(z.strictObject({familyId: key, resolution: key, prevails: z.array(key), superseded: z.array(key), sideBySide: z.array(key), highlighted: z.boolean()})).max(L.files),
    /** What the documents say, quoted with file and page or sheet; kept apart from everything the method states. */
    documentary: z.array(z.strictObject({findingId: key, fileId: key, page: z.number().int().nullable(), section: text.nullable(), text})).max(L.findings + L.gaps),
    notRead: z.array(z.strictObject({fileId: key, pages: z.array(z.number().int()).nullable(), statement})).max(L.findings),
    gaps: z.array(z.strictObject({item: statement, why: statement, purposes: z.array(key).min(1), conditional: z.boolean()})).max(L.gaps),
    questions: z.array(statement).max(2),
    /** A later turn: only the rows what arrived touches, the identity checks it allows, and the facts recorded with author and date. */
    update: z.strictObject({rowsUpdated: z.array(key), rowsAdded: z.array(key), rowsPreserved: z.number().int(), newFindings: z.array(z.strictObject({statement, quoted: z.strictObject({fileId: key, page: z.number().int().nullable(), section: text.nullable(), text}).nullable()})),
      identityChecks: z.array(z.strictObject({id: key, status: z.enum(["matches", "differs", "not_run"]), reported: decimal.nullable(), recomposed: decimal.nullable()})),
      informed: z.array(z.strictObject({statement: text, author: text, date: z.iso.date()})), stillOpen: z.array(statement)}).nullable(),
    /** Set when the update could not be read: everything above is the prior inventory, as history. */
    historical: z.strictObject({inventoryFingerprint: hash, reason: z.literal("update_not_read")}).nullable(),
    numericAnalysis: z.literal("none"), documentsValidated: z.literal(false),
  }).nullable(),
  gaps: z.array(z.strictObject({operand: text, reason: text})).max(L.entities + L.decisions + L.vault + L.files + L.informed + 1),
  status: z.enum(["framed", "partial", "prepared_for_human_review"]),
  exclusions: z.array(z.enum(packetExclusions)).length(5).refine((v) => v.join("|") === packetExclusions.join("|"), "Exact exclusion ledger required"),
  grantsExecution: z.literal(false), grantsPublication: z.literal(false), fingerprint: hash,
});
export type DocumentFolderInventoryPacket = z.infer<typeof documentFolderInventoryPacketOutputSchema>;

/** Organizes a folder the person dropped: the inventory by subject (and by entity first when the folder
 * spans several companies), each file read by content with entity, period, version and situation; the
 * copy by hash and what was already in the vault; versions resolved without deleting any; amendments read
 * with the original; what was not read, by page; what in the folder matters for the decisions in course,
 * each with its source; the gaps for the purpose; at most two questions. A later turn updates only the rows
 * touched. It never calculates ratios, projects, recommends, validates a document or sends anything. */
export function prepareDocumentFolderInventoryPacket(raw: unknown): DocumentFolderInventoryPacket {
  const input = documentFolderInventoryPacketInputSchema.parse(raw);
  const result = calculateAdoptedDocumentFolderInventory(input.analysis, input.mode);
  // An update that could not be read leaves the base inventory standing, and the packet partial.
  // An update that could not be read never restates the prior effects as current: the prior inventory is shown as
  // identified history, with no decision findings, no general findings and no open questions.
  const historical = result.inventory === null && result.priorInventory !== null;
  const inv = result.inventory ?? result.priorInventory;
  const readings = inv ? {
    opening: {files: inv.counts.files, groups: [...new Set(inv.groups.map((g) => g.label))], duplicates: inv.counts.duplicates, superseded: inv.counts.superseded, inVault: inv.counts.inVault},
    historical: historical ? {inventoryFingerprint: result.base.inventoryFingerprint!, reason: "update_not_read" as const} : null,
    decisionFindings: historical ? null : inv.decisionFindings?.map((d) => ({rank: d.rank, statement: d.statement, decisionIds: d.decisionIds, sources: d.sources})) ?? null,
    generalFindings: historical ? null : inv.generalFindings?.map((d) => ({rank: d.rank, statement: d.statement})) ?? null,
    versions: inv.families.map((f) => ({familyId: f.id, resolution: f.resolution, prevails: f.prevails, superseded: f.superseded, sideBySide: f.sideBySide, highlighted: f.highlighted})),
    documentary: [...inv.findings.filter((f) => f.quoted !== null && f.status === "open").map((f) => ({findingId: f.id, ...f.quoted!})),
      ...inv.findings.filter((f) => f.changes !== null && f.status === "open").flatMap((f) => f.changes!.flatMap((c) => [...c.before ? [{findingId: f.id, ...c.before}] : [], {findingId: f.id, ...c.after}])),
      ...inv.gaps.filter((g) => g.quoted !== null && g.status === "open" && !inv.findings.some((f) => f.id === g.findingId && f.quoted !== null)).map((g) => ({findingId: g.id, ...g.quoted!}))],
    notRead: inv.findings.filter((f) => (f.code === "page_unreadable" || f.code === "file_unreadable") && f.status === "open")
      .map((f) => ({fileId: f.anchor, pages: f.code === "page_unreadable" ? f.sources.flatMap((s) => s.page === null ? [] : [s.page]) : null, statement: f.statement})),
    gaps: inv.gaps.filter((g) => g.status === "open").map((g) => ({item: g.item, why: g.why, purposes: g.purposes, conditional: g.conditional})),
    questions: historical ? [] : inv.questions.filter((q) => q.status === "open").map((q) => q.text),
    update: inv.update ? {rowsUpdated: inv.update.rowsUpdated, rowsAdded: inv.update.rowsAdded, rowsPreserved: inv.update.rowsPreserved,
      newFindings: inv.findings.filter((f) => inv.update!.findingsAdded.includes(f.id)).map((f) => ({statement: f.statement, quoted: f.quoted})),
      // Only the checks the arrival made possible are restated.
      identityChecks: inv.identityChecks.filter((c) => result.priorInventory?.identityChecks.some((p) => p.id === c.id && p.status !== c.status) ?? false)
        .map((c) => ({id: c.id, status: c.status, reported: c.reported, recomposed: c.recomposed})),
      informed: inv.informed.map((i) => ({statement: i.statement, author: i.author, date: i.date})),
      stillOpen: inv.gaps.filter((g) => g.status === "open" && !g.conditional).map((g) => g.item)} : null,
    numericAnalysis: "none" as const, documentsValidated: false as const,
  } : null;
  // A copy read two ways is a declared conflict the person resolves; the packet is partial until then.
  const gaps = [...result.gaps, ...(inv?.readingConflicts ?? []).flatMap((c) => c.fileIds.map((id) => ({operand: `document_folder_inventory.${result.analysisId}.file.${id}.reading`, reason: "reading_conflicts_with_same_hash"})))];
  const status = !inv ? (result.status === "base_only" ? "partial" as const : "framed" as const) : gaps.length ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "document-folder-inventory-packet.v1" as const, executorVersion: documentFolderInventoryPacketVersion,
    question: input.question, mode: input.mode, basisFingerprint: result.basisFingerprint, scope: result.scope, entityId: result.entityId,
    result, readings, gaps, status, exclusions: packetExclusions, grantsExecution: false as const, grantsPublication: false as const};
  return documentFolderInventoryPacketOutputSchema.parse({...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")});
}

import {z} from "zod";
import {capacityUuid} from "./debt-capacity-premises";
import type {ProposedHypothesis} from "./investment-premises";
import {documentReadingSchema} from "./document-folder-inventory";
import {inventoryDecisionRecordSchema, inventoryEntityRecordSchema, inventoryInformedRecordSchema, inventoryVaultRecordSchema} from "./adopted-document-folder-inventory";

const text = z.string().trim().min(1).max(2000);
const key = z.string().regex(/^[a-z0-9][a-z0-9-]{0,39}$/);
const hash = z.string().regex(/^[a-f0-9]{64}$/);
const origins = ["document", "informed", "house", "estimate"] as const;
const originLabel: Record<(typeof origins)[number], string> = {document: "documento", informed: "informado", house: "premissa da casa", estimate: "estimativa"};
/** A value and where it came from; the source names the file read, the message or the project context. */
const fact = <T extends z.ZodType>(value: T) => z.strictObject({value, origin: z.enum(origins), source: text});
type Origin = {origin: (typeof origins)[number]; source: string};
const context = {entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/), definitionVersionId: z.uuid(), openingDate: z.iso.date(), readingDate: z.iso.date()};

/** The folder as facts: each file reading as the extraction produced it from content (origin: document),
 * the company's entities, the decisions in course and the vault (the project context). Nothing is adopted
 * until a person confirms the set. */
export const documentFolderInventoryFactsSchema = z.strictObject({
  inventoryId: z.uuid(), ...context,
  /** The company under analysis, by its registry id. */
  subjectEntityId: fact(key),
  entities: z.array(fact(inventoryEntityRecordSchema.safeExtend({id: key}))).min(1).max(50),
  decisions: z.array(fact(inventoryDecisionRecordSchema.safeExtend({id: key}))).max(12),
  vault: z.array(fact(inventoryVaultRecordSchema.safeExtend({documentId: key}))).max(200),
  /** In arrival order. */
  files: z.array(fact(documentReadingSchema)).min(1).max(200),
}).superRefine((f, ctx) => {
  const fail = (message: string) => ctx.addIssue({code: "custom", message});
  if (f.readingDate <= f.openingDate) fail("The reading date must come after the start of the window");
  for (const [name, ids] of [["entity", f.entities.map((e) => e.value.id)], ["decision", f.decisions.map((d) => d.value.id)], ["vault entry", f.vault.map((v) => v.value.documentId)], ["file", f.files.map((x) => x.value.fileId)]] as const)
    if (new Set(ids).size !== ids.length) fail(`Duplicate ${name}`);
  if (f.files.some((x) => x.origin !== "document")) fail("A file reading comes from the document");
});
export type DocumentFolderInventoryFacts = z.infer<typeof documentFolderInventoryFactsSchema>;

/** What arrived after the inventory: readings, and facts the person informed with author and date. */
export const documentFolderUpdateFactsSchema = z.strictObject({
  updateId: z.uuid(), ...context, priorFingerprint: fact(hash),
  files: z.array(fact(documentReadingSchema)).max(50),
  informed: z.array(fact(inventoryInformedRecordSchema.safeExtend({id: key}))).max(20),
}).superRefine((f, ctx) => {
  if (f.informed.some((i) => i.origin !== "informed")) ctx.addIssue({code: "custom", message: "An informed fact is informed by the person"});
  if (new Set(f.files.map((x) => x.value.fileId)).size !== f.files.length) ctx.addIssue({code: "custom", message: "Duplicate file"});
});
export type DocumentFolderUpdateFacts = z.infer<typeof documentFolderUpdateFactsSchema>;

export const documentFolderInventoryAnalysisId = (inventoryId: string) => capacityUuid(`offroad:document-folder-inventory:${inventoryId}:analysis`);
export const documentFolderUpdateAnalysisId = (updateId: string) => capacityUuid(`offroad:document-folder-inventory-update:${updateId}:analysis`);
/** The size of one working basis. */
export const maxDocumentFolderInventoryHypotheses = 256;

function proposer(f: z.infer<z.ZodObject<typeof context>>, prefix: string) {
  const out: ProposedHypothesis[] = [];
  const add = (path: string, unit: string, value: ProposedHypothesis["value"], reason: string) => out.push({fieldPath: prefix + path,
    dimensions: {entityId: f.entityId, perimeter: f.perimeter, periodStart: f.openingDate, periodEnd: f.readingDate, currency: f.currency, unit, scale: "1", scenario: "base", definitionVersionId: f.definitionVersionId},
    value, reason});
  const why = (x: Origin) => `Origem: ${originLabel[x.origin]}. ${x.source}`;
  // One record per adoption, as canonical JSON: the reader parses it with the strict schema.
  const json = (path: string, value: unknown, x: Origin) => add(path, "identity", {type: "text", value: JSON.stringify(value)}, why(x));
  const order = (path: string, ids: string[], source: string) => {if (ids.length) add(path, "identity", {type: "list", value: ids}, `Origem: premissa da casa. ${source}`);};
  return {out, json, order, add, why};
}

/** The hypotheses one confirmation adopts for the folder: one record per file reading, entity, decision
 * and vault entry, and the arrival order. Deterministic; nothing is read from a file name here. */
export function proposeDocumentFolderInventoryHypotheses(raw: unknown): ProposedHypothesis[] {
  const f = documentFolderInventoryFactsSchema.parse(raw);
  const {out, json, order, add, why} = proposer(f, `document_folder_inventory.${documentFolderInventoryAnalysisId(f.inventoryId)}.`);
  add("subject.entity", "identity", {type: "text", value: f.subjectEntityId.value}, why(f.subjectEntityId));
  for (const e of f.entities) {const {id, ...v} = e.value; json(`entity.${id}.record`, v, e);}
  for (const d of f.decisions) {const {id, ...v} = d.value; json(`decision.${id}.record`, v, d);}
  for (const x of f.vault) {const {documentId, ...v} = x.value; json(`vault.${documentId}.record`, v, x);}
  for (const x of f.files) json(`file.${x.value.fileId}.reading`, x.value, x);
  order("order.entities", f.entities.map((e) => e.value.id), "Ordem do cadastro como informada");
  order("order.decisions", f.decisions.map((d) => d.value.id), "Ordem das decisões em curso como informada");
  order("order.vault", f.vault.map((v) => v.value.documentId), "Ordem do cofre como informada");
  order("order.files", f.files.map((x) => x.value.fileId), "Ordem de chegada dos arquivos");
  if (out.length > maxDocumentFolderInventoryHypotheses) throw new Error("document_inventory_premises_exceed_basis");
  return out;
}

/** The hypotheses for what arrived later: the readings, the informed facts and the basis it updates. */
export function proposeDocumentFolderUpdateHypotheses(raw: unknown): ProposedHypothesis[] {
  const f = documentFolderUpdateFactsSchema.parse(raw);
  const {out, json, order, add, why} = proposer(f, `document_folder_inventory_update.${documentFolderUpdateAnalysisId(f.updateId)}.`);
  add("prior.fingerprint", "identity", {type: "text", value: f.priorFingerprint.value}, why(f.priorFingerprint));
  for (const x of f.files) json(`file.${x.value.fileId}.reading`, x.value, x);
  for (const i of f.informed) {const {id, ...v} = i.value; json(`informed.${id}.record`, v, i);}
  order("order.files", f.files.map((x) => x.value.fileId), "Ordem de chegada dos arquivos");
  order("order.informed", f.informed.map((i) => i.value.id), "Ordem das informações recebidas");
  if (out.length > maxDocumentFolderInventoryHypotheses) throw new Error("document_inventory_premises_exceed_basis");
  return out;
}

import {createHash} from "node:crypto";
import {deterministicRunEvidenceFingerprint, type DeterministicMethodRun, type DeterministicMethodRunCase} from "@offroad/credit-playbook";
import {documentFolderInventoryPacketOutputSchema, prepareDocumentFolderInventoryPacket, type DocumentFolderInventoryPacket, type DocumentFolderInventoryPacketInput} from "./document-folder-inventory-packet";
import type {DocumentReading} from "./document-folder-inventory";
