    const keys = [...new Set([original, ...chain].flatMap((f) => [...entriesOf(f).keys()]))].sort(byKey);
    for (const key of keys) {
      const type = typeOf(key), base = entriesOf(original).get(key);
      const setters = chain.filter((f) => entriesOf(f).has(key));
      if (!setters.length) {
