    const seen = [...new Set(own.flatMap((e) => {const m = pattern.exec(e.fieldPath.slice(prefix.length)); return m ? [m[1]!] : [];}))].filter((x) => !listed.includes(x)).sort();
    return [...listed, ...seen];
  };
  const n = (p: string, unit: string) => select(p, unit, "number"), t = (p: string, unit: string) => select(p, unit, "text");
  const dt = (p: string) => select(p, "date", "date"), b = (p: string) => select(p, "convention", "boolean"), l = (p: string, unit: string) => select(p, unit, "list");
  const proposal = {lender: t("proposal.lender", "text"), indexer: t("proposal.indexer", "convention"), firmness: t("proposal.firmness", "convention"), termSheetDate: dt("proposal.termSheetDate"),
    validityDays: n("proposal.validityDays", "days"), amount: n("proposal.amount", "currency"), annualSpread: n("proposal.annualSpread", "ratio"), feeRate: n("proposal.feeRate", "ratio"),
    drawDate: dt("proposal.drawDate"), paymentDay: n("proposal.paymentDay", "count"), graceMonths: n("proposal.graceMonths", "count"), installments: n("proposal.installments", "count"),
    installmentEveryMonths: n("proposal.installmentEveryMonths", "count"), interestEveryMonths: n("proposal.interestEveryMonths", "count"), amortization: t("proposal.amortization", "convention"),
    collateralKind: t("proposal.collateralKind", "convention"), coverage: n("proposal.coverage", "ratio"), restrictedAccount: b("proposal.restrictedAccount"),
    ...(anyOf(["proposal.covenantLimit", "proposal.covenantTestDates", "proposal.covenantDefinition"])
      ? {covenantLimit: n("proposal.covenantLimit", "ratio"), covenantTestDates: l("proposal.covenantTestDates", "date"), covenantDefinition: t("proposal.covenantDefinition", "convention")}
      : {covenantLimit: null, covenantTestDates: null, covenantDefinition: null}),
    prepaymentPenaltyRate: n("proposal.prepaymentPenaltyRate", "ratio"), prepaymentPenaltyMonths: n("proposal.prepaymentPenaltyMonths", "count"),
    reciprocity: t("proposal.reciprocity", "convention"), bankSawIndenture: b("proposal.bankSawIndenture")};
  const policy = anyOf(["covenant.policyLimit", "covenant.policyTestDates", "covenant.policySource"])
    ? {policyLimit: n("covenant.policyLimit", "ratio"), policyTestDates: l("covenant.policyTestDates", "date"), policySource: t("covenant.policySource", "text")}
    : {policyLimit: null, policyTestDates: null, policySource: null};
  const marketFields = ["comparable", "low", "median", "high", "sample", "confidence", "observedOn"].map((x) => `market.${x}`);
  const historyFields = ["label", "spread", "date", "adjustmentIds", "adjustmentFamilies", "adjustmentBps", "adjustmentAnchors"].map((x) => `history.${x}`);
  const analysis = {envelope: input.envelope, scope: input.scope, entityId: d.entityId!, perimeter: d.perimeter!, currency: d.currency!, openingDate: d.periodStart!, endDate: d.periodEnd!,
    numericInterpretations: [], analysisId, scenario: sc, readingDate: dt("readingDate"), needDate: dt("needDate"), proposal,
    creditTax: {fixedRate: n("creditTax.fixedRate", "ratio"), dailyRate: n("creditTax.dailyRate", "ratio"), maxDays: n("creditTax.maxDays", "days")},
    curve: {years: l("curve.years", "identity"), rates: l("curve.rates", "ratio")}, tax: {regime: t("tax.regime", "convention"), rate: n("tax.rate", "ratio"), taxableAfterCalendar: optional("tax.taxableAfterCalendar", "convention", "boolean")},
    uses: keys("use", "order.uses").map((id) => {const q = `use.${id}.`; return {id, label: t(q + "label", "text"), amount: n(q + "amount", "currency"), kind: t(q + "kind", "convention"),
      tenorMinYears: n(q + "tenorMinYears", "years"), tenorMaxYears: n(q + "tenorMaxYears", "years")};}),
    seasonalPeak: optional("seasonalPeak", "currency", "number"),
    calendar: {periodEnds: l("calendar.periodEnds", "date"), existingService: l("calendar.existingService", "currency"), availableForService: l("calendar.availableForService", "currency"),
      closingCash: l("calendar.closingCash", "currency"), taxable: l("calendar.taxable", "boolean"), minimumCash: optional("calendar.minimumCash", "currency", "number")},
    covenant: {indentureLimit: n("covenant.indentureLimit", "ratio"), indentureTestDates: l("covenant.indentureTestDates", "date"), indentureSource: t("covenant.indentureSource", "text"), requiredScenarios: l("covenant.requiredScenarios", "identity"),
      ...policy, ...(anyOf(["dates", "scenarios", "debt", "cash", "reportedEbitda", "definitionAdjustment"].map((x) => `covenant.${x}`))
        ? {dates: l("covenant.dates", "date"), scenarios: l("covenant.scenarios", "identity"), debt: l("covenant.debt", "currency"), cash: l("covenant.cash", "currency"),
          reportedEbitda: l("covenant.reportedEbitda", "currency"), definitionAdjustment: l("covenant.definitionAdjustment", "currency")}
        : {dates: null, scenarios: null, debt: null, cash: null, reportedEbitda: null, definitionAdjustment: null})},
    portfolio: keys("bucket", "order.buckets").map((id) => {const q = `bucket.${id}.`; return {id, label: t(q + "label", "text"), amount: n(q + "amount", "currency"),
      contract: t(q + "contract", "convention"), encumbrance: t(q + "encumbrance", "convention"), holder: optional(q + "holder", "text", "text"), pastDue: b(q + "pastDue"),
      countsAgainstBasket: b(q + "countsAgainstBasket")};}),
    basket: {limit: n("basket.limit", "currency"), basis: t("basket.basis", "convention"), occupied: n("basket.occupied", "currency"),
      consentLeadDaysMin: n("basket.consentLeadDaysMin", "days"), consentLeadDaysMax: n("basket.consentLeadDaysMax", "days")},
    collateralReference: {coverageLow: n("collateralReference.coverageLow", "ratio"), coverageHigh: n("collateralReference.coverageHigh", "ratio")},
    market: anyOf(marketFields) ? {comparable: b("market.comparable"), low: n("market.low", "ratio"), median: n("market.median", "ratio"), high: n("market.high", "ratio"),
      sample: n("market.sample", "count"), confidence: t("market.confidence", "convention"), observedOn: dt("market.observedOn")} : null,
    history: anyOf(historyFields) ? {label: t("history.label", "text"), spread: n("history.spread", "ratio"), date: dt("history.date"), adjustmentIds: l("history.adjustmentIds", "identity"),
      adjustmentFamilies: l("history.adjustmentFamilies", "convention"), adjustmentBps: l("history.adjustmentBps", "ratio"), adjustmentAnchors: l("history.adjustmentAnchors", "text")} : null,
    variants: keys("variant", "order.variants").map((id) => {const q = `variant.${id}.`; return {id, label: t(q + "label", "text"), graceMonths: n(q + "graceMonths", "count"),
      installments: n(q + "installments", "count"), coverage: n(q + "coverage", "ratio"), restrictedAccount: b(q + "restrictedAccount")};}),
    alternatives: keys("alternative", "order.alternatives").map((id) => {const q = `alternative.${id}.`; return {id, label: t(q + "label", "text"),
      allInSpread: optional(q + "allInSpread", "ratio", "number"), collateral: n(q + "collateral", "currency"), usesCovered: l(q + "usesCovered", "identity"),
      monthsToMoneyMin: n(q + "monthsToMoneyMin", "months"), monthsToMoneyMax: n(q + "monthsToMoneyMax", "months")};}),
  };
  // A missing operand carries the lowest resolved definition so the reference is stable; the executor ignores it.
  const borrowed = [...definitions].sort((a, b) => a.definitionVersionId < b.definitionVersionId ? -1 : 1)[0];
  if (borrowed) for (const m of missing) {m.definitionVersionId = borrowed.definitionVersionId; m.definitionKind = borrowed.definitionKind;}
  return receivedProposalPacketInputSchema.parse({schemaVersion: "received-proposal-packet-input.v1", question: input.question, analysis});
}

import {z} from "zod";
import {methodDataContractFromJsonSchema} from "@offroad/credit-playbook";
import {receivedProposalPacketInputSchema, receivedProposalPacketOutputSchema, receivedProposalPacketVersion} from "./evaluate-received-proposal-packet";

/** Build-owned contract publication, kept apart from the executor so the released artifact
 * bundles only the calculation and its schemas. */
export function receivedProposalPacketExecutorContracts() {
  const options = {reused: "inline", cycles: "throw", unrepresentable: "throw"} as const;
  const inputSchema = z.toJSONSchema(receivedProposalPacketInputSchema, {...options, io: "input"});
  const outputSchema = z.toJSONSchema(receivedProposalPacketOutputSchema, options);
  return {schemaVersion: "method-executor-contracts.v1",
    executor: {module: "@offroad/financial-model", exportName: "prepareReceivedProposalPacket", version: receivedProposalPacketVersion},
    inputs: methodDataContractFromJsonSchema("received-proposal-packet-input", receivedProposalPacketVersion, inputSchema),
    outputs: methodDataContractFromJsonSchema("received-proposal-packet-output", receivedProposalPacketVersion, outputSchema),
    validationSchemas: {input: inputSchema, output: outputSchema}};
}

import {describe, expect, it} from "vitest";
import {prepareReceivedProposalPacket, receivedProposalPacketOutputSchema} from "./evaluate-received-proposal-packet";
import {calculateAdoptedReceivedProposal} from "./adopted-evaluate-received-proposal";
import {adoptedReceivedProposalOutputSchema} from "./evaluate-received-proposal-results";
import {receivedProposalPacketExecutorContracts} from "./evaluate-received-proposal-contracts";
import {auroraReceivedProposal, auroraReceivedProposalBasis, receivedProposalQuestion as question} from "./evaluate-received-proposal.test-support";

const packet = (k = auroraReceivedProposal()) => prepareReceivedProposalPacket({schemaVersion: "received-proposal-packet-input.v1", question, analysis: auroraReceivedProposalBasis(k).seal()});
const n = (v: string | null | undefined, p = 1) => Number(v).toFixed(p);
describe("received proposal packet", {timeout: 180_000}, () => {
  const p = packet(), r = p.readings!;
  it("leads with firmness and the year the calendar already concentrates", () => {
    expect(r.firmness).toEqual({firmness: "indicative", validUntil: "2026-09-13", bankSawIndenture: false, diligenceMayReopenStructure: true});
    expect([r.liquidity.peakYear, n(r.liquidity.existingService), n(r.liquidity.proposalService), n(r.liquidity.availableForService), r.liquidity.peakQuarter, r.liquidity.firstBelowPolicyWith])
      .toEqual([2027, "89.7", "12.2", "35.7", "2027-09-30", "2027-09-30"]);
    expect(p.status).toBe("prepared_for_human_review");
  });
  it("reads collateral against the assignable portfolio and the aggregate basket", () => {
    expect([r.collateral.required, r.collateral.nominallyFree, r.collateral.assignable, r.collateral.shortfallToAssignable]).toEqual(["39", "46", "25.41", "13.59"]);
    expect(r.collateral.excluded.map((x) => x.id)).toEqual(["rede-a", "redes-c-d", "vencidos"]);
    expect([r.negativePledge.remaining, r.negativePledge.excess, r.negativePledge.consentRequired, r.negativePledge.consentBy]).toEqual(["3", "36", true, "2026-09-13"]);
  });
  it("keeps facts, readings and recommendations apart, with what would change them and no verdict", () => {
    expect(r.assessment).toEqual({
      facts: ["proposal_indicative", "collateral_exceeds_assignable_portfolio", "assignment_prohibited_receivables_excluded", "indenture_consent_required",
        "peak_year_service_exceeds_available_cash", "cash_below_minimum_with_proposal", "board_policy_breached_in_a_case", "lender_tests_more_often_than_indenture",
        "restricted_account_requested", "coverage_at_top_of_reference"],
      readings: ["term_longer_than_seasonal_use", "term_shorter_than_capex_use", "all_in_cost_well_above_nominal", "nominal_spread_above_median_within_range",
        "improvement_partly_paid_in_collateral", "diligence_may_reopen_structure"],
      recommendations: ["address_indenture_consent_before_signing", "ask_longer_grace_and_tenor", "ask_lower_coverage_and_no_restricted_account", "separate_uses_by_term", "keep_price_discussion_secondary"],
      wouldChange: ["debtor_consent_for_restricted_receivables", "indenture_clause_wording", "other_free_asset_for_collateral", "seasonal_need_above_adopted", "committed_terms_after_diligence"]});
    expect(r.questions).toEqual(["lender_covenant_definition", "reciprocity_expected_by_lender", "restricted_debtor_consent", "indenture_clause_wording", "other_free_asset"]);
    expect(Object.keys(r)).not.toContain("verdict");
  });
  it("prices the asks and puts the nominal spread and the cost over the life side by side", () => {
    expect([n(r.price.nominalSpread, 4), n(r.price.equivalentSpread, 4), n(r.price.equivalentSpreadNet, 4), r.price.marketPosition]).toEqual(["0.0210", "0.0490", "0.0324", "above_median_within_range"]);
    expect(r.asks.map((a) => [a.id, n(a.peakYearServiceDelta), a.consentStillRequired])).toEqual([["carencia-12-prazo-48", "-6.0", true], ["carencia-12-prazo-60", "-6.4", true], ["cobertura-120-sem-conta", "0.0", true]]);
  });
  it("does not conclude compliance with a required covenant test missing", () => {
    expect([r.covenant.anyBreachWith, r.covenant.missingTests]).toEqual([true, []]);
    const k = auroraReceivedProposal(); k.covenant.measurements = k.covenant.measurements.filter((m) => !(m.scenario === "bank" && ["2026-12-31", "2027-12-31"].includes(m.date)));
    const q = packet(k);
    expect([q.status, q.readings!.covenant.anyBreachWith, q.readings!.assessment.readings.includes("covenant_tests_missing"), q.gaps.filter((g) => g.operand.includes(".covenant.bank.")).length]).toEqual(["partial", null, true, 2]);
  });
  it("conditions the net cost on taxable profit in every period", () => {
    expect(r.price.netConvention).toBe("full_deductibility_simplified");
    const k = auroraReceivedProposal(); k.calendar.taxable = k.calendar.taxable.map(() => false);
    const q = packet(k);
    expect([q.status, q.readings!.price.equivalentSpreadNet, q.readings!.price.netConvention, q.gaps.some((g) => g.operand.endsWith(".calendar.taxable"))]).toEqual(["partial", null, "not_all_periods_taxable", true]);
  });
  it("refuses a changed value under the old fingerprint, in the packet and in the adopted result", () => {
    expect(() => receivedProposalPacketOutputSchema.parse({...p, readings: {...r, price: {...r.price, equivalentSpread: r.price.nominalSpread}}})).toThrow("received_proposal_fingerprint_mismatch");
    const ev = p.result.evaluation!;
    expect(() => receivedProposalPacketOutputSchema.parse({...p, result: {...p.result, evaluation: {...ev, cost: {...ev.cost, equivalentSpread: ev.proposal.annualSpread}}}})).toThrow("received_proposal_fingerprint_mismatch");
    expect(receivedProposalPacketOutputSchema.parse(JSON.parse(JSON.stringify(p))).fingerprint).toBe(p.fingerprint);
  });
  it("turns a limit with no test at all into gaps, for each limit and for all of them", () => {
    // Without the December tests the indenture and the policy are untested; without any, the lender too.
    for (const [drop, untested] of [[["2026-12-31", "2027-12-31", "2028-12-31"], ["indenture", "board-policy"]],
      [["2026-12-31", "2027-06-30", "2027-12-31", "2028-06-30", "2028-12-31"], ["indenture", "proposal", "board-policy"]]] as const) {
      const k = auroraReceivedProposal(); k.variants = [];
      k.covenant.measurements = k.covenant.measurements.filter((m) => !(drop as readonly string[]).includes(m.date));
      const q = packet(k);
      expect([q.status, q.readings!.covenant.anyBreachWith, q.readings!.covenant.untestedLimits]).toEqual(["partial", null, untested]);
      expect(untested.every((l) => q.gaps.some((g) => g.operand.endsWith(`.covenant.limit.${l}`)))).toBe(true);
    }
  });
  it("does not state the net cost for a life past the fiscal calendar without an adopted hypothesis", () => {
    const k = auroraReceivedProposal(); k.tax.taxableAfterCalendar = null;
    const q = packet(k);
    expect([q.status, q.readings!.price.netConvention, q.readings!.price.equivalentSpreadNet, q.readings!.asks.map((a) => a.netConvention)])
      .toEqual(["partial", "life_beyond_fiscal_calendar", null, ["life_beyond_fiscal_calendar", "life_beyond_fiscal_calendar", "life_beyond_fiscal_calendar"]]);
    expect(q.gaps.filter((g) => g.operand.endsWith(".tax.taxableAfterCalendar") || g.operand.endsWith(".net")).length).toBe(4);
  });
  it("refuses a tax rate above one in the adopted reader, by decimal comparison", () => {
    for (const rate of ["1.5", "1.00000000000000000001"]) {const k = auroraReceivedProposal(); k.tax.rate = rate; expect(() => packet(k)).toThrow("received_proposal_tax_rate_out_of_domain");}
    // The reader refuses it on its own, even when another operand is missing and the kernel never runs.
    const f = auroraReceivedProposalBasis({...auroraReceivedProposal(), tax: {regime: "lucro_real", rate: "1.00000000000000000001", taxableAfterCalendar: true}});
    const i = f.seal(); i.basket = {...i.basket, occupied: {...i.basket.occupied, decisionId: null, missingReason: "Ausente"}};
    expect(() => calculateAdoptedReceivedProposal(i)).toThrow("received_proposal_tax_rate_out_of_domain");
  });
  it("reads the lender's frequency and first date from its effective dates only", () => {
    const k = auroraReceivedProposal(); k.variants = [];
    k.proposal.covenant = {...k.proposal.covenant!, testDates: ["2027-12-31", "2026-09-30", "2026-08-31", "2026-07-31"]};
    const q = packet(k);
    expect([q.result.evaluation!.proposal.firstLenderTestDate, q.readings!.covenant.testsPerYear, q.readings!.covenant.lenderDatesBeforeDraw,
      q.readings!.assessment.facts.includes("lender_tests_more_often_than_indenture")]).toEqual(["2027-12-31", {indenture: 1, lender: 1}, ["2026-07-31", "2026-08-31", "2026-09-30"], false]);
  });
  it("refuses a repeated test date in the adopted reader before the kernel runs", () => {
    const k = auroraReceivedProposal(); k.covenant.indenture = {...k.covenant.indenture, testDates: [...k.covenant.indenture.testDates, "2026-12-31"]};
    const f = auroraReceivedProposalBasis(k), i = f.seal(); i.basket = {...i.basket, occupied: {...i.basket.occupied, decisionId: null, missingReason: "Ausente"}};
    expect(() => calculateAdoptedReceivedProposal(i)).toThrow("received_proposal_duplicate_test_date");
  });
  it("is partial without a comparable market and deterministic, validated and published", () => {
    const k = auroraReceivedProposal(); k.market = {...k.market!, comparable: false};
    const q = packet(k);
    expect([q.status, q.readings!.price.marketPosition, q.readings!.assessment.recommendations.includes("keep_price_discussion_secondary")]).toEqual(["partial", null, false]);
    expect(packet().fingerprint).toBe(p.fingerprint);
    expect(adoptedReceivedProposalOutputSchema.parse(calculateAdoptedReceivedProposal(auroraReceivedProposalBasis().seal())).status).toBe("partial_composition");
    expect(receivedProposalPacketExecutorContracts().executor).toEqual({module: "@offroad/financial-model", exportName: "prepareReceivedProposalPacket", version: "2026.10.27-v1"});
  });
});

import Decimal from "decimal.js";
import {z} from "zod";
import {financialCoreVersion} from "@offroad/financial-core";
import {adoptedReceivedProposalInputSchema, calculateAdoptedReceivedProposal} from "./adopted-evaluate-received-proposal";
import {adoptedReceivedProposalOutputSchema, receivedProposalBucketReasons, receivedProposalNetConventions, receivedProposalFingerprint, verifiedReceivedProposalFingerprint} from "./evaluate-received-proposal-results";

export const receivedProposalPacketVersion = "2026.10.27-v1";
const Exact = Decimal.clone({precision: 60});
const text = z.string().trim().min(1).max(2000), key = z.string().trim().min(1).max(160), date = z.iso.date();
const hash = z.string().regex(/^[a-f0-9]{64}$/), decimal = z.string().regex(/^-?\d{1,24}(?:\.\d{1,20})?$/);
export const receivedProposalPacketExclusions = ["proposal_acceptance", "counterparty_contact", "credit_approval", "legal_opinion", "reciprocity_pricing"] as const;
/** A tight headroom, in turns of EBITDA, below which the tree makes the covenant a negotiation point. */
const tightHeadroom = new Exact("0.3");

export const receivedProposalFactCodes = ["proposal_indicative", "collateral_exceeds_assignable_portfolio", "assignment_prohibited_receivables_excluded", "indenture_consent_required",
  "peak_year_service_exceeds_available_cash", "cash_below_minimum_with_proposal", "board_policy_breached_in_a_case", "lender_tests_more_often_than_indenture",
  "restricted_account_requested", "coverage_at_top_of_reference"] as const;
export const receivedProposalReadingCodes = ["term_longer_than_seasonal_use", "term_shorter_than_capex_use", "all_in_cost_well_above_nominal", "nominal_spread_below_range",
  "nominal_spread_at_or_below_median", "nominal_spread_above_median_within_range", "nominal_spread_above_range", "improvement_partly_paid_in_collateral", "real_improvement_against_last_operation",
  "covenant_headroom_tight", "diligence_may_reopen_structure", "covenant_tests_missing", "net_cost_conditioned_on_taxable_profit"] as const;
export const receivedProposalRecommendationCodes = ["address_indenture_consent_before_signing", "ask_longer_grace_and_tenor", "ask_lower_coverage_and_no_restricted_account",
  "separate_uses_by_term", "keep_price_discussion_secondary"] as const;
export const receivedProposalChangeCodes = ["debtor_consent_for_restricted_receivables", "indenture_clause_wording", "other_free_asset_for_collateral", "seasonal_need_above_adopted",
  "committed_terms_after_diligence"] as const;
/** Asked before any reading when the term itself is not confirmed. */
export const receivedProposalOpenQuestionCodes = ["indexer_confirmation"] as const;
export const receivedProposalQuestionCodes = ["lender_covenant_definition", "reciprocity_expected_by_lender", "restricted_debtor_consent", "indenture_clause_wording", "other_free_asset"] as const;

/** One received proposal, evaluated for the company that would take it. */
export const receivedProposalPacketInputSchema = z.strictObject({
  schemaVersion: z.literal("received-proposal-packet-input.v1"),
  question: text,
  analysis: adoptedReceivedProposalInputSchema,
});
export type ReceivedProposalPacketInput = z.infer<typeof receivedProposalPacketInputSchema>;

export const receivedProposalPacketOutputSchema = z.strictObject({
  schemaVersion: z.literal("received-proposal-packet.v1"), executorVersion: z.literal(receivedProposalPacketVersion), financialCoreVersion: key,
  question: text, basisFingerprint: hash, scope: adoptedReceivedProposalInputSchema.shape.scope, entityId: z.uuid(), currency: z.string().regex(/^[A-Z]{3}$/),
  result: adoptedReceivedProposalOutputSchema,
  /** What the answer must say, in the order the tree weighs it. */
  readings: z.strictObject({
    firmness: z.strictObject({firmness: z.enum(["indicative", "committed"]), validUntil: date, bankSawIndenture: z.boolean(), diligenceMayReopenStructure: z.boolean()}),
    liquidity: z.strictObject({peakYear: z.number().int(), existingService: decimal, proposalService: decimal, totalService: decimal, availableForService: decimal,
      peakQuarter: date, minimumCashWith: z.strictObject({periodEnd: date, amount: decimal}), firstBelowPolicyWith: date.nullable(), firstBelowPolicyWithout: date.nullable()}),
    fit: z.strictObject({seasonalShare: decimal, weightedAverageLifeYears: decimal, finalPaymentDate: date,
      uses: z.array(z.strictObject({id: key, amount: decimal, reading: z.enum(["longer_than_use", "shorter_than_use", "within_use"])})).min(1).max(8)}),
    covenant: z.strictObject({rows: z.array(z.strictObject({date, scenario: key, ratioWith: decimal.nullable(),
      headroom: z.array(z.strictObject({limitId: z.enum(["indenture", "proposal", "board-policy"]), testedOnDate: z.boolean(), headroomWith: decimal.nullable(), breachedWith: z.boolean()})).max(3)})).max(12),
      testsPerYear: z.strictObject({indenture: z.number().int(), lender: z.number().int()}),
      anyBreachWith: z.boolean().nullable(), missingTests: z.array(z.strictObject({date, scenario: key})).max(64),
      untestedLimits: z.array(z.enum(["indenture", "proposal", "board-policy"])).max(3), lenderDatesBeforeDraw: z.array(date).max(24)}),
    collateral: z.strictObject({required: decimal, nominallyFree: decimal, assignable: decimal, shortfallToAssignable: decimal.nullable(), assignableLeftAfter: decimal.nullable(),
      seasonalPeak: decimal.nullable(), excluded: z.array(z.strictObject({id: key, amount: decimal, holder: text.nullable(), reasons: z.array(z.enum(receivedProposalBucketReasons)).min(1).max(3)})).max(12),
      coverage: decimal, restrictedAccount: z.boolean()}),
    negativePledge: z.strictObject({basis: z.enum(["aggregate", "per_operation"]), limit: decimal, occupied: decimal, remaining: decimal, consentRequired: z.boolean(), excess: decimal.nullable(),
      consentBy: date, needDate: date, slackDays: z.number().int()}),
    /** Price is two readings: the nominal spread against the market and the cost over the life; never one for the other. */
    price: z.strictObject({nominalSpread: decimal, equivalentSpread: decimal, equivalentSpreadNet: decimal.nullable(),
      /** The net figure is the spread reduced by the tax rate, assuming full deduction when paid; stated only under lucro real with every period taxable. */
      netConvention: z.enum(receivedProposalNetConventions), upfrontShare: decimal, creditTaxRate: decimal,
      weightedAverageLifeYears: decimal, marketPosition: z.enum(["below_range", "at_or_below_median", "above_median_within_range", "above_range"]).nullable(),
      history: z.strictObject({observedBps: decimal, expectedBps: decimal, residualBps: decimal.nullable()}).nullable()}),
    /** What to ask the lender, each with what it buys. */
    asks: z.array(z.strictObject({id: key, label: text, peakYearServiceDelta: decimal, equivalentSpreadDeltaBps: decimal, collateralDelta: decimal, consentStillRequired: z.boolean(), netConvention: z.enum(receivedProposalNetConventions),
      restrictedAccount: z.boolean()})).max(4),
    alternatives: z.array(z.strictObject({id: key, usesCovered: z.array(key).min(1).max(8), allInSpreadDifferenceBps: decimal.nullable(), consentRequired: z.boolean()})).max(4),
    /** Fact, reading and recommendation kept apart, with what would change the conclusion. There is no verdict field. */
    assessment: z.strictObject({facts: z.array(z.enum(receivedProposalFactCodes)).max(10), readings: z.array(z.enum(receivedProposalReadingCodes)).max(13),
      recommendations: z.array(z.enum(receivedProposalRecommendationCodes)).max(5), wouldChange: z.array(z.enum(receivedProposalChangeCodes)).max(5)}),
    questions: z.array(z.enum(receivedProposalQuestionCodes)).max(5),
    /** The packet speaks of terms; it neither accepts the proposal nor writes to the lender. */
    process: z.strictObject({acceptsProposal: z.literal(false), contactsLender: z.literal(false), counterproposalSent: z.literal(false)}),
  }).nullable(),
  gaps: z.array(z.strictObject({operand: text, reason: text})).max(1024),
  openQuestions: z.array(z.enum(receivedProposalOpenQuestionCodes)).max(1),
  status: z.enum(["framed", "partial", "prepared_for_human_review"]),
  exclusions: z.array(z.enum(receivedProposalPacketExclusions)).length(5)
    .refine((v) => v.join("|") === receivedProposalPacketExclusions.join("|"), "Exact exclusion ledger required"),
  grantsExecution: z.literal(false), grantsPublication: z.literal(false), fingerprint: hash,
}).superRefine(verifiedReceivedProposalFingerprint);
export type ReceivedProposalPacket = z.infer<typeof receivedProposalPacketOutputSchema>;

/** Whether a received proposal is good for the company that would take it, read on terms and never as a
 * verdict: its cost over its life apart from its nominal spread, its service against the year the
 * company's calendar already concentrates, its fit with each use of the money, the covenant on every
 * definition and on the board's policy, the collateral against the portfolio that can be assigned and
 * against the indenture's basket, its spread against the market and the company's last operation, what
 * each ask to the lender buys, and what would change the reading. Deterministic; contacts no one. */
export function prepareReceivedProposalPacket(raw: unknown): ReceivedProposalPacket {
  const input = receivedProposalPacketInputSchema.parse(raw);
  const result = adoptedReceivedProposalOutputSchema.parse(calculateAdoptedReceivedProposal(input.analysis));
  const e = result.evaluation;
  const readings = e ? (() => {
    const peak = e.calendar.years.find((y) => y.year === e.calendar.peakYear)!;
    const consent = e.negativePledge.consentRequired, shortfall = e.collateral.shortfallToAssignable !== null && new Exact(e.collateral.shortfallToAssignable).gt(0);
    const prohibited = e.collateral.portfolio.buckets.some((b) => b.reasons.includes("assignment_prohibited_without_debtor_consent"));
    const policyBreached = e.covenant.rows.some((r) => r.limits.some((l) => l.limitId === "board-policy" && l.testedOnDate && l.breachedWith));
    const tight = e.covenant.rows.some((r) => r.limits.some((l) => l.kind === "contractual" && l.testedOnDate && l.headroomWith !== null && new Exact(l.headroomWith).lt(tightHeadroom)));
    const diligence = consent && !e.proposal.bankSawIndenture;
    const residual = e.price.history?.residualBps ?? null, guarantee = e.price.history?.steps.some((s) => s.family === "guarantee" && new Exact(s.bps).lt(0)) ?? false;
    const peakRelief = e.variants.some((v) => new Exact(v.deltas.peakYearService).lt(0));
    const lighterCollateral = e.variants.some((v) => new Exact(v.deltas.collateral).lt(0) || (!v.restrictedAccount && e.collateral.restrictedAccount));
    const usesCoveredWithoutConsent = new Set(e.alternatives.filter((a) => !a.consentRequired).flatMap((a) => a.usesCovered));
    const seasonal = e.fit.uses.filter((u) => u.kind === "seasonal_working_capital");
    const market = e.price.market?.position ?? null;
    const facts = ([["proposal_indicative", e.proposal.firmness === "indicative"], ["collateral_exceeds_assignable_portfolio", shortfall],
      ["assignment_prohibited_receivables_excluded", prohibited], ["indenture_consent_required", consent],
      ["peak_year_service_exceeds_available_cash", new Exact(peak.shortfallWith).gt(0)], ["cash_below_minimum_with_proposal", e.calendar.minimumCash.belowPolicyWith.length > 0],
      ["board_policy_breached_in_a_case", policyBreached], ["lender_tests_more_often_than_indenture", e.covenant.testsPerYear.lender > e.covenant.testsPerYear.indenture],
      ["restricted_account_requested", e.collateral.restrictedAccount], ["coverage_at_top_of_reference", e.collateral.coverageReference.atOrAboveTop]] as const).filter(([, on]) => on).map(([c]) => c);
    const readingCodes = ([["term_longer_than_seasonal_use", seasonal.some((u) => u.reading === "longer_than_use")],
      ["term_shorter_than_capex_use", e.fit.uses.some((u) => u.kind === "long_lived_capex" && u.reading === "shorter_than_use")],
      ["all_in_cost_well_above_nominal", new Exact(e.cost.nominalToEquivalentBps).gt(100)],
      ["nominal_spread_below_range", market === "below_range"], ["nominal_spread_at_or_below_median", market === "at_or_below_median"],
      ["nominal_spread_above_median_within_range", market === "above_median_within_range"], ["nominal_spread_above_range", market === "above_range"],
      ["improvement_partly_paid_in_collateral", residual !== null && new Exact(residual).gt(0) && guarantee], ["real_improvement_against_last_operation", residual !== null && !new Exact(residual).gt(0)],
      ["covenant_headroom_tight", tight], ["diligence_may_reopen_structure", diligence], ["covenant_tests_missing", e.covenant.missingTests.length > 0],
      ["net_cost_conditioned_on_taxable_profit", e.cost.netConvention === "not_all_periods_taxable" || e.cost.netConvention === "life_beyond_fiscal_calendar"]] as const).filter(([, on]) => on).map(([c]) => c);
    const recommendations = ([["address_indenture_consent_before_signing", consent], ["ask_longer_grace_and_tenor", peakRelief],
      ["ask_lower_coverage_and_no_restricted_account", lighterCollateral], ["separate_uses_by_term", e.fit.uses.every((u) => usesCoveredWithoutConsent.has(u.id))],
      ["keep_price_discussion_secondary", market === "at_or_below_median" || market === "above_median_within_range"]] as const).filter(([, on]) => on).map(([c]) => c);
    const wouldChange = ([["debtor_consent_for_restricted_receivables", prohibited && shortfall], ["indenture_clause_wording", consent], ["other_free_asset_for_collateral", consent],
      ["seasonal_need_above_adopted", seasonal.length > 0], ["committed_terms_after_diligence", e.proposal.firmness === "indicative"]] as const).filter(([, on]) => on).map(([c]) => c);
    const questions = ([["lender_covenant_definition", e.proposal.covenantDefinition === "not_stated"], ["reciprocity_expected_by_lender", e.proposal.reciprocity === "none_stated"],
      ["restricted_debtor_consent", prohibited && shortfall], ["indenture_clause_wording", consent], ["other_free_asset", consent]] as const).filter(([, on]) => on).map(([c]) => c);
    return {
      firmness: {firmness: e.proposal.firmness, validUntil: e.proposal.validUntil, bankSawIndenture: e.proposal.bankSawIndenture, diligenceMayReopenStructure: diligence},
      liquidity: {peakYear: peak.year, existingService: peak.existingService, proposalService: peak.proposalService, totalService: peak.totalService, availableForService: peak.availableForService,
        peakQuarter: e.calendar.peakQuarter.periodEnd, minimumCashWith: e.calendar.minimumCash.with,
        firstBelowPolicyWith: e.calendar.minimumCash.belowPolicyWith[0] ?? null, firstBelowPolicyWithout: e.calendar.minimumCash.belowPolicyWithout[0] ?? null},
      fit: {seasonalShare: e.fit.seasonalShare, weightedAverageLifeYears: e.fit.weightedAverageLifeYears, finalPaymentDate: e.proposal.finalPaymentDate,
        uses: e.fit.uses.map((u) => ({id: u.id, amount: u.amount, reading: u.reading}))},
      covenant: {rows: e.covenant.rows.map((r) => ({date: r.date, scenario: r.scenario, ratioWith: r.ratioWith,
        headroom: r.limits.map((l) => ({limitId: l.limitId, testedOnDate: l.testedOnDate, headroomWith: l.headroomWith, breachedWith: l.breachedWith}))})), testsPerYear: e.covenant.testsPerYear,
        anyBreachWith: e.covenant.anyBreachWith, missingTests: e.covenant.missingTests, untestedLimits: e.covenant.untestedLimits, lenderDatesBeforeDraw: e.covenant.lenderDatesBeforeDraw},
      collateral: {required: e.collateral.required, nominallyFree: e.collateral.portfolio.nominallyFree, assignable: e.collateral.portfolio.assignable,
        shortfallToAssignable: e.collateral.shortfallToAssignable, assignableLeftAfter: e.collateral.assignableLeftAfter, seasonalPeak: e.collateral.seasonalPeak,
        excluded: e.collateral.portfolio.buckets.filter((b) => !b.assignable).map((b) => ({id: b.id, amount: b.amount, holder: b.holder, reasons: b.reasons})),
        coverage: e.collateral.coverage, restrictedAccount: e.collateral.restrictedAccount},
      negativePledge: {basis: e.negativePledge.basis, limit: e.negativePledge.limit, occupied: e.negativePledge.occupied, remaining: e.negativePledge.remaining, consentRequired: consent,
        excess: e.negativePledge.excess, consentBy: e.negativePledge.consentWindow.by, needDate: e.negativePledge.consentWindow.needDate, slackDays: e.negativePledge.consentWindow.slackDays},
      price: {nominalSpread: e.proposal.annualSpread, equivalentSpread: e.cost.equivalentSpread, equivalentSpreadNet: e.cost.equivalentSpreadNet, netConvention: e.cost.netConvention, upfrontShare: e.cost.upfrontShare,
        creditTaxRate: e.cost.creditTaxRate, weightedAverageLifeYears: e.cost.weightedAverageLifeYears, marketPosition: market,
        history: e.price.history ? {observedBps: e.price.history.observedBps, expectedBps: e.price.history.expectedBps, residualBps: e.price.history.residualBps} : null},
      asks: e.variants.map((v) => ({id: v.id, label: v.label, peakYearServiceDelta: v.deltas.peakYearService, equivalentSpreadDeltaBps: v.deltas.equivalentSpreadBps,
        collateralDelta: v.deltas.collateral, consentStillRequired: v.collateral.consentRequired, netConvention: v.netConvention, restrictedAccount: v.restrictedAccount})),
      alternatives: e.alternatives.map((a) => ({id: a.id, usesCovered: a.usesCovered, allInSpreadDifferenceBps: a.allInSpreadDifferenceBps, consentRequired: a.consentRequired})),
      assessment: {facts: [...facts], readings: [...readingCodes], recommendations: [...recommendations], wouldChange: [...wouldChange]}, questions: [...questions],
      process: {acceptsProposal: false as const, contactsLender: false as const, counterproposalSent: false as const},
    };
  })() : null;
  const prefix = `received_proposal.${input.analysis.analysisId}.`;
  const gaps = [...result.gaps,
    ...(e && !e.price.market ? [{operand: prefix + "market", reason: "Referência de mercado abaixo do limiar de comparabilidade ou ausente; o preço não é comparado ao mercado"}] : []),
    ...(e && !e.price.history ? [{operand: prefix + "history", reason: "Sem operação anterior comparável; a ponte contra o histórico da companhia não roda"}] : []),
    ...(e && e.cost.netConvention === "regime_unknown" ? [{operand: prefix + "tax.regime", reason: "Regime tributário não informado; custo líquido não calculado"}] : []),
    ...(e && e.cost.netConvention === "not_all_periods_taxable" ? [{operand: prefix + "calendar.taxable", reason: "Há períodos sem lucro tributável na vida da proposta; o custo líquido pela convenção de dedução plena não é afirmado"}] : []),
    ...(e && e.cost.netConvention === "life_beyond_fiscal_calendar" ? [{operand: prefix + "tax.taxableAfterCalendar", reason: `A proposta vai até ${e.proposal.finalPaymentDate}, além do calendário fiscal; sem hipótese adotada para esses períodos, o custo líquido não é afirmado`}] : []),
    ...(e?.variants ?? []).filter((v) => v.netConvention === "life_beyond_fiscal_calendar" || v.netConvention === "not_all_periods_taxable").map((v) => ({operand: `${prefix}variant.${v.id}.net`,
      reason: v.netConvention === "life_beyond_fiscal_calendar" ? `A variante vai até ${v.finalPaymentDate}, além do calendário fiscal; custo líquido não afirmado` : "Há período sem lucro tributável na vida da variante; custo líquido não afirmado"})),
    ...(e?.covenant.untestedLimits ?? []).map((l) => ({operand: `${prefix}covenant.limit.${l}`, reason: `Nenhuma apuração adotada nas datas de teste do limite ${l}; o limite não é testado`})),
    ...(e?.covenant.missingTests ?? []).map((m) => ({operand: `${prefix}covenant.${m.scenario}.${m.date}`, reason: `Apuração exigida de ${m.date} no cenário ${m.scenario} não adotada; nenhuma conclusão de cumprimento sem ela`}))];
  const openQuestions = result.gaps.some((g) => g.operand.endsWith(".proposal.indexer")) ? ["indexer_confirmation" as const] : [];
  const status = !e ? "framed" as const : gaps.length ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "received-proposal-packet.v1" as const, executorVersion: receivedProposalPacketVersion, financialCoreVersion,
    question: input.question, basisFingerprint: result.basisFingerprint, scope: result.scope, entityId: result.entityId, currency: result.currency,
    result, readings, gaps, openQuestions, status, exclusions: [...receivedProposalPacketExclusions],
    grantsExecution: false as const, grantsPublication: false as const};
  return receivedProposalPacketOutputSchema.parse({...payload, fingerprint: receivedProposalFingerprint(payload)});
}

import {createHash} from "node:crypto";
import {describe, expect, it} from "vitest";
import type {AdoptionBasisEntry, AdoptionBasisSnapshot} from "@offroad/reconciliation";
import {composeBoundReceivedProposal} from "./evaluate-received-proposal-composer";
import {prepareReceivedProposalPacket} from "./evaluate-received-proposal-packet";
import {proposeReceivedProposalHypotheses, type ReceivedProposalFacts} from "./evaluate-received-proposal-premises";
import {auroraReceivedProposalBasis, auroraReceivedProposalFacts, receivedProposalQuestion as question} from "./evaluate-received-proposal.test-support";
import {analysisTestId as id} from "./adopted-analysis.test-support";

function envelopeOf(entries: AdoptionBasisEntry[]) {
  const snapshot: AdoptionBasisSnapshot = {schemaVersion: "contextual-adoption.v1", versionId: id(500), setId: id(6), workId: id(7), purpose: "synthetic received proposal",
    contextKey: "proposta-recebida", revision: 1, previousVersionId: null, classification: "working_basis", entries};
  const canonical = JSON.stringify(snapshot);
  return {envelope: {canonical, fingerprint: createHash("sha256").update(canonical).digest("hex")}, scope: {workId: id(7), purpose: snapshot.purpose, versionId: id(500)}};
}
function adopt(facts: ReceivedProposalFacts) {
  let n = 9000;
  const entries = proposeReceivedProposalHypotheses(facts).map((h) => ({decisionId: id(n++), slotKey: createHash("sha256").update(h.fieldPath + h.dimensions.scenario).digest("hex"),
    kind: "hypothesis", fieldPath: h.fieldPath, dimensions: {...h.dimensions}, value: h.value, observationId: null, referenceValue: null, referenceDimensions: null,
    definitionKind: "managerial", actorId: id(5), reason: h.reason}) as AdoptionBasisEntry);
  return {entries, ...envelopeOf(entries)};
}
const packetOf = (b: ReturnType<typeof envelopeOf>) => prepareReceivedProposalPacket(composeBoundReceivedProposal({envelope: b.envelope, scope: b.scope, question}));

describe("ficha 1 premises proposed from facts with origin, adopted, composed and measured", {timeout: 300_000}, () => {
  it("stays inside the basis limit and states the origin of every premise", () => {
    const h = proposeReceivedProposalHypotheses(auroraReceivedProposalFacts());
    expect(h.length).toBeLessThanOrEqual(256);
    expect(h.every((x) => x.reason.startsWith("Origem: "))).toBe(true);
    expect(h.find((x) => x.fieldPath.endsWith(".proposal.drawDate"))!.reason).toMatch(/^Origem: estimativa\./);
    expect(h.find((x) => x.fieldPath.endsWith(".proposal.annualSpread"))!.reason).toMatch(/^Origem: documento\./);
    expect(h.find((x) => x.fieldPath.endsWith(".market.median"))!.reason).toMatch(/^Origem: faixa de mercado\./);
  });
  it("reproduces the hand-built basis: same readings and numbers", () => {
    const p = packetOf(envelopeOf(adopt(auroraReceivedProposalFacts()).entries));
    const reference = prepareReceivedProposalPacket({schemaVersion: "received-proposal-packet-input.v1", question, analysis: auroraReceivedProposalBasis().seal()});
    expect(p.status).toBe(reference.status);
    expect(p.readings).toEqual(reference.readings);
    expect(p.result.evaluation).toEqual(reference.result.evaluation);
    expect([p.readings!.collateral.assignable, p.readings!.negativePledge.remaining]).toEqual(["25.41", "3"]);
  });
  it("declares an absent mandatory operand missing and leaves an absent optional group null", () => {
    const a = adopt(auroraReceivedProposalFacts());
    const gapped = packetOf(envelopeOf(a.entries.filter((e) => !e.fieldPath.endsWith(".basket.occupied"))));
    expect(gapped.status).toBe("framed");
    expect(gapped.gaps.some((g) => g.operand.endsWith(".basket.occupied") && g.reason.startsWith("No contribution adopted for basket.occupied"))).toBe(true);
    const facts = auroraReceivedProposalFacts(); facts.policy = null; facts.history = null;
    const input = composeBoundReceivedProposal({...envelopeOf(adopt(facts).entries), question});
    expect([input.analysis.covenant.policyLimit, input.analysis.history]).toEqual([null, null]);
    expect(packetOf(envelopeOf(adopt(facts).entries)).status).toBe("partial");
  });
  it("reports two contributions for one slot as missing, never picks one", () => {
    const a = adopt(auroraReceivedProposalFacts()), twin = a.entries.find((e) => e.fieldPath.endsWith(".basket.basis"))!;
    const entries = [...a.entries, {...twin, decisionId: id(9999), slotKey: "f".repeat(64), value: {type: "text" as const, value: "per_operation"}}];
    const input = composeBoundReceivedProposal({...envelopeOf(entries), question});
    expect(input.analysis.basket.basis.missingReason).toContain("2 contributions match basket.basis");
    expect(packetOf(envelopeOf(entries)).status).toBe("framed");
  });
  it("composes every listed or named bucket and never drops one silently", () => {
    const a = adopt(auroraReceivedProposalFacts()), order = a.entries.find((e) => e.fieldPath.endsWith(".order.buckets"))!;
    const unlisted = a.entries.map((e) => e === order ? {...e, value: {type: "list" as const, value: (e.value.value as string[]).filter((x) => x !== "rede-a")}} : e);
    expect(composeBoundReceivedProposal({...envelopeOf(unlisted), question}).analysis.portfolio.map((b) => b.id).at(-1)).toBe("rede-a");
    expect(packetOf(envelopeOf(unlisted)).readings!.collateral.assignable).toBe("25.41");
  });
  it("never assumes the indexer: absent, it is asked; estimated, it is refused", () => {
    const facts = auroraReceivedProposalFacts(); facts.indexer = null;
    const h = proposeReceivedProposalHypotheses(facts);
    expect(h.some((x) => x.fieldPath.endsWith(".proposal.indexer"))).toBe(false);
    const q = packetOf(envelopeOf(adopt(facts).entries));
    expect([q.status, q.openQuestions, q.gaps.some((g) => g.operand.endsWith(".proposal.indexer"))]).toEqual(["framed", ["indexer_confirmation"], true]);
    expect(h.length).toBe(proposeReceivedProposalHypotheses(auroraReceivedProposalFacts()).length - 1);
    const guessed = auroraReceivedProposalFacts(); guessed.indexer = {value: "cdi_plus", origin: "estimate", source: "provavelmente CDI"};
    expect(() => proposeReceivedProposalHypotheses(guessed)).toThrow("never assumed");
    const reason = proposeReceivedProposalHypotheses(auroraReceivedProposalFacts()).find((x) => x.fieldPath.endsWith(".proposal.indexer"))!.reason;
    expect(reason).toBe("Origem: documento. term sheet do Itaú: CDI mais 2,10% ao ano");
  });
  it("refuses generated tax rates outside [0, 1] in the facts and proposes those inside", () => {
    let seed = 20261027; const next = () => {seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648;};
    for (let k = 0; k < 60; k++) {
      const rate = (Math.floor(next() * 30000) / 10000).toFixed(4), facts = auroraReceivedProposalFacts(); facts.tax.value.rate = rate;
      if (Number(rate) > 1) expect(() => proposeReceivedProposalHypotheses(facts)).toThrow("Tax rate outside [0, 1]");
      else expect(proposeReceivedProposalHypotheses(facts).find((h) => h.fieldPath.endsWith(".tax.rate"))!.value).toEqual({type: "number", value: rate});
    }
  });
  it("refuses a rate just above one in the facts and composes an absence of every covenant test into gaps", () => {
    const high = auroraReceivedProposalFacts(); high.tax.value.rate = "1.00000000000000000001";
    expect(() => proposeReceivedProposalHypotheses(high)).toThrow("Tax rate outside [0, 1]");
    const none = auroraReceivedProposalFacts(); none.measurements.value = [];
    const q = packetOf(envelopeOf(adopt(none).entries));
    expect([q.status, q.readings!.covenant.anyBreachWith, q.readings!.covenant.untestedLimits, q.readings!.covenant.missingTests.length]).toEqual(["partial", null, ["indenture", "proposal", "board-policy"], 10]);
  });
  it("from facts to packet: a repeated test date is refused in every list and permutations change no derived field", () => {
    let seed = 20261027; const next = () => {seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648;};
    const shuffle = <T>(xs: readonly T[]) => {const y = [...xs]; for (let a = y.length - 1; a > 0; a--) {const b = Math.floor(next() * (a + 1)); [y[a], y[b]] = [y[b]!, y[a]!];} return y;};
    type Facts = ReturnType<typeof auroraReceivedProposalFacts>;
    const lists: [string, (f: Facts) => string[], (f: Facts, v: string[]) => void][] = [
      ["indenture", (f) => f.indenture.value.testDates, (f, v) => {f.indenture.value.testDates = v;}],
      ["policy", (f) => f.policy!.value.testDates, (f, v) => {f.policy!.value.testDates = v;}],
      ["lender", (f) => f.proposal.value.covenant!.testDates, (f, v) => {f.proposal.value.covenant!.testDates = v;}]];
    const facts = () => {const f = auroraReceivedProposalFacts(); f.variants = []; return f;};
    for (const [name, get, set] of lists) {
      const f = facts(), d = get(f); set(f, [...d, d[Math.floor(next() * d.length)]!]);
      expect(() => proposeReceivedProposalHypotheses(f)).toThrow(`received_proposal_duplicate_test_date: ${name}`);
    }
    const twin = facts(); twin.measurements.value = [...twin.measurements.value, twin.measurements.value[0]!];
    expect(() => proposeReceivedProposalHypotheses(twin)).toThrow("received_proposal_covenant_duplicate_test");
    const reference = packetOf(envelopeOf(adopt(facts()).entries));
    expect(reference.readings!.assessment.facts.includes("lender_tests_more_often_than_indenture")).toBe(true);
    for (const [, get, set] of [...lists, ["measurements", () => [], () => undefined] as const]) {
      const f = facts();
      if (get(f).length) set(f, shuffle(get(f))); else f.measurements.value = shuffle(f.measurements.value);
      const p = packetOf(envelopeOf(adopt(f).entries));
      expect(p.readings).toEqual(reference.readings);
      expect(p.result.evaluation).toEqual(reference.result.evaluation);
    }
  });
  it("refuses inconsistent facts before proposing premises", () => {
    const holder = auroraReceivedProposalFacts(); holder.portfolio[1]!.value.holder = null;
    expect(() => proposeReceivedProposalHypotheses(holder)).toThrow("names the holder of its assignment");
    const free = auroraReceivedProposalFacts(); free.portfolio[3]!.value.countsAgainstBasket = true;
    expect(() => proposeReceivedProposalHypotheses(free)).toThrow("cannot occupy the basket");
    const test = auroraReceivedProposalFacts(); test.measurements.value[0]!.date = "2026-11-30";
    expect(() => proposeReceivedProposalHypotheses(test)).toThrow("is not a period end");
    const precise = auroraReceivedProposalFacts(); precise.proposal.value.amount = "30.123456789";
    expect(() => proposeReceivedProposalHypotheses(precise)).toThrow();
