  const setup = `<pageSetup orientation="${orientation}" paperSize="9" fitToWidth="1" fitToHeight="0"/>`;
  const before = xml.includes("</worksheet>") ? "</worksheet>" : "";
  return before ? xml.replace(before, `${margins}${setup}${before}`) : xml;
