import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import type {ReconciledFact} from "@offroad/reconciliation";
import {validateAssumptionBook, type AssumptionUnit} from "./assumptions";
import type {InstitutionalModelInput, OpeningBalanceSheet, RevenueSegmentDriver, OperatingCostDriver, TaxDrivers} from "./institutional-model";

export type InstitutionalModelSource = {
  sourceDocument: string;
  version: string;
  hash: string;
  asOfDate: string;
  /** Denomination of selected historical amounts, explicitly reviewed upstream. */
  currency: string | null;
  amountScale: "units" | "thousands" | "millions" | null;
};
export type InstitutionalFactSelection = {
  fieldPath: string;
  periodEnd: string;
  /** Required for flow amounts; omit for opening balance-sheet stocks. */
  periodStart?: string;
  entityName: string;
  entityScope: "consolidated" | "standalone" | "segment";
  sourceDocument: string;
  sourceVersion: string;
  sourceHash: string;
};
type OpeningAmount = Exclude<keyof OpeningBalanceSheet,"period">;
type CostSelection = Extract<OperatingCostDriver,{method:"percent_of_revenue"}>
  | (Omit<Extract<OperatingCostDriver,{method:"base_and_growth"}>,"baseCost"> & {baseCost:InstitutionalFactSelection});
export type InstitutionalModelConfiguration = Omit<InstitutionalModelInput,"openingBalanceSheet"|"revenueSegments"|"operatingCosts"|"taxes"> & {
  absenceConfirmations?: {debtInstruments?: {confirmedBy:string;confirmedAt:string;rationale:string};capex?: {confirmedBy:string;confirmedAt:string;rationale:string}};
  openingBalanceSheet: {period:string; bindings:Record<OpeningAmount,InstitutionalFactSelection>};
  revenueSegments: readonly (Omit<RevenueSegmentDriver,"baseRevenue"> & {baseRevenue:InstitutionalFactSelection})[];
  operatingCosts: readonly CostSelection[];
  taxes: Omit<TaxDrivers,"openingTaxLossCarryforward"|"openingDisallowedInterestCarryforward"> & {
    openingTaxLossCarryforward:InstitutionalFactSelection;
    openingDisallowedInterestCarryforward:InstitutionalFactSelection;
  };
};
export type InstitutionalModelInputGap = {
  targetPath:string;
  code:"configuration_required"|"fact_missing"|"fact_ambiguous"|"fact_disputed"|"fact_invalid"|"source_unbound"|"period_mismatch"|"unit_mismatch"|"configuration_invalid"|"assumption_invalid";
  detail:string;
};
export type InstitutionalFactLineage = {
  targetPath:string;fieldPath:string;periodStart?:string;periodEnd:string;entityName:string;entityScope:string;
  value:string;sourceDocument:string;sourceVersion:string;sourceHash:string;sourceAsOfDate:string;anchor:unknown;
};
export type PreparedInstitutionalModelInput = {
  status:"ready"|"missing_inputs";
  input:InstitutionalModelInput|null;
  missingInputs:readonly InstitutionalModelInputGap[];
  lineage:readonly InstitutionalFactLineage[];
  inputFingerprint:string|null;
  sourceBindings:readonly InstitutionalModelSource[];
  configurationFingerprint:string;
  limitations:readonly string[];
};
const openingFields:readonly OpeningAmount[]=["unrestrictedCash","restrictedCash","receivables","inventory","otherCurrentAssets","netPpe","otherAssets","payables","otherCurrentLiabilities","grossDebt","otherLiabilities","equity"];
const validDate=(value:string)=> /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(`${value}T00:00:00Z`)) && new Date(`${value}T00:00:00Z`).toISOString().slice(0,10)===value;
const hash=(value:unknown)=>createHash("sha256").update(stableJson(value)).digest("hex");
function stableJson(value:unknown):string {
  if(Array.isArray(value))return `[${value.map(stableJson).join(",")}]`;
  if(value!==null&&typeof value==="object")return `{${Object.entries(value).filter(([,v])=>v!==undefined).sort(([a],[b])=>a<b?-1:a>b?1:0).map(([k,v])=>`${JSON.stringify(k)}:${stableJson(v)}`).join(",")}}`;
  return JSON.stringify(value);
}

/** Assemble existing reconciled facts and a reviewed scenario configuration without defaults.
 * This pure adapter does not verify tenant authority, documents or scenario approval: callers
 * must supply those through their governed readers. Missing inputs never become zero balances.
 */
export function prepareInstitutionalModelInput(request:{
  facts:readonly ReconciledFact[];
  sources:readonly InstitutionalModelSource[];
  configuration?:InstitutionalModelConfiguration;
}):PreparedInstitutionalModelInput {
  const missingInputs:InstitutionalModelInputGap[]=[];
  const lineage:InstitutionalFactLineage[]=[];
  const limitations=[
    "Annual model only; all historical amounts must be explicitly denominated in model-currency units.",
    "Historical balances and drivers use one evidenced entity/perimeter; cross-entity consolidation requires a separately reviewed mapping and is not inferred here.",
    "Source versions, denomination and scenario configuration are supplied by governed callers; this adapter is not an authorization or document-verification boundary.",
    "Readiness assembles inputs only; arithmetic review, sector applicability and release approval remain separate.",
  ];
  const gap=(targetPath:string,code:InstitutionalModelInputGap["code"],detail:string)=>{missingInputs.push({targetPath,code,detail});};
  const blocked=():PreparedInstitutionalModelInput=>({status:"missing_inputs",input:null,missingInputs,lineage,inputFingerprint:null,sourceBindings:[],configurationFingerprint:hash(request.configuration??null),limitations});
  const config=request.configuration;
  if(!config){gap("configuration","configuration_required","A reviewed assumption book, instrument ledger and explicit historical selections are required.");return blocked();}
  const openingYear=config.openingBalanceSheet.period;
  const periods=config.assumptionBook.periods;
  if(!/^\d{4}$/.test(openingYear)||periods.length===0||periods.some((p,i)=>!/^\d{4}$/.test(p)||Number(p)!==Number(openingYear)+i+1))gap("periods","period_mismatch","Opening and forecast periods must be consecutive annual years.");
  if(!validDate(config.assumptionBook.asOfDate))gap("assumptionBook.asOfDate","configuration_invalid","A real as-of date is required.");
  if(!/^[A-Z]{3}$/.test(config.currency))gap("currency","unit_mismatch","An explicit model currency is required.");
  const asOf=config.assumptionBook.asOfDate;
  const select=(selection:InstitutionalFactSelection|undefined,targetPath:string,flow=false):string|null=>{
    if(!selection){gap(targetPath,"fact_missing","An explicit historical fact selection is required, including an evidenced zero when applicable.");return null;}
    if(!selection.entityName?.trim()||!["consolidated","standalone","segment"].includes(selection.entityScope)){
      gap(targetPath,"fact_invalid","Entity and perimeter must be explicit.");return null;
    }
    if(!validDate(selection.periodEnd)||selection.periodEnd!==`${openingYear}-12-31`||selection.periodEnd>asOf
      ||(flow&&selection.periodStart!==`${openingYear}-01-01`)){
      gap(targetPath,"period_mismatch","Historical opening stocks and annual flows must match the selected base period before the model as-of date.");return null;
    }
    // Current observations coexist. An explicit source selection, never ranking, chooses input.
    // Pre-observation snapshots retain their original shape as a labelled compatibility input.
    const candidates=request.facts.flatMap(f=>{
      const observations=f.observations??[f.accepted];
      return observations.filter(o=>o.fieldPath===selection.fieldPath&&o.periodEnd===selection.periodEnd
        &&o.entityName===selection.entityName&&o.entityScope===selection.entityScope&&o.sourceDocument===selection.sourceDocument)
        .map(observation=>({observation,legacy:f.observations===undefined,parent:f}));
    });
    if(candidates.length!==1){gap(targetPath,candidates.length?"fact_ambiguous":"fact_missing","Exactly one observation must match the selected field, period, entity, perimeter and source.");return null;}
    const {observation:fact,legacy,parent}=candidates[0]!;
    if(legacy&&parent.disputed){gap(targetPath,"fact_disputed","The historical snapshot is disputed; supply an explicit observation selection.");return null;}
    if(fact.valueType!=="number"||!fact.anchorVerified||fact.anchor===undefined||fact.anchor===null||stableJson(fact.anchor)==="{}"
      ||(flow&&fact.periodStart!==selection.periodStart)||/project|forecast|budget/i.test(fact.informationClass)
      ||! /^(historical_financials|interim_financials)\./.test(selection.fieldPath)
      ||(legacy&&(parent.key.fieldPath!==selection.fieldPath||parent.key.periodEnd!==selection.periodEnd||parent.key.entityName!==selection.entityName))){
      gap(targetPath,"fact_invalid","Use an anchored historical numeric observation with matching period and entity, never a projection substituted for history.");return null;
    }
    try{
      if(!new Decimal(fact.normalizedValue).isFinite()||(legacy&&!new Decimal(parent.value).eq(fact.normalizedValue)))throw new Error();
    }catch{gap(targetPath,"fact_invalid","The selected numeric observation must be finite and historical snapshots must remain internally consistent.");return null;}
    const sources=request.sources.filter(s=>s.sourceDocument===selection.sourceDocument);
    const source=sources.length===1?sources[0]:undefined;
    if(!source||!source.version.trim()||! /^[a-f0-9]{64}$/i.test(source.hash)||source.version!==selection.sourceVersion
      ||source.hash!==selection.sourceHash||!validDate(source.asOfDate)||source.asOfDate>asOf){
      gap(targetPath,"source_unbound","The selected source version/hash must match one dated current source declaration.");return null;
    }
    if(source.currency!==config.currency||source.amountScale!=="units"){
      gap(targetPath,"unit_mismatch","Historical values must already be normalized to model-currency units; source presentation scale must not be applied twice.");return null;
    }
    lineage.push({targetPath,fieldPath:selection.fieldPath,...(selection.periodStart?{periodStart:selection.periodStart}:{}),periodEnd:selection.periodEnd,
      entityName:selection.entityName,entityScope:selection.entityScope,value:fact.normalizedValue,sourceDocument:source.sourceDocument,
      sourceVersion:source.version,sourceHash:source.hash,sourceAsOfDate:source.asOfDate,anchor:fact.anchor});
    return fact.normalizedValue;
  };
  const values:Partial<Record<OpeningAmount,string>>={};
  const openingSelections=openingFields.map(field=>config.openingBalanceSheet.bindings[field]).filter(Boolean);
  if(new Set(openingSelections.map(s=>`${s.entityName}|${s.entityScope}`)).size>1)gap("openingBalanceSheet","configuration_invalid","Opening balances must belong to one explicit entity and perimeter; do not consolidate by addition.");
  for(const field of openingFields){const value=select(config.openingBalanceSheet.bindings[field],`openingBalanceSheet.${field}`);if(value!==null)values[field]=value;}
  const perimeter=openingSelections[0];
  const driverSelections=[...config.revenueSegments.map(s=>s.baseRevenue),...config.operatingCosts.flatMap(c=>c.method==="base_and_growth"?[c.baseCost]:[]),config.taxes.openingTaxLossCarryforward,config.taxes.openingDisallowedInterestCarryforward];
  if(perimeter&&driverSelections.some(s=>s&&(s.entityName!==perimeter.entityName||s.entityScope!==perimeter.entityScope)))gap("historicalPerimeter","configuration_invalid","Historical drivers and tax balances must match the opening entity/perimeter; consolidation relationships are not inferred.");
  const revenueSegments=config.revenueSegments.map(segment=>({...segment,baseRevenue:select(segment.baseRevenue,`revenueSegments.${segment.id}.baseRevenue`,true)}));
  const operatingCosts=config.operatingCosts.map(cost=>cost.method==="percent_of_revenue"?cost:{...cost,baseCost:select(cost.baseCost,`operatingCosts.${cost.id}.baseCost`,true)});
  const openingTaxLossCarryforward=select(config.taxes.openingTaxLossCarryforward,"taxes.openingTaxLossCarryforward");
  const openingDisallowedInterestCarryforward=select(config.taxes.openingDisallowedInterestCarryforward,"taxes.openingDisallowedInterestCarryforward");
  for(const [path,rows] of [["revenueSegments",config.revenueSegments],["operatingCosts",config.operatingCosts],["capex",config.capex],["debtInstruments",config.debtInstruments]] as const){
    const ids=rows.map(row=>"id" in row?row.id:row.instrumentId);
    const absence = path === "capex" || path === "debtInstruments" ? config.absenceConfirmations?.[path] : undefined;
    const confirmedAbsent = absence && absence.confirmedBy.trim() && absence.rationale.trim() && Number.isFinite(Date.parse(absence.confirmedAt));
    if((!ids.length&&!confirmedAbsent)||ids.some(id=>!id.trim())||new Set(ids).size!==ids.length)gap(path,"configuration_invalid","Explicit unique driver/instrument identities or reviewed confirmation of no debt/capex are required.");
    if(ids.length&&absence)gap(path,"configuration_invalid","Absence confirmation conflicts with supplied instruments or capex.");
  }
  const requireAssumption=(id:string|undefined,unit:AssumptionUnit,path:string)=>{
    const assumption=config.assumptionBook.assumptions.find(a=>a.id===id);
    if(!assumption){gap(path,"assumption_invalid","An explicit governed assumption is required, including zero or no-change premises.");return;}
    if(assumption.unit!==unit)gap(path,"unit_mismatch",`Assumption ${id} must use ${unit}.`);
  };
  for(const segment of config.revenueSegments){for(const id of [segment.volumeGrowthAssumptionId,segment.priceGrowthAssumptionId,segment.mixEffectAssumptionId,segment.fxEffectAssumptionId])requireAssumption(id,"percent",`revenueSegments.${segment.id}`);requireAssumption(segment.inorganicRevenueAssumptionId,"currency",`revenueSegments.${segment.id}.inorganic`);}
  for(const cost of config.operatingCosts)requireAssumption(cost.method==="percent_of_revenue"?cost.ratioAssumptionId:cost.growthAssumptionId,"percent",`operatingCosts.${cost.id}`);
  for(const item of config.capex)requireAssumption(item.amountAssumptionId,"currency",`capex.${item.id}`);
  for(const id of [config.existingAssetDepreciationAssumptionId,config.distributionsAssumptionId,config.minimumOperatingCashAssumptionId])requireAssumption(id,"currency","cashAndDepreciation");
  for(const id of [config.workingCapital.dsoAssumptionId,config.workingCapital.dioAssumptionId,config.workingCapital.dpoAssumptionId])requireAssumption(id,"days","workingCapital");
  for(const id of [config.workingCapital.otherCurrentAssetsPctRevenueAssumptionId,config.workingCapital.otherCurrentLiabilitiesPctRevenueAssumptionId,config.taxes.cashTaxRateAssumptionId])requireAssumption(id,"percent","workingCapitalAndTax");
  if(config.taxes.interestDeductibilityEbitdaPctAssumptionId)requireAssumption(config.taxes.interestDeductibilityEbitdaPctAssumptionId,"percent","taxes.interestLimit");
  for(const id of [config.minimumDscrAssumptionId,config.maximumNetLeverageAssumptionId])if(id)requireAssumption(id,"multiple","covenants");
  for(const issue of validateAssumptionBook(config.assumptionBook).filter(i=>i.severity==="blocker"))gap(`assumptionBook.${issue.assumptionId??"book"}`,"assumption_invalid",issue.message);
  for(const instrument of config.debtInstruments){
    if(instrument.periods.map(p=>p.period).join("|")!==periods.join("|"))gap(`debtInstruments.${instrument.instrumentId}`,"period_mismatch","Debt periods must match the annual model horizon.");
    for(const row of instrument.periods){
      if(row.drawdown===undefined||(!row.repayAll&&(row.scheduledPrincipal===undefined||row.prepayment===undefined)))gap(`debtInstruments.${instrument.instrumentId}.${row.period}`,"configuration_invalid","Explicit drawdown and repayment premises are required; absence is not a zero cash flow.");
    }
  }
  for(const assumption of config.assumptionBook.assumptions)for(const evidence of assumption.evidence){
    const sources=request.sources.filter(s=>s.sourceDocument===evidence.sourceId);
    if(sources.length!==1||!validDate(sources[0]!.asOfDate)||sources[0]!.asOfDate>asOf||!sources[0]!.version.trim()||! /^[a-f0-9]{64}$/i.test(sources[0]!.hash)||sources[0]!.asOfDate!==evidence.asOfDate)gap(`assumptionBook.${assumption.id}`,"source_unbound","Assumption evidence must resolve to one dated versioned source declaration.");
  }
  for(const instrument of config.debtInstruments)for(const row of instrument.periods){
    const links=config.debtRateLineage.filter(link=>link.instrumentId===instrument.instrumentId&&link.period===row.period);
    if(links.length!==1){gap(`debtRateLineage.${instrument.instrumentId}.${row.period}`,"source_unbound","Exactly one rate lineage entry is required per instrument and period.");continue;}
    const link=links[0]!;
    for(const [id,date] of [[link.indexationSourceId,link.indexationAsOfDate],[link.couponSourceId,link.couponAsOfDate]]){
      const sources=request.sources.filter(s=>s.sourceDocument===id);
      if(sources.length!==1||sources[0]!.asOfDate!==date||!validDate(date!)||date!>asOf||!sources[0]!.version.trim()||! /^[a-f0-9]{64}$/i.test(sources[0]!.hash))gap(`debtRateLineage.${instrument.instrumentId}.${row.period}`,"source_unbound","Rate lineage must resolve to a dated versioned source declaration.");
    }
  }
  if(missingInputs.length)return blocked();
  const input:InstitutionalModelInput={...config,
    openingBalanceSheet:{period:openingYear,...values} as OpeningBalanceSheet,
    revenueSegments:revenueSegments as RevenueSegmentDriver[],operatingCosts:operatingCosts as OperatingCostDriver[],
    taxes:{...config.taxes,openingTaxLossCarryforward:openingTaxLossCarryforward!,openingDisallowedInterestCarryforward:openingDisallowedInterestCarryforward!},
  };
  // Detach the snapshot from mutable workflow JSON and anchors before fingerprinting.
  const snapshot=JSON.parse(JSON.stringify(input)) as InstitutionalModelInput;
  const lineageSnapshot=JSON.parse(JSON.stringify(lineage)) as InstitutionalFactLineage[];
  const usedSourceIds=new Set([...lineage.map(link=>link.sourceDocument),...config.assumptionBook.assumptions.flatMap(a=>a.evidence.map(e=>e.sourceId)),...config.debtRateLineage.flatMap(link=>[link.indexationSourceId,link.couponSourceId])]);
  const sourceBindings=request.sources.filter(source=>usedSourceIds.has(source.sourceDocument)).map(source=>({...source})).sort((a,b)=>a.sourceDocument<b.sourceDocument?-1:a.sourceDocument>b.sourceDocument?1:0);
  return {status:"ready",input:snapshot,missingInputs:[],lineage:lineageSnapshot,sourceBindings,configurationFingerprint:hash(config),inputFingerprint:hash({input:snapshot,lineage:lineageSnapshot,sourceBindings}),limitations};
}

/** Exact scenario/configuration identity used for optimistic answer application. */
export const fingerprintInstitutionalModelConfiguration=(configuration:InstitutionalModelConfiguration)=>hash(configuration);

import {
  aggregateIndexedDebtSchedules,
  calculateAnnualCapexDepreciation,
  buildIndexedDebtSchedule,
  type IndexedDebtInstrumentInput,
} from "@offroad/financial-core";
import Decimal from "decimal.js";

import {assumptionValue, validateAssumptionBook, type AssumptionBook} from "./assumptions";

export type OpeningBalanceSheet = {
  period: string;
  unrestrictedCash: string;
  restrictedCash: string;
  receivables: string;
  inventory: string;
  otherCurrentAssets: string;
  netPpe: string;
  otherAssets: string;
  payables: string;
  otherCurrentLiabilities: string;
  grossDebt: string;
  otherLiabilities: string;
  equity: string;
};

export type RevenueSegmentDriver = {
  id: string;
  baseRevenue: string;
  volumeGrowthAssumptionId: string;
  priceGrowthAssumptionId: string;
  mixEffectAssumptionId: string;
  fxEffectAssumptionId: string;
  inorganicRevenueAssumptionId: string;
};

export type OperatingCostDriver =
  | {id: string; method: "percent_of_revenue"; ratioAssumptionId: string}
  | {id: string; method: "base_and_growth"; baseCost: string; growthAssumptionId: string};

export type CapexDriver = {
  id: string;
  classification: "maintenance" | "growth";
  amountAssumptionId: string;
  usefulLifeYears: number;
  depreciationConvention: "next_period" | "half_year";
};

export type WorkingCapitalDrivers = {
  dsoAssumptionId: string;
  dioAssumptionId: string;
  dpoAssumptionId: string;
  otherCurrentAssetsPctRevenueAssumptionId: string;
  otherCurrentLiabilitiesPctRevenueAssumptionId: string;
};

export type TaxDrivers = {
  cashTaxRateAssumptionId: string;
  interestDeductibilityEbitdaPctAssumptionId?: string;
  openingTaxLossCarryforward?: string;
  openingDisallowedInterestCarryforward?: string;
};

export type DebtRateLineage = {
  instrumentId: string;
  period: string;
  indexationSourceId: string;
  indexationAsOfDate: string;
  indexationMethodology: string;
  couponSourceId: string;
  couponAsOfDate: string;
  couponMethodology: string;
};

export type InstitutionalModelInput = {
  absenceConfirmations?: {debtInstruments?: {confirmedBy:string;confirmedAt:string;rationale:string};capex?: {confirmedBy:string;confirmedAt:string;rationale:string}};
  modelId: string;
  currency: string;
  assumptionBook: AssumptionBook;
  openingBalanceSheet: OpeningBalanceSheet;
  revenueSegments: readonly RevenueSegmentDriver[];
  operatingCosts: readonly OperatingCostDriver[];
  capex: readonly CapexDriver[];
  existingAssetDepreciationAssumptionId: string;
  workingCapital: WorkingCapitalDrivers;
  taxes: TaxDrivers;
  debtInstruments: readonly IndexedDebtInstrumentInput[];
  debtRateLineage: readonly DebtRateLineage[];
  distributionsAssumptionId: string;
  minimumOperatingCashAssumptionId: string;
  minimumDscrAssumptionId?: string;
  maximumNetLeverageAssumptionId?: string;
  sectorPackId?: string;
};

export type InstitutionalModelPeriod = {
  period: string;
  revenue: string;
  revenueBySegment: Readonly<Record<string, string>>;
  operatingCosts: string;
  operatingCostsByLine: Readonly<Record<string, string>>;
  ebitda: string;
  depreciation: string;
  ebit: string;
  cashCoupon: string;
  cashIndexation: string;
  capitalizedCoupon: string;
  capitalizedIndexation: string;
  financeExpense: string;
  accountingEbt: string;
  taxableIncome: string;
  cashTax: string;
  netIncome: string;
  receivables: string;
  inventory: string;
  payables: string;
  otherCurrentAssets: string;
  otherCurrentLiabilities: string;
  netWorkingCapital: string;
  changeInNetWorkingCapital: string;
  maintenanceCapex: string;
  growthCapex: string;
  totalCapex: string;
  cfads: string;
  principalPaid: string;
  debtService: string;
  debtDrawdown: string;
  distributions: string;
  openingGrossDebt: string;
  closingGrossDebt: string;
  unrestrictedCash: string;
  restrictedCash: string;
  netPpe: string;
  otherAssets: string;
  otherLiabilities: string;
  equity: string;
  totalAssets: string;
  totalLiabilitiesAndEquity: string;
  balanceCheck: string;
  netDebt: string;
  netDebtToEbitda: string | null;
  dscr: string | null;
  interestCoverage: string | null;
  liquidityHeadroom: string;
  taxLossCarryforward: string;
  disallowedInterestCarryforward: string;
  minimumDscrHeadroom: string | null;
  maximumNetLeverageHeadroom: string | null;
};

export type InstitutionalFinancialModel = {
  modelId: string;
  currency: string;
  scenarioId: string;
  asOfDate: string;
  sectorPackId?: string;
  openingBalanceCheck: string;
  debtOpeningCheck: string;
  periods: readonly InstitutionalModelPeriod[];
  lineage: Readonly<Record<string, readonly string[]>>;
  limitations: readonly string[];
};

const d = (value: Decimal.Value) => new Decimal(value);
const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
const sum = (values: readonly Decimal[]) => values.reduce((total, value) => total.plus(value), new Decimal(0));
const safeRatio = (numerator: Decimal, denominator: Decimal): string | null =>
  denominator.lte(0) ? null : out(numerator.div(denominator));

function balanceTotalAssets(balance: OpeningBalanceSheet): Decimal {
  return sum([
    d(balance.unrestrictedCash), d(balance.restrictedCash), d(balance.receivables), d(balance.inventory),
    d(balance.otherCurrentAssets), d(balance.netPpe), d(balance.otherAssets),
  ]);
}

function balanceTotalLiabilitiesAndEquity(balance: OpeningBalanceSheet): Decimal {
  return sum([
    d(balance.payables), d(balance.otherCurrentLiabilities), d(balance.grossDebt),
    d(balance.otherLiabilities), d(balance.equity),
  ]);
}

function depreciationFromNewCapex(
  driver: CapexDriver,
  capexByPeriod: readonly Decimal[],
  currentPeriodIndex: number,
): Decimal {
  return d(calculateAnnualCapexDepreciation({
    amountsByYear: capexByPeriod.map(amount=>amount.toFixed()),
    usefulLifeYears: driver.usefulLifeYears,
    convention: driver.depreciationConvention,
    yearIndex: currentPeriodIndex,
  }).value);
}

export function buildInstitutionalFinancialModel(input: InstitutionalModelInput): InstitutionalFinancialModel {
  if (!input.modelId.trim()) throw new RangeError("model id is required");
  if (input.revenueSegments.length === 0) throw new RangeError("at least one revenue segment is required");
  if (input.operatingCosts.length === 0) throw new RangeError("at least one operating cost line is required");
  const absenceConfirmed=(kind:"capex"|"debtInstruments")=>{const c=input.absenceConfirmations?.[kind];return !!c&&!!c.confirmedBy.trim()&&!!c.rationale.trim()&&Number.isFinite(Date.parse(c.confirmedAt));};
  if((input.capex.length>0&&input.absenceConfirmations?.capex)||(input.debtInstruments.length>0&&input.absenceConfirmations?.debtInstruments))throw new RangeError("absence confirmation conflicts with supplied capex or debt");
  if (input.capex.length === 0 && !absenceConfirmed("capex")) throw new RangeError("capex lines or an explicit absence confirmation are required");
  const assumptionBlockers = validateAssumptionBook(input.assumptionBook).filter((issue) => issue.severity === "blocker");
  if (assumptionBlockers.length > 0) throw new RangeError(assumptionBlockers.map((issue) => issue.message).join("; "));
  const periods = [...input.assumptionBook.periods];
  if (!/^\d{4}$/.test(input.openingBalanceSheet.period) || periods.some((period,index)=>!/^\d{4}$/.test(period)||Number(period)!==Number(input.openingBalanceSheet.period)+index+1)) {
    throw new RangeError("institutional model requires consecutive annual periods after the opening year");
  }
  if (input.debtInstruments.length === 0 && !absenceConfirmed("debtInstruments")) throw new RangeError("instrument-level debt schedules or an explicit absence confirmation are required");
  for (const debt of input.debtInstruments) {
    if (debt.periods.map((period) => period.period).join("|") !== periods.join("|")) {
      throw new RangeError(`debt periods do not match the model horizon: ${debt.instrumentId}`);
    }
    for (const period of debt.periods) {
      const rateLineage = input.debtRateLineage.find((candidate) => candidate.instrumentId === debt.instrumentId && candidate.period === period.period);
      if (!rateLineage) throw new RangeError(`debt rate lineage is required: ${debt.instrumentId}:${period.period}`);
      if (!rateLineage.indexationSourceId.trim() || !rateLineage.indexationMethodology.trim() || !rateLineage.couponSourceId.trim() || !rateLineage.couponMethodology.trim()) {
        throw new RangeError(`debt rate lineage is incomplete: ${debt.instrumentId}:${period.period}`);
      }
      if (rateLineage.indexationAsOfDate > input.assumptionBook.asOfDate || rateLineage.couponAsOfDate > input.assumptionBook.asOfDate) {
        throw new RangeError(`debt rate lineage is dated after the model: ${debt.instrumentId}:${period.period}`);
      }
    }
  }
  for (const capex of input.capex) {
    if (!Number.isInteger(capex.usefulLifeYears) || capex.usefulLifeYears <= 0) throw new RangeError(`invalid useful life: ${capex.id}`);
  }

  const debtSchedules = input.debtInstruments.map(buildIndexedDebtSchedule);
  const debtRows = aggregateIndexedDebtSchedules(debtSchedules, input.debtInstruments.length===0&&absenceConfirmed("debtInstruments")?periods:undefined);
  const debtOpening = sum(input.debtInstruments.map((instrument) => d(instrument.openingPrincipal)));
  const openingBalanceCheck = balanceTotalAssets(input.openingBalanceSheet).minus(balanceTotalLiabilitiesAndEquity(input.openingBalanceSheet));
  const debtOpeningCheck = d(input.openingBalanceSheet.grossDebt).minus(debtOpening);
  if (!openingBalanceCheck.abs().lte("0.01")) throw new RangeError("opening balance sheet does not balance");
  if (!debtOpeningCheck.abs().lte("0.01")) throw new RangeError("opening gross debt does not reconcile to the instrument ledger");

  const revenueState = new Map(input.revenueSegments.map((segment) => [segment.id, d(segment.baseRevenue)]));
  const costState = new Map(input.operatingCosts.flatMap((cost) => cost.method === "base_and_growth" ? [[cost.id, d(cost.baseCost)] as const] : []));
  const capexSchedules = new Map(input.capex.map((driver) => [driver.id, periods.map((period) => assumptionValue(input.assumptionBook, driver.amountAssumptionId, period))]));
  const result: InstitutionalModelPeriod[] = [];

  let priorNwc = sum([
    d(input.openingBalanceSheet.receivables), d(input.openingBalanceSheet.inventory), d(input.openingBalanceSheet.otherCurrentAssets),
    d(input.openingBalanceSheet.payables).neg(), d(input.openingBalanceSheet.otherCurrentLiabilities).neg(),
  ]);
  let cash = d(input.openingBalanceSheet.unrestrictedCash);
  let ppe = d(input.openingBalanceSheet.netPpe);
  let equity = d(input.openingBalanceSheet.equity);
  let taxLossCarryforward = d(input.taxes.openingTaxLossCarryforward ?? 0);
  let disallowedInterestCarryforward = d(input.taxes.openingDisallowedInterestCarryforward ?? 0);

  periods.forEach((period, periodIndex) => {
    const revenueBySegment: Record<string, string> = {};
    for (const segment of input.revenueSegments) {
      const prior = revenueState.get(segment.id);
      if (!prior) throw new RangeError(`missing revenue state: ${segment.id}`);
      const organicFactor = d(1)
        .plus(assumptionValue(input.assumptionBook, segment.volumeGrowthAssumptionId, period))
        .mul(d(1).plus(assumptionValue(input.assumptionBook, segment.priceGrowthAssumptionId, period)))
        .mul(d(1).plus(assumptionValue(input.assumptionBook, segment.mixEffectAssumptionId, period)))
        .mul(d(1).plus(assumptionValue(input.assumptionBook, segment.fxEffectAssumptionId, period)));
      const current = prior.mul(organicFactor).plus(assumptionValue(input.assumptionBook, segment.inorganicRevenueAssumptionId, period));
      revenueState.set(segment.id, current);
      revenueBySegment[segment.id] = out(current);
    }
    const revenue = sum(Object.values(revenueBySegment).map(d));

    const operatingCostsByLine: Record<string, string> = {};
    for (const cost of input.operatingCosts) {
      let current: Decimal;
      if (cost.method === "percent_of_revenue") {
        current = revenue.mul(assumptionValue(input.assumptionBook, cost.ratioAssumptionId, period));
      } else {
        const prior = costState.get(cost.id);
        if (!prior) throw new RangeError(`missing cost state: ${cost.id}`);
        current = prior.mul(d(1).plus(assumptionValue(input.assumptionBook, cost.growthAssumptionId, period)));
        costState.set(cost.id, current);
      }
      operatingCostsByLine[cost.id] = out(current);
    }
    const operatingCosts = sum(Object.values(operatingCostsByLine).map(d));
    const ebitda = revenue.minus(operatingCosts);

    const currentCapex = input.capex.map((driver) => ({driver, amount: capexSchedules.get(driver.id)?.[periodIndex] ?? d(0)}));
    const maintenanceCapex = sum(currentCapex.filter(({driver}) => driver.classification === "maintenance").map(({amount}) => amount));
    const growthCapex = sum(currentCapex.filter(({driver}) => driver.classification === "growth").map(({amount}) => amount));
    const totalCapex = maintenanceCapex.plus(growthCapex);
    const newAssetDepreciation = sum(input.capex.map((driver) => depreciationFromNewCapex(driver, capexSchedules.get(driver.id) ?? [], periodIndex)));
    const depreciation = assumptionValue(input.assumptionBook, input.existingAssetDepreciationAssumptionId, period).plus(newAssetDepreciation);
    const ebit = ebitda.minus(depreciation);

    const debtRow = debtRows[periodIndex];
    if (!debtRow || debtRow.period !== period) throw new RangeError(`missing aggregate debt row for ${period}`);
    const cashCoupon = d(debtRow.couponPaid);
    const cashIndexation = d(debtRow.indexationPaid);
    const capitalizedCoupon = d(debtRow.couponCapitalized);
    const capitalizedIndexation = d(debtRow.indexationCapitalized);
    const financeExpense = d(debtRow.financeExpense);
    const accountingEbt = ebit.minus(financeExpense);

    const interestCapacity = input.taxes.interestDeductibilityEbitdaPctAssumptionId
      ? Decimal.max(ebitda, 0).mul(assumptionValue(input.assumptionBook, input.taxes.interestDeductibilityEbitdaPctAssumptionId, period))
      : financeExpense.plus(disallowedInterestCarryforward);
    const deductibleCurrentInterest = Decimal.min(financeExpense, interestCapacity);
    const unusedCapacity = Decimal.max(interestCapacity.minus(deductibleCurrentInterest), 0);
    const priorDisallowedUsed = Decimal.min(disallowedInterestCarryforward, unusedCapacity);
    disallowedInterestCarryforward = disallowedInterestCarryforward.plus(financeExpense).minus(deductibleCurrentInterest).minus(priorDisallowedUsed);
    const preNolTaxableIncome = Decimal.max(ebit.minus(deductibleCurrentInterest).minus(priorDisallowedUsed), 0);
    const currentLoss = Decimal.max(ebit.minus(deductibleCurrentInterest).minus(priorDisallowedUsed).neg(), 0);
    const nolUtilized = Decimal.min(taxLossCarryforward, preNolTaxableIncome);
    const taxableIncome = preNolTaxableIncome.minus(nolUtilized);
    taxLossCarryforward = taxLossCarryforward.minus(nolUtilized).plus(currentLoss);
    const cashTax = taxableIncome.mul(assumptionValue(input.assumptionBook, input.taxes.cashTaxRateAssumptionId, period));
    const netIncome = accountingEbt.minus(cashTax);

    const dso = assumptionValue(input.assumptionBook, input.workingCapital.dsoAssumptionId, period);
    const dio = assumptionValue(input.assumptionBook, input.workingCapital.dioAssumptionId, period);
    const dpo = assumptionValue(input.assumptionBook, input.workingCapital.dpoAssumptionId, period);
    const receivables = revenue.mul(dso).div(365);
    const inventory = operatingCosts.mul(dio).div(365);
    const payables = operatingCosts.mul(dpo).div(365);
    const otherCurrentAssets = revenue.mul(assumptionValue(input.assumptionBook, input.workingCapital.otherCurrentAssetsPctRevenueAssumptionId, period));
    const otherCurrentLiabilities = revenue.mul(assumptionValue(input.assumptionBook, input.workingCapital.otherCurrentLiabilitiesPctRevenueAssumptionId, period));
    const nwc = receivables.plus(inventory).plus(otherCurrentAssets).minus(payables).minus(otherCurrentLiabilities);
    const changeInNwc = nwc.minus(priorNwc);
    priorNwc = nwc;

    const cfads = ebitda.minus(cashTax).minus(changeInNwc).minus(totalCapex);
    const principalPaid = d(debtRow.scheduledPrincipal).plus(debtRow.prepayment);
    const debtService = cashCoupon.plus(cashIndexation).plus(principalPaid);
    const debtDrawdown = d(debtRow.drawdown);
    const distributions = assumptionValue(input.assumptionBook, input.distributionsAssumptionId, period);
    cash = cash.plus(ebitda).minus(cashTax).minus(changeInNwc).minus(totalCapex)
      .minus(cashCoupon).minus(cashIndexation).plus(debtDrawdown).minus(principalPaid).minus(distributions);
    ppe = ppe.plus(totalCapex).minus(depreciation);
    equity = equity.plus(netIncome).minus(distributions);
    const closingGrossDebt = d(debtRow.closingPrincipal);
    const restrictedCash = d(input.openingBalanceSheet.restrictedCash);
    const otherAssets = d(input.openingBalanceSheet.otherAssets);
    const otherLiabilities = d(input.openingBalanceSheet.otherLiabilities);
    const totalAssets = sum([cash, restrictedCash, receivables, inventory, otherCurrentAssets, ppe, otherAssets]);
    const totalLiabilitiesAndEquity = sum([payables, otherCurrentLiabilities, closingGrossDebt, otherLiabilities, equity]);
    const balanceCheck = totalAssets.minus(totalLiabilitiesAndEquity);
    const netDebt = closingGrossDebt.minus(cash);
    const minimumCash = assumptionValue(input.assumptionBook, input.minimumOperatingCashAssumptionId, period);
    const dscr = safeRatio(cfads, debtService);
    const leverage = safeRatio(netDebt, ebitda);
    const minimumDscr = input.minimumDscrAssumptionId ? assumptionValue(input.assumptionBook, input.minimumDscrAssumptionId, period) : null;
    const maximumLeverage = input.maximumNetLeverageAssumptionId ? assumptionValue(input.assumptionBook, input.maximumNetLeverageAssumptionId, period) : null;

    result.push({
      period, revenue: out(revenue), revenueBySegment, operatingCosts: out(operatingCosts), operatingCostsByLine,
      ebitda: out(ebitda), depreciation: out(depreciation), ebit: out(ebit), cashCoupon: out(cashCoupon),
      cashIndexation: out(cashIndexation), capitalizedCoupon: out(capitalizedCoupon), capitalizedIndexation: out(capitalizedIndexation),
      financeExpense: out(financeExpense), accountingEbt: out(accountingEbt), taxableIncome: out(taxableIncome),
      cashTax: out(cashTax), netIncome: out(netIncome), receivables: out(receivables), inventory: out(inventory),
      payables: out(payables), otherCurrentAssets: out(otherCurrentAssets), otherCurrentLiabilities: out(otherCurrentLiabilities),
      netWorkingCapital: out(nwc), changeInNetWorkingCapital: out(changeInNwc), maintenanceCapex: out(maintenanceCapex),
      growthCapex: out(growthCapex), totalCapex: out(totalCapex), cfads: out(cfads), principalPaid: out(principalPaid),
      debtService: out(debtService), debtDrawdown: out(debtDrawdown), distributions: out(distributions),
      openingGrossDebt: debtRow.openingPrincipal, closingGrossDebt: out(closingGrossDebt), unrestrictedCash: out(cash),
      restrictedCash: out(restrictedCash), netPpe: out(ppe), otherAssets: out(otherAssets), otherLiabilities: out(otherLiabilities),
      equity: out(equity), totalAssets: out(totalAssets), totalLiabilitiesAndEquity: out(totalLiabilitiesAndEquity),
      balanceCheck: out(balanceCheck), netDebt: out(netDebt), netDebtToEbitda: leverage, dscr,
      interestCoverage: safeRatio(ebitda, cashCoupon.plus(cashIndexation)), liquidityHeadroom: out(cash.minus(minimumCash)),
      taxLossCarryforward: out(taxLossCarryforward), disallowedInterestCarryforward: out(disallowedInterestCarryforward),
      minimumDscrHeadroom: minimumDscr && dscr !== null ? out(d(dscr).minus(minimumDscr)) : null,
      maximumNetLeverageHeadroom: maximumLeverage && leverage !== null ? out(maximumLeverage.minus(d(leverage))) : null,
    });
  });

  const lineage: Record<string, readonly string[]> = {
    revenue: input.revenueSegments.flatMap((segment) => [segment.volumeGrowthAssumptionId, segment.priceGrowthAssumptionId, segment.mixEffectAssumptionId, segment.fxEffectAssumptionId, segment.inorganicRevenueAssumptionId]),
    operatingCosts: input.operatingCosts.map((cost) => cost.method === "percent_of_revenue" ? cost.ratioAssumptionId : cost.growthAssumptionId),
    workingCapital: Object.values(input.workingCapital),
    capexAndDepreciation: [input.existingAssetDepreciationAssumptionId, ...input.capex.map((driver) => driver.amountAssumptionId)],
    taxes: [input.taxes.cashTaxRateAssumptionId, ...(input.taxes.interestDeductibilityEbitdaPctAssumptionId ? [input.taxes.interestDeductibilityEbitdaPctAssumptionId] : [])],
    debt: [
      ...input.debtInstruments.map((instrument) => instrument.instrumentId),
      ...input.debtRateLineage.flatMap((lineage) => [lineage.indexationSourceId, lineage.couponSourceId]),
    ],
    distributions: [input.distributionsAssumptionId],
    liquidity: [input.minimumOperatingCashAssumptionId],
  };

  return {
    modelId: input.modelId,
    currency: input.currency,
