import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import type {AdoptionBasisEntry, AdoptionBasisSnapshot} from "@offroad/reconciliation";
import type {AnalysisSelection} from "./adopted-analysis-binding";
import type {AdoptedInvestmentAnalysisInput} from "./adopted-investment-analysis";
import {analysisTestId as id} from "./adopted-analysis.test-support";

const D = Decimal.clone({precision: 60}), mm = (v: Decimal.Value) => new D(v).times(1000000).toDecimalPlaces(8).toFixed();

/** One synthetic adopted basis holding several scenarios of the C32 packaging line, each with
 * its own horizon. Synthetic hypotheses for calibration only; never production parameters. */
export function c32PacketBasis() {
  const entries: AdoptionBasisEntry[] = []; let n = 2000;
  const snapshot: AdoptionBasisSnapshot = {schemaVersion: "contextual-adoption.v1", versionId: id(1500), setId: id(1006),
    workId: id(1007), purpose: "synthetic investment decision", contextKey: "synthetic", revision: 1,
    previousVersionId: null, classification: "working_basis", entries};
  const scope = {workId: id(1007), purpose: snapshot.purpose, versionId: snapshot.versionId};
  const inputs: AdoptedInvestmentAnalysisInput[] = [];
  const analysisId = id(1004);

  /** Mirrors projeto_embalagem.py: economy factor scales the run-rate economy, capex factor
   * scales capex and depreciation, a later start delays the ramp, deferral shifts the project. */
  const contributor = (scenario: string, openingDate: string, endDate: string) => (path: string, unit: string, value: AdoptionBasisEntry["value"]): AnalysisSelection => {
    const decisionId = id(n++);
    entries.push({decisionId, slotKey: createHash("sha256").update(path + scenario).digest("hex"), kind: "hypothesis",
      fieldPath: `investment.${analysisId}.${path}`,
      dimensions: {entityId: id(1001), perimeter: "standalone", periodStart: openingDate, periodEnd: endDate, currency: "BRL", unit, scale: "1", scenario, definitionVersionId: id(1003)},
      value, observationId: null, referenceValue: null, referenceDimensions: null, definitionKind: "managerial", actorId: id(1005), reason: "Synthetic C32 calibration hypothesis"});
    return {decisionId, definitionVersionId: id(1003), definitionKind: "managerial", missingReason: null};
  };
  /** A sensitivity that adopts only the operands it changes and inherits the rest. */
  function overlay(base: AdoptedInvestmentAnalysisInput, scenario: string, change: (contribute: ReturnType<typeof contributor>, input: AdoptedInvestmentAnalysisInput, years: number[]) => void) {
    const input = structuredClone({...base, envelope: {canonical: "", fingerprint: ""}}) as AdoptedInvestmentAnalysisInput;
    input.scenario = scenario; input.inheritedScenario = base.scenario;
    const years = Array.from({length: Number(base.endDate.slice(0, 4)) - 2025}, (_, k) => 2026 + k);
    change(contributor(scenario, base.openingDate, base.endDate), input, years);
    inputs.push(input); return input;
  }
  function addCase(o: {scenario: string; economyFactor?: Decimal.Value; capexFactor?: Decimal.Value; operationStart?: string; deferYears?: number; withCompany?: boolean; quantum?: string}) {
    const defer = o.deferYears ?? 0, economy = new D(o.economyFactor ?? 1), capexFactor = new D(o.capexFactor ?? 1);
    const openingDate = "2025-12-31", endDate = `${2036 + defer}-12-31`;
    const years = Array.from({length: 11 + defer}, (_, k) => 2026 + k);
    const contribute = contributor(o.scenario, openingDate, endDate);
    const number = (p: string, unit: string, value: string) => contribute(p, unit, {type: "number", value});
    const text = (p: string, value: string) => contribute(p, "convention", {type: "text", value});
    const date = (p: string, value: string) => contribute(p, "date", {type: "date", value});
    const list = (p: string, unit: string, value: string[]) => contribute(p, unit, {type: "list", value});
    const growth = (y: number) => new D("1.04").pow(Math.max(0, y - 2027));
    const capex = (y: number) => y - defer === 2026 ? capexFactor.times(10) : y - defer === 2027 ? capexFactor.times(8) : new D(0);
    const series: Record<string, (y: number) => Decimal.Value> = {
      annualNetRevenue: () => 0, annualAvoidedOperatingCost: y => growth(y).times(30).times(economy),
      annualVariableOperatingCost: y => growth(y).times("19.5").times(economy), annualFixedOperatingCost: y => growth(y).times("4.5").times(economy),
      annualMaintenanceCapex: () => "0.6", annualDepreciation: () => capexFactor.times("1.8"), growthCapexPaid: capex};
    const money = Object.fromEntries(Object.entries(series).map(([k, f]) => [k, list("project." + k, "currency", years.map(y => {
      const v = new D(f(y)); return v.eq(0) ? "0" : mm(v);
    }))]));
    const opening = Object.fromEntries(["receivables", "inventory", "newPayables", "lostSupplierCredit"].map(k => [k, number("project.openingWorkingCapital." + k, "currency", "0")]));
    const project = {money, openingWorkingCapital: opening, cashTaxRate: list("project.cashTaxRate", "ratio", years.map(() => "0.34")),
      lossTaxTreatment: list("project.lossTaxTreatment", "convention", years.map(() => "no_cash_benefit")), fixedCostScaling: list("project.fixedCostScaling", "convention", years.map(() => "load")),
      exposure: {mode: "monthly_ramp", operationStartMonth: date("project.ramp.operationStartMonth", o.operationStart ?? `${2027 + defer}-05-01`), stageMonths: list("project.ramp.stageMonths", "months", ["3"]), stageLoads: list("project.ramp.stageLoads", "ratio", ["0.5"]), terminalLoad: number("project.ramp.terminalLoad", "ratio", "1")},
      closingWorkingCapital: {mode: "startup_drivers", startup: {money: {annualIncrementalRevenue: number("project.startup.annualIncrementalRevenue", "currency", "0"), annualNewVariableCost: number("project.startup.annualNewVariableCost", "currency", mm("19.5")), annualDisplacedPurchases: number("project.startup.annualDisplacedPurchases", "currency", mm("30"))},
        days: {receivableDays: number("project.startup.receivableDays", "days", "0"), inventoryDays: number("project.startup.inventoryDays", "days", "45"), newSupplierDays: number("project.startup.newSupplierDays", "days", "30"), lostSupplierDays: number("project.startup.lostSupplierDays", "days", "60")}, adoptedYearDays: text("project.startup.adoptedYearDays", "360")},
        retainedCapitalMultipliers: list("project.startup.retainedCapitalMultipliers", "ratio", years.map(y => y < 2027 + defer || y === years.at(-1) ? "0" : "1"))}};
    const companyMoney = {ebitda: "40", nonCashEbitdaBridge: "0", cashLeasePayments: "3", netWorkingCapitalChange: "2", maintenanceCapex: "8", growthCapex: "4", taxableBaseBeforeProject: "20", netFinancingCashAvailable: "-10", netCapitalCashAvailable: "0", netRestrictedCashMovement: "0", closingDebtStock: "30"};
    const company = o.withCompany === false ? null : {openingAvailableCash: number("company.openingAvailableCash", "currency", mm("20")), openingRestrictedCash: number("company.openingRestrictedCash", "currency", mm("7")),
      money: Object.fromEntries(Object.entries(companyMoney).map(([k, v]) => [k, list("company." + k, "currency", years.map(y => k === "closingDebtStock" && y >= 2033 ? "0" : mm(v)))])),
      cashTaxRate: list("company.cashTaxRate", "ratio", years.map(() => "0.34")), lossTaxTreatment: list("company.lossTaxTreatment", "convention", years.map(() => "no_cash_benefit")),
      debtInventoryStatus: text("company.debtInventoryStatus", "provided"), debtIds: list("company.debtIds", "identity", ["synthetic-debt"]), finalPaymentDates: list("company.finalPaymentDates", "date", ["2033-12-31"])};
    const valuation = {perspective: text("valuation.perspective", "standalone_project"), baseDate: date("valuation.baseDate", "2026-12-31"), timing: text("valuation.timing", "adopted_times"), adoptedTimes: list("valuation.adoptedTimes", "years", years.map((_, k) => String(k))),
      discountRate: number("valuation.discountRate", "ratio", "0.15"), irrLower: number("valuation.irrLower", "ratio", "-0.5"), irrUpper: number("valuation.irrUpper", "ratio", "2"), precisionMode: text("valuation.precisionMode", o.quantum ? "calibration_monetary_quantum" : "unrounded"), precisionDecimals: number("valuation.precisionDecimals", "count", "0"), precisionQuantum: number("valuation.precisionQuantum", "currency", o.quantum ?? "0")};
    const input = {envelope: {canonical: "", fingerprint: ""}, scope, entityId: id(1001), perimeter: "standalone", currency: "BRL", openingDate, endDate, numericInterpretations: [],
      analysisId, scenario: o.scenario, periodEnds: list("periodEnds", "date", years.map(y => `${y}-12-31`)), project, company, valuation} as unknown as AdoptedInvestmentAnalysisInput;
    inputs.push(input); return input;
  }
  function seal() {
    const canonical = JSON.stringify(snapshot), envelope = {canonical, fingerprint: createHash("sha256").update(canonical).digest("hex")};
    for (const input of inputs) input.envelope = envelope;
    return envelope;
  }
  return {entries, addCase, overlay, seal, contributor};
}

/** The five C32 cases of projeto_embalagem.py, as a packet input. Sensitivities adopt only
 * what they change; the deferral moves every dated series and so is adopted in full. */
export function c32PacketInput(o: {quantum?: string} = {}) {
  const b = c32PacketBasis();
  const base = b.addCase({scenario: "base", ...o});
  const growth = (y: number) => new D("1.04").pow(Math.max(0, y - 2027));
  const series = (years: number[], f: (y: number) => Decimal) => ({type: "list" as const, value: years.map(y => {const v = f(y); return v.eq(0) ? "0" : mm(v);})});
  const economy4 = b.overlay(base, "economy-4", (c, i, years) => {
    const factor = new D(4).div(6);
    i.project.money.annualAvoidedOperatingCost = c("project.annualAvoidedOperatingCost", "currency", series(years, y => growth(y).times(30).times(factor)));
    i.project.money.annualVariableOperatingCost = c("project.annualVariableOperatingCost", "currency", series(years, y => growth(y).times("19.5").times(factor)));
    i.project.money.annualFixedOperatingCost = c("project.annualFixedOperatingCost", "currency", series(years, y => growth(y).times("4.5").times(factor)));
  });
  const capex120 = b.overlay(base, "capex-120", (c, i, years) => {
    i.project.money.growthCapexPaid = c("project.growthCapexPaid", "currency", series(years, y => y === 2026 ? new D(12) : y === 2027 ? new D("9.6") : new D(0)));
    i.project.money.annualDepreciation = c("project.annualDepreciation", "currency", series(years, () => new D("2.16")));
  });
  const slower = b.overlay(base, "slower-start", (c, i) => {
    if (i.project.exposure.mode !== "monthly_ramp") throw new Error("ramp expected");
    i.project.exposure.operationStartMonth = c("project.ramp.operationStartMonth", "date", {type: "date", value: "2027-11-01"});
  });
  const cases = [
    {id: "base", role: "base" as const, label: "Linha de embalagem, cronograma original", changes: [], analysis: base},
    {id: "economy-4", role: "sensitivity" as const, label: "Economia de R$ 4 milhões por ano", changes: ["Economia anual em regime de R$ 4 milhões em vez de R$ 6 milhões"], analysis: economy4},
    {id: "capex-120", role: "sensitivity" as const, label: "Capex 20% maior", changes: ["Capex e depreciação 20% maiores"], analysis: capex120},
    {id: "slower-start", role: "sensitivity" as const, label: "Partida seis meses mais lenta", changes: ["Operação começa em novembro de 2027"], analysis: slower},
    {id: "defer-12", role: "deferral" as const, label: "Adiar doze meses", changes: ["Desembolsos e partida um ano depois"], analysis: b.addCase({scenario: "defer-12", deferYears: 1, ...o})},
  ];
  return {basis: b, input: {schemaVersion: "investment-decision-packet-input.v1" as const, question: "A linha de embalagem se paga e deve seguir agora?", cases}, seal: b.seal};
}

/** The same five cases with their roles, labels, changes and inheritance adopted in the basis,
 * as the bound composer reads them. */
export function c32PacketWithCaseMetadata(o: {quantum?: string} = {}) {
  const f = c32PacketInput(o);
  for (const c of f.input.cases) {
    const a = c.analysis, add = f.basis.contributor(a.scenario, a.openingDate, a.endDate);
    add("case.role", "convention", {type: "text", value: c.role});
    add("case.label", "explanation", {type: "text", value: c.label});
    if (c.changes.length) add("case.changes", "explanation", {type: "list", value: c.changes});
    if (a.inheritedScenario) add("case.inherits", "convention", {type: "text", value: a.inheritedScenario});
  }
  return f;
}

import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {z} from "zod";
import {financialCoreVersion} from "@offroad/financial-core";
import {adoptedInvestmentAnalysisInputSchema, calculateAdoptedInvestmentAnalysis} from "./adopted-investment-analysis";
import {adoptedInvestmentAnalysisOutputSchema} from "./ficha-calculation-results";

export const investmentDecisionPacketVersion = "2026.10.09-v1";
const Exact = Decimal.clone({precision: 80, rounding: Decimal.ROUND_HALF_UP});
const fmt = (d: Decimal) => d.toDecimalPlaces(20).toFixed();
const text = z.string().trim().min(1).max(2000), key = z.string().trim().min(1).max(160);
const decimal = z.string().regex(/^-?\d{1,24}(?:\.\d{1,20})?$/), date = z.iso.date(), hash = z.string().regex(/^[a-f0-9]{64}$/);
const roles = ["base", "sensitivity", "deferral", "staged", "alternative"] as const;

/** One question, several adopted versions of the same project. Every case is a complete,
 * separately adopted scenario (its own scenario label in the basis); the packet never edits
 * a base operand to fabricate a sensitivity, and never supplies a number of its own. */
export const investmentDecisionPacketInputSchema = z.strictObject({
  schemaVersion: z.literal("investment-decision-packet-input.v1"),
  question: text,
  cases: z.array(z.strictObject({
    id: key, role: z.enum(roles), label: text,
    /** What this case changes against the base, in words. Numbers come only from adoptions. */
    changes: z.array(text).max(20),
    analysis: adoptedInvestmentAnalysisInputSchema,
  })).min(1).max(16),
}).superRefine((input, ctx) => {
  const fail = (message: string) => ctx.addIssue({code: "custom", message});
  if (input.cases.filter(c => c.role === "base").length !== 1) fail("Exactly one base case is required");
  if (new Set(input.cases.map(c => c.id)).size !== input.cases.length) fail("Duplicate case identity");
  if (new Set(input.cases.map(c => `${c.analysis.analysisId}\u0000${c.analysis.scenario}`)).size !== input.cases.length) fail("Each case needs its own adopted scenario");
  const [first] = input.cases;
  for (const c of input.cases) {
    const a = c.analysis, b = first!.analysis;
    if (a.envelope.fingerprint !== b.envelope.fingerprint || a.scope.workId !== b.scope.workId || a.scope.purpose !== b.scope.purpose
      || a.scope.versionId !== b.scope.versionId || a.entityId !== b.entityId || a.perimeter !== b.perimeter || a.currency !== b.currency)
      fail("All cases must read the same adopted basis, entity, perimeter and currency");
    if (c.role === "base" && c.changes.length) fail("The base case declares no changes");
    if (c.role === "base" && c.analysis.inheritedScenario !== undefined) fail("The base case inherits nothing");
    const baseScenario = input.cases.find(x => x.role === "base")?.analysis.scenario;
    if (c.analysis.inheritedScenario !== undefined && c.analysis.inheritedScenario !== baseScenario) fail("A case may inherit only the base scenario");
    if (c.role !== "base" && !c.changes.length) fail("A non-base case must say what it changes");
  }
});
export type InvestmentDecisionPacketInput = z.infer<typeof investmentDecisionPacketInputSchema>;

const caseMetrics = z.strictObject({
  caseId: key, role: z.enum(roles), label: text, scenario: key,
  netPresentValue: decimal.nullable(), deltaNetPresentValue: decimal.nullable(),
  npvSign: z.enum(["positive", "zero", "negative"]).nullable(), signDiffersFromBase: z.boolean().nullable(),
  annualIrr: decimal.nullable(), irrStatus: z.enum(["calculated", "nonconventional_stream", "root_not_bracketed"]).nullable(),
  irrMinusDiscountRate: decimal.nullable(), discountRate: decimal.nullable(),
  paybackYears: decimal.nullable(), paybackRemainsRecoveredAtEnd: z.boolean().nullable(),
  startupWorkingCapital: decimal.nullable(),
  peakCumulativeCashNeed: z.strictObject({amount: decimal, periodEndDate: date}).nullable(),
  totalUnleveredCashFlow: decimal.nullable(),
  companyMinimumCash: z.strictObject({
    withoutProject: z.strictObject({amount: decimal, periodEndDate: date}),
    withProject: z.strictObject({amount: decimal, periodEndDate: date}),
  }).nullable(),
  resultStatus: z.enum(["missing_inputs", "partial_composition"]),
});
export const investmentDecisionPacketOutputSchema = z.strictObject({
  schemaVersion: z.literal("investment-decision-packet.v1"), executorVersion: z.literal(investmentDecisionPacketVersion),
  financialCoreVersion: key, question: text, basisFingerprint: hash,
  scope: adoptedInvestmentAnalysisInputSchema.shape.scope, entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/),
  cases: z.array(z.strictObject({id: key, role: z.enum(roles), label: text, changes: z.array(text).max(20), result: adoptedInvestmentAnalysisOutputSchema})).min(1).max(16),
  comparison: z.strictObject({
    baseCaseId: key, metrics: z.array(caseMetrics).min(1).max(16),
    /** Cases whose value sign differs from the base: the premises that change the conclusion. */
    conclusionChangingCaseIds: z.array(key).max(16),
    /** Deferral and staging cases measured on company cash, not on project value alone. */
    timingCaseIds: z.array(key).max(16),
  }),
  gaps: z.array(z.strictObject({caseId: key, operand: text, reason: text})).max(4096),
  status: z.enum(["framed", "partial", "prepared_for_human_review"]),
  classification: z.enum(["working_hypothesis", "working_selection"]),
  exclusions: z.array(z.enum(["financing_recommendation", "tax_law_inference", "intraperiod_cash_certification", "method_release"])).length(4)
    .refine(v => v.join("|") === "financing_recommendation|tax_law_inference|intraperiod_cash_certification|method_release", "Exact exclusion ledger required"),
  grantsExecution: z.literal(false), grantsPublication: z.literal(false), fingerprint: hash,
});
export type InvestmentDecisionPacket = z.infer<typeof investmentDecisionPacketOutputSchema>;

const minimum = (rows: {endDate: string; amount: string}[]) => rows.reduce<{amount: string; periodEndDate: string} | null>((low, r) =>
  low === null || new Exact(r.amount).lt(low.amount) ? {amount: r.amount, periodEndDate: r.endDate} : low, null);

/** Investment economics before any financing: every adopted case is recomputed by the same
 * engine, then compared to the base on value, return against the adopted discount rate,
 * payback, startup working capital, peak cash need and company cash with and without the
 * project. Deterministic and offline; it recommends nothing and grants nothing. */
export function prepareInvestmentDecisionPacket(raw: unknown): InvestmentDecisionPacket {
  const input = investmentDecisionPacketInputSchema.parse(raw);
  const results = input.cases.map(c => ({c, r: adoptedInvestmentAnalysisOutputSchema.parse(calculateAdoptedInvestmentAnalysis(c.analysis))}));
  const base = results.find(x => x.c.role === "base")!;
  const baseNpv = base.r.valuation ? new Exact(base.r.valuation.netPresentValue) : null;
  const sign = (d: Decimal) => d.gt(0) ? "positive" as const : d.lt(0) ? "negative" as const : "zero" as const;
  const metrics = results.map(({c, r}) => {
    const v = r.valuation, npv = v ? new Exact(v.netPresentValue) : null, rate = v ? v.operands.discountRate : null;
    // The output schema validated these decimal columns; the record helper erases their key types.
    const rows = (r.project?.rows ?? []) as unknown as {endDate: string; cumulativeUnleveredCashFlow: string}[];
    type CompanyRow = {endDate: string; withoutProject: {closingAvailableCash: string}; withProject: {closingAvailableCash: string}};
    const companyRows = (r.company?.rows ?? []) as unknown as CompanyRow[];
    const peak = rows.length ? minimum(rows.map(q => ({endDate: q.endDate, amount: q.cumulativeUnleveredCashFlow}))) : null;
    // The counterfactual measures the opening balance and every period end; the minimum covers both.
    const opening = r.company ? {endDate: c.analysis.openingDate, amount: r.company.operands.openingAvailableCash} : null;
    const company = r.company && opening ? {
      withoutProject: minimum([opening, ...companyRows.map(q => ({endDate: q.endDate, amount: q.withoutProject.closingAvailableCash}))])!,
      withProject: minimum([opening, ...companyRows.map(q => ({endDate: q.endDate, amount: q.withProject.closingAvailableCash}))])!,
    } : null;
    return {caseId: c.id, role: c.role, label: c.label, scenario: c.analysis.scenario,
      netPresentValue: npv ? fmt(npv) : null, deltaNetPresentValue: npv && baseNpv ? fmt(npv.minus(baseNpv)) : null,
      npvSign: npv ? sign(npv) : null, signDiffersFromBase: npv && baseNpv ? sign(npv) !== sign(baseNpv) : null,
      annualIrr: v?.annualIrr ?? null, irrStatus: v?.irrStatus ?? null,
      irrMinusDiscountRate: v?.annualIrr && rate ? fmt(new Exact(v.annualIrr).minus(rate)) : null, discountRate: rate,
      paybackYears: v?.payback?.interpolatedTimeYears ?? null, paybackRemainsRecoveredAtEnd: v ? v.paybackRemainsRecoveredAtEnd : null,
      startupWorkingCapital: (r.startupCapital as {netRequirement?: string} | null)?.netRequirement ?? null,
      peakCumulativeCashNeed: peak && new Exact(peak.amount).lt(0) ? peak : null,
      totalUnleveredCashFlow: r.project?.totalUnleveredCashFlow ?? null, companyMinimumCash: company, resultStatus: r.status};
  });
  const gaps = results.flatMap(({c, r}) => r.gaps.map(g => ({caseId: c.id, ...g})));
  const status = !base.r.project ? "framed" as const : gaps.length ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "investment-decision-packet.v1" as const, executorVersion: investmentDecisionPacketVersion, financialCoreVersion,
    question: input.question, basisFingerprint: base.r.basisFingerprint, scope: base.r.scope, entityId: base.r.entityId,
    perimeter: base.r.perimeter, currency: base.r.currency,
    cases: results.map(({c, r}) => ({id: c.id, role: c.role, label: c.label, changes: c.changes, result: r})),
    comparison: {baseCaseId: base.c.id, metrics,
      conclusionChangingCaseIds: metrics.filter(m => m.signDiffersFromBase).map(m => m.caseId),
      timingCaseIds: metrics.filter(m => m.role === "deferral" || m.role === "staged").map(m => m.caseId)},
    gaps, status,
    classification: results.some(x => x.r.classification === "working_hypothesis") ? "working_hypothesis" as const : "working_selection" as const,
    exclusions: ["financing_recommendation", "tax_law_inference", "intraperiod_cash_certification", "method_release"] as const,
    grantsExecution: false as const, grantsPublication: false as const};
  return investmentDecisionPacketOutputSchema.parse({...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")});
}

import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {deterministicRunEvidenceFingerprint, type DeterministicMethodRun, type DeterministicMethodRunCase} from "@offroad/credit-playbook";
import {investmentDecisionPacketOutputSchema, prepareInvestmentDecisionPacket, type InvestmentDecisionPacketInput} from "./investment-decision-packet";
import {c32PacketInput} from "./investment-decision-packet.test-support";

// Evaluation-only module; not exported to application consumers. All cases are synthetic
// calibrations of ficha C32 (projeto_embalagem.py), never production parameters.
const fingerprint = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const D = Decimal.clone({precision: 60});
const mi = (v: string | null, places = 1) => v === null ? null : new D(v).div(1000000).toDecimalPlaces(places).toNumber();
const pct = (v: string | null) => v === null ? null : new D(v).times(100).toDecimalPlaces(1).toNumber();
type Case = DeterministicMethodRunCase;
type Evidence = Omit<DeterministicMethodRun, "schemaVersion" | "humanApproval" | "run">;
export const investmentDecisionMethodVersion = "2026.10.09-v2";
export const investmentDecisionRunIds = {
  gold: "investment-project-2026-10-09-v2-gold",
  adversarial: "investment-project-2026-10-09-v2-adversarial",
  consistency: "investment-project-2026-10-09-v2-consistency",
} as const;

const sealed = (o: {quantum?: string} = {}) => {const f = c32PacketInput(o); f.seal(); return f.input;};
/** C32 with company EBITDA of R$ 100 mi a year: every period close exceeds the opening balance. */
const strongCompany = () => {
  const f = c32PacketInput(), e = f.basis.entries.find(x => x.fieldPath.endsWith(".company.ebitda") && x.dimensions.scenario === "base")!;
  e.value = {type: "list", value: (e.value as {value: string[]}).value.map(() => "100000000")}; f.seal(); return f.input;
};
type Packet = ReturnType<typeof prepareInvestmentDecisionPacket>;
function observe(id: string, input: InvestmentDecisionPacketInput, expected: unknown, select: (p: Packet) => unknown): Case {
  const result = prepareInvestmentDecisionPacket(input);
  const observed = JSON.stringify(select(result)), expectation = JSON.stringify(expected);
  return {id, expectation, observed, inputFingerprint: fingerprint(input), outputFingerprint: fingerprint(result), passed: expectation === observed};
}
const metric = (p: Packet, id: string) => p.comparison.metrics.find(m => m.caseId === id)!;

function goldCases(): Case[] {
  return [
    // Expectations come from the independent Python oracle (outputs/fichas-ensaio-2026-10/C32/projeto_resultados.json).
    observe("c32-five-cases-independent-oracle", sealed({quantum: "10000"}), [
      ["base", 0.7, 15.8, 5.9], ["economy-4", -6.3, 7.7, 8.2], ["capex-120", -2.1, 13, 6.4], ["slower-start", -1, 14, 6.3], ["defer-12", 1.4, 16.7, 6.7]],
      p => p.comparison.metrics.map(m => [m.caseId, mi(m.netPresentValue), pct(m.annualIrr), new D(m.paybackYears!).toDecimalPlaces(1).toNumber()])),
    observe("startup-working-capital-of-verticalization", sealed(), {startup: "5812500", lostSupplierCredit: "5000000"},
      p => ({startup: metric(p, "base").startupWorkingCapital, lostSupplierCredit: (p.cases[0]!.result.startupCapital as unknown as {lostSupplierCredit: string}).lostSupplierCredit})),
    observe("eleven-annual-flows-after-tax-maintenance-and-working-capital", sealed(), [-10, -11.66, 4.13, 4.3, 4.47, 4.64, 4.83, 5.02, 5.22, 5.43, 11.46],
      p => (p.cases[0]!.result.project!.rows as unknown as {unleveredCashFlow: string}[]).map(r => mi(r.unleveredCashFlow, 2))),
    observe("premises-that-change-the-conclusion", sealed(), {changing: ["economy-4", "capex-120", "slower-start"], timing: ["defer-12"]},
      p => ({changing: p.comparison.conclusionChangingCaseIds, timing: p.comparison.timingCaseIds})),
    observe("cash-consumed-before-payback", sealed(), {amount: -21.66, periodEndDate: "2027-12-31"},
      p => ({amount: mi(metric(p, "base").peakCumulativeCashNeed!.amount, 2), periodEndDate: metric(p, "base").peakCumulativeCashNeed!.periodEndDate})),
    observe("return-near-cost-of-capital-is-marginal", sealed({quantum: "10000"}), {irrMinusDiscountPoints: 0.8, discountRate: "0.15"},
      p => ({irrMinusDiscountPoints: new D(metric(p, "base").irrMinusDiscountRate!).times(100).toDecimalPlaces(1).toNumber(), discountRate: metric(p, "base").discountRate})),
    observe("company-minimum-includes-opening-balance", sealed(), {without: [20, "2025-12-31"], with: [10.74, "2027-12-31"]},
      p => {const c = metric(p, "base").companyMinimumCash!; return {without: [mi(c.withoutProject.amount, 2), c.withoutProject.periodEndDate], with: [mi(c.withProject.amount, 2), c.withProject.periodEndDate]};}),
    observe("opening-balance-is-the-minimum-when-every-close-is-higher", strongCompany(), {without: [20, "2025-12-31"], with: [20, "2025-12-31"]},
      p => {const c = metric(p, "base").companyMinimumCash!; return {without: [mi(c.withoutProject.amount, 2), c.withoutProject.periodEndDate], with: [mi(c.withProject.amount, 2), c.withProject.periodEndDate]};}),
    observe("company-cash-with-and-without-the-project", sealed(), {projectLowersMinimum: true},
      p => {const c = metric(p, "base").companyMinimumCash!; return {projectLowersMinimum: new D(c.withProject.amount).lt(c.withoutProject.amount)};}),
    (() => {
      const input = sealed(); const base = input.cases[0]!.analysis;
      base.valuation.discountRate = {...base.valuation.discountRate, decisionId: null, missingReason: "Custo de capital não adotado"};
      return observe("absent-cost-of-capital-is-a-gap-not-a-default", input, {status: "partial", npv: null, startup: "5812500", gap: true, changing: []},
        p => ({status: p.status, npv: metric(p, "base").netPresentValue, startup: metric(p, "base").startupWorkingCapital,
          gap: p.gaps.some(g => g.caseId === "base" && g.reason === "Custo de capital não adotado"), changing: p.comparison.conclusionChangingCaseIds}));
    })(),
    observe("unrounded-precision-is-the-default", sealed(), {base: 0.73, economy: -6.35},
      p => ({base: mi(metric(p, "base").netPresentValue, 2), economy: mi(metric(p, "economy-4").netPresentValue, 2)})),
  ];
}

function adversarialCases(): Case[] {
  const attempts: [string, () => unknown, string][] = [
    ["tampered-envelope", () => {const i = sealed(); for (const c of i.cases) c.analysis.envelope = {...c.analysis.envelope, canonical: c.analysis.envelope.canonical.replace("19500000", "9500000")}; return i;}, "adoption_basis_integrity_mismatch"],
    ["undeclared-inheritance", () => {const i = sealed(); delete (i.cases[1]!.analysis as {inheritedScenario?: string}).inheritedScenario; return i;}, "analysis_basis_context_mismatch"],
    ["inherits-another-sensitivity", () => {const i = sealed(); i.cases[2]!.analysis.inheritedScenario = "economy-4"; return i;}, "A case may inherit only the base scenario"],
    ["base-inherits", () => {const i = sealed(); i.cases[0]!.analysis.inheritedScenario = "economy-4"; return i;}, "The base case inherits nothing"],
    ["two-bases", () => {const i = sealed(); (i.cases[1] as {role: string}).role = "base"; return i;}, "Exactly one base case is required"],
    ["mixed-currency", () => {const i = sealed(); i.cases[3]!.analysis = {...i.cases[3]!.analysis, currency: "USD"}; return i;}, "same adopted basis"],
    ["silent-sensitivity", () => {const i = sealed(); i.cases[2]!.changes = []; return i;}, "must say what it changes"],
    ["free-result-in-request", () => ({...sealed(), netPresentValue: "1000000"}), "Unrecognized key"],
    ["fabricated-grant-in-result", () => ({forge: true}), "grantsExecution"],
  ];
  return attempts.map(([id, build, message]) => {
    let observed: string, passed: boolean, input: unknown;
    try {
      input = build();
      if ((input as {forge?: boolean}).forge) {
        const packet = prepareInvestmentDecisionPacket(sealed());
        investmentDecisionPacketOutputSchema.parse({...packet, grantsExecution: true});
      } else prepareInvestmentDecisionPacket(input);
      observed = "accepted"; passed = false;
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      passed = detail.includes(message); observed = passed ? "rejected by expected boundary" : `unexpected error: ${detail.slice(0, 250)}`;
    }
    return {id, expectation: "rejected by expected boundary", observed, inputFingerprint: fingerprint(input ?? null), outputFingerprint: fingerprint({observed}), passed};
  });
}

function consistencyCases(): Case[] {
  return [sealed(), sealed({quantum: "10000"})].flatMap((input, fixtureIndex) => {
    const before = fingerprint(input), first = prepareInvestmentDecisionPacket(input);
    return Array.from({length: 3}, (_, repeat) => {
      const result = prepareInvestmentDecisionPacket(JSON.parse(JSON.stringify(input)));
      const passed = fingerprint(result) === fingerprint(first) && fingerprint(input) === before;
      return {id: `fixture-${fixtureIndex + 1}-repeat-${repeat + 1}`,
        expectation: "same inputs and versions reproduce all output bytes without mutation",
        observed: passed ? "same inputs and versions reproduce all output bytes without mutation" : "output or input changed",
        inputFingerprint: before, outputFingerprint: fingerprint(result), passed};
    });
  });
}

export function buildInvestmentDecisionRuns(): Evidence[] {
  return ([{kind: "gold", cases: goldCases()}, {kind: "adversarial", cases: adversarialCases()},
    {kind: "consistency", cases: consistencyCases()}] as const).map(({kind, cases}) => {
    const evidence = {runId: investmentDecisionRunIds[kind], kind,
      method: {id: "analyze-investment-project", version: investmentDecisionMethodVersion},
      executor: {module: "@offroad/financial-model", exportName: "prepareInvestmentDecisionPacket"},
      harness: {module: "@offroad/financial-model/src/investment-decision-runs.test-support.ts", exportName: "buildInvestmentDecisionRuns"},
      modelCalls: 0 as const, cases, result: cases.every(c => c.passed) ? "pass" as const : "fail" as const};
    return {...evidence, evidenceFingerprint: deterministicRunEvidenceFingerprint(evidence),
      notes: "Synthetic deterministic execution calibrated on ficha C32. Numerical expectations do not constitute independent review, content approval, live access verification or publication."};
  });
}

import Decimal from "decimal.js";
import {z} from "zod";

const Exact = Decimal.clone({precision: 80, rounding: Decimal.ROUND_HALF_UP});
const fmt = (v: Decimal) => v.toDecimalPlaces(8).toFixed();
const text = z.string().trim().min(1).max(2000);
const amount = z.string().regex(/^\d{1,24}(?:\.\d{1,20})?$/);
const ratio = z.string().regex(/^-?\d{1,4}(?:\.\d{1,20})?$/);
const month = z.iso.date().refine(d => d.endsWith("-01"), "Operation starts on the first day of a month");
const origins = ["document", "informed", "house", "estimate"] as const;
const originLabel: Record<(typeof origins)[number], string> = {document: "documento", informed: "informado", house: "premissa da casa", estimate: "estimativa"};
/** A value and where it came from; the source names the document, the message or the house rule. */
const fact = <T extends z.ZodType>(value: T) => z.strictObject({value, origin: z.enum(origins), source: text});

/** The facts of one investment, each with its origin. These are proposals: nothing here is
 * adopted until a person confirms the set, and every number later read by the method comes from
 * the adopted basis, not from this object. */
export const investmentFactsSchema = z.strictObject({
  analysisId: z.uuid(), entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/),
  definitionVersionId: z.uuid(),
  /** First projected year and number of years in the explicit horizon (economic life plus the build). */
  firstYear: z.number().int().min(2000).max(2200), years: z.number().int().min(3).max(40),
  capex: fact(z.array(z.strictObject({year: z.number().int(), amount})).min(1).max(40)),
  operationStart: fact(month),
  ramp: fact(z.strictObject({stageMonths: z.array(z.number().int().min(1).max(60)).max(6), stageLoads: z.array(ratio).max(6)})),
  annualIncrementalRevenue: fact(amount), annualDisplacedPurchases: fact(amount),
  annualNewVariableCost: fact(amount), annualNewFixedCost: fact(amount),
  /** Annual growth of benefits and costs after the year operation starts. */
  annualGrowth: fact(ratio), annualMaintenance: fact(amount), usefulLifeYears: fact(z.number().int().min(1).max(60)),
  cashTaxRate: fact(ratio), receivableDays: fact(amount), inventoryDays: fact(amount), newSupplierDays: fact(amount), lostSupplierDays: fact(amount),
  discountRate: fact(ratio),
  /** Whether the startup working capital returns in the last year of the horizon. */
  workingCapitalReturnsAtEnd: fact(z.boolean()),
  sensitivities: z.strictObject({benefitFactor: fact(ratio), capexFactor: fact(ratio), startDelayMonths: fact(z.number().int().min(1).max(36)), deferMonths: fact(z.literal(12))}),
}).superRefine((f, ctx) => {
  if (f.ramp.value.stageMonths.length !== f.ramp.value.stageLoads.length) ctx.addIssue({code: "custom", message: "Ramp stages and loads must align"});
  const last = f.firstYear + f.years - 1;
  if (f.capex.value.some(c => c.year < f.firstYear || c.year > last)) ctx.addIssue({code: "custom", message: "Capex outside the horizon"});
  if (Number(f.operationStart.value.slice(0, 4)) > last) ctx.addIssue({code: "custom", message: "Operation starts after the horizon"});
});
export type InvestmentFacts = z.infer<typeof investmentFactsSchema>;
export type ProposedHypothesis = {fieldPath: string; dimensions: {entityId: string; perimeter: string; periodStart: string; periodEnd: string;
  currency: string; unit: string; scale: "1"; scenario: string; definitionVersionId: string}; value: {type: "number" | "text" | "date" | "list"; value: string | string[]} | {type: "boolean"; value: boolean}; reason: string};

const addMonths = (d: string, n: number) => {const x = new Date(`${d}T00:00:00Z`); x.setUTCMonth(x.getUTCMonth() + n); return x.toISOString().slice(0, 10);};

/** The hypotheses one confirmation adopts: the base case, three sensitivities that adopt only
 * what they change, and a twelve-month deferral adopted in full, each with its role, label and
 * what it changes. Every reason states the origin of the number. Deterministic. */
export function proposeInvestmentHypotheses(raw: unknown): ProposedHypothesis[] {
  const f = investmentFactsSchema.parse(raw);
  const out: ProposedHypothesis[] = [], prefix = `investment.${f.analysisId}.`;
  const why = (x: {origin: (typeof origins)[number]; source: string}) => `Origem: ${originLabel[x.origin]}. ${x.source}`;
  const house = (source: string) => `Origem: premissa da casa. ${source}`;
  const mi = (v: Decimal.Value) => new Exact(v).div(1000000).toDecimalPlaces(1).toFixed().replace(".", ",");
  function caseBuilder(scenario: string, shiftYears: number) {
    const openingDate = `${f.firstYear - 1}-12-31`, endDate = `${f.firstYear + f.years - 1 + shiftYears}-12-31`;
    const years = Array.from({length: f.years + shiftYears}, (_, k) => f.firstYear + k);
    const add = (path: string, unit: string, value: ProposedHypothesis["value"], reason: string) => out.push({fieldPath: prefix + path,
      dimensions: {entityId: f.entityId, perimeter: f.perimeter, periodStart: openingDate, periodEnd: endDate, currency: f.currency, unit, scale: "1", scenario, definitionVersionId: f.definitionVersionId},
      value, reason});
    return {years, add, list: (path: string, unit: string, values: string[], reason: string) => add(path, unit, {type: "list", value: values}, reason)};
  }
  const startYear = Number(f.operationStart.value.slice(0, 4));
  const growth = (y: number) => new Exact(1).plus(f.annualGrowth.value).pow(Math.max(0, y - startYear));
  const capexOf = (y: number, factor: Decimal.Value, shift: number) => f.capex.value.filter(c => c.year + shift === y).reduce((s, c) => s.plus(new Exact(c.amount).times(factor)), new Exact(0));
  const totalCapex = f.capex.value.reduce((s, c) => s.plus(c.amount), new Exact(0));
  const benefitSeries = (years: number[], key: "annualDisplacedPurchases" | "annualNewVariableCost" | "annualNewFixedCost" | "annualIncrementalRevenue", factor: Decimal.Value) =>
    years.map(y => fmt(growth(y).times(f[key].value).times(factor)));

  function fullCase(scenario: string, shift: number, role: string, label: string, changes: string[]) {
    const c = caseBuilder(scenario, shift), {years} = c;
    c.add("case.role", "convention", {type: "text", value: role}, house("Papel do caso na análise do investimento"));
    c.add("case.label", "explanation", {type: "text", value: label}, house("Rótulo do caso"));
    if (changes.length) c.add("case.changes", "explanation", {type: "list", value: changes}, house("O que o caso muda em relação ao caso base"));
    c.list("periodEnds", "date", years.map(y => `${y}-12-31`), house("Fim de cada ano do horizonte explícito"));
    c.list("project.annualNetRevenue", "currency", benefitSeries(years, "annualIncrementalRevenue", 1), why(f.annualIncrementalRevenue));
    c.list("project.annualAvoidedOperatingCost", "currency", benefitSeries(years, "annualDisplacedPurchases", 1), why(f.annualDisplacedPurchases));
    c.list("project.annualVariableOperatingCost", "currency", benefitSeries(years, "annualNewVariableCost", 1), why(f.annualNewVariableCost));
    c.list("project.annualFixedOperatingCost", "currency", benefitSeries(years, "annualNewFixedCost", 1), why(f.annualNewFixedCost));
    c.list("project.annualMaintenanceCapex", "currency", years.map(() => fmt(new Exact(f.annualMaintenance.value))), why(f.annualMaintenance));
    c.list("project.growthCapexPaid", "currency", years.map(y => fmt(capexOf(y, 1, shift))), why(f.capex));
    c.list("project.annualDepreciation", "currency", years.map(() => fmt(totalCapex.div(f.usefulLifeYears.value))), why(f.usefulLifeYears) + " Depreciação linear do capex total pela vida útil.");
    for (const k of ["receivables", "inventory", "newPayables", "lostSupplierCredit"]) c.add("project.openingWorkingCapital." + k, "currency", {type: "number", value: "0"}, house("Projeto novo, sem giro incremental na abertura"));
    c.list("project.cashTaxRate", "ratio", years.map(() => f.cashTaxRate.value), why(f.cashTaxRate));
    c.list("project.lossTaxTreatment", "convention", years.map(() => "no_cash_benefit"), house("Prejuízo do projeto não gera benefício de caixa isolado"));
    c.list("project.fixedCostScaling", "convention", years.map(() => "load"), house("Custo fixo acompanha a carga da operação"));
    const start = addMonths(f.operationStart.value, shift * 12);
    c.add("project.ramp.operationStartMonth", "date", {type: "date", value: start}, why(f.operationStart));
    c.list("project.ramp.stageMonths", "months", f.ramp.value.stageMonths.map(String), why(f.ramp));
    c.list("project.ramp.stageLoads", "ratio", f.ramp.value.stageLoads, why(f.ramp));
    c.add("project.ramp.terminalLoad", "ratio", {type: "number", value: "1"}, house("Carga cheia depois da rampa"));
    c.add("project.startup.annualIncrementalRevenue", "currency", {type: "number", value: fmt(new Exact(f.annualIncrementalRevenue.value))}, why(f.annualIncrementalRevenue));
    c.add("project.startup.annualNewVariableCost", "currency", {type: "number", value: fmt(new Exact(f.annualNewVariableCost.value))}, why(f.annualNewVariableCost));
    c.add("project.startup.annualDisplacedPurchases", "currency", {type: "number", value: fmt(new Exact(f.annualDisplacedPurchases.value))}, why(f.annualDisplacedPurchases));
    for (const k of ["receivableDays", "inventoryDays", "newSupplierDays", "lostSupplierDays"] as const)
      c.add("project.startup." + k, "days", {type: "number", value: f[k].value}, why(f[k]));
    c.add("project.startup.adoptedYearDays", "convention", {type: "text", value: "360"}, house("Prazos em dias sobre ano comercial de 360 dias"));
    const startYearShifted = Number(start.slice(0, 4));
    c.list("project.startup.retainedCapitalMultipliers", "ratio", years.map((y, n) => y < startYearShifted || (f.workingCapitalReturnsAtEnd.value && n === years.length - 1) ? "0" : "1"), why(f.workingCapitalReturnsAtEnd));
    c.add("valuation.perspective", "convention", {type: "text", value: "standalone_project"}, house("Projeto avaliado isolado, sem financiamento"));
    c.add("valuation.baseDate", "date", {type: "date", value: `${f.firstYear}-12-31`}, house("Valor na data do fim do primeiro ano"));
    c.add("valuation.timing", "convention", {type: "text", value: "adopted_times"}, house("Fluxo de cada ano no ponto do ano, primeiro ano em t igual a zero"));
    c.list("valuation.adoptedTimes", "years", years.map((_, k) => String(k)), house("Grade anual do valor"));
    c.add("valuation.discountRate", "ratio", {type: "number", value: f.discountRate.value}, why(f.discountRate));
    c.add("valuation.irrLower", "ratio", {type: "number", value: "-0.5"}, house("Intervalo de busca da TIR"));
