import {z} from "zod";
import {readContextualBasis, type AdoptionBasisEntry} from "@offroad/reconciliation";
import {actualOperatingDriverNames, projectedOperatingDriverNames, type ProjectedOperatingDriver} from "@offroad/financial-core";
import {adoptedValueSelectionSchema} from "./adopted-debt-inputs";
import {hasUnitScale} from "./adopted-input-scale";
import {actualOperatingItems, operatingProjectionDriverUnits} from "./adopted-operating-projection-drivers";
import {operatingProjectionPacketInputSchema, type OperatingProjectionPacketInput} from "./operating-projection-packet";

const text = z.string().trim().min(1).max(2000);
export const boundOperatingProjectionInputSchema = z.strictObject({
  envelope: z.strictObject({canonical: z.string().min(2).max(1048576), fingerprint: z.string().regex(/^[a-f0-9]{64}$/)}),
  scope: z.strictObject({workId: z.uuid(), purpose: z.string().min(3).max(300), versionId: z.uuid()}),
  question: text,
});
type Selection = z.infer<typeof adoptedValueSelectionSchema>;
type ValueType = AdoptionBasisEntry["value"]["type"];
const uuid = "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}";
const id = "[a-z0-9][a-z0-9-]{0,39}";
const anchorPath = new RegExp(`^operating_projection\\.(${uuid})\\.actual\\.periodEnd$`);
const scenarioPath = new RegExp(`^scenario\\.(${id})\\.`);
const overridePath = new RegExp(`^scenario\\.(${id})\\.override\\.([A-Za-z]+)(?:\\.origin)?$`);
const versionPath = new RegExp(`^version\\.(${id})\\.`);

/** Composes the projection packet input from the working basis alone. The analysis exists only when the
 * basis adopts the end of its actual year (`operating_projection.<analysis>.actual.periodEnd`); its
 * scenarios and company versions are every id the field paths name, in the adopted order. Every operand
 * is selected by field path, scenario, unit and type within the analysis' own dimensions; an absent
 * operand, or one adopted twice for the same slot, is declared missing with its reason. A scenario rule
 * exists only when the basis adopts one of its parts. No number is supplied here. */
export function composeBoundOperatingProjection(raw: unknown): OperatingProjectionPacketInput {
  const input = boundOperatingProjectionInputSchema.parse(raw);
  const basis = readContextualBasis(input.envelope, input.scope);
  const entries = [...basis.entries].sort((a, b) => a.decisionId < b.decisionId ? -1 : 1);
  const anchors = entries.flatMap((e) => {const m = anchorPath.exec(e.fieldPath); return m && e.value.type === "date" ? [{analysisId: m[1]!, entry: e}] : [];});
  if (!anchors.length) throw new Error("operating_projection_analysis_missing");
  if (anchors.length > 1) throw new Error("operating_projection_analysis_ambiguous");
  const {analysisId, entry: anchor} = anchors[0]!, prefix = `operating_projection.${analysisId}.`, d = anchor.dimensions, top = d.scenario!;
  const own = entries.filter((e) => e.fieldPath.startsWith(prefix) && e.dimensions.entityId === d.entityId && e.dimensions.perimeter === d.perimeter
    && e.dimensions.currency === d.currency && e.dimensions.periodStart === d.periodStart && e.dimensions.periodEnd === d.periodEnd);
  const rel = (e: AdoptionBasisEntry) => e.fieldPath.slice(prefix.length);
  const used = new Set<string>(), definitions: Selection[] = [], missing: Selection[] = [];
  function select(p: string, scenario: string, unit: string, type: ValueType, absent?: string): Selection {
    // As the reader allows, an operand carries its own scenario or, explicitly, the inherited top one; one candidate across both.
    const matches = own.filter((e) => rel(e) === p && e.value.type === type && e.dimensions.unit === unit && (e.dimensions.scenario === scenario || e.dimensions.scenario === top)
      && (unit === "currency" || hasUnitScale(e.dimensions.scale)) && !used.has(e.decisionId));
    if (matches.length === 1) {
      const e = matches[0]!; used.add(e.decisionId);
      const selection = {decisionId: e.decisionId, definitionVersionId: e.dimensions.definitionVersionId!, definitionKind: e.definitionKind, missingReason: null};
      definitions.push(selection); return selection;
    }
    const selection = {decisionId: null, definitionVersionId: d.definitionVersionId!, definitionKind: anchor.definitionKind,
      missingReason: matches.length > 1 ? `${matches.length} contributions match ${p} for scenario ${scenario}; keep one value per slot in the working basis`
        : absent ?? `No contribution adopted for ${p} in scenario ${scenario}`};
    missing.push(selection); return selection;
  }
  // Structure the reader takes as plain fields; each must be adopted once.
  function meta<T extends ValueType>(p: string, type: T, scenario?: string) {
    const found = own.filter((e) => rel(e) === p && e.value.type === type && (scenario === undefined || e.dimensions.scenario === scenario));
    if (found.length > 1) throw new Error("operating_projection_structure_ambiguous");
    return found[0] as (AdoptionBasisEntry & {value: Extract<AdoptionBasisEntry["value"], {type: T}>}) | undefined;
  }
  const ids = (pattern: RegExp, order: string) => {
    const found = new Set(own.flatMap((e) => {const m = pattern.exec(rel(e)); return m ? [m[1]!] : [];}));
    const listed = (meta(order, "list", top)?.value.value ?? []).filter((x) => found.has(x));
    return [...new Set(listed), ...[...found].filter((x) => !listed.includes(x)).sort()];
  };
  const has = (p: string) => own.some((e) => rel(e) === p);
  const at = (p: string, unit: string, type: ValueType) => select(p, top, unit, type);
  const drivers = (names: readonly ProjectedOperatingDriver[], path: (k: string) => string, unit: (k: ProjectedOperatingDriver) => string, type: ValueType) =>
    Object.fromEntries(names.map((k) => [k, at(path(k), unit(k), type)]));
  const scenarios = ids(scenarioPath, "order.scenarios").map((k) => {
    const p = `scenario.${k}.`, role = meta(p + "role", "text");
    if (!role) throw new Error("operating_projection_scenario_structure_missing");
    const sc = role.dimensions.scenario!, pick = (name: string, unit: string, type: ValueType) => select(p + name, sc, unit, type);
    const rule = (name: string) => has(p + name) || has(p + name + ".origin") ? {value: pick(name, "ratio", "number"), origin: pick(name + ".origin", "origin", "text")} : null;
    const overridden = [...new Set(own.flatMap((e) => {const m = overridePath.exec(rel(e)); return m && m[1] === k ? [m[2]!] : [];}))].sort();
    if (overridden.some((x) => !(projectedOperatingDriverNames as readonly string[]).includes(x))) throw new Error("operating_projection_scenario_structure_invalid");
    const shocked = own.some((e) => rel(e).startsWith(p + "shock."));
    return {id: k, label: meta(p + "label", "text", sc)?.value.value ?? k, role: z.enum(["alternative", "informed"]).parse(role.value.value),
      basedOn: meta(p + "basedOn", "text", sc)?.value.value ?? "base", scenario: sc,
      volumeGrowthRate: rule("volumeGrowthRate"), volumeFactor: rule("volumeFactor"),
      overrides: (overridden as ProjectedOperatingDriver[]).map((o) => ({driver: o, values: pick(`override.${o}`, operatingProjectionDriverUnits[o], "list"),
        origin: pick(`override.${o}.origin`, "origin", "text")})),
      inputCostShock: shocked ? {fromPeriodEnd: pick("shock.fromPeriodEnd", "date", "date"), rate: pick("shock.rate", "ratio", "number"),
        passThroughLagMonths: pick("shock.passThroughLagMonths", "months", "number"), origin: pick("shock.origin", "origin", "text")} : null};
  });
  const companyVersions = ids(versionPath, "order.versions").map((k) => {
    const p = `version.${k}.`, gap = meta(p + "causeGap", "text", top)?.value.value;
    return {id: k, label: meta(p + "label", "text", top)?.value.value ?? k, status: at(p + "status", "convention", "text"), periodEnd: at(p + "periodEnd", "date", "date"),
      metric: at(p + "metric", "convention", "text"), value: at(p + "value", "currency", "number"), origin: at(p + "origin", "origin", "text"),
      cause: select(p + "cause", top, "text", "text", gap)};
  });
  const analysis = {envelope: input.envelope, scope: input.scope, entityId: d.entityId!, perimeter: d.perimeter!, currency: d.currency!,
    openingDate: d.periodStart!, endDate: d.periodEnd!, numericInterpretations: [], analysisId, scenario: top,
    purpose: at("purpose", "text", "text"), periodEnds: at("periodEnds", "date", "list"),
    conventions: {dayCountBasis: at("convention.dayCountBasis", "convention", "text"), calibrationTolerance: at("convention.calibrationTolerance", "ratio", "number")},
    actual: {periodStart: at("actual.periodStart", "date", "date"), periodEnd: select("actual.periodEnd", top, "date", "date"),
      drivers: drivers(actualOperatingDriverNames, (k) => `actual.${k}`, (k) => operatingProjectionDriverUnits[k], "number"),
      reportedRevenue: at("actual.reportedRevenue", "currency", "number"), reportedEbitda: at("actual.reportedEbitda", "currency", "number"),
      origins: Object.fromEntries(actualOperatingItems.map((k) => [k, at(`actual.${k}.origin`, "origin", "text")]))},
    base: {drivers: drivers(projectedOperatingDriverNames, (k) => `base.${k}`, (k) => operatingProjectionDriverUnits[k], "list"),
      origins: drivers(projectedOperatingDriverNames, (k) => `base.${k}.origins`, () => "origin", "list")},
    scenarios, companyVersions};
  // A missing operand carries the lowest resolved definition so the reference is stable; the reader ignores it.
  const borrowed = [...definitions].sort((a, b) => a.definitionVersionId < b.definitionVersionId ? -1 : 1)[0];
  if (borrowed) for (const m of missing) {m.definitionVersionId = borrowed.definitionVersionId; m.definitionKind = borrowed.definitionKind;}
  return operatingProjectionPacketInputSchema.parse({schemaVersion: "operating-projection-packet-input.v1", question: input.question, analysis});
}

import {z} from "zod";
import {methodDataContractFromJsonSchema} from "@offroad/credit-playbook";
import {operatingProjectionPacketInputSchema, operatingProjectionPacketOutputSchema, operatingProjectionPacketVersion} from "./operating-projection-packet";

/** Build-owned contract publication, kept apart from the executor so the released artifact
 * bundles only the calculation and its schemas. */
export function operatingProjectionPacketExecutorContracts() {
  const options = {reused: "inline", cycles: "throw", unrepresentable: "throw"} as const;
  const inputSchema = z.toJSONSchema(operatingProjectionPacketInputSchema, {...options, io: "input"});
  const outputSchema = z.toJSONSchema(operatingProjectionPacketOutputSchema, options);
  return {schemaVersion: "method-executor-contracts.v1",
    executor: {module: "@offroad/financial-model", exportName: "prepareOperatingProjectionPacket", version: operatingProjectionPacketVersion},
    inputs: methodDataContractFromJsonSchema("operating-projection-packet-input", operatingProjectionPacketVersion, inputSchema),
    outputs: methodDataContractFromJsonSchema("operating-projection-packet-output", operatingProjectionPacketVersion, outputSchema),
    validationSchemas: {input: inputSchema, output: outputSchema}};
}

import {createHash} from "node:crypto";
import {z} from "zod";
import {financialCoreVersion} from "@offroad/financial-core";
import {adoptedDriverProjectionInputSchema, calculateAdoptedDriverProjection} from "./adopted-operating-projection-drivers";
import {adoptedDriverProjectionOutputSchema} from "./operating-projection-results";

export const operatingProjectionPacketVersion = "2026.10.26-v1";
const text = z.string().trim().min(1).max(2000), key = z.string().trim().min(1).max(160);
const hash = z.string().regex(/^[a-f0-9]{64}$/), decimal = z.string().regex(/^-?\d{1,24}(?:\.\d{1,20})?$/);
const origin = z.enum(["document", "informed", "house", "estimate"]);
/** The three things only the company knows that move a projection by driver; asked while not informed. */
export const operatingProjectionQuestions = ["volume", "pass_through", "receivable_days"] as const;

export const operatingProjectionPacketInputSchema = z.strictObject({
  schemaVersion: z.literal("operating-projection-packet-input.v1"),
  question: text,
  analysis: adoptedDriverProjectionInputSchema,
});
export type OperatingProjectionPacketInput = z.infer<typeof operatingProjectionPacketInputSchema>;

const effects = z.strictObject({ebitda: decimal, cashAvailableForDebt: decimal, changeInWorkingCapital: decimal});
export const operatingProjectionPacketOutputSchema = z.strictObject({
  schemaVersion: z.literal("operating-projection-packet.v1"), executorVersion: z.literal(operatingProjectionPacketVersion), financialCoreVersion: key,
  question: text, basisFingerprint: hash, scope: adoptedDriverProjectionInputSchema.shape.scope, entityId: z.uuid(), currency: z.string().regex(/^[A-Z]{3}$/),
  result: adoptedDriverProjectionOutputSchema,
  /** What the answer must say, in order. */
  readings: z.strictObject({
    purpose: text.nullable(),
    /** Reproducing the actual year proves arithmetic; `documented` says whether every actual operand is a document. */
    calibration: z.strictObject({periodId: key, reportedRevenue: decimal, modeledRevenue: decimal, reportedEbitda: decimal, modeledEbitda: decimal, reproduces: z.boolean(),
      reportedRevenueOrigin: origin.nullable(), reportedEbitdaOrigin: origin.nullable(), documented: z.boolean()}),
    projected: z.strictObject({
      base: z.array(z.strictObject({periodId: key, revenue: decimal, ebitda: decimal, margin: decimal.nullable(), changeInWorkingCapital: decimal,
        cashAvailableForDebt: decimal, conversion: decimal.nullable()})).min(1).max(40),
      comparisons: z.array(z.strictObject({versionId: key, status: z.enum(["approved", "under_review"]), periodId: key, metric: z.enum(["revenue", "ebitda"]),
        companyValue: decimal, projectedValue: decimal, difference: decimal, unitPriceEquivalent: decimal.nullable(), cause: text.nullable()})).max(12),
      sensitivities: z.array(z.strictObject({periodId: key, ebitdaPerOnePercentPrice: decimal, ebitdaLossPerOnePercentInputCost: decimal,
        workingCapitalPerReceivableDay: decimal})).min(1).max(40),
      scenarios: z.array(z.strictObject({id: key, role: z.enum(["alternative", "informed"]), basedOn: key,
        /** What the scenario changes and where each change comes from; only a document is data. */
        changes: z.array(z.strictObject({item: key, origin: origin.nullable(), nature: z.enum(["data", "assumption"])})).max(16),
        rows: z.array(z.strictObject({periodId: key, ebitda: decimal, margin: decimal.nullable(), cashAvailableForDebt: decimal, effects})).min(1).max(40)})).max(12),
      largestCashReduction: z.strictObject({scenarioId: key, periodId: key, cashEffect: decimal, workingCapitalChangeEffect: decimal}).nullable(),
    }).nullable(),
    /** Data and assumptions kept apart: every actual and projected operand keeps its adopted origin; only a document is data. */
    ledger: z.array(z.strictObject({driver: key, periodId: key, origin: origin.nullable(), nature: z.enum(["data", "assumption"])})).max(1024),
    questions: z.array(z.enum(operatingProjectionQuestions)).max(3),
    openQuestions: z.array(key).max(12),
  }).nullable(),
  gaps: z.array(z.strictObject({operand: text, reason: text})).max(1024),
  status: z.enum(["framed", "partial", "prepared_for_human_review"]),
  exclusions: z.array(z.enum(["financing_recommendation", "debt_service", "credit_approval", "method_release"])).length(4)
    .refine((v) => v.join("|") === "financing_recommendation|debt_service|credit_approval|method_release", "Exact exclusion ledger required"),
  grantsExecution: z.literal(false), grantsPublication: z.literal(false), fingerprint: hash,
});
export type OperatingProjectionPacket = z.infer<typeof operatingProjectionPacketOutputSchema>;
const answered = (o: string | null | undefined) => o === "informed" || o === "document";
const nature = (o: string | null) => o === "document" ? "data" as const : "assumption" as const;

/** A projection by driver for a stated purpose: the last actual year rebuilt from its drivers, the base by
 * year with cash available for debt, the company's own budget and revision side by side with the cause
 * of each difference, sensitivities in currency, the scenarios against the one each is based on, data
 * and assumptions kept apart, and at most three questions that only the company can answer. When the
 * last year is not reproduced nothing is projected. It ends at the projection; it does not recommend
 * financing. Deterministic. */
export function prepareOperatingProjectionPacket(raw: unknown): OperatingProjectionPacket {
  const input = operatingProjectionPacketInputSchema.parse(raw);
  const result = adoptedDriverProjectionOutputSchema.parse(calculateAdoptedDriverProjection(input.analysis));
  const r = result.projection;
  const readings = r ? (() => {
    const c = r.calibration, p = r.projection, roles = new Map(input.analysis.scenarios.map((s) => [s.id, s.role]));
    const causes = new Map(result.companyVersions.map((v) => [v.versionId, v.cause]));
    const periodIds = r.projection?.base.map((x) => x.periodId) ?? [];
    const ledger = [...result.origins.actual.map((a) => ({driver: a.item, periodId: c.periodId, origin: a.origin, nature: nature(a.origin)})),
      ...result.origins.base.flatMap((b) => (b.origins ?? []).map((o, i) => ({driver: b.driver, periodId: periodIds[i] ?? String(i), origin: o, nature: nature(o)})))];
    const actualOrigin = (item: string) => result.origins.actual.find((a) => a.item === item)?.origin ?? null;
    const changes = new Map(result.origins.scenarios.map((s) => [s.scenarioId, [
      ...s.volumeGrowthRate ? [{item: "volumeGrowthRate", origin: s.volumeGrowthRate}] : [], ...s.volumeFactor ? [{item: "volumeFactor", origin: s.volumeFactor}] : [],
      ...s.overrides.map((o) => ({item: o.driver, origin: o.origin})), ...s.inputCostShock ? [{item: "inputCostShock", origin: s.inputCostShock}] : []]
      .map((x) => ({...x, nature: nature(x.origin)}))]));
    const informed = result.origins.scenarios.filter((s) => roles.get(s.scenarioId) === "informed");
    const baseOf = (d: string) => result.origins.base.find((b) => b.driver === d)?.origins ?? [];
    const questions = operatingProjectionQuestions.filter((q) => q === "volume"
      ? !(baseOf("volume").every(answered) || informed.some((s) => answered(s.volumeGrowthRate) || answered(s.volumeFactor) || s.overrides.some((o) => o.driver === "volume" && answered(o.origin))))
      : q === "pass_through" ? !result.origins.scenarios.some((s) => answered(s.inputCostShock))
        : !(baseOf("receivableDays").every(answered) || informed.some((s) => s.overrides.some((o) => o.driver === "receivableDays" && answered(o.origin)))));
    return {purpose: result.purpose,
      calibration: {periodId: c.periodId, reportedRevenue: c.reportedRevenue, modeledRevenue: c.modeledRevenue, reportedEbitda: c.reportedEbitda,
        modeledEbitda: c.modeledEbitda, reproduces: c.reproduces, reportedRevenueOrigin: actualOrigin("reportedRevenue"),
        reportedEbitdaOrigin: actualOrigin("reportedEbitda"), documented: result.origins.actual.every((a) => a.origin === "document")},
      projected: p ? {
        base: p.base.map((x) => ({periodId: x.periodId, revenue: x.revenue, ebitda: x.ebitda, margin: x.margin, changeInWorkingCapital: x.changeInWorkingCapital,
          cashAvailableForDebt: x.cashAvailableForDebt, conversion: x.conversion})),
        comparisons: p.comparisons.map((x) => ({versionId: x.id, status: x.status, periodId: x.periodId, metric: x.metric, companyValue: x.companyValue,
          projectedValue: x.projectedValue, difference: x.difference, unitPriceEquivalent: x.unitPriceEquivalent, cause: causes.get(x.id) ?? null})),
        sensitivities: p.sensitivities.map((x) => ({periodId: x.periodId, ebitdaPerOnePercentPrice: x.ebitdaPerOnePercentPrice,
          ebitdaLossPerOnePercentInputCost: x.ebitdaLossPerOnePercentInputCost, workingCapitalPerReceivableDay: x.workingCapitalPerReceivableDay})),
        scenarios: p.scenarios.map((s) => ({id: s.id, role: s.role, basedOn: s.basedOn, changes: changes.get(s.id) ?? [],
          rows: s.rows.map((x) => ({periodId: x.periodId, ebitda: x.ebitda, margin: x.margin, cashAvailableForDebt: x.cashAvailableForDebt, effects: x.effects}))})),
        largestCashReduction: p.largestCashReduction} : null,
      ledger, questions, openQuestions: result.openQuestions.map((q) => q.versionId)};
  })() : null;
  const gaps = result.gaps;
  const status = !readings?.projected ? "framed" as const : gaps.length || result.openQuestions.length ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "operating-projection-packet.v1" as const, executorVersion: operatingProjectionPacketVersion, financialCoreVersion,
    question: input.question, basisFingerprint: result.basisFingerprint, scope: result.scope, entityId: result.entityId, currency: result.currency,
    result, readings, gaps, status,
    exclusions: ["financing_recommendation", "debt_service", "credit_approval", "method_release"] as const,
    grantsExecution: false as const, grantsPublication: false as const};
  return operatingProjectionPacketOutputSchema.parse({...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")});
}

import {z} from "zod";
import {actualOperatingDriverNames, projectedOperatingDriverNames} from "@offroad/financial-core";
import {capacityUuid} from "./debt-capacity-premises";
import type {ProposedHypothesis} from "./investment-premises";
import {operatingProjectionDriverUnits} from "./adopted-operating-projection-drivers";

const text = z.string().trim().min(1).max(2000), label = z.string().trim().min(1).max(300);
/** Ids travel inside field paths, so they never carry a dot. */
const key = z.string().regex(/^[a-z0-9][a-z0-9-]{0,39}$/);
/** Volumes, unit prices, days and money carry at most eight decimals, as the adopted reader takes them. */
const operand = z.string().regex(/^\d{1,24}(?:\.\d{1,8})?$/), signedOperand = z.string().regex(/^-?\d{1,24}(?:\.\d{1,8})?$/);
const rate = z.string().regex(/^\d{1,4}(?:\.\d{1,20})?$/), signedRate = z.string().regex(/^-?\d{1,4}(?:\.\d{1,20})?$/);
const origins = ["document", "informed", "house", "estimate"] as const;
type Origin = {origin: (typeof origins)[number]; source: string};
const originLabel: Record<(typeof origins)[number], string> = {document: "documento", informed: "informado", house: "premissa da casa", estimate: "estimativa"};
/** A value and where it came from; the source names the document, the message or the house rule. */
const fact = <T extends z.ZodType>(value: T) => z.strictObject({value, origin: z.enum(origins), source: text});
const driver = z.enum(projectedOperatingDriverNames);
const column = (d: z.infer<typeof driver>) => z.array(d === "taxRate" ? rate : operand);

/** The facts of one projection by driver, each with its origin. Nothing here is adopted until a person
 * confirms the set; every number the method reads comes from the adopted basis. */
export const operatingProjectionFactsSchema = z.strictObject({
  projectionId: z.uuid(), entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/), definitionVersionId: z.uuid(),
  purpose: fact(text),
  conventions: z.strictObject({dayCountBasis: fact(z.enum(["360", "365"])), calibrationTolerance: fact(rate)}),
  /** The last actual year; its drivers rebuild the reported revenue and EBITDA. */
  actual: z.strictObject({periodStart: z.iso.date(), periodEnd: z.iso.date(),
    drivers: fact(z.strictObject(Object.fromEntries(actualOperatingDriverNames.map((k) => [k, operand])) as Record<(typeof actualOperatingDriverNames)[number], typeof operand>)),
    reportedRevenue: fact(signedOperand), reportedEbitda: fact(signedOperand)}),
  periodEnds: z.array(z.iso.date()).min(1).max(40),
  /** One column per driver, one value and one origin per projected year. */
  base: z.array(z.strictObject({driver, values: z.array(z.string()).min(1).max(40), origins: z.array(z.enum(origins)).min(1).max(40), source: text})).length(13),
  scenarios: z.array(z.strictObject({id: key, label, role: z.enum(["alternative", "informed"]), basedOn: key,
    volumeGrowthRate: fact(signedRate).nullable(), volumeFactor: fact(rate).nullable(),
    overrides: z.array(z.strictObject({driver, values: z.array(z.string()).min(1).max(40), origin: z.enum(origins), source: text})).max(13),
    inputCostShock: fact(z.strictObject({fromPeriodEnd: z.iso.date(), rate: signedRate, passThroughLagMonths: z.number().int().min(0).max(12)})).nullable(),
  })).max(12),
  /** The company's own budget or revision; compared, never replaced. A cause not stated is null and its source says so. */
  companyVersions: z.array(z.strictObject({id: key, label,
    version: fact(z.strictObject({status: z.enum(["approved", "under_review"]), periodEnd: z.iso.date(), metric: z.enum(["revenue", "ebitda"]), value: signedOperand})),
    cause: fact(text.nullable())})).max(12),
}).superRefine((f, ctx) => {
  const fail = (message: string) => ctx.addIssue({code: "custom", message});
  const n = f.periodEnds.length;
  if (f.actual.periodEnd < f.actual.periodStart) fail("The actual year must end after it starts");
  if (f.periodEnds.some((d, i) => d <= (i === 0 ? f.actual.periodEnd : f.periodEnds[i - 1]!))) fail("Projected periods must follow the actual year in order");
  if (new Set(f.base.map((b) => b.driver)).size !== 13) fail("Every driver needs one base column");
  for (const b of f.base) {
    if (b.values.length !== n || b.origins.length !== n) fail(`Base column ${b.driver} must have one value and one origin per projected year`);
    if (!column(b.driver).safeParse(b.values).success) fail(`Base column ${b.driver} has an invalid value`);
  }
  const ids = new Set<string>(["base"]);
  for (const s of f.scenarios) {
    if (ids.has(s.id)) fail("Duplicate scenario");
    if (!ids.has(s.basedOn)) fail(`Scenario ${s.id} must be based on the base or an earlier scenario`);
    ids.add(s.id);
    if (new Set(s.overrides.map((o) => o.driver)).size !== s.overrides.length) fail(`Scenario ${s.id} repeats an override`);
    for (const o of s.overrides) if (o.values.length !== n || !column(o.driver).safeParse(o.values).success) fail(`Override ${o.driver} of ${s.id} must have one valid value per projected year`);
    if (s.volumeGrowthRate && s.volumeFactor) fail(`Scenario ${s.id} has two volume rules`);
    if ((s.volumeGrowthRate || s.volumeFactor) && s.overrides.some((o) => o.driver === "volume")) fail(`Scenario ${s.id} has two volume rules`);
    if (s.inputCostShock && !f.periodEnds.includes(s.inputCostShock.value.fromPeriodEnd)) fail(`Scenario ${s.id} shocks an unknown period`);
  }
  if (new Set(f.companyVersions.map((v) => v.id)).size !== f.companyVersions.length) fail("Duplicate company version");
  for (const v of f.companyVersions) {
    if (v.version.origin !== "document" && v.version.origin !== "informed") fail(`Company version ${v.id} must come from the company`);
    if (!f.periodEnds.includes(v.version.value.periodEnd)) fail(`Company version ${v.id} is for an unknown period`);
  }
});
export type OperatingProjectionFacts = z.infer<typeof operatingProjectionFactsSchema>;

export const operatingProjectionAnalysisId = (projectionId: string) => capacityUuid(`offroad:operating-projection:${projectionId}:analysis`);
/** The size of one working basis. */
export const maxOperatingProjectionHypotheses = 256;

/** The hypotheses one confirmation adopts, at the paths, units and scenarios the adopted reader reads
 * (`operating_projection.<analysis>.`). Each scenario adopts only what it changes, in its own scenario.
 * The reader's structure (scenario order, labels, roles and bases; version labels) is adopted as extra
 * hypotheses it ignores, so the packet is composed from the basis alone. A cause not stated adopts no
 * cause and states why. Every reason states the origin. Deterministic. */
export function proposeOperatingProjectionHypotheses(raw: unknown): ProposedHypothesis[] {
  const f = operatingProjectionFactsSchema.parse(raw);
  const out: ProposedHypothesis[] = [], prefix = `operating_projection.${operatingProjectionAnalysisId(f.projectionId)}.`;
  const why = (x: Origin) => `Origem: ${originLabel[x.origin]}. ${x.source}`;
  const house = (source: string) => `Origem: premissa da casa. ${source}`;
  const add = (path: string, unit: string, value: ProposedHypothesis["value"], reason: string, scenario = "base") => out.push({fieldPath: prefix + path,
    dimensions: {entityId: f.entityId, perimeter: f.perimeter, periodStart: f.actual.periodEnd, periodEnd: f.periodEnds[f.periodEnds.length - 1]!, currency: f.currency,
      unit, scale: "1", scenario, definitionVersionId: f.definitionVersionId}, value, reason});
  const txt = (path: string, unit: string, value: string, reason: string, scenario?: string) => add(path, unit, {type: "text", value}, reason, scenario);
  const num = (path: string, unit: string, value: string, reason: string, scenario?: string) => add(path, unit, {type: "number", value}, reason, scenario);
  const list = (path: string, unit: string, value: string[], reason: string, scenario?: string) => add(path, unit, {type: "list", value}, reason, scenario);
  const date = (path: string, value: string, reason: string, scenario?: string) => add(path, "date", {type: "date", value}, reason, scenario);
  txt("purpose", "text", f.purpose.value, why(f.purpose));
  list("periodEnds", "date", f.periodEnds, house("Anos projetados"));
  txt("convention.dayCountBasis", "convention", f.conventions.dayCountBasis.value, why(f.conventions.dayCountBasis));
  num("convention.calibrationTolerance", "ratio", f.conventions.calibrationTolerance.value, why(f.conventions.calibrationTolerance));
  date("actual.periodStart", f.actual.periodStart, why(f.actual.drivers));
  date("actual.periodEnd", f.actual.periodEnd, why(f.actual.drivers));
  for (const k of actualOperatingDriverNames) num(`actual.${k}`, operatingProjectionDriverUnits[k], f.actual.drivers.value[k], why(f.actual.drivers));
  num("actual.reportedRevenue", "currency", f.actual.reportedRevenue.value, why(f.actual.reportedRevenue));
  num("actual.reportedEbitda", "currency", f.actual.reportedEbitda.value, why(f.actual.reportedEbitda));
  // The origin of every actual operand is adopted: reproducing the year proves arithmetic, not that the figures are documents.
  for (const k of actualOperatingDriverNames) txt(`actual.${k}.origin`, "origin", f.actual.drivers.origin, why(f.actual.drivers));
  txt("actual.reportedRevenue.origin", "origin", f.actual.reportedRevenue.origin, why(f.actual.reportedRevenue));
  txt("actual.reportedEbitda.origin", "origin", f.actual.reportedEbitda.origin, why(f.actual.reportedEbitda));
  for (const b of f.base) {
    const reason = `Origem: ${[...new Set(b.origins)].map((o) => originLabel[o]).join(", ")}. ${b.source}`;
    list(`base.${b.driver}`, operatingProjectionDriverUnits[b.driver], b.values, reason);
    list(`base.${b.driver}.origins`, "origin", b.origins, reason);
  }
  list("order.scenarios", "identity", f.scenarios.map((s) => s.id), house("Ordem de leitura dos cenários"));
  for (const s of f.scenarios) {
    const p = `scenario.${s.id}.`, sc = s.id;
    txt(p + "label", "explanation", s.label, house("Nome do cenário"), sc);
    txt(p + "role", "convention", s.role, house("Papel do cenário"), sc);
    txt(p + "basedOn", "identity", s.basedOn, house("Cenário de referência"), sc);
    for (const [name, r] of [["volumeGrowthRate", s.volumeGrowthRate], ["volumeFactor", s.volumeFactor]] as const) if (r) {
      num(p + name, "ratio", r.value, why(r), sc); txt(p + name + ".origin", "origin", r.origin, why(r), sc);
    }
    for (const o of s.overrides) {
      list(p + `override.${o.driver}`, operatingProjectionDriverUnits[o.driver], o.values, why(o), sc);
      txt(p + `override.${o.driver}.origin`, "origin", o.origin, why(o), sc);
    }
    const c = s.inputCostShock;
    if (c) {
      date(p + "shock.fromPeriodEnd", c.value.fromPeriodEnd, why(c), sc);
      num(p + "shock.rate", "ratio", c.value.rate, why(c), sc);
      num(p + "shock.passThroughLagMonths", "months", String(c.value.passThroughLagMonths), why(c), sc);
      txt(p + "shock.origin", "origin", c.origin, why(c), sc);
    }
  }
  list("order.versions", "identity", f.companyVersions.map((v) => v.id), house("Ordem de leitura das versões da companhia"));
  for (const v of f.companyVersions) {
    const p = `version.${v.id}.`, r = why(v.version);
    txt(p + "label", "explanation", v.label, r);
    txt(p + "status", "convention", v.version.value.status, r);
    date(p + "periodEnd", v.version.value.periodEnd, r);
    txt(p + "metric", "convention", v.version.value.metric, r);
    num(p + "value", "currency", v.version.value.value, r);
    txt(p + "origin", "origin", v.version.origin, r);
    // A cause not stated is asked, never assumed: the reason it is missing is adopted instead.
    if (v.cause.value === null) txt(p + "causeGap", "explanation", v.cause.source, why(v.cause));
    else txt(p + "cause", "text", v.cause.value, why(v.cause));
  }
  if (out.length > maxOperatingProjectionHypotheses) throw new Error("operating_projection_premises_exceed_basis");
  return out;
}

import {z} from "zod";
import {adoptionBasisEntrySchema} from "@offroad/reconciliation";
import {adoptedAnalysisContextSchema} from "./adopted-analysis-binding";

