}
const assumption = (p: Packet, id: string) => p.readings!.assumptions.find((a) => a.assumptionId === id)!;
const driver = (p: Packet, id: string, d: string) => assumption(p, id).drivers.find((x) => x.driver === d)!;

function goldCases(): Case[] {
