  const bridges = bridgeIds.map((lineId) => ({lineId, causes: causes.filter((c) => c.lineId === lineId).map((c) => c.cause)}));
  const streamUpdates = keys("streamUpdate", "order.streamUpdates").map((streamId) => {
    const p = `streamUpdate.${streamId}.`;
    const kind = meta(p + "transformKind", "text", "quarter_update_stream_transform", false), unit = kind === "delay" ? "days" : "ratio";
    return {streamId, causeIds: z.array(keyOf).parse(meta(p + "causeIds", "list", "quarter_update_stream_causes", true)),
      transformKind: select(p + "transformKind", "convention", "text"), transformValue: select(p + "transformValue", unit, "number")};
  });
  const addedStreams = keys("added", "order.added").map((id) => {
    const p = `added.${id}.`;
    return {id, label: select(p + "label", "text", "text"), dates: select(p + "dates", "date", "list"), amounts: select(p + "amounts", "currency", "list")};
  });
  const facilities = keys("facility", "order.facilities").map((id) => {
    const p = `facility.${id}.`;
    return {id, label: select(p + "label", "text", "text"), limit: select(p + "limit", "currency", "number"), source: select(p + "source", "text", "text")};
  });
  const steps = keys("step", "order.steps").map((facilityId) => {
    const p = `step.${facilityId}.`, mode = z.enum(["fixed", "residual"]).parse(meta(p + "mode", "text", "quarter_update_step_mode", true));
    return mode === "fixed" ? {facilityId, mode, streamId: one(p + "streamId", "quarter_update_step_stream"),
      replacesStreamIds: z.array(keyOf).parse(meta(p + "replacesStreamIds", "list", "quarter_update_step_replacement", true))}
      : {facilityId, mode, date: select(p + "date", "date", "date")};
  });
  const dependents = keys("dependent", "order.dependents").map((id) => {
    const p = `dependent.${id}.`;
    return {id, label: select(p + "label", "text", "text"), kind: select(p + "kind", "convention", "text"), reads: select(p + "reads", "identity", "list"),
      horizonStart: select(p + "horizonStart", "date", "date"), horizonEnd: select(p + "horizonEnd", "date", "date"), recomputedBy: select(p + "recomputedBy", "convention", "text"), owner: optional(p + "owner", "text", "text"),
      quantities: select(p + "quantities", "identity", "list"), definition: optional(p + "definition", "text", "text"), scenario: optional(p + "scenario", "identity", "text")};
  });
  const measurementIds = z.array(keyOf).min(1).parse(meta("covenant.measurementIds", "list", "quarter_update_covenant_measurement", true));
  const update = {envelope: closeInput.envelope, scope: closeInput.scope, entityId: d.entityId!, perimeter: d.perimeter!, currency: d.currency!,
    openingDate: d.periodStart!, endDate: d.periodEnd!, numericInterpretations: [], analysisId, scenario: sc,
    priorWeeklyFingerprint: select("prior.weeklyCash.fingerprint", "identity", "text"), priorCovenantFingerprint: select("prior.covenant.fingerprint", "identity", "text"),
    lines, carry: {cashLineId: one("carry.cashLineId", "quarter_update_carry"), ebitdaLineId: one("carry.ebitdaLineId", "quarter_update_carry")},
    bridges, streamUpdates, addedStreams, covenant: {measurementIds}, facilities, steps, dependents, materialityFloor: select("materialityFloor", "currency", "number")};
  // A missing operand carries the lowest resolved definition so the reference is stable; the executor ignores it.
  const borrowed = [...definitions].sort((a, b) => a.definitionVersionId < b.definitionVersionId ? -1 : 1)[0];
  if (borrowed) for (const m of missing) {m.definitionVersionId = borrowed.definitionVersionId; m.definitionKind = borrowed.definitionKind;}
  return {update, measurementIds};
}

import {z} from "zod";
import {methodDataContractFromJsonSchema} from "@offroad/credit-playbook";
import {quarterUpdatePacketInputSchema, quarterUpdatePacketOutputSchema, quarterUpdatePacketVersion} from "./quarter-update-packet";

/** Build-owned contract publication, kept apart from the executor so the released artifact
 * bundles only the calculation and its schemas. */
export function quarterUpdatePacketExecutorContracts() {
  const options = {reused: "inline", cycles: "throw", unrepresentable: "throw"} as const;
  const inputSchema = z.toJSONSchema(quarterUpdatePacketInputSchema, {...options, io: "input"});
  const outputSchema = z.toJSONSchema(quarterUpdatePacketOutputSchema, options);
  return {schemaVersion: "method-executor-contracts.v1",
    executor: {module: "@offroad/financial-model", exportName: "prepareQuarterUpdatePacket", version: quarterUpdatePacketVersion},
    inputs: methodDataContractFromJsonSchema("quarter-update-packet-input", quarterUpdatePacketVersion, inputSchema),
    outputs: methodDataContractFromJsonSchema("quarter-update-packet-output", quarterUpdatePacketVersion, outputSchema),
    validationSchemas: {input: inputSchema, output: outputSchema}};
}

import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {z} from "zod";
import {financialCoreVersion} from "@offroad/financial-core";
import {calculateAdoptedQuarterUpdate, quarterUpdateAnalysesSchema} from "./adopted-quarter-update";
import {adoptedQuarterUpdateOutputSchema} from "./quarter-update-results";

export const quarterUpdatePacketVersion = "2026.10.26-v1";
const Exact = Decimal.clone({precision: 60});
const text = z.string().trim().min(1).max(2000), key = z.string().trim().min(1).max(160);
const hash = z.string().regex(/^[a-f0-9]{64}$/), decimal = z.string().regex(/^-?\d{1,24}(?:\.\d{1,20})?$/);
const week = z.strictObject({weekStart: z.iso.date(), closing: decimal});
const beforeAfter = <T extends z.ZodType>(v: T) => z.strictObject({prior: v, updated: v});

/** One question after a quarter closes. The prior weekly cash and covenant test travel as they were
 * adopted; the close is its own basis. */
export const quarterUpdatePacketInputSchema = z.strictObject({
  schemaVersion: z.literal("quarter-update-packet-input.v1"),
  question: text,
  analysis: quarterUpdateAnalysesSchema,
  /** Dependents the question names explicitly; if one of them is not updated here the packet is partial. */
  askedDependentIds: z.array(key).max(24).default([]),
}).superRefine((i, ctx) => {
  if (i.askedDependentIds.some((id) => !i.analysis.update.dependents.some((d) => d.id === id))) ctx.addIssue({code: "custom", message: "The question names a dependent the analysis does not carry"});
});
export type QuarterUpdatePacketInput = z.infer<typeof quarterUpdatePacketInputSchema>;
const decisions = ["short_term_financing", "covenant_headroom", "third_party_material"] as const;
const packetExclusions = ["accounting_close", "cause_attribution", "financing_cost_comparison", "third_party_distribution", "credit_approval"] as const;

export const quarterUpdatePacketOutputSchema = z.strictObject({
  schemaVersion: z.literal("quarter-update-packet.v1"), executorVersion: z.literal(quarterUpdatePacketVersion), financialCoreVersion: key,
  question: text, basisFingerprint: hash, scope: quarterUpdateAnalysesSchema.shape.update.shape.scope, entityId: z.uuid(), currency: z.string().regex(/^[A-Z]{3}$/),
  result: adoptedQuarterUpdateOutputSchema,
  /** What the answer must say, in order: what changed, why, what persists, what it changes, the action, what did not change and the question. */
  readings: z.strictObject({
    deviations: z.array(z.strictObject({lineId: key, projected: decimal, actual: decimal, deviation: decimal})).max(24),
    bridges: z.array(z.strictObject({lineId: key, deviation: decimal, residual: decimal,
      causes: z.array(z.strictObject({id: key, label: text, amount: decimal, classification: z.enum(["calendar", "structural"]), until: z.iso.date().nullable()})).max(12)})).max(8),
    persisting: z.array(z.strictObject({causeId: key, until: z.iso.date(), nature: z.enum(["flow", "balance"]), weeklyEffect: decimal.nullable(), materialityFloor: decimal,
      ebitdaAhead: decimal, cashAhead: decimal})).max(96),
    /** The weekly series are derived from the prior ones by each cause's transform; a cause propagates only if its derived effect
     * reaches the larger of the absolute floor (R$ 1,000 in the basis's units) and the relative share of its own amount. */
    materiality: z.strictObject({absolute: decimal, relative: decimal}),
    oneOff: z.array(key).max(96),
    /** A balance shift (receivable days) is already inside the closed cash and is carried once; it is never absorbed again ahead.
     * The ficha C54 oracle absorbs it a second time in the December test; this method does not. */
    balanceShiftsCarriedOnce: z.array(z.strictObject({causeId: key, amount: decimal})).max(96),
    tightestWeek: beforeAfter(week), shortfallToMinimum: beforeAfter(decimal), closingAtHorizon: beforeAfter(decimal),
    /** The facility that tops up the weeks: whether the need now exceeds its limit and where its whole limit leaves the tightest week. */
    topUp: z.strictObject({facilityId: key, limit: decimal, needExceedsLimit: z.boolean(), fullLimitMinimum: week, fullLimitCovers: z.boolean()}).nullable(),
    action: z.strictObject({steps: z.array(z.strictObject({facilityId: key, amount: decimal, limit: decimal, withinLimit: z.boolean()})).max(4),
      withinApproved: z.boolean(), covers: z.boolean().nullable(), minimumAfter: week.nullable()}),
    /** One reading per definition: the indenture's and, when the board adopted it, the managerial one; each headroom names the definition it is measured on. */
    covenant: z.strictObject({
      measurements: z.array(z.strictObject({measurementId: key, definitionRead: text, ratio: beforeAfter(decimal.nullable()), trailingEbitda: beforeAfter(decimal)})).max(8),
      headroom: z.array(z.strictObject({measurementId: key, definitionRead: text, limitId: key, kind: z.enum(["contractual", "board_policy"]), limitDefinition: text.nullable(),
        ebitdaHeadroom: beforeAfter(decimal), breached: z.boolean()})).max(16),
      anyBreach: z.boolean(), notUpdated: z.array(key).max(24)}),
    /** The year's EBITDA as the leading test reads it (the trailing twelve months at the test date). */
    projectedEbitda: beforeAfter(decimal),
    decisionsChanged: z.array(z.enum(decisions)).max(3),
    /** Updated only for a result this packet computes; the rest is affected (with the method that owns it), unchanged or stale. */
    updated: z.array(key).max(24), unchanged: z.array(key).max(24), stale: z.array(key).max(24), affectedNotRecomputed: z.array(key).max(24),
    ownedElsewhere: z.array(z.strictObject({dependentId: key, owner: text.nullable()})).max(24),
    openQuestions: z.array(z.strictObject({causeId: key, question: text})).max(96),
    /** The prior versions are kept as adopted; this packet never sends a material to anyone. */
    priorVersionsKept: z.literal(true), sentToThirdParties: z.literal(false),
  }).nullable(),
  gaps: z.array(z.strictObject({operand: text, reason: text})).max(1024),
  status: z.enum(["framed", "partial", "prepared_for_human_review"]),
  exclusions: z.array(z.enum(packetExclusions)).length(5).refine((v) => v.join("|") === packetExclusions.join("|"), "Exact exclusion ledger required"),
  grantsExecution: z.literal(false), grantsPublication: z.literal(false), fingerprint: hash,
});
export type QuarterUpdatePacket = z.infer<typeof quarterUpdatePacketOutputSchema>;

/** What the closed quarter changed and what it changes ahead: actual against projected; EBITDA and
 * cash explained by cause to the exact deviation, the residual named; what is one-off and what persists
 * until a date; the weekly cash and the covenant test measured again on the prior versions, kept beside
 * the update; whether the need now exceeds the facility that tops up the weeks; the action within what
 * is approved; the covenant by each definition read, indenture and managerial, with the definition behind
 * each headroom; which dependents were updated, which did not change and which material is stale; and the
 * question that changes the diagnosis. A balance shift is carried once in the closed cash: unlike the ficha
 * C54 oracle, it is not absorbed again in the December test. Deterministic; it never sends a material to a
 * third party. */
export function prepareQuarterUpdatePacket(raw: unknown): QuarterUpdatePacket {
  const input = quarterUpdatePacketInputSchema.parse(raw);
  const result = adoptedQuarterUpdateOutputSchema.parse(calculateAdoptedQuarterUpdate(input.analysis));
  const u = result.update;
  const readings = u ? (() => {
    const causes = u.bridges.flatMap((b) => b.causes);
    const residualStep = u.action.steps.find((s) => s.mode === "residual"), full = u.action.fullLimit[0];
    const topUp = residualStep && full ? {facilityId: residualStep.facilityId, limit: residualStep.limit,
      needExceedsLimit: new Exact(u.weekly.tightest.updated.shortfallToMinimum).gt(residualStep.limit), fullLimitMinimum: full.minimum, fullLimitCovers: full.covers} : null;
    const definitions = new Map(result.covenantDefinitions.map((d) => [d.limitId, d.definition]));
    const headroom = u.covenant.measurements.flatMap((m) => {
      const before = u.covenant.prior.measurements.find((x) => x.id === m.id)!, after = u.covenant.updated.measurements.find((x) => x.id === m.id)!;
      return after.tests.map((t) => ({measurementId: m.id, definitionRead: m.label, limitId: t.limitId, kind: t.kind, limitDefinition: definitions.get(t.limitId) ?? null, breached: t.breached,
        ebitdaHeadroom: {prior: before.tests.find((x) => x.limitId === t.limitId)!.ebitdaHeadroom, updated: t.ebitdaHeadroom}}));
    });
    const lessHeadroom = headroom.some((h) => new Exact(h.ebitdaHeadroom.updated).lt(h.ebitdaHeadroom.prior));
    const needGrew = new Exact(u.weekly.tightest.updated.shortfallToMinimum).gt(u.weekly.tightest.prior.shortfallToMinimum);
    const by = (status: string) => u.dependents.filter((d) => d.status === status).map((d) => d.id);
    const last = u.action.steps[u.action.steps.length - 1];
    return {
      deviations: u.lines.map((l) => ({lineId: l.id, projected: l.projected, actual: l.actual, deviation: l.deviation})),
      bridges: u.bridges.map((b) => ({lineId: b.lineId, deviation: b.deviation, residual: b.residual,
        causes: b.causes.map((c) => ({id: c.id, label: c.label, amount: c.amount, classification: c.classification, until: c.until}))})),
      persisting: u.propagation.filter((p) => p.classification === "structural").map((p) => ({causeId: p.causeId, until: p.until!, nature: p.nature!,
        weeklyEffect: p.weeklyEffect, materialityFloor: p.materialityFloor!, ebitdaAhead: p.ebitdaAhead!, cashAhead: p.cashAhead!})),
      materiality: u.materiality,
      balanceShiftsCarriedOnce: causes.filter((c) => c.nature === "balance").map((c) => ({causeId: c.id, amount: c.amount})),
      oneOff: causes.filter((c) => c.classification === "calendar").map((c) => c.id),
      tightestWeek: {prior: {weekStart: u.weekly.tightest.prior.weekStart, closing: u.weekly.tightest.prior.closing},
        updated: {weekStart: u.weekly.tightest.updated.weekStart, closing: u.weekly.tightest.updated.closing}},
      shortfallToMinimum: {prior: u.weekly.tightest.prior.shortfallToMinimum, updated: u.weekly.tightest.updated.shortfallToMinimum},
      closingAtHorizon: u.weekly.closing, topUp,
      action: {steps: u.action.steps.map((s) => ({facilityId: s.facilityId, amount: s.amount, limit: s.limit, withinLimit: s.withinLimit})),
        withinApproved: u.action.withinApproved, covers: u.action.covers, minimumAfter: last ? last.minimum : null},
      covenant: {measurements: u.covenant.measurements.map((m) => ({measurementId: m.id, definitionRead: m.label, ratio: m.ratio, trailingEbitda: m.trailingEbitda})),
        headroom, anyBreach: u.covenant.updated.anyBreach, notUpdated: u.covenant.measurementsNotUpdated},
      projectedEbitda: u.covenant.measurements[0]!.trailingEbitda,
      // A decision changes when the need grows, the headroom shrinks or a material sent before the close no longer carries the closed figures.
      decisionsChanged: [...needGrew ? ["short_term_financing" as const] : [], ...lessHeadroom ? ["covenant_headroom" as const] : [], ...by("stale").length ? ["third_party_material" as const] : []],
      updated: by("updated"), unchanged: by("unchanged"), stale: by("stale"), affectedNotRecomputed: by("affected_not_recomputed"),
      ownedElsewhere: u.dependents.filter((d) => d.status === "affected_not_recomputed" && d.binding !== "matched").map((d) => ({dependentId: d.id, owner: d.owner})),
      openQuestions: causes.filter((c) => c.question !== null).map((c) => ({causeId: c.id, question: c.question!})),
      priorVersionsKept: true as const, sentToThirdParties: false as const,
    };
  })() : null;
  // A dependent the question names and this packet does not update is a gap; otherwise it is information for its owner.
  const asked = (u?.dependents ?? []).filter((d) => input.askedDependentIds.includes(d.id) && d.status === "affected_not_recomputed" && d.binding !== "matched")
    .map((d) => ({operand: `quarter_update.${result.analysisId}.dependent.${d.id}`, reason: "asked_dependent_not_recomputed"}));
  const gaps = [...result.gaps, ...(u?.gaps ?? []).map((g) => ({operand: `quarter_update.${result.analysisId}.${g.item}`, reason: g.reason})), ...asked];
  const status = !u ? "framed" as const : gaps.length ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "quarter-update-packet.v1" as const, executorVersion: quarterUpdatePacketVersion, financialCoreVersion,
    question: input.question, basisFingerprint: result.basisFingerprint, scope: result.scope, entityId: result.entityId, currency: result.currency,
    result, readings, gaps, status, exclusions: packetExclusions, grantsExecution: false as const, grantsPublication: false as const};
  return quarterUpdatePacketOutputSchema.parse({...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")});
}

import {z} from "zod";
import {capacityUuid} from "./debt-capacity-premises";
import type {ProposedHypothesis} from "./investment-premises";

const text = z.string().trim().min(1).max(2000);
const key = z.string().regex(/^[a-z0-9][a-z0-9-]{0,39}$/);
/** Money carries at most eight decimals, as the adopted numeric representation reads it. */
const money = z.string().regex(/^-?\d{1,24}(?:\.\d{1,8})?$/);
const unsignedMoney = z.string().regex(/^\d{1,24}(?:\.\d{1,8})?$/);
/** Days and ratios stay within six integer digits. */
const measure = /^-?\d{1,6}(?:\.\d{1,8})?$/;
const hash = z.string().regex(/^[a-f0-9]{64}$/);
const origins = ["document", "informed", "house", "estimate"] as const;
const originLabel: Record<(typeof origins)[number], string> = {document: "documento", informed: "informado", house: "premissa da casa", estimate: "estimativa"};
/** A value and where it came from; the source names the document, the message or the house rule. */
const fact = <T extends z.ZodType>(value: T) => z.strictObject({value, origin: z.enum(origins), source: text});
type Origin = {origin: (typeof origins)[number]; source: string};

/** A currency line is money in the basis's own units, the units of the prior results it updates (reais when
 * the priors are in reais); a line in days or a ratio is a measure. */
const line = z.strictObject({id: key, label: text, unit: z.enum(["currency", "days", "ratio"]), projected: money, actual: money})
  .refine((l) => l.unit === "currency" || (measure.test(l.projected) && measure.test(l.actual)), {message: "A line in days or a ratio carries at most six integer digits"});
/** A cause of one bridged deviation: one-off (calendar) or persisting until a date (structural). */
const cause = z.strictObject({id: key, label: text, amount: money, classification: z.enum(["calendar", "structural"]), until: z.iso.date().nullable(),
  equalsDeviationOf: key.nullable(), driverLineId: key.nullable(), basis: z.enum(["document", "interpretation"]), question: text.nullable(),
  /** A structural flow recurs each period; a structural balance shift is carried once in the closed cash. Null for a calendar cause. */
  nature: z.enum(["flow", "balance"]).nullable()});
const series = {dates: z.array(z.iso.date()).min(1).max(2000), amounts: z.array(unsignedMoney).min(1).max(2000)};
const step = z.discriminatedUnion("mode", [
  z.strictObject({facilityId: key, mode: z.literal("fixed"), streamId: key, replacesStreamIds: z.array(key).min(1).max(8)}),
  z.strictObject({facilityId: key, mode: z.literal("residual"), date: z.iso.date()})]);
/** recomputedBy names the result this packet computes ("weekly_cash", "covenant:<measurement>", "projection:<year>") or "none"; owner names the method that must recompute it otherwise. */
const dependent = z.strictObject({id: key, label: text, kind: z.enum(["analysis", "plan", "material"]), reads: z.array(key).max(24),
  horizonStart: z.iso.date(), horizonEnd: z.iso.date(), recomputedBy: z.string().regex(/^(none|weekly_cash|covenant:[a-z0-9][a-z0-9-]{0,39}|projection:[1-9]\d{3})$/), owner: text.nullable(),
  /** Its economic identity: the quantities it consumes, and the definition and scenario they are measured on. */
  quantities: z.array(z.string().regex(/^[a-z][a-z0-9_]{0,59}$/)).max(8), definition: text.nullable(), scenario: text.nullable()});
/** How the cause moves the series inside its window: amounts scaled by a factor, or events delayed by days. */
const transform = z.discriminatedUnion("kind", [z.strictObject({kind: z.literal("scale"), factor: z.string().regex(/^\d{1,4}(?:\.\d{1,8})?$/)}),
  z.strictObject({kind: z.literal("delay"), days: z.number().int().min(-366).max(366)})]);

/** The facts of one quarter close, each with its origin. The prior weekly cash and covenant test are
 * named by the fingerprint of the basis each was adopted on; nothing of them is restated here. Nothing
 * is adopted until a person confirms the set; every number the method reads comes from the basis. */
export const quarterUpdateFactsSchema = z.strictObject({
  updateId: z.uuid(), entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/), definitionVersionId: z.uuid(),
  quarterStart: z.iso.date(), quarterEnd: z.iso.date(),
  priorWeeklyFingerprint: fact(hash), priorCovenantFingerprint: fact(hash),
  lines: z.array(fact(line)).min(1).max(24),
  carry: fact(z.strictObject({cashLineId: key, ebitdaLineId: key})),
  bridges: z.array(z.strictObject({lineId: key, causes: z.array(fact(cause)).min(1).max(12)})).min(2).max(8),
  /** Series moved by one cause each: the method derives them from the prior weekly cash by the transform. */
  streamUpdates: z.array(fact(z.strictObject({streamId: key, causeIds: z.array(key).min(1).max(8), transform}))).max(16),
  /** R$ 1,000 in the basis's own units (0.001 when figures are in millions). */
  materialityFloor: fact(unsignedMoney),
  addedStreams: z.array(fact(z.strictObject({id: key, label: text, ...series}))).max(4),
  /** The prior test measurements the close updates, the leading one first; their effects are derived, never stated. */
  covenant: fact(z.strictObject({measurementIds: z.array(key).min(1).max(8)})),
  facilities: z.array(fact(z.strictObject({id: key, label: text, limit: unsignedMoney, source: text}))).max(8),
  steps: z.array(fact(step)).max(4),
  dependents: z.array(fact(dependent)).max(24),
}).superRefine((f, ctx) => {
  const fail = (message: string) => ctx.addIssue({code: "custom", message});
  if (f.quarterEnd <= f.quarterStart) fail("The quarter must end after it starts");
  const lines = new Map(f.lines.map((l) => [l.value.id, l.value]));
  if (lines.size !== f.lines.length) fail("Duplicate line");
  const known = (id: string | null) => id === null || lines.has(id);
  const {cashLineId, ebitdaLineId} = f.carry.value;
  if (cashLineId === ebitdaLineId || [cashLineId, ebitdaLineId].some((id) => lines.get(id)?.unit !== "currency")) fail("Cash and EBITDA must be two currency lines of the close");
  if (new Set(f.bridges.map((b) => b.lineId)).size !== f.bridges.length || ![cashLineId, ebitdaLineId].every((id) => f.bridges.some((b) => b.lineId === id))) fail("Cash and EBITDA each need one bridge");
  const causes = new Map<string, z.infer<typeof cause>>();
  for (const b of f.bridges) {
    if (lines.get(b.lineId)?.unit !== "currency") fail(`Bridge ${b.lineId} must be a currency line of the close`);
    for (const {value: c} of b.causes) {
      if (causes.has(c.id)) fail(`Duplicate cause ${c.id}`);
      causes.set(c.id, c);
      if ((c.classification === "structural") !== (c.until !== null)) fail(`Cause ${c.id}: a structural cause persists until a date; a calendar cause has none`);
      if (c.until !== null && c.until <= f.quarterEnd) fail(`Cause ${c.id} must persist past the close`);
      if ((c.classification === "structural") !== (c.nature !== null)) fail(`Cause ${c.id}: only a structural cause is a flow or a balance shift`);
      if (c.classification === "structural" && b.lineId !== cashLineId && b.lineId !== ebitdaLineId) fail(`Cause ${c.id}: a structural cause belongs to the cash or the EBITDA bridge`);
      if (c.nature === "balance" && b.lineId !== cashLineId) fail(`Cause ${c.id}: a balance shift belongs to the cash bridge`);
      if (!known(c.equalsDeviationOf) || !known(c.driverLineId) || c.equalsDeviationOf === b.lineId) fail(`Cause ${c.id} names a line the close does not carry`);
    }
  }
  const structural = (id: string) => causes.get(id)?.classification === "structural";
  for (const {value: u} of f.streamUpdates) {
    if (!u.causeIds.every(structural)) fail(`Stream ${u.streamId} must be moved by structural causes of the close`);
  }
  for (const {value: s} of f.addedStreams) if (s.dates.length !== s.amounts.length) fail(`Stream ${s.id} must have one amount per date`);
  if (new Set(f.covenant.value.measurementIds).size !== f.covenant.value.measurementIds.length) fail("Duplicate covenant measurement");
  const facilities = new Set(f.facilities.map((x) => x.value.id));
  if (facilities.size !== f.facilities.length) fail("Duplicate facility");
  if (new Set(f.steps.map((s) => s.value.facilityId)).size !== f.steps.length || f.steps.some((s) => !facilities.has(s.value.facilityId))) fail("Each step draws once on a facility of the close");
  for (const {value: s} of f.steps) if (s.mode === "fixed" && !f.addedStreams.some((x) => x.value.id === s.streamId)) fail(`Step on ${s.facilityId} draws a stream the close does not add`);
  if (new Set(f.dependents.map((d) => d.value.id)).size !== f.dependents.length) fail("Duplicate dependent");
  for (const {value: d} of f.dependents) if (!d.reads.every((id) => lines.has(id)) || d.horizonEnd < d.horizonStart) fail(`Dependent ${d.id} reads a line the close does not carry or has no horizon`);
