  const result = adoptedWeeklyCashOutputSchema.parse(calculateAdoptedWeeklyCash(input.analysis));
  const w = result.weekly;
  const readings = w ? (() => {
    const informed = w.cases.find((c) => c.role === "informed")!;
    const tight = informed.rows.find((r) => r.weekStart === informed.minimum.weekStart)!;
    // Only a case with this action alone proves it covers.
    const covers = (caseIds: string[]) => caseIds.some((id) => w.cases.find((c) => c.id === id)!.weeksBelowMinimum.length === 0);
    const byCost = w.actions.map((a) => ({id: a.id, cost: a.cost, covers: covers(a.isolatedCases)}));
    const cheapest = w.actions.find((a) => covers(a.isolatedCases)) ?? null;
    const pressed = informed.weeksBelowMinimum.length ? informed.rows.filter((r) => r.belowMinimum) : [tight];
    // Summed by stream identity, so two streams with the same label stay two causes.
    const sums = new Map<string, {label: string; amount: Decimal}>();
    for (const r of pressed) for (const o of r.outflowsByStream) if (o.category === "debt" || o.category === "statutory") {
      const prev = sums.get(o.streamId); sums.set(o.streamId, {label: o.label, amount: (prev?.amount ?? new Exact(0)).plus(o.amount)});
    }
    const causes = [...sums.entries()].sort((a, b) => b[1].amount.cmp(a[1].amount) || (a[0] < b[0] ? -1 : 1)).slice(0, 24)
      .map(([streamId, v]) => ({streamId, label: v.label, amount: v.amount.toFixed()}));
    const actionCases = new Set(w.actions.flatMap((a) => a.cases));
    return {tightestWeek: {weekStart: tight.weekStart, closing: tight.closing, belowMinimum: tight.belowMinimum},
      weeksBelowMinimum: informed.weeksBelowMinimum, shortfallToMinimum: informed.shortfallToMinimum, causes,
      obligationsNotExamined: w.coverage.filter((c) => c.status === "not_examined").map((c) => c.obligation),
      closingHidesTheWeek: informed.weeksBelowMinimum.length > 0 && new Exact(informed.closing).gte(w.minimumCash),
      cheapestCoveringAction: cheapest === null ? null : {id: cheapest.id, cost: cheapest.cost, openAtCovenantTest: cheapest.openAtCovenantTest},
      actionsByCost: byCost,
      sensitivities: w.cases.filter((c) => c.role === "alternative" && !actionCases.has(c.id))
        .map((c) => ({caseId: c.id, minimum: c.minimum.closing, weekStart: c.minimum.weekStart, weeksBelowMinimum: c.weeksBelowMinimum.length}))};
  })() : null;
  const gaps = [...result.gaps, ...(w?.gaps ?? []).map((g) => ({operand: `weekly_cash.${input.analysis.analysisId}.coverage.${g.item}`, reason: g.reason}))];
  const status = !w ? "framed" as const : gaps.length ? "partial" as const : "prepared_for_human_review" as const;
  const payload = {schemaVersion: "weekly-cash-packet.v1" as const, executorVersion: weeklyCashPacketVersion, financialCoreVersion,
    question: input.question, basisFingerprint: result.basisFingerprint, scope: result.scope, entityId: result.entityId, currency: result.currency,
    result, readings, gaps, status,
    exclusions: ["business_day_inference", "intraday_liquidity", "receivables_assignment_eligibility", "credit_approval"] as const,
    grantsExecution: false as const, grantsPublication: false as const};
  return weeklyCashPacketOutputSchema.parse({...payload, fingerprint: createHash("sha256").update(JSON.stringify(payload)).digest("hex")});
}

import {z} from "zod";
import {weeklyCashObligations} from "@offroad/financial-core";
import {capacityUuid} from "./debt-capacity-premises";
import type {ProposedHypothesis} from "./investment-premises";

const text = z.string().trim().min(1).max(2000);
const key = z.string().regex(/^[a-z0-9][a-z0-9-]{0,39}$/);
/** Money carries at most eight decimals, as the adopted numeric representation reads it. */
const money = z.string().regex(/^-?\d{1,24}(?:\.\d{1,8})?$/);
const unsignedMoney = z.string().regex(/^\d{1,24}(?:\.\d{1,8})?$/);
const ratio = z.string().regex(/^\d{1,4}(?:\.\d{1,20})?$/);
const days = z.number().int().min(0).max(9999);
const origins = ["document", "informed", "house", "estimate"] as const;
const originLabel: Record<(typeof origins)[number], string> = {document: "documento", informed: "informado", house: "premissa da casa", estimate: "estimativa"};
/** A value and where it came from; the source names the document, the message or the house rule. */
const fact = <T extends z.ZodType>(value: T) => z.strictObject({value, origin: z.enum(origins), source: text});
type Origin = {origin: (typeof origins)[number]; source: string};

/** A dated series of cash events of one kind: one amount per date, in currency units. */
const stream = z.strictObject({
  id: key, label: text, category: z.enum(["debt", "statutory", "operating", "action"]), direction: z.enum(["inflow", "outflow"]),
  /** The obligation the answer cannot leave out that this stream carries; only outflows carry one. */
  obligation: z.enum(weeklyCashObligations).nullable(),
  dates: z.array(z.iso.date()).min(1).max(2000), amounts: z.array(unsignedMoney).min(1).max(2000),
});
const weeklyCase = z.strictObject({id: key, label: text, role: z.enum(["informed", "alternative"]), streamIds: z.array(key).min(1).max(40)});
/** A costed premise: the action stream it draws, the stream it replaces if any, and its terms. */
const action = z.strictObject({
  id: key, label: text, streamId: key, replacesStreamId: key.nullable(), amount: unsignedMoney, days, rate: ratio, ratePeriod: z.enum(["annual", "monthly"]),
  iofDaily: ratio, iofDailyCapDays: days, iofAdditional: ratio, upfrontFee: ratio, repaymentDate: z.iso.date(),
});
const coverageStatus = z.enum(["included", "not_applicable", "not_examined"]);

/** The facts of one weekly cash question, each with its origin. Nothing here is adopted until a
 * person confirms the set; every number the method reads comes from the adopted basis. The weeks run
 * from the opening date (a Monday) to the end date (a Sunday); money is in the company's currency units. */
export const weeklyCashFactsSchema = z.strictObject({
  weeklyCashId: z.uuid(), entityId: z.uuid(), perimeter: text, currency: z.string().regex(/^[A-Z]{3}$/), definitionVersionId: z.uuid(),
  openingDate: z.iso.date(), endDate: z.iso.date(),
  openingCash: fact(money), minimumCash: fact(money),
  /** The balance a period closing shows at the end date; absent, the closing is not compared. */
  projectionClosing: fact(money).nullable(),
  calendarEnd: fact(z.iso.date()), covenantTestDate: fact(z.iso.date()).nullable(),
  streams: z.array(fact(stream)).min(1).max(40),
  cases: z.array(fact(weeklyCase)).min(1).max(8),
  actions: z.array(fact(action)).max(4),
  coverage: z.strictObject(Object.fromEntries(weeklyCashObligations.map((o) => [o, fact(coverageStatus)])) as Record<(typeof weeklyCashObligations)[number], ReturnType<typeof fact<typeof coverageStatus>>>),
}).superRefine((f, ctx) => {
  const fail = (message: string) => ctx.addIssue({code: "custom", message});
  const day = (d: string) => Date.parse(`${d}T00:00:00Z`) / 86400000;
  if (new Date(`${f.openingDate}T00:00:00Z`).getUTCDay() !== 1) fail("The opening date must be a Monday");
  if (f.endDate <= f.openingDate || (day(f.endDate) - day(f.openingDate) + 1) % 7 !== 0) fail("The horizon must be whole weeks after the opening date");
  const streams = new Map(f.streams.map((s) => [s.value.id, s.value]));
  if (streams.size !== f.streams.length) fail("Duplicate stream");
  for (const {value: s} of f.streams) {
    if (s.dates.length !== s.amounts.length) fail(`Stream ${s.id} must have one amount per date`);
    if (s.dates.some((d) => d < f.openingDate || d > f.endDate)) fail(`Stream ${s.id} has an event outside the horizon`);
    if (s.obligation !== null && s.direction !== "outflow") fail(`Stream ${s.id} carries an obligation but is not an outflow`);
  }
  if (new Set(f.cases.map((c) => c.value.id)).size !== f.cases.length || f.cases.filter((c) => c.value.role === "informed").length !== 1) fail("Exactly one informed case and unique case ids");
  for (const {value: c} of f.cases) {
    if (new Set(c.streamIds).size !== c.streamIds.length || c.streamIds.some((id) => !streams.has(id))) fail(`Case ${c.id} names a stream the analysis does not carry`);
  }
  if (new Set(f.actions.map((a) => a.value.id)).size !== f.actions.length || new Set(f.actions.map((a) => a.value.streamId)).size !== f.actions.length) fail("Duplicate action");
  for (const {value: a} of f.actions) {
    const s = streams.get(a.streamId);
    if (!s || s.category !== "action" || s.direction !== "inflow") fail(`Action ${a.id} needs an action inflow stream`);
    if (a.replacesStreamId !== null && (!streams.has(a.replacesStreamId) || a.replacesStreamId === a.streamId)) fail(`Action ${a.id} replaces a stream the analysis does not carry`);
  }
  // An action stream with no action would be cash without a cost.
  for (const s of streams.values()) if (s.category === "action" && !f.actions.some((a) => a.value.streamId === s.id)) fail(`Stream ${s.id} is an action without its terms`);
});
export type WeeklyCashFacts = z.infer<typeof weeklyCashFactsSchema>;

export const weeklyCashAnalysisId = (weeklyCashId: string) => capacityUuid(`offroad:weekly-cash:${weeklyCashId}:analysis`);
/** The size of one working basis. */
export const maxWeeklyCashHypotheses = 256;

/** The hypotheses one confirmation adopts: every date, amount, classification, threshold and
 * action term the adopted reader reads, plus the structure it receives as given (case composition,
 * labels, the stream each action draws and replaces, and the order of streams, cases and actions),
 * so the packet is composed from the basis alone. Event series stay lists, one per stream. Every
 * reason states the origin of the number. Deterministic; nothing is calculated here. */
export function proposeWeeklyCashHypotheses(raw: unknown): ProposedHypothesis[] {
  const f = weeklyCashFactsSchema.parse(raw);
  const out: ProposedHypothesis[] = [], prefix = `weekly_cash.${weeklyCashAnalysisId(f.weeklyCashId)}.`;
  const why = (x: Origin) => `Origem: ${originLabel[x.origin]}. ${x.source}`;
  const house = (source: string) => `Origem: premissa da casa. ${source}`;
  const add = (path: string, unit: string, value: ProposedHypothesis["value"], reason: string) => out.push({fieldPath: prefix + path,
    dimensions: {entityId: f.entityId, perimeter: f.perimeter, periodStart: f.openingDate, periodEnd: f.endDate, currency: f.currency, unit, scale: "1", scenario: "base", definitionVersionId: f.definitionVersionId},
    value, reason});
  const num = (path: string, unit: string, value: string, reason: string) => add(path, unit, {type: "number", value}, reason);
  const txt = (path: string, unit: string, value: string, reason: string) => add(path, unit, {type: "text", value}, reason);
  const list = (path: string, unit: string, value: string[], reason: string) => add(path, unit, {type: "list", value}, reason);
  const date = (path: string, value: string, reason: string) => add(path, "date", {type: "date", value}, reason);

  num("openingCash", "currency", f.openingCash.value, why(f.openingCash));
  num("minimumCash", "currency", f.minimumCash.value, why(f.minimumCash));
  if (f.projectionClosing) num("projectionClosing", "currency", f.projectionClosing.value, why(f.projectionClosing));
  date("calendarEnd", f.calendarEnd.value, why(f.calendarEnd));
  if (f.covenantTestDate) date("covenantTestDate", f.covenantTestDate.value, why(f.covenantTestDate));
  for (const o of weeklyCashObligations) txt(`coverage.${o}`, "convention", f.coverage[o].value, why(f.coverage[o]));
  for (const s of f.streams) {
    const v = s.value, p = `stream.${v.id}.`, r = why(s);
    txt(p + "label", "text", v.label, r);
    txt(p + "category", "convention", v.category, r);
    txt(p + "direction", "convention", v.direction, r);
    if (v.obligation !== null) txt(p + "obligation", "convention", v.obligation, r);
    list(p + "dates", "date", v.dates, r);
    list(p + "amounts", "currency", v.amounts, r);
  }
  // Case composition is structure the reader receives as given; adopted so it is not the composer's guess.
  for (const c of f.cases) {
    const v = c.value, p = `case.${v.id}.`, r = why(c);
    txt(p + "role", "convention", v.role, r);
    txt(p + "label", "text", v.label, r);
    list(p + "streamIds", "identity", v.streamIds, r);
  }
  for (const a of f.actions) {
    const v = a.value, p = `action.${v.id}.`, r = why(a);
    txt(p + "label", "text", v.label, r);
    txt(p + "streamId", "identity", v.streamId, r);
    if (v.replacesStreamId !== null) txt(p + "replacesStreamId", "identity", v.replacesStreamId, r);
    num(p + "amount", "currency", v.amount, r);
    num(p + "days", "days", String(v.days), r);
    num(p + "rate", "ratio", v.rate, r);
    txt(p + "ratePeriod", "convention", v.ratePeriod, r);
    num(p + "iofDaily", "ratio", v.iofDaily, r);
    num(p + "iofDailyCapDays", "days", String(v.iofDailyCapDays), r);
    num(p + "iofAdditional", "ratio", v.iofAdditional, r);
    num(p + "upfrontFee", "ratio", v.upfrontFee, r);
    date(p + "repaymentDate", v.repaymentDate, r);
  }
  list("order.streams", "identity", f.streams.map((s) => s.value.id), house("Ordem dos fluxos como informada"));
  list("order.cases", "identity", f.cases.map((c) => c.value.id), house("Ordem dos casos como informada"));
  if (f.actions.length) list("order.actions", "identity", f.actions.map((a) => a.value.id), house("Ordem das ações como informada"));
  // A working basis holds at most 256 premises; a set larger than that is refused here, not at confirmation.
  if (out.length > maxWeeklyCashHypotheses) throw new Error("weekly_cash_premises_exceed_basis");
  return out;
}

import {createHash} from "node:crypto";
import Decimal from "decimal.js";
import {deterministicRunEvidenceFingerprint, type DeterministicMethodRun, type DeterministicMethodRunCase} from "@offroad/credit-playbook";
import {prepareWeeklyCashPacket, weeklyCashPacketOutputSchema, type WeeklyCashPacketInput} from "./weekly-cash-packet";
import {auroraWeeklyCashBasis} from "./weekly-cash.test-support";

// Evaluation-only module; not exported to application consumers. All cases are synthetic
// calibrations of ficha C18 (modelo_c18.py), never production parameters.
const fingerprint = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
const D = Decimal.clone({precision: 60});
const r = (v: string | null | undefined, p = 1) => v == null ? null : new D(v).toDecimalPlaces(p).toNumber();
type Case = DeterministicMethodRunCase;
type Evidence = Omit<DeterministicMethodRun, "schemaVersion" | "humanApproval" | "run">;
type Packet = ReturnType<typeof prepareWeeklyCashPacket>;
export const weeklyCashMethodVersion = "2026.10.23-v1";
export const weeklyCashRunIds = {
  gold: "project-weekly-cash-2026-10-23-v1-gold",
  adversarial: "project-weekly-cash-2026-10-23-v1-adversarial",
  consistency: "project-weekly-cash-2026-10-23-v1-consistency",
} as const;
const question = "Como fica o caixa até dezembro e o que vence?";
type Basis = ReturnType<typeof auroraWeeklyCashBasis>;
const packetInput = (edit: (f: Basis) => void = () => undefined, after: (i: WeeklyCashPacketInput) => void = () => undefined): WeeklyCashPacketInput => {
  const f = auroraWeeklyCashBasis(); edit(f);
  const i = {schemaVersion: "weekly-cash-packet-input.v1", question, analysis: f.seal()} as WeeklyCashPacketInput; after(i); return i;
};
function observe(id: string, input: WeeklyCashPacketInput, expected: unknown, select: (p: Packet) => unknown): Case {
  const result = prepareWeeklyCashPacket(input), observed = JSON.stringify(select(result)), expectation = JSON.stringify(expected);
  return {id, expectation, observed, inputFingerprint: fingerprint(input), outputFingerprint: fingerprint(result), passed: expectation === observed};
}
const at = (p: Packet, id: string) => p.result.weekly!.cases.find((c) => c.id === id)!;

function goldCases(): Case[] {
  const base = () => packetInput(), packet = prepareWeeklyCashPacket(base());
  const reuse = (id: string, expected: unknown, select: (p: Packet) => unknown): Case => {
    const observed = JSON.stringify(select(packet)), expectation = JSON.stringify(expected);
    return {id, expectation, observed, inputFingerprint: fingerprint(base()), outputFingerprint: fingerprint(packet), passed: expectation === observed};
  };
  return [
    // Expectations come from the independent Python oracle (outputs/fichas-ensaio-2026-10/C18/resultados.json) and the ficha's answer key.
    reuse("tightest-week-is-the-week-of-21-december", {week: "2026-12-21", closing: 7.5, withinTolerance: true},
      (p) => ({week: p.readings!.tightestWeek.weekStart, closing: r(p.readings!.tightestWeek.closing), withinTolerance: new D(p.readings!.tightestWeek.closing).minus("7.5").abs().lte(2)})),
    reuse("two-weeks-under-the-minimum", ["2026-12-14", "2026-12-21"], (p) => p.readings!.weeksBelowMinimum),
    reuse("causes-named-across-the-weeks-under-the-minimum", [["Debênture 2021, amortização", 15], ["Debênture 2021, juros semestrais", 5.1], ["Impostos sobre vendas (saldo a pagar)", 2.4],
      ["13º salário, 2ª parcela e encargos", 2.1], ["CCB Bradesco, juros trimestrais", 1.7], ["Finame (principal e juros)", 0.8], ["INSS", 0.5]],
      (p) => p.readings!.causes.map((c) => [c.label, r(c.amount)])),
    reuse("december-closing-reconciles-with-the-projection", {weekly: 16.1, projection: 16, near: true},
      (p) => ({weekly: r(p.result.weekly!.reconciliation!.weekly), projection: r(p.result.weekly!.reconciliation!.projection), near: new D(p.result.weekly!.reconciliation!.difference).abs().lt("0.5")})),
    reuse("closing-hides-the-week", true, (p) => p.readings!.closingHidesTheWeek),
    reuse("calendar-of-what-falls-due-by-31-december", {debt15dec: [["CCB Bradesco, juros trimestrais", 1.7], ["Debênture 2021, amortização", 15], ["Debênture 2021, juros semestrais", 5.1], ["Finame (principal e juros)", 0.8]],
      thirteenth: [["2026-11-30", 1.5], ["2026-12-18", 2.1]]},
      (p) => ({debt15dec: p.result.weekly!.calendar.filter((x) => x.category === "debt" && x.date === "2026-12-15").map((x) => [x.label, r(x.amount)]),
        thirteenth: p.result.weekly!.calendar.filter((x) => x.label.startsWith("13º")).map((x) => [x.date, r(x.amount)])})),
    reuse("actions-costed-for-the-time-in-use", [["conta-garantida", 0.12], ["antecipacao", 0.25], ["linha-25", 0.87]],
      (p) => p.readings!.actionsByCost.map((a) => [a.id, r(a.cost, 2)])),
    observe("same-label-streams-stay-distinct-causes", packetInput((f) => {f.entries.find((x) => x.fieldPath.endsWith("stream.debenture-juros.label"))!.value = {type: "text", value: "Debênture 2021, amortização"};}),
      [["debenture-amortizacao", 15], ["debenture-juros", 5.1]], (p) => p.readings!.causes.filter((c) => c.label === "Debênture 2021, amortização").map((c) => [c.streamId, r(c.amount)])),
    observe("two-actions-in-one-case-prove-neither-covers-alone", packetInput((f) => undefined, (i) => {
      i.analysis.cases = [...i.analysis.cases.filter((c) => c.id !== "conta-garantida" && c.id !== "antecipacao"),
        {id: "ambas", label: "Saque e antecipação", role: "alternative", streamIds: [...i.analysis.cases[0]!.streamIds, "conta-garantida", "antecipacao"]}];
    }), {cheapest: "linha-25", covers: [["conta-garantida", false], ["antecipacao", false], ["linha-25", true]]},
      (p) => ({cheapest: p.readings!.cheapestCoveringAction!.id, covers: p.readings!.actionsByCost.map((a) => [a.id, a.covers])})),
    reuse("cheapest-covering-action-is-the-existing-overdraft", {id: "conta-garantida", worst: 15.5}, (p) => ({id: p.readings!.cheapestCoveringAction!.id, worst: r(at(p, "conta-garantida").minimum.closing)})),
    reuse("overdraft-open-at-the-covenant-test-nets-to-zero", {open: true, effect: {grossDebt: "8", cash: "8", netDebt: "0"}},
      (p) => ({open: p.readings!.cheapestCoveringAction!.openAtCovenantTest, effect: p.result.weekly!.actions[0]!.covenantEffect})),
    reuse("a-harvest-of-30-million", {minimum: 2.5, weeks: 3}, (p) => ({minimum: r(at(p, "safra-30").minimum.closing), weeks: at(p, "safra-30").weeksBelowMinimum.length})),
    reuse("harvest-delayed-two-weeks", {minimum: 12, closing: 18.4}, (p) => ({minimum: r(at(p, "safra-adiada").minimum.closing), closing: r(at(p, "safra-adiada").closing)})),
    reuse("without-the-harvest-line", {minimum: -9.5, closing: -0.9}, (p) => ({minimum: r(at(p, "sem-linha").minimum.closing), closing: r(at(p, "sem-linha").closing)})),
    (() => {
      const i = packetInput() as WeeklyCashPacketInput & {analysis: {minimumCash: {decisionId: string | null; missingReason: string | null}}};
      i.analysis.minimumCash = {...i.analysis.minimumCash, decisionId: null, missingReason: "Caixa mínimo não informado"};
      return observe("absent-minimum-is-a-gap-not-a-default", i, {status: "framed", gap: true},
        (p) => ({status: p.status, gap: p.gaps.some((g) => g.reason === "Caixa mínimo não informado")}));
    })(),
  ];
}

function adversarialCases(): Case[] {
  const attempts: [string, () => unknown, string][] = [
    ["tampered-envelope", () => {const i = packetInput(); i.analysis.envelope = {...i.analysis.envelope, canonical: i.analysis.envelope.canonical.replace('"41"', '"51"')}; return i;}, "adoption_basis_integrity_mismatch"],
