          book.Workbook ??= {};
          book.Workbook.Names ??= [];
          if (book.Workbook.Names.some(entry => entry.Name === name)) throw new Error("roundtrip_defined_name_duplicate");
          book.Workbook.Names.push({Name: name, Ref: `'${sheet.name[lang].replaceAll("'", "''")}'!$${columnLetter(columnIndex)}$${rowIndex + 1}`});
        }
      });
    });

    worksheet["!ref"] = XLSX.utils.encode_range({
      s: {c: 0, r: 0},
      e: {c: Math.max(maxColumn, 0), r: Math.max(sheet.rows.length - 1, 0)},
    });
    worksheet["!cols"] = sheet.widths.map((width) => ({wch: width}));
    XLSX.utils.book_append_sheet(book, worksheet, sheet.name[lang]);
  }

  return book;
}

/**
 * The bytes to hand a browser.
 *
 * `type: "array"` yields an ArrayBuffer, not a typed array — asserting the return type without
 * wrapping it produced an object that looked right to TypeScript and had no indexable bytes.
 */
export function toXlsxBuffer(model: FinancialModel, lang: "pt" | "en", cover?: WorkbookCover): Uint8Array {
  return new Uint8Array(XLSX.write(toWorkbook(model, lang, cover), {bookType: "xlsx", type: "array"}) as ArrayBuffer);
}

