  const lines = ordered.map((row) => [
    row.DT_REFER,
    row.CD_CONTA,
    row.DS_CONTA,
    `value=${formatCvmValue(row)}`,
    row.DT_FIM_EXERC ? `period_end=${row.DT_FIM_EXERC}` : null,
