    taskSpecs: compiled.tasks.map((task, ordinal) => ({
      ...task,
      dependencies: [...task.dependencies],
      ordinal,
      batch: batchByTask.get(task.id) ?? 0,
    })),
    parallelBatches: compiled.parallelBatches.map((batch) => [...batch]),
  };
