import Decimal from "decimal.js";

/** Coexisting source assertions. Ranking orders a proposed reading; it never adopts it. */

export type FactKey = {
  fieldPath: string;
  periodStart?: string;
  periodEnd?: string;
  entityName?: string;
  entityScope?: string;
  currency?: string;
  unit?: string;
  scale?: string;
  scenario?: string;
  definitionVersionId?: string;
};

export type FactCandidate = {
  fieldPath: string;
  /** Decimal string for numbers, ISO date, text, "true"/"false", JSON array for lists. */
  normalizedValue: string;
  valueType: "text" | "number" | "date" | "boolean" | "list";
  sourceDocument: string;
  /** 1 (audited) to 7 (company statement). Reading order only. */
  evidenceRank: number;
  informationClass: string;
  confidence: number;
  anchorVerified: boolean;
  periodStart?: string;
  periodEnd?: string;
  entityName?: string;
  /** Explicit perimeter; none of these scopes takes precedence over another. */
  entityScope?: string;
  currency?: string;
  unit?: string;
  scale?: string;
  scenario?: string;
  definitionVersionId?: string;
  /** Where in the document it was found; carried through so a fact never loses its citation. */
  anchor?: unknown;
};

export type FactConflict = {
  candidate: FactCandidate;
  /** Relative difference against the accepted value; absent for non-numeric facts. */
  relativeDelta?: string;
};

export type ReconciledFact = {
  key: FactKey;
  /** Proposed reading for compatibility; not an adopted or official value. */
  value: string;
  valueType: FactCandidate["valueType"];
  /** @deprecated Proposed reference only. Contextual adoption is a separate command. */
  accepted: FactCandidate;
  /** All assertions, including corroboration with the same value. */
  observations?: FactCandidate[];
  /** Everything that said otherwise, ordered by rank then confidence. Never discarded. */
  conflicts: FactConflict[];
  /** True when at least one conflict differs beyond the tolerance the caller passed. */
  disputed: boolean;
};

// One to three digits: an {i} index, never a year such as historical_financials.2025.
const indexedPath = /^(.*)\.(\d{1,3})\.([a-z0-9_]+)$/;

export function factKeyOf(candidate: FactCandidate): string {
  // Indexed tuples (instruments, customers, windows) are rows of one document: the same index in
  // another document is another row, not the same fact read twice.
  const tupleScope = indexedPath.test(candidate.fieldPath) ? candidate.sourceDocument : "";
  return JSON.stringify([candidate.fieldPath, ...dimensionTuple(candidate), tupleScope]);
}

const isNumeric = (candidate: FactCandidate) => candidate.valueType === "number";

/**
 * Orders candidates for the same fact by how much the desk trusts them.
 *
 * Rank first, because that is a property of the document and not of the reading. Then a
 * verified anchor, because a value the verifier could confirm against the page outranks one it
 * could not, at equal rank. Then confidence, then the raw value as a tiebreak so the result is
 * deterministic — two runs over the same data room must reconcile identically, or nothing
 * downstream can be trusted.
 */
export function dimensionTuple(candidate: FactKey): Array<string | null> {
  return [candidate.entityName, candidate.entityScope, candidate.periodStart, candidate.periodEnd,
    candidate.currency, candidate.unit, candidate.scale, candidate.scenario, candidate.definitionVersionId].map((value) => value ?? null);
}

export function compareCandidates(a: FactCandidate, b: FactCandidate): number {
  if (a.evidenceRank !== b.evidenceRank) return a.evidenceRank - b.evidenceRank;
  if (a.anchorVerified !== b.anchorVerified) return a.anchorVerified ? -1 : 1;
  if (a.confidence !== b.confidence) return b.confidence - a.confidence;
  return a.normalizedValue.localeCompare(b.normalizedValue);
}

/** Relative difference between two numeric strings, as a decimal string. Null when not comparable. */
export function relativeDelta(accepted: string, other: string): string | null {
  const a = new Decimal(accepted);
  const b = new Decimal(other);
  if (!a.isFinite() || !b.isFinite()) return null;
  if (a.isZero()) return b.isZero() ? "0" : null;
  return b.minus(a).dividedBy(a).abs().toDecimalPlaces(6).toFixed();
}

export type ReconcileOptions = {
  /** A conflict beyond this relative difference marks the fact disputed. Default 1%. */
  disputeTolerance?: string;
};

export function reconcileFacts(candidates: readonly FactCandidate[], options: ReconcileOptions = {}): ReconciledFact[] {
  const tolerance = new Decimal(options.disputeTolerance ?? "0.01");
  const grouped = new Map<string, FactCandidate[]>();
  for (const candidate of candidates) {
    const key = factKeyOf(candidate);
    grouped.set(key, [...(grouped.get(key) ?? []), candidate]);
  }

  const facts: ReconciledFact[] = [];
  for (const group of grouped.values()) {
    const ordered = [...group].sort(compareCandidates);
    const accepted = ordered[0];
    if (!accepted) continue;

    const conflicts: FactConflict[] = [];
    let disputed = false;
    for (const other of ordered.slice(1)) {
      if (other.normalizedValue === accepted.normalizedValue) continue;
      const delta = isNumeric(accepted) && isNumeric(other) ? relativeDelta(accepted.normalizedValue, other.normalizedValue) : null;
      if (delta === null || new Decimal(delta).gt(tolerance)) disputed = true;
      conflicts.push(delta === null ? {candidate: other} : {candidate: other, relativeDelta: delta});
    }

    facts.push({
      key: {
        fieldPath: accepted.fieldPath,
        ...(accepted.periodStart ? {periodStart: accepted.periodStart} : {}),
        ...(accepted.entityScope ? {entityScope: accepted.entityScope} : {}),
        ...(accepted.currency ? {currency: accepted.currency} : {}),
        ...(accepted.unit ? {unit: accepted.unit} : {}),
        ...(accepted.scale ? {scale: accepted.scale} : {}),
        ...(accepted.scenario ? {scenario: accepted.scenario} : {}),
        ...(accepted.definitionVersionId ? {definitionVersionId: accepted.definitionVersionId} : {}),
        ...(accepted.periodEnd ? {periodEnd: accepted.periodEnd} : {}),
        ...(accepted.entityName ? {entityName: accepted.entityName} : {}),
      },
      value: accepted.normalizedValue,
      valueType: accepted.valueType,
      accepted,
      observations: ordered,
      conflicts,
      disputed,
    });
  }
  return facts;
}

/**
 * One number per row of one document, across the whole case.
 *
 * Every table numbers its rows from one, and so does every document: the ITR's note 15 has a
 * `debt.instruments.1`, the letter's table has a `debt.instruments.1`, and without this step
 * the two are one fact with a conflict, the reconciliation reports a contradiction the room
 * never stated, and the desk reads one instrument where there were two. Tuples are grouped by
 * document and original index, ordered by the document's evidence rank, and renumbered 1..N.
 */
export function renumberIndexedGroups(facts: readonly ReconciledFact[]): ReconciledFact[] {
  type TupleKey = string;
  const groups = new Map<string, Map<TupleKey, {rank: number; document: string; index: number}>>();
  for (const fact of facts) {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match) continue;
    const [, group, index] = match as unknown as [string, string, string];
    const document = fact.accepted.sourceDocument;
    const tupleKey = `${document}#${index}`;
    const tuples = groups.get(group) ?? new Map();
    if (!tuples.has(tupleKey)) tuples.set(tupleKey, {rank: fact.accepted.evidenceRank, document, index: Number(index)});
    groups.set(group, tuples);
  }
  const renumbered = new Map<string, Map<TupleKey, number>>();
  for (const [group, tuples] of groups) {
    const ordered = [...tuples.entries()].sort(([, a], [, b]) => a.rank - b.rank || a.document.localeCompare(b.document) || a.index - b.index);
    renumbered.set(group, new Map(ordered.map(([key], position) => [key, position + 1])));
  }
  return facts.map((fact) => {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match) return fact;
    const [, group, index, key] = match as unknown as [string, string, string, string];
    const next = renumbered.get(group)?.get(`${fact.accepted.sourceDocument}#${index}`);
    if (next === undefined || String(next) === index) return fact;
    return {...fact, key: {...fact.key, fieldPath: `${group}.${next}.${key}`}};
  });
}

const fold = (text: string): string => text.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, " ").trim();

/**
 * Rows from different documents that name the same contract are one instrument.
 *
 * Camil's ITR lists twelve debenture series with balances and the AGOE proposal describes the
 * same series with their rates and maturities. After renumbering they are twenty-four rows;
 * a desk reads twelve. Rows whose lender text folds to the same string are merged: the fields
 * of the higher-ranked document win on conflict, the others fill in what it lacks, and the
 * conflicts stay on the fact. Only the debt group is merged, because it is the one where a
 * name identifies a contract.
 */
/** Groups where a name identifies the row, and the field that carries the name. */
const identityGroups: ReadonlyArray<{group: string; keys: string[]}> = [
  // A bank is not a contract. Prefer contract/issuance/series; when it is absent, combine
  // lender, instrument and maturity so two facilities from the same bank are not collapsed.
  {group: "debt.instruments", keys: ["contract_id", "lender", "instrument_type", "maturity"]},
  // Nimbus measured the people case: the deck's management table and its cap table both list
  // the founders, and two tables gave the CEO twice with the same 28%.
  {group: "company.controllers", keys: ["name"]},
  {group: "company.management", keys: ["name"]},
  {group: "customers.top_customers", keys: ["name"]},
];

export function mergeInstrumentsByIdentity(facts: readonly ReconciledFact[]): ReconciledFact[] {
  return identityGroups.reduce<ReconciledFact[]>((current, entry) => mergeByIdentity(current, entry.group, entry.keys), [...facts]);
}

function mergeByIdentity(facts: readonly ReconciledFact[], group: string, identityKeys: string[]): ReconciledFact[] {
  const byTuple = new Map<number, ReconciledFact[]>();
  for (const fact of facts) {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match || match[1] !== group) continue;
    const index = Number(match[2]);
    byTuple.set(index, [...(byTuple.get(index) ?? []), fact]);
  }
  if (byTuple.size < 2) return [...facts];
  const identity = (tuple: ReconciledFact[]): string | null => {
    if (group === "debt.instruments") {
      const contract = tuple.find((fact) => fact.key.fieldPath.endsWith(".contract_id"));
      if (contract) return `contract:${fold(contract.value)}`;
      const lender = tuple.find((fact) => fact.key.fieldPath.endsWith(".lender"));
      // An issuance/series label is itself the contractual identity across an ITR, an
      // indenture and a corporate approval. An ordinary bank name is not.
      if (lender && /(emiss|serie|series|debenture)/.test(fold(lender.value))) return `issuance:${fold(lender.value)}`;
      const parts = identityKeys.slice(1).map((key) => tuple.find((fact) => fact.key.fieldPath.endsWith(`.${key}`))?.value).filter(Boolean);
      return parts.length >= 2 ? `terms:${parts.map((value) => fold(value!)).join("|")}` : null;
    }
    const named = tuple.find((fact) => identityKeys.some((key) => fact.key.fieldPath.endsWith(`.${key}`)));
    return named ? fold(named.value) : null;
  };
  const canonical = new Map<string, number>();
  const remap = new Map<number, number>();
  for (const [index, tuple] of [...byTuple.entries()].sort(([a], [b]) => a - b)) {
    const id = identity(tuple);
    if (!id) continue;
    const existing = canonical.get(id);
    if (existing === undefined) canonical.set(id, index);
    else remap.set(index, existing);
  }
  if (remap.size === 0) return [...facts];
  const merged: ReconciledFact[] = [];
  const seen = new Map<string, ReconciledFact>();
  for (const fact of facts) {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match || match[1] !== group) { merged.push(fact); continue; }
    const index = Number(match[2]);
    const target = remap.get(index) ?? index;
    const path = `${group}.${target}.${match[3]}`;
    const candidate = target === index ? fact : {...fact, key: {...fact.key, fieldPath: path}};
    const key = JSON.stringify([path, ...dimensionTuple(fact.key)]);
    const prior = seen.get(key);
    if (!prior) { seen.set(key, candidate); merged.push(candidate); continue; }
    // Same field from two documents: the better-ranked reading stands, the other is a conflict.
    const [winner, loser] = compareCandidates(prior.accepted, candidate.accepted) <= 0 ? [prior, candidate] : [candidate, prior];
    const conflict = loser.value === winner.value ? [] : [{candidate: loser.accepted, ...(isNumeric(loser.accepted) && isNumeric(winner.accepted) ? {relativeDelta: relativeDelta(winner.value, loser.value) ?? undefined} : {})}];
    const combined: ReconciledFact = {...winner, observations: [...(winner.observations ?? [winner.accepted]), ...(loser.observations ?? [loser.accepted])], conflicts: [...winner.conflicts, ...loser.conflicts, ...conflict].filter((entry): entry is FactConflict => Boolean(entry)), disputed: winner.disputed || loser.disputed || conflict.length > 0};
    seen.set(key, combined);
    merged[merged.indexOf(prior)] = combined;
  }
  // Compress the surviving indices to 1..N without splitting by document again: a merged
  // instrument now carries facts from two documents on purpose.
  const survivors = [...new Set(merged.map((fact) => indexedPath.exec(fact.key.fieldPath)).filter((match): match is RegExpExecArray => Boolean(match) && match![1] === group).map((match) => Number(match[2])))].sort((a, b) => a - b);
  const compress = new Map(survivors.map((index, position) => [index, position + 1]));
  return merged.map((fact) => {
    const match = indexedPath.exec(fact.key.fieldPath);
    if (!match || match[1] !== group) return fact;
    const next = compress.get(Number(match[2]));
    if (next === undefined || String(next) === match[2]) return fact;
    return {...fact, key: {...fact.key, fieldPath: `${group}.${next}.${match[3]}`}};
  });
}

/** Index for the rules and the calculations: field path (+ period) → fact. */
export function indexFacts(facts: readonly ReconciledFact[]): Map<string, ReconciledFact> {
  const buckets = new Map<string, ReconciledFact[]>();
  for (const fact of facts) {
    for (const key of [[fact.key.fieldPath, fact.key.periodEnd ?? ""].join("|"), fact.key.fieldPath]) {
      buckets.set(key, [...(buckets.get(key) ?? []), fact]);
    }
  }
  // An unqualified lookup must never choose a perimeter, currency or definition implicitly.
  return new Map([...buckets].filter(([, values]) => values.length === 1).map(([key, values]) => [key, values[0]!]));
}

export function factValue(index: Map<string, ReconciledFact>, fieldPath: string, periodEnd?: string): Decimal | null {
  const fact = index.get(periodEnd ? [fieldPath, periodEnd].join("|") : fieldPath);
  if (!fact || fact.valueType !== "number") return null;
  const value = new Decimal(fact.value);
  return value.isFinite() ? value : null;
}

/** A proposed analytical basis must be dimensionally usable before any calculation.
 * Contextual adoption is separate; unknown units/perimeters cannot be repaired by ranking. */
export function calculationBasis(facts: readonly ReconciledFact[]): {
  facts: ReconciledFact[];
  blocked: Array<{fieldPath: string; reasons: string[]}>;
} {
  const numeric = facts.filter((fact) => fact.valueType === "number");
  const perimeters = new Set(numeric.map((fact) => fact.key.entityScope).filter(Boolean));
  const entities = new Set(numeric.map((fact) => fact.key.entityName).filter(Boolean));
  const currencies = new Set(numeric.map((fact) => fact.key.currency).filter(Boolean));
  const byPath = new Map<string, number>();
  for (const fact of facts) byPath.set(fact.key.fieldPath, (byPath.get(fact.key.fieldPath) ?? 0) + 1);
  const blocked: Array<{fieldPath: string; reasons: string[]}> = [];
  const usable = facts.filter((fact) => {
    const reasons: string[] = [];
    if (fact.valueType === "number") {
      if (!fact.key.entityScope) reasons.push("perimeter_unknown");
      if (!fact.key.unit) reasons.push("unit_unknown");
      if (!fact.key.scale || !/^[0-9]+(?:\.[0-9]+)?$/.test(fact.key.scale) || new Decimal(fact.key.scale).lte(0)) reasons.push("scale_unknown");
      if (!fact.key.currency && !["ratio", "percent", "percentage", "count", "days", "months", "years"].includes(fact.key.unit ?? "")) reasons.push("currency_unknown");
      if (perimeters.size > 1 || entities.size > 1) reasons.push("context_selection_required");
      if (currencies.size > 1) reasons.push("currency_selection_required");
    }
    if ((byPath.get(fact.key.fieldPath) ?? 0) > 1) reasons.push("dimension_selection_required");
    if (fact.conflicts.length > 0) reasons.push("conflicting_observations");
    if (reasons.length > 0) { blocked.push({fieldPath: fact.key.fieldPath, reasons}); return false; }
    return true;
  });
  return {facts: usable, blocked};
}

packages/reconciliation/src/gaps.ts.content:
import {
  archetype,
  assessSufficiency,
  materialFieldRequirements,
  requirementIsSatisfied,
  type ArchetypeId,
  type ClassifiedDocument,
  type InformationAnswers,
  type RequirementResponses,
} from "@offroad/credit-playbook";

import type {ReconciledFact} from "./facts";
import type {ExceptionSeverity} from "@offroad/credit-ontology";

/**
 * What is missing, said as a question rather than a silence.
 *
 * Half of what a credit desk sends back is not a correction — it is a request. "We need the
 * payoff letters", "we need proof of the equity contribution", "we need an updated appraisal".
 * Those are not failures of the extraction; they are the desk doing its job, and they are the
 * single most useful thing a company can receive early, because each one is a week saved later.
 *
 * Two sources, both deterministic:
 *
 *   1. **The playbook's checklist** — a required document nobody sent.
 *   2. **The material fields** — a fact the analysis needs that no document stated. This is
 *      what the extractor's `absent_fields` becomes once it is scoped by what the operation
 *      actually requires.
 *
 * Nothing here is invented. A gap names the document or the field, says why it matters, and
 * points at whoever can close it.
 */

export type InformationGap = {
  id: string;
  severity: ExceptionSeverity;
  title: string;
  description: string;
  /** Who closes it. Almost always the company. */
  ownerRole: "company" | "internal_analyst" | "external_advisor";
  /** The requirement or field path behind it, for traceability. */
  reference: string;
};

export function findGaps(input: {
  archetypeId: ArchetypeId;
  documents: readonly ClassifiedDocument[];
  facts: readonly ReconciledFact[];
  locale?: "pt" | "en";
  informationAnswers?: InformationAnswers;
  requirementResponses?: RequirementResponses;
  additionalAvailableFieldPaths?: readonly string[];
}): InformationGap[] {
  const locale = input.locale ?? "pt";
  const gaps: InformationGap[] = [];

  // 1 — documents the operation requires that nobody sent.
  const sufficiency = assessSufficiency(
    input.archetypeId,
    input.documents,
    input.informationAnswers,
    input.requirementResponses,
  );
  for (const status of sufficiency.missing) {
    const {requirement} = status;
    gaps.push({
      id: `missing_document:${requirement.id}`,
      severity: requirement.level === "minimum" ? "high" : "medium",
      title: requirement.labels[locale],
      description: requirement.rationale[locale],
      ownerRole: "company",
      reference: requirement.id,
    });
  }

  // 2 — material facts the analysis needs that no document stated.
  const present = new Set([
    ...input.facts.map((fact) => fact.key.fieldPath),
    ...(input.additionalAvailableFieldPaths ?? []),
  ]);
  const definition = archetype(input.archetypeId);
  for (const requirement of materialFieldRequirements(input.archetypeId)) {
    if (requirementIsSatisfied(requirement, present)) continue;
    const path = requirement.anyOf[0] ?? requirement.id;

    const focus = definition.focus.find((entry) => entry.evidence.some((evidence) => evidence.replace(/\{[a-z]+\}/g, "") === path.replace(/\.\d+\./g, ".")));
    gaps.push({
      id: `missing_field:${requirement.id}`,
      severity: "medium",
      title:
        locale === "pt"
          ? `Informação não encontrada: ${path}`
          : `Information not found: ${path}`,
      description: focus
        ? locale === "pt"
          ? `Nenhum documento enviado declara este dado, e ele é necessário para responder: ${focus.question.pt}`
          : `No document states this, and it is needed to answer: ${focus.question.en}`
        : locale === "pt"
          ? "Nenhum documento enviado declara este dado, e ele é material para a análise."
          : "No document states this, and it is material to the analysis.",
      ownerRole: "company",
      reference: requirement.id,
    });
  }

  return gaps;
}

/**
 * The archetype's known risks, raised as hypotheses to test.
 *
 * These are the questions an experienced lender asks before the numbers are even finished, and
 * they come from the playbook rather than from the data — which is the point. A desk does not
 * wait to be surprised by a ramp-up assumption; it asks about the ramp-up because it is a
 * growth deal.
 */
export function archetypeQuestions(archetypeId: ArchetypeId, locale: "pt" | "en" = "pt"): InformationGap[] {
  const definition = archetype(archetypeId);
  return definition.risks.map((risk) => ({
    id: `risk:${risk.id}`,
    severity: risk.severity === "critical" ? ("high" as const) : risk.severity,
    title: risk.labels[locale],
    description:
      locale === "pt"
        ? `Hipótese a testar neste tipo de operação. Como se verifica: ${risk.test.pt}`
        : `A hypothesis to test in this kind of operation. How it is checked: ${risk.test.en}`,
    ownerRole: "internal_analyst" as const,
    reference: risk.id,
  }));
}

packages/reconciliation/src/calculations.content:
import Decimal from "decimal.js";
import {calculateAdjustedEbitda, calculateLeverage, applyCollateralHaircuts, type CalculationResult} from "@offroad/financial-core";

import {factValue, type ReconciledFact} from "./facts";
import type {RuleContext} from "./rules";

/**
 * The numbers the desk computes, each one showing its work.
 *
 * Every calculation here is arithmetic over reconciled facts, done by `financial-core` in
 * Decimal, and every one carries a trace: which inputs, from which fact, from which document.
 * That is the whole difference between a platform that says "leverage is 2.87x" and one that
 * can be asked *why* and answer with the two numbers and the two documents they came from.
 *
 * A calculation whose inputs are missing does not appear. It is never estimated, never carried
 * over from a neighbouring period, never defaulted to zero — the gap is reported instead, and
 * a missing metric with a named cause is more useful to a credit committee than a number
 * nobody can source.
 */

export type TracedCalculation = {
  id: string;
  labels: {pt: string; en: string};
  value: string;
  /** Inputs, in order, with where each came from. */
  trace: Array<{label: string; value: string; fieldPath?: string; sourceDocument?: string}>;
  /** Facts this calculation depends on — the audit trail from number to page. */
  inputs: string[];
  warnings: string[];
};

/** Missing inputs, so the caller can turn them into a question rather than a silent absence. */
export type CalculationGap = {
  id: string;
  labels: {pt: string; en: string};
  missing: string[];
};

export type CalculationSet = {
  calculations: TracedCalculation[];
  gaps: CalculationGap[];
};

type Sourced = {value: Decimal; fieldPath: string; sourceDocument?: string};

function sourced(context: RuleContext, fieldPath: string, periodEnd?: string): Sourced | null {
  const value = factValue(context.index, fieldPath, periodEnd);
  if (value === null) return null;
  const fact: ReconciledFact | undefined = context.index.get(periodEnd ? [fieldPath, periodEnd].join("|") : fieldPath);
  return {value, fieldPath, ...(fact?.accepted.sourceDocument ? {sourceDocument: fact.accepted.sourceDocument} : {})};
}

function traced(
  id: string,
  labels: {pt: string; en: string},
  result: CalculationResult,
  inputs: Sourced[],
): TracedCalculation {
  const byLabel = new Map(inputs.map((input, index) => [index, input]));
  return {
    id,
    labels,
    value: result.value,
    trace: result.trace.map((entry, index) => {
      const input = byLabel.get(index);
      return {
        label: entry.label,
        value: entry.value,
        ...(input?.fieldPath ? {fieldPath: input.fieldPath} : {}),
        ...(input?.sourceDocument ? {sourceDocument: input.sourceDocument} : {}),
      };
    }),
    inputs: inputs.map((input) => input.fieldPath),
    warnings: result.warnings,
  };
}

/**
 * Computes what can be computed, and names what cannot.
 *
 * The set is deliberately small and load-bearing: net debt, adjusted EBITDA, leverage before
 * and after the operation, collateral capacity after haircuts, and the sources/uses totals.
 * These are the numbers a credit committee asks for first, and the ones every downstream
 * document repeats.
 */
export function computeCalculations(context: RuleContext): CalculationSet {
  const calculations: TracedCalculation[] = [];
  const gaps: CalculationGap[] = [];
  // Projection dates can be years ahead of the balance sheet. They must never move the
  // calculation anchor forward and make today's cash, debt and LTM EBITDA disappear.
  const period = [...new Set(
    context.facts
      .filter((fact) => /^(historical|interim)_financials\./.test(fact.key.fieldPath))
      .map((fact) => fact.key.periodEnd)
      .filter((value): value is string => Boolean(value)),
  )].sort().reverse()[0] ?? context.periods[0];
  const year = period?.slice(0, 4) ?? "";

  const pick = (paths: string[]): Sourced | null => {
    for (const path of paths) {
      const found = sourced(context, path, period) ?? sourced(context, path);
      if (found) return found;
    }
    return null;
  };

  // ---- net debt -------------------------------------------------------------------------
  const grossDebt = pick(["debt.total_gross", `historical_financials.${year}.gross_debt`, `interim_financials.${year}_07.gross_debt`]);
  const cash = pick([`historical_financials.${year}.cash`, `interim_financials.${year}_07.cash`]);

  let netDebt: Sourced | null = null;
  if (grossDebt && cash) {
    const value = grossDebt.value.minus(cash.value);
    netDebt = {value, fieldPath: "calculated.net_debt"};
    calculations.push({
      id: "net_debt",
      labels: {pt: "Dívida líquida", en: "Net debt"},
      value: value.toDecimalPlaces(2).toFixed(),
      trace: [
        {label: "gross_debt", value: grossDebt.value.toFixed(), fieldPath: grossDebt.fieldPath, ...(grossDebt.sourceDocument ? {sourceDocument: grossDebt.sourceDocument} : {})},
        {label: "cash", value: cash.value.toFixed(), fieldPath: cash.fieldPath, ...(cash.sourceDocument ? {sourceDocument: cash.sourceDocument} : {})},
      ],
      inputs: [grossDebt.fieldPath, cash.fieldPath],
      warnings: [],
    });
  } else {
    gaps.push({
      id: "net_debt",
      labels: {pt: "Dívida líquida", en: "Net debt"},
      missing: [!grossDebt ? "dívida bruta" : "", !cash ? "caixa e equivalentes" : ""].filter(Boolean),
    });
  }

  // ---- adjusted EBITDA ------------------------------------------------------------------
  const ebitda = pick([`historical_financials.${year}.ebitda`, `interim_financials.${year}_07.ebitda_ltm`, `interim_financials.${year}_07.ebitda`]);
  let adjustedEbitda: Sourced | null = null;
  if (ebitda) {
    // Add-backs are only included once a human approved them (R10); none are assumed here.
    const result = calculateAdjustedEbitda(ebitda.value, []);
    adjustedEbitda = {value: new Decimal(result.value), fieldPath: "calculated.adjusted_ebitda"};
    calculations.push(
      traced("adjusted_ebitda", {pt: "EBITDA ajustado", en: "Adjusted EBITDA"}, result, [ebitda, ebitda]),
    );
  } else {
    gaps.push({id: "adjusted_ebitda", labels: {pt: "EBITDA ajustado", en: "Adjusted EBITDA"}, missing: ["EBITDA do período"]});
  }

  // ---- leverage, before and after -------------------------------------------------------
  if (netDebt && adjustedEbitda && adjustedEbitda.value.gt(0)) {
    const result = calculateLeverage(netDebt.value, adjustedEbitda.value);
    calculations.push(
      traced("leverage_pre_transaction", {pt: "Alavancagem pré-operação", en: "Leverage before the transaction"}, result, [netDebt, adjustedEbitda]),
    );

    const requested = pick(["transaction.requested_amount"]);
    if (requested) {
      const refinancing = pick(["transaction.refinancing"]);
      const companyCash = pick(["project.company_cash"]);
      const projectedEbitda = pick([`projections.${year}.ebitda`]);
      const postGross = (grossDebt?.value ?? new Decimal(0))
        .plus(requested.value)
        .minus(refinancing?.value ?? new Decimal(0));
      calculations.push({
        id: "gross_debt_post_transaction",
        labels: {pt: "Dívida bruta pós-operação", en: "Gross debt after the transaction"},
        value: postGross.toDecimalPlaces(2).toFixed(),
        trace: [
          {label: "gross_debt", value: (grossDebt?.value ?? new Decimal(0)).toFixed(), ...(grossDebt?.fieldPath ? {fieldPath: grossDebt.fieldPath} : {})},
          {label: "requested_amount", value: requested.value.toFixed(), fieldPath: requested.fieldPath},
          ...(refinancing ? [{label: "refinancing_repaid", value: refinancing.value.negated().toFixed(), fieldPath: refinancing.fieldPath}] : []),
        ],
        inputs: [grossDebt?.fieldPath ?? "", requested.fieldPath, refinancing?.fieldPath ?? ""].filter(Boolean),
        warnings: [],
      });

      const postCash = (cash?.value ?? new Decimal(0)).minus(companyCash?.value ?? new Decimal(0));
      const leverageEbitda = projectedEbitda ?? adjustedEbitda;
      const postNet = postGross.minus(postCash);
      const postResult = calculateLeverage(postNet, leverageEbitda.value);
      calculations.push({
        id: "leverage_post_transaction",
        labels: {pt: "Alavancagem pós-operação", en: "Leverage after the transaction"},
        value: postResult.value,
        trace: [
          {label: "gross_debt_post_transaction", value: postGross.toFixed(), fieldPath: "calculated.gross_debt_post_transaction"},
          {label: "cash_before_transaction", value: (cash?.value ?? new Decimal(0)).toFixed(), ...(cash?.fieldPath ? {fieldPath: cash.fieldPath} : {})},
          ...(companyCash ? [{label: "company_cash_used", value: companyCash.value.toFixed(), fieldPath: companyCash.fieldPath}] : []),
          {label: projectedEbitda ? "projected_ebitda_at_closing" : "current_adjusted_ebitda", value: leverageEbitda.value.toFixed(), fieldPath: leverageEbitda.fieldPath},
        ],
        inputs: [grossDebt?.fieldPath ?? "", requested.fieldPath, refinancing?.fieldPath ?? "", cash?.fieldPath ?? "", companyCash?.fieldPath ?? "", leverageEbitda.fieldPath].filter(Boolean),
        warnings: [
          ...postResult.warnings,
          ...(projectedEbitda
            ? ["usa o EBITDA projetado para o ano do fechamento, identificado como premissa da administração"]
            : ["na ausência de EBITDA para o fechamento, mantém o EBITDA ajustado atual"]),
        ],
      });
    }
  } else if (!gaps.some((gap) => gap.id === "net_debt" || gap.id === "adjusted_ebitda")) {
    gaps.push({id: "leverage", labels: {pt: "Alavancagem", en: "Leverage"}, missing: ["EBITDA positivo"]});
  }

  // ---- collateral capacity --------------------------------------------------------------
  const collateralItems = context.facts
    .filter((fact) => /^collateral\.assets\.\d+\.eligible_base$/.test(fact.key.fieldPath) && fact.valueType === "number")
    .map((fact) => {
      const index = fact.key.fieldPath.split(".")[2];
      const haircut = factValue(context.index, `collateral.assets.${index}.policy_haircut`);
      const description = context.index.get(`collateral.assets.${index}.description`);
      return {
        name: description?.value ?? `ativo ${index}`,
        grossValue: fact.value,
        haircutRate: haircut ? haircut.toFixed() : "0",
        fieldPath: fact.key.fieldPath,
        sourceDocument: fact.accepted.sourceDocument,
      };
    });

  const collateralCapacityComponents = [
    "collateral.receivables_capacity",
    "collateral.inventory_capacity",
    "collateral.property_equipment_capacity",
  ]
    .map((fieldPath) => sourced(context, fieldPath, period) ?? sourced(context, fieldPath))
    .filter((item): item is Sourced => item !== null);

  if (collateralItems.length > 0) {
    const result = applyCollateralHaircuts(collateralItems);
    calculations.push({
      id: "collateral_capacity_total",
      labels: {pt: "Capacidade de garantias após haircut", en: "Collateral capacity after haircuts"},
      value: result.value,
      trace: result.trace.map((entry, index) => ({
        label: entry.label,
        value: entry.value,
        ...(collateralItems[index]?.fieldPath ? {fieldPath: collateralItems[index]!.fieldPath} : {}),
        ...(collateralItems[index]?.sourceDocument ? {sourceDocument: collateralItems[index]!.sourceDocument} : {}),
      })),
      inputs: collateralItems.map((item) => item.fieldPath),
      warnings: result.warnings,
    });
  } else if (collateralCapacityComponents.length > 0) {
    const total = collateralCapacityComponents.reduce((sum, item) => sum.plus(item.value), new Decimal(0));
    calculations.push({
      id: "collateral_capacity_total",
      labels: {pt: "Capacidade de garantias após haircut", en: "Collateral capacity after haircuts"},
      value: total.toDecimalPlaces(2).toFixed(),
      trace: collateralCapacityComponents.map((item) => ({
        label: item.fieldPath,
        value: item.value.toFixed(),
        fieldPath: item.fieldPath,
        ...(item.sourceDocument ? {sourceDocument: item.sourceDocument} : {}),
      })),
      inputs: collateralCapacityComponents.map((item) => item.fieldPath),
      warnings: [],
    });
  } else {
    gaps.push({
      id: "collateral_capacity_total",
      labels: {pt: "Capacidade de garantias", en: "Collateral capacity"},
      missing: ["base elegível e haircut por ativo"],
    });
  }

  // ---- stabilized project add-on --------------------------------------------------------
  const investmentIndexes = [...new Set(
    context.facts
      .map((fact) => fact.key.fieldPath.match(/^project\.investments\.(\d+)\.stabilized_revenue$/)?.[1])
      .filter((index): index is string => Boolean(index)),
  )].sort((a, b) => Number(a) - Number(b));
  if (investmentIndexes.length > 0) {
    const revenues = investmentIndexes
      .map((index) => sourced(context, `project.investments.${index}.stabilized_revenue`))
      .filter((item): item is Sourced => item !== null);
    const margins = investmentIndexes
      .map((index) => sourced(context, `project.investments.${index}.stabilized_ebitda_margin`))
      .filter((item): item is Sourced => item !== null);
    if (revenues.length === investmentIndexes.length) {
      const totalRevenue = revenues.reduce((sum, item) => sum.plus(item.value), new Decimal(0));
      calculations.push({
        id: "addon_stabilized_revenue",
        labels: {pt: "Receita estabilizada incremental", en: "Stabilized incremental revenue"},
        value: totalRevenue.toDecimalPlaces(2).toFixed(),
        trace: revenues.map((item) => ({label: item.fieldPath, value: item.value.toFixed(), fieldPath: item.fieldPath, ...(item.sourceDocument ? {sourceDocument: item.sourceDocument} : {})})),
        inputs: revenues.map((item) => item.fieldPath),
        warnings: ["run-rate estabilizado do projeto, não receita do primeiro ano"],
      });
    }
    if (revenues.length === investmentIndexes.length && margins.length === investmentIndexes.length) {
      const totalEbitda = investmentIndexes.reduce((sum, _index, position) =>
        sum.plus(revenues[position]!.value.times(margins[position]!.value)), new Decimal(0));
      calculations.push({
        id: "addon_stabilized_ebitda",
        labels: {pt: "EBITDA estabilizado incremental", en: "Stabilized incremental EBITDA"},
        value: totalEbitda.toDecimalPlaces(2).toFixed(),
        trace: investmentIndexes.flatMap((_index, position) => [
          {label: revenues[position]!.fieldPath, value: revenues[position]!.value.toFixed(), fieldPath: revenues[position]!.fieldPath, ...(revenues[position]!.sourceDocument ? {sourceDocument: revenues[position]!.sourceDocument} : {})},
          {label: margins[position]!.fieldPath, value: margins[position]!.value.toFixed(), fieldPath: margins[position]!.fieldPath, ...(margins[position]!.sourceDocument ? {sourceDocument: margins[position]!.sourceDocument} : {})},
        ]),
        inputs: investmentIndexes.flatMap((_index, position) => [revenues[position]!.fieldPath, margins[position]!.fieldPath]),
        warnings: ["receita estabilizada multiplicada pela margem EBITDA estabilizada de cada unidade"],
      });
    } else if (revenues.length > 0) {
      gaps.push({
        id: "addon_stabilized_ebitda",
        labels: {pt: "EBITDA estabilizado incremental", en: "Stabilized incremental EBITDA"},
        missing: ["margem EBITDA estabilizada de cada unidade"],
      });
    }
  }

  // ---- sources and uses -----------------------------------------------------------------
  for (const [side, id, labels] of [
    ["sources", "sources_total", {pt: "Total das fontes", en: "Total sources"}],
    ["uses", "uses_total", {pt: "Total dos usos", en: "Total uses"}],
  ] as const) {
    const entries = context.facts.filter(
      (fact) => /^transaction\.sources_and_uses\.\d+\.side$/.test(fact.key.fieldPath) && fact.value === side,
    );
    if (entries.length === 0) continue;

    const amounts = entries
      .map((fact) => context.index.get(fact.key.fieldPath.replace(/\.side$/, ".amount")))
      .filter((fact): fact is ReconciledFact => Boolean(fact) && fact!.valueType === "number");
    if (amounts.length === 0) continue;

    const total = amounts.reduce((sum, fact) => sum.plus(new Decimal(fact.value)), new Decimal(0));
    calculations.push({
      id,
      labels,
      value: total.toDecimalPlaces(2).toFixed(),
      trace: amounts.map((fact) => ({
        label: fact.key.fieldPath,
        value: fact.value,
        fieldPath: fact.key.fieldPath,
        ...(fact.accepted.sourceDocument ? {sourceDocument: fact.accepted.sourceDocument} : {}),
      })),
      inputs: amounts.map((fact) => fact.key.fieldPath),
      warnings: [],
    });
  }

  return {calculations, gaps};
}

