import Decimal from "decimal.js";

import {decimal, full, ONE, receivablesPoolKernelsVersion, requireNonNegative, requireUnitInterval, safeRatio, sum, type ReceivablesPoolKernelTrace} from "./pool-shared";

export type ReceivablesPoolCashReceipt = {
  id: string;
  amount: string;
  receivableId: string | null;
  debtorId: string | null;
  linkedAccount: boolean;
  duplicateOf: string | null;
  anchorVerified: boolean;
};

export type ReceivablesPoolReconciliationLine = {
  left: string;
  right: string;
  difference: string;
  /** Absolute difference over the larger of |right| and one, so a zero ledger cannot divide by zero. */
  differenceShare: string;
  tolerance: string;
  status: "tied" | "outside_tolerance";
};

export type ReceivablesPoolReconciliation = {
  version: typeof receivablesPoolKernelsVersion;
  /** Title balances of the tape against the accounting gross receivables balance. */
  tapeToAccounting: ReceivablesPoolReconciliationLine;
  /** Collections recorded on the titles against the collections the accounting reports. */
  tapeCollectionsToAccounting: ReceivablesPoolReconciliationLine;
  /** Reported collections against the cash actually received, duplicates excluded. */
  collectionsToCash: ReceivablesPoolReconciliationLine;
  cashControls: {
    grossCashReceipts: string;
    validCashReceipts: string;
    mappedCash: string;
    linkedAccountCash: string;
    /** Mapped cash over valid cash (floored at one); the caller decides how a zero-cash period counts. */
    mappedShare: string;
    linkedAccountShare: string;
    duplicateReceiptIds: string[];
    unanchoredReceiptIds: string[];
    unknownMappingReceiptIds: string[];
    excludedDuplicateCash: string;
  };
  trace: ReceivablesPoolKernelTrace;
};

/**
 * Ties the tape to the accounting control, the tape collections to the reported collections and
 * the reported collections to cash, keeping every difference above tolerance visible. Receipts
 * named as duplicates are excluded from cash before any comparison; a receipt whose title is
 * unknown or whose debtor differs from the tape is an unknown mapping and never counts as mapped.
 */
export function reconcileReceivablesPoolLedgers(input: {
  tapeOutstanding: string;
  accountingGrossBalance: string;
  tapeCollections: string;
  reportedCollections: string;
  receipts: readonly ReceivablesPoolCashReceipt[];
  titles: readonly {id: string; debtorId: string}[];
  maximumAccountingMismatchShare: string;
  maximumCashMismatchShare: string;
}): ReceivablesPoolReconciliation {
  const tape = requireNonNegative("tapeOutstanding", input.tapeOutstanding);
  const accounting = requireNonNegative("accountingGrossBalance", input.accountingGrossBalance);
  const tapeCollections = requireNonNegative("tapeCollections", input.tapeCollections);
  const reportedCollections = requireNonNegative("reportedCollections", input.reportedCollections);
  const accountingTolerance = requireUnitInterval("maximumAccountingMismatchShare", input.maximumAccountingMismatchShare);
  const cashTolerance = requireUnitInterval("maximumCashMismatchShare", input.maximumCashMismatchShare);
  for (const receipt of input.receipts) requireNonNegative(`amount of receipt ${receipt.id}`, receipt.amount);

  const validReceipts = input.receipts.filter((receipt) => receipt.duplicateOf === null);
  const cash = sum(validReceipts.map((receipt) => receipt.amount));
  const grossCash = sum(input.receipts.map((receipt) => receipt.amount));
  const titleById = new Map(input.titles.map((title) => [title.id, title]));
  const unknownMappingReceiptIds = validReceipts.filter((receipt) => {
    if (receipt.receivableId === null || receipt.debtorId === null) return false;
    const title = titleById.get(receipt.receivableId);
    return title === undefined || title.debtorId !== receipt.debtorId;
  }).map((receipt) => receipt.id);
  const unknownMapping = new Set(unknownMappingReceiptIds);
  const mappedCash = sum(validReceipts.filter((receipt) => receipt.receivableId !== null && receipt.debtorId !== null && !unknownMapping.has(receipt.id)).map((receipt) => receipt.amount));
  const linkedCash = sum(validReceipts.filter((receipt) => receipt.linkedAccount).map((receipt) => receipt.amount));

  const line = (left: Decimal, right: Decimal, tolerance: Decimal): ReceivablesPoolReconciliationLine => {
    const difference = left.minus(right).abs();
    const differenceShare = safeRatio(difference, Decimal.max(right.abs(), ONE));
    return {
      left: full(left), right: full(right), difference: full(difference), differenceShare: full(differenceShare),
      tolerance: full(tolerance), status: differenceShare.lte(tolerance) ? "tied" : "outside_tolerance",
    };
  };
  const tapeToAccounting = line(tape, accounting, accountingTolerance);
  const tapeCollectionsToAccounting = line(tapeCollections, reportedCollections, cashTolerance);
  const collectionsToCash = line(cash, reportedCollections, cashTolerance);
  return {
    version: receivablesPoolKernelsVersion,
    tapeToAccounting,
    tapeCollectionsToAccounting,
    collectionsToCash,
    cashControls: {
      grossCashReceipts: full(grossCash),
      validCashReceipts: full(cash),
      mappedCash: full(mappedCash),
      linkedAccountCash: full(linkedCash),
      mappedShare: full(safeRatio(mappedCash, Decimal.max(cash, ONE))),
      linkedAccountShare: full(safeRatio(linkedCash, Decimal.max(cash, ONE))),
      duplicateReceiptIds: input.receipts.filter((receipt) => receipt.duplicateOf !== null).map((receipt) => receipt.id),
      unanchoredReceiptIds: input.receipts.filter((receipt) => !receipt.anchorVerified).map((receipt) => receipt.id),
      unknownMappingReceiptIds,
      excludedDuplicateCash: full(grossCash.minus(cash)),
    },
    trace: {
      id: "receivables.pool_reconciliation",
      formula: "difference = |left - right|; differenceShare = difference / max(|right|, 1); tied when differenceShare <= tolerance; cash excludes receipts named as duplicates; mappedShare = mappedCash / max(cash, 1)",
      operands: {
        tapeOutstanding: full(tape),
        accountingGrossBalance: full(accounting),
        tapeCollections: full(tapeCollections),
        reportedCollections: full(reportedCollections),
        validCashReceipts: full(cash),
        grossCashReceipts: full(grossCash),
        receipts: String(input.receipts.length),
        maximumAccountingMismatchShare: full(decimal(accountingTolerance)),
        maximumCashMismatchShare: full(decimal(cashTolerance)),
      },
      result: [tapeToAccounting.status, tapeCollectionsToAccounting.status, collectionsToCash.status].join(","),
    },
  };
}

packages/financial-core/src/credit-revie.content:
import Decimal from "decimal.js";

import type {CalculationTrace} from "./credit-math";
import {finiteFigure as finite, fullFigure as full, parseFigure} from "./figure-input";

/**
 * The arithmetic of the credit review (stage 19, third polish).
 *
 * `@offroad/credit-analysis` reads the rates, covenants and receivables coverage a debt schedule
 * writes in prose, builds the desk's inputs from reconciled facts, rates the credit on the desk's
 * ten-grade scale and runs the stress table a committee reads before it prices. Every figure of that
 * work is computed here, in Decimal at 40 significant digits with half-up rounding, with a trace
 * naming the formula and the operands; the package keeps the grammar of the prose it reads, the
 * scale's thresholds and weights as data, and the sentences.
 *
 * Figures are full-precision decimal strings unless the kernel states the precision it applies. A
 * value received that is not a finite decimal number is refused, never read as zero; a figure read
 * from a document or a fact that is not one is handed on as null, so the reading becomes an open
 * question instead of a number.
 */
export const creditReviewArithmeticVersion = "2026.09.27-v1";

// The same arithmetic contract the package root declares, so a kernel imported on its own computes
// exactly what it computes inside the review.
Decimal.set({precision: 40, rounding: Decimal.ROUND_HALF_UP, toExpNeg: -30, toExpPos: 30});

const ZERO = new Decimal(0);

// Figures written in a document -----------------------------------------------------------------

/** Digits grouped by dots in threes, the first group without a leading zero, and the decimals after a comma: "1.234,5". */
const groupedFigure = /^[1-9]\d{0,2}(?:\.\d{3})+(?:,\d+)?$/;
/** Digits without grouping and the decimals after a comma: "4,10", "130". */
const plainFigure = /^\d+(?:,\d+)?$/;
/** A single dot that cannot group thousands (it is not followed by exactly three digits of a valid group): "4.10", "3.0". */
const pointFigure = /^\d+\.\d+$/;

export type DocumentFigure = {
  /** The figure in decimal notation, its digits as the document writes them ("3,0" is "3.0"), or null when the text is not a figure. */
  readonly value: string | null;
  readonly trace: CalculationTrace;
};

/**
 * A figure as a Brazilian document writes it: dots group the thousands in threes and a comma marks
 * the decimals ("1.234,5" is 1234.5, "4,10" is 4.10). A single dot that cannot group thousands can
 * only mark the decimals ("4.10" is 4.10, never 410). Any other text (two commas, a group that is
 * not three digits, a separator at either end) is not a figure, and the reading is null.
 */
export function readDocumentFigure(input: {text: string}): DocumentFigure {
  const text = input.text;
  let value: string | null = null;
  let notation = "not a figure";
  if (groupedFigure.test(text)) {
    value = text.replace(/\./g, "").replace(",", ".");
    notation = "grouped thousands";
  } else if (plainFigure.test(text)) {
    value = text.replace(",", ".");
    notation = "no grouping";
  } else if (pointFigure.test(text)) {
    value = text;
    notation = "decimal point";
  }
  return {
    value,
    trace: {
      id: "review.document_figure",
      formula: "dots group thousands in threes and a comma marks the decimals; a single dot that cannot group thousands marks the decimals; any other text is not a figure",
      operands: {text, notation},
      result: value ?? "not a figure",
    },
  };
}

/**
 * A percentage written in a document as a decimal fraction, rounded half-up to `decimals` places:
 * "4,10" is 0.041000 at six places, "130" is 1.3000 at four. Null when the text is not a figure.
 */
export function readDocumentPercent(input: {text: string; decimals: number}): DocumentFigure {
  if (!Number.isInteger(input.decimals) || input.decimals < 0 || input.decimals > 20) throw new RangeError("decimals must be an integer between 0 and 20");
  const figure = readDocumentFigure({text: input.text}).value;
  const value = figure === null ? null : new Decimal(figure).div(100).toFixed(input.decimals, Decimal.ROUND_HALF_UP);
  return {
    value,
    trace: {
      id: "review.document_percent",
      formula: `percentage read as a document writes it / 100, half-up to ${input.decimals} decimals`,
      operands: {text: input.text, figure: figure ?? "not a figure"},
      result: value ?? "not a figure",
    },
  };
}

/**
 * The annual rate a monthly rate compounds to: (1 + monthly rate)^12 - 1. A rate of 1.42% a month is
 * 18.44% a year, not 17.04%: the gap a schedule kept by hand leaves out in the company's favour.
 */
export function annualRateForMonthlyRate(input: {monthlyRate: Decimal.Value}): {readonly value: string; readonly trace: CalculationTrace} {
  const monthly = finite("monthly rate", input.monthlyRate);
  const annual = monthly.plus(1).pow(12).minus(1);
  return {
    value: full(annual),
    trace: {id: "review.monthly_compounding", formula: "annual = (1 + monthly rate)^12 - 1", operands: {monthlyRate: full(monthly)}, result: full(annual)},
  };
}

// Figures stated as facts -----------------------------------------------------------------------

/**
 * A figure a reconciled fact states, surrounding spaces aside, in decimal notation (the notation of
 * every kernel): the figure, or null when the text is not a finite decimal number.
 */
export function readFactFigure(input: {text: string}): {readonly value: string | null; readonly trace: CalculationTrace} {
  const parsed = parseFigure(input.text.trim());
  const value = parsed ? full(parsed) : null;
  return {
    value,
    trace: {id: "review.fact_figure", formula: "the fact's text, surrounding spaces aside, read in decimal notation", operands: {text: input.text}, result: value ?? "not a figure"},
  };
}

/**
 * A count of months a fact states, as the number the trajectory reads: null when the text is not a
 * finite decimal number (an empty text is no count, never zero months).
 */
export function readMonthCount(input: {text: string}): {readonly value: number | null; readonly trace: CalculationTrace} {
  const figure = readFactFigure({text: input.text}).value;
  const value = figure === null ? null : new Decimal(figure).toNumber();
  return {
    value,
    trace: {id: "review.month_count", formula: "the fact's count of months, read in decimal notation", operands: {text: input.text}, result: value === null ? "not a figure" : String(value)},
  };
}

/**
 * The largest of the amounts stated for one request, compared exactly: the amount as stated, and its
 * position. On a tie the first stated wins, so the documents keep precedence over the product's form.
 */
export function selectLargestAmount(input: {amounts: readonly Decimal.Value[]}): {readonly value: Decimal.Value; readonly index: number; readonly trace: CalculationTrace} {
  if (input.amounts.length === 0) throw new RangeError("at least one amount is required");
  const figures = input.amounts.map((amount, index) => finite(`amount ${index + 1}`, amount));
  let index = 0;
  figures.forEach((figure, position) => {
    if (figure.gt(figures[index]!)) index = position;
  });
  return {
    value: input.amounts[index]!,
    index,
    trace: {
      id: "review.largest_amount",
      formula: "the largest amount, compared exactly; the first stated on a tie",
      operands: Object.fromEntries(figures.map((figure, position) => [`amount${position + 1}`, full(figure)])),
      result: full(figures[index]!),
    },
  };
}

// The internal rating ---------------------------------------------------------------------------

/**
 * Interest coverage as the rating reads it: EBITDA over the magnitude of the year's interest
 * expense. Not computed (null) when the expense is zero.
 */
export function calculateRatingCoverage(input: {ebitda: Decimal.Value; financialExpenses: Decimal.Value}): {readonly value: string | null; readonly trace: CalculationTrace} {
  const ebitda = finite("EBITDA", input.ebitda);
  const expenses = finite("financial expenses", input.financialExpenses).abs();
  const coverage = expenses.gt(0) ? ebitda.div(expenses) : null;
  return {
    value: coverage ? full(coverage) : null,
    trace: {
      id: "rating.interest_coverage",
      formula: "coverage = EBITDA / |interest expense|; not computed over a zero expense",
      operands: {ebitda: full(ebitda), financialExpenses: full(expenses)},
      result: coverage ? full(coverage) : "not computed (zero expense)",
    },
  };
}

/** The direction of EBITDA: (current - prior) / |prior|. Not computed (null) over a prior year of zero. */
export function calculateEbitdaTrend(input: {current: Decimal.Value; prior: Decimal.Value}): {readonly value: string | null; readonly trace: CalculationTrace} {
  const current = finite("current EBITDA", input.current);
  const prior = finite("prior EBITDA", input.prior);
  const growth = prior.isZero() ? null : current.minus(prior).div(prior.abs());
  return {
    value: growth ? full(growth) : null,
    trace: {
      id: "rating.ebitda_trend",
      formula: "growth = (current EBITDA - prior EBITDA) / |prior EBITDA|; not computed over a prior of zero",
      operands: {current: full(current), prior: full(prior)},
      result: growth ? full(growth) : "not computed (zero prior)",
    },
  };
}

export type RatingBand = {readonly limit: Decimal.Value; readonly points: number};

/**
 * The points a factor earns against its bands, compared exactly. `at_most`: the first band whose
 * limit the value does not exceed wins (ascending ceilings). `at_least`: the last band whose limit the
 * value reaches wins (ascending floors). A value no band admits earns `otherwise`.
 */
export function scoreRatingFactor(input: {value: Decimal.Value; bands: readonly RatingBand[]; reading: "at_most" | "at_least"; otherwise: number}): {readonly points: number; readonly trace: CalculationTrace} {
  const value = finite("factor value", input.value);
  const limits = input.bands.map((band, index) => ({limit: finite(`band ${index + 1} limit`, band.limit), points: band.points}));
  let points = input.otherwise;
  if (input.reading === "at_most") {
    const band = limits.find((entry) => value.lte(entry.limit));
    if (band) points = band.points;
  } else {
    for (const entry of limits) if (value.gte(entry.limit)) points = entry.points;
  }
  return {
    points,
    trace: {
      id: "rating.factor_points",
      formula: input.reading === "at_most"
        ? "points of the first band whose ceiling the value does not exceed; otherwise the floor points"
        : "points of the last band whose floor the value reaches; otherwise the floor points",
      operands: {value: full(value), bands: limits.map((entry) => `${full(entry.limit)}:${entry.points}`).join(", "), otherwise: String(input.otherwise)},
      result: String(points),
    },
  };
}

/**
 * The grade of the internal rating from its assessable factors: the score is the weighted points
 * over the most the assessable factors allow, times 100, half-up to a whole number (0 when nothing is
 * assessable); the grade is 10 - floor(score / 11.2), between 1 and 10, one grade for each 11.2 points
 * from grade 10 at a score of 0 (a score of 100 is grade 2); a critical leverage or runway floors it
 * at 8.
 */
export function gradeInternalRating(input: {factors: ReadonlyArray<{points: number | null; weight: number}>; floorAtEight: boolean}): {
  readonly score: number;
  readonly grade: number;
  readonly assessed: number;
  readonly trace: CalculationTrace;
} {
  const assessable = input.factors.filter((factor) => factor.points !== null);
  const earned = assessable.reduce((sum, factor) => sum.plus(finite("factor points", factor.points!).times(finite("factor weight", factor.weight))), ZERO);
  const possible = assessable.reduce((sum, factor) => sum.plus(finite("factor weight", factor.weight).times(4)), ZERO);
  const score = possible.gt(0) ? earned.times(100).div(possible).toDecimalPlaces(0, Decimal.ROUND_HALF_UP) : ZERO;
  const stepped = Decimal.min(10, Decimal.max(1, new Decimal(10).minus(score.div("11.2").floor())));
  const grade = input.floorAtEight ? Decimal.max(stepped, 8) : stepped;
  return {
    score: score.toNumber(),
    grade: grade.toNumber(),
    assessed: assessable.length,
    trace: {
      id: "rating.grade",
      formula: "score = weighted points / (4 x weights assessed) x 100, half-up to a whole number; grade = 10 - floor(score / 11.2), between 1 and 10; at least 8 when a critical leverage or runway floors it",
      operands: {earned: full(earned), possible: full(possible), floorAtEight: String(input.floorAtEight)},
      result: `score=${full(score)}; grade=${full(grade)}`,
    },
  };
}

// The stress table ------------------------------------------------------------------------------

export type StressScenarioId = "ebitda_minus_20" | "ebitda_minus_30" | "cdi_plus_300" | "cycle_plus_15" | "top_customer_lost";

export type StressScenarioFigures = {
  readonly id: StressScenarioId;
  /** EBITDA after the shock. */
  readonly ebitda: string;
  /** Leverage after the shock (post-transaction net debt over the shocked EBITDA); null when that EBITDA is not positive. */
  readonly leverage: string | null;
  /** Interest on the post-transaction gross debt at the shocked cost; null when no cost is known. */
  readonly annualInterest: string | null;
  /** Working capital the shock absorbs; null when the shock absorbs none or revenue is not stated. */
  readonly workingCapitalNeed: string | null;
  /** New money the tightest covenant still admits after the shock; null without a covenant or a positive EBITDA. */
  readonly covenantHeadroom: string | null;
  /** Whether the shocked leverage breaks the tightest covenant; null when either is absent. */
  readonly breachesCovenant: boolean | null;
};

/**
 * The stress table a committee reads before it prices, on the desk's own numbers: EBITDA down 20% and
 * 30%, the CDI up 300 basis points passed in full to the stack's cost, the cash cycle 15 days longer
 * (15/365 of the year's revenue absorbed in working capital) and the largest customer gone (its share
 * of revenue times the contribution margin lost, off EBITDA). The transaction amount is the one
 * stated, or the largest of the desk's scenarios (never below zero).
 */
export function calculateStressTable(input: {
  ebitda: Decimal.Value;
  netDebtPre: Decimal.Value;
  grossDebt: Decimal.Value;
  amount: Decimal.Value | null;
  scenarioAmounts: readonly Decimal.Value[];
  covenantCeiling: Decimal.Value | null;
  weightedCost: Decimal.Value | null;
  cdi: Decimal.Value;
  cycleDays: Decimal.Value | null;
  revenue: Decimal.Value | null;
  topCustomerShare: Decimal.Value | null;
  lostCustomerMargin: Decimal.Value;
}): {
  readonly amount: string;
  readonly netDebtPost: string;
  readonly grossDebtPost: string;
  /** The CDI after the 300 basis-point shock. */
  readonly shockedCdi: string;
  /** The cash cycle after the 15-day shock; null when the cycle is not stated. */
  readonly shockedCycleDays: string | null;
  readonly scenarios: readonly StressScenarioFigures[];
  readonly trace: CalculationTrace;
} {
  const ebitda = finite("EBITDA", input.ebitda);
  const amount = input.amount !== null
    ? finite("transaction amount", input.amount)
    : input.scenarioAmounts.reduce<Decimal>((max, value, index) => {
      const scenario = finite(`scenario amount ${index + 1}`, value);
      return scenario.gt(max) ? scenario : max;
    }, ZERO);
  const netDebtPost = finite("net debt", input.netDebtPre).plus(amount);
  const grossDebtPost = finite("gross debt", input.grossDebt).plus(amount);
  const ceiling = input.covenantCeiling === null ? null : finite("covenant ceiling", input.covenantCeiling);
  const cost = input.weightedCost === null ? null : finite("weighted cost", input.weightedCost);
  const cdi = finite("CDI", input.cdi);
  const cycle = input.cycleDays === null ? null : finite("cash cycle", input.cycleDays);
  const revenue = input.revenue === null ? null : finite("revenue", input.revenue);
  const share = input.topCustomerShare === null ? null : finite("largest customer's share", input.topCustomerShare);
  const margin = finite("contribution margin lost", input.lostCustomerMargin);
  const lost = share && revenue ? revenue.times(share).times(margin) : null;

  const scenario = (id: StressScenarioId, shocked: Decimal, shockedCost: Decimal | null, workingCapitalNeed: Decimal | null): StressScenarioFigures => {
    const leverage = shocked.gt(0) ? netDebtPost.div(shocked) : null;
    const headroom = ceiling && shocked.gt(0) ? ceiling.times(shocked).minus(netDebtPost) : null;
    return {
      id,
      ebitda: full(shocked),
      leverage: leverage ? full(leverage) : null,
      annualInterest: shockedCost ? full(grossDebtPost.times(shockedCost)) : null,
      workingCapitalNeed: workingCapitalNeed ? full(workingCapitalNeed) : null,
      covenantHeadroom: headroom ? full(headroom) : null,
      breachesCovenant: leverage && ceiling ? leverage.gt(ceiling) : null,
    };
  };

  const scenarios = [
    scenario("ebitda_minus_20", ebitda.times("0.8"), cost, null),
    scenario("ebitda_minus_30", ebitda.times("0.7"), cost, null),
    scenario("cdi_plus_300", ebitda, cost ? cost.plus("0.03") : null, null),
    scenario("cycle_plus_15", ebitda, cost, revenue ? revenue.times(15).div(365) : null),
    scenario("top_customer_lost", lost ? ebitda.minus(lost) : ebitda, cost, null),
  ];
  const shockedCdi = cdi.plus("0.03");
  const shockedCycle = cycle ? cycle.plus(15) : null;
  return {
    amount: full(amount),
    netDebtPost: full(netDebtPost),
    grossDebtPost: full(grossDebtPost),
    shockedCdi: full(shockedCdi),
    shockedCycleDays: shockedCycle ? full(shockedCycle) : null,
    scenarios,
    trace: {
      id: "stress.table",
      formula: "net debt and gross debt after the amount; EBITDA x 0.8 and x 0.7; cost + 0.03; revenue x 15 / 365 absorbed; EBITDA - revenue x largest share x margin lost; "
        + "leverage = net debt after / shocked EBITDA when positive; interest = gross debt after x cost; headroom = ceiling x shocked EBITDA - net debt after; breach when leverage > ceiling",
      operands: {
        ebitda: full(ebitda), amount: full(amount), netDebtPre: String(input.netDebtPre), grossDebt: String(input.grossDebt),
        covenantCeiling: ceiling ? full(ceiling) : "none", weightedCost: cost ? full(cost) : "none", cdi: full(cdi),
        revenue: revenue ? full(revenue) : "none", topCustomerShare: share ? full(share) : "none", lostCustomerMargin: full(margin),
      },
      result: scenarios.map((entry) => `${entry.id}: leverage=${entry.leverage ?? "none"}`).join("; "),
    },
  };
}

packages/financial-core/src/deal-arithme.content:
import Decimal from "decimal.js";

import type {CalculationTrace} from "./credit-math";
import {finiteFigure as finite, fullFigure as full} from "./figure-input";

/**
 * The arithmetic of the deal structure (stage 19, third polish, part 2B).
 *
 * `@offroad/deal-structure` sizes an operation against the walls a desk sizes it against, designs the
 * security package from the inventory, states the indicative term sheet and compiles the operation,
 * the structure and its alternatives. The figures of that work are computed here, in Decimal at 40
 * significant digits with half-up rounding, with a trace naming the formula and the operands; the
 * package keeps the policy it applies as data (the shares of the venture wall, the haircuts and ranks
 * of each class of collateral), the calendar, the gates and the sentences.
 *
 * Figures are full-precision decimal strings unless the kernel states the precision the structure
 * publishes. A value received that is not a finite decimal number is refused, never read as zero.
 */
export const dealArithmeticVersion = "2026.09.27-v1";

// The same arithmetic contract the package root declares, so a kernel imported on its own computes
// exactly what it computes inside the structure.
Decimal.set({precision: 40, rounding: Decimal.ROUND_HALF_UP, toExpNeg: -30, toExpPos: 30});

const ZERO = new Decimal(0);
/** An amount at cents, half-up, as the structure publishes it. */
const cents = (value: Decimal) => value.toDecimalPlaces(2, Decimal.ROUND_HALF_UP);

// Capacity ----------------------------------------------------------------------------------------

/**
 * The venture-debt wall: the lower of a share of the annual recurring revenue and a share of the last
 * equity round, each counted only when it is positive, half-up to cents; null when neither is. On a
 * tie the recurring revenue binds, as it is stated first.
 */
export function calculateVentureDebtCapacity(input: {arr: Decimal.Value | null; lastEquityRound: Decimal.Value | null; arrShare: Decimal.Value; roundShare: Decimal.Value}): {
  readonly value: string | null;
  readonly binding: "arr" | "last_equity_round" | null;
  readonly trace: CalculationTrace;
} {
  const arrShare = finite("share of ARR", input.arrShare);
  const roundShare = finite("share of the last round", input.roundShare);
  const candidates: Array<{binding: "arr" | "last_equity_round"; value: Decimal}> = [];
  const arr = input.arr === null ? null : finite("ARR", input.arr);
  const round = input.lastEquityRound === null ? null : finite("last equity round", input.lastEquityRound);
  if (arr && arr.gt(0)) candidates.push({binding: "arr", value: arr.times(arrShare)});
  if (round && round.gt(0)) candidates.push({binding: "last_equity_round", value: round.times(roundShare)});
  const lowest = candidates.reduce<(typeof candidates)[number] | null>((min, entry) => (min === null || entry.value.lt(min.value) ? entry : min), null);
  const value = lowest ? full(cents(lowest.value)) : null;
  return {
    value,
    binding: lowest?.binding ?? null,
    trace: {
      id: "deal.venture_capacity",
      formula: "min(ARR x share of ARR, last round x share of the round), each only when positive, half-up to cents; ARR binds on a tie",
      operands: {arr: arr ? full(arr) : "none", arrShare: full(arrShare), lastEquityRound: round ? full(round) : "none", roundShare: full(roundShare)},
      result: value === null ? "not computed (no positive ARR or round)" : `${value} (${lowest!.binding})`,
    },
  };
}

/**
 * The room under the leverage ceiling: EBITDA times the ceiling, less the net debt already
 * outstanding, never below zero (a company already above the ceiling has no incremental room, not
 * negative room), half-up to cents. Not computed (null) when EBITDA is not positive.
 */
export function calculateLeverageCeilingRoom(input: {adjustedEbitda: Decimal.Value; leverageCeiling: Decimal.Value; existingNetDebt: Decimal.Value}): {
  readonly value: string | null;
  /** EBITDA at cents, as the capacity's trace states it. */
  readonly ebitda: string;
  readonly trace: CalculationTrace;
} {
  const ebitda = finite("adjusted EBITDA", input.adjustedEbitda);
  const ceiling = finite("leverage ceiling", input.leverageCeiling);
  const netDebt = finite("existing net debt", input.existingNetDebt);
  const room = ebitda.gt(0) ? cents(Decimal.max(ebitda.times(ceiling).minus(netDebt), ZERO)) : null;
  return {
    value: room ? full(room) : null,
    ebitda: full(cents(ebitda)),
    trace: {
      id: "deal.leverage_ceiling_room",
      formula: "room = max(EBITDA x leverage ceiling - existing net debt, 0), half-up to cents; not computed when EBITDA is not positive",
      operands: {adjustedEbitda: full(ebitda), leverageCeiling: full(ceiling), existingNetDebt: full(netDebt)},
      result: room ? full(room) : "not computed (EBITDA not positive)",
    },
  };
}

/** The lowest of the figures, compared exactly, and its position: the first on a tie; null when there is none. */
export function selectLowestFigure(input: {values: readonly Decimal.Value[]}): {readonly value: string | null; readonly index: number | null; readonly trace: CalculationTrace} {
  const figures = input.values.map((value, index) => finite(`figure ${index + 1}`, value));
  let index: number | null = null;
  figures.forEach((figure, position) => {
    if (index === null || figure.lt(figures[index]!)) index = position;
  });
  const value = index === null ? null : full(figures[index]!);
  return {
    value,
    index,
    trace: {
      id: "deal.lowest_figure",
      formula: "the lowest figure, compared exactly; the first on a tie",
      operands: Object.fromEntries(figures.map((figure, position) => [`figure${position + 1}`, full(figure)])),
      result: value ?? "none",
    },
  };
}

// Collateral --------------------------------------------------------------------------------------

export type CollateralAssetFigures = {
  value: Decimal.Value;
  encumbered: Decimal.Value;
  /** The haircut applied, as a fraction: the room's, or the policy's for the class. */
  haircut: Decimal.Value;
  /** The quality rank of the class a lender reads it in: 1 first. */
  rank: number;
};

/**
 * The coverage a security package reaches. Each asset's free value is its value less what is already
 * pledged, never below zero, and its eligible value the free value after the haircut, half-up to
 * cents. The assets are ordered by rank, then by eligible value, largest first (ties keep the order
 * given), and taken in that order, skipping those with no eligible value, until the eligible value
 * taken reaches the amount times the coverage required. The coverage reached is the eligible value
 * taken over the amount.
 */
export function designCollateralCoverage(input: {assets: readonly CollateralAssetFigures[]; amount: Decimal.Value; coverage: Decimal.Value}): {
  readonly required: string;
  /** Per asset, in the order given: the haircut at four decimals and the eligible value at cents. */
  readonly lines: ReadonlyArray<{readonly haircut: string; readonly eligible: string}>;
  /** The positions of the assets in the order they are taken. */
  readonly order: readonly number[];
  /** The positions of the assets taken into the package. */
  readonly selected: readonly number[];
  readonly eligibleSelected: string;
  /** The eligible value taken over the amount; null when the amount is zero. */
  readonly coverageReached: string | null;
  readonly sufficient: boolean;
  /** What the package lacks to reach the coverage required; null when it reaches it. */
  readonly shortfall: string | null;
  readonly trace: CalculationTrace;
} {
  const amount = finite("amount", input.amount);
  const coverage = finite("coverage required", input.coverage);
  const required = amount.times(coverage);
  const lines = input.assets.map((asset, index) => {
    const haircut = finite(`haircut of asset ${index + 1}`, asset.haircut);
    const free = Decimal.max(finite(`value of asset ${index + 1}`, asset.value).minus(finite(`encumbrance of asset ${index + 1}`, asset.encumbered)), 0);
    return {rank: asset.rank, haircut, free, eligible: cents(free.times(new Decimal(1).minus(haircut)))};
  });
  const order = lines.map((_, index) => index).sort((a, b) => lines[a]!.rank - lines[b]!.rank || lines[b]!.eligible.comparedTo(lines[a]!.eligible));
  const selected: number[] = [];
  let running = new Decimal(0);
  for (const index of order) {
    if (running.gte(required)) break;
    const eligible = lines[index]!.eligible;
    if (eligible.lte(0)) continue;
    selected.push(index);
    running = running.plus(eligible);
  }
  const sufficient = running.gte(required);
  const reached = amount.isZero() ? null : running.div(amount);
  const shortfall = sufficient ? null : required.minus(running);
  return {
    required: full(required),
    lines: lines.map((line) => ({haircut: line.haircut.toFixed(4, Decimal.ROUND_HALF_UP), eligible: line.eligible.toFixed(2)})),
    order,
    selected,
    eligibleSelected: full(running),
    coverageReached: reached ? full(reached) : null,
    sufficient,
    shortfall: shortfall ? full(shortfall) : null,
    trace: {
      id: "deal.collateral_coverage",
      formula: "free = max(value - encumbered, 0); eligible = free x (1 - haircut), half-up to cents; taken by rank, then largest eligible, until the eligible taken reaches amount x coverage; coverage reached = eligible taken / amount",
      operands: {amount: full(amount), coverage: full(coverage), assets: String(lines.length)},
      result: `required=${full(required)}; taken=${full(running)}; ${sufficient ? "sufficient" : `short by ${full(shortfall!)}`}`,
    },
  };
}

// Amounts of the operation, the structure and its alternatives -------------------------------------

/** Amounts summed exactly, in the order given. */
export function sumAmounts(input: {amounts: readonly Decimal.Value[]}): {readonly value: string; readonly trace: CalculationTrace} {
  const amounts = input.amounts.map((amount, index) => finite(`amount ${index + 1}`, amount));
  const sum = amounts.reduce((total, amount) => total.plus(amount), new Decimal(0));
  return {
    value: full(sum),
    trace: {id: "deal.amount_sum", formula: "sum of the amounts, in the order given", operands: Object.fromEntries(amounts.map((amount, index) => [`amount${index + 1}`, full(amount)])), result: full(sum)},
  };
}

/** How far one amount sits from another: the signed difference and its magnitude. */
export function calculateAmountDifference(input: {amount: Decimal.Value; reference: Decimal.Value}): {readonly value: string; readonly magnitude: string; readonly trace: CalculationTrace} {
  const amount = finite("amount", input.amount);
  const reference = finite("reference amount", input.reference);
  const difference = amount.minus(reference);
  return {
    value: full(difference),
    magnitude: full(difference.abs()),
    trace: {id: "deal.amount_difference", formula: "difference = amount - reference; magnitude = |difference|", operands: {amount: full(amount), reference: full(reference)}, result: full(difference)},
  };
}

/**
 * Whether two amounts tie within a tolerance: the magnitude of their difference against the magnitude
 * of the tolerance (a tolerance written as negative reads as its magnitude). A gap exactly at the
 * tolerance ties.
 */
export function testWithinTolerance(input: {difference: Decimal.Value; tolerance: Decimal.Value}): {readonly within: boolean; readonly trace: CalculationTrace} {
  const magnitude = finite("difference", input.difference).abs();
  const tolerance = finite("tolerance", input.tolerance).abs();
  const within = magnitude.lte(tolerance);
  return {
    within,
    trace: {id: "deal.within_tolerance", formula: "ties when |difference| <= |tolerance|", operands: {difference: full(finite("difference", input.difference)), tolerance: full(tolerance)}, result: within ? "within" : "outside"},
  };
}

/** What the capacity envelope leaves out of the request: the request less the envelope, never below zero. */
export function calculateSizingGap(input: {requested: Decimal.Value; envelope: Decimal.Value}): {readonly value: string; readonly trace: CalculationTrace} {
  const requested = finite("requested amount", input.requested);
  const envelope = finite("capacity envelope", input.envelope);
  const gap = Decimal.max(requested.minus(envelope), 0);
  return {
    value: full(gap),
    trace: {id: "deal.sizing_gap", formula: "gap = max(requested - envelope, 0)", operands: {requested: full(requested), envelope: full(envelope)}, result: full(gap)},
  };
}

/** Amounts summed by key (a year of maturities, a period), keys in the order first seen. */
export function sumAmountsByKey(input: {entries: ReadonlyArray<{key: string; amount: Decimal.Value}>}): {readonly totals: Readonly<Record<string, string>>; readonly trace: CalculationTrace} {
  const totals = new Map<string, Decimal>();
  input.entries.forEach((entry, index) => {
    totals.set(entry.key, (totals.get(entry.key) ?? new Decimal(0)).plus(finite(`amount ${index + 1}`, entry.amount)));
  });
  const result = Object.fromEntries([...totals.entries()].map(([key, total]) => [key, full(total)]));
  return {
    totals: result,
    trace: {id: "deal.amounts_by_key", formula: "amounts summed by key, keys in the order first seen", operands: {entries: String(input.entries.length)}, result: Object.entries(result).map(([key, total]) => `${key}=${total}`).join("; ")},
  };
}

packages/financial-core/src/relative-deb.content:
import Decimal from "decimal.js";
import {z} from "zod";

const Exact = Decimal.clone({precision: 80, rounding: Decimal.ROUND_HALF_UP});
const figure = z.string().regex(/^-?\d{1,24}(?:\.\d{1,20})?$/);
const unsigned = figure.refine(v => new Exact(v).gte(0));
const id = z.string().trim().min(1).max(160);
const date = z.iso.date();
const fmt = (v: Decimal) => v.toDecimalPlaces(20).toFixed();
export const relativeDebtCostVersion = "2026.10.07-v1";
export const relativeDebtCostBridgeInputSchema = z.strictObject({
  ownSpreadBps: figure, peerSpreadBps: figure,
  pricingBasis: z.enum(["same_indexer_quoted_spread", "equivalent_spread_on_same_dated_curve"]),
  ownIndexer: id, peerIndexer: id, curveVersion: id.nullable(),
  coverage: z.enum(["complete_scoped_bridge", "limited_adjustments"]),
  adjustments: z.array(z.strictObject({id, family: z.enum(["pricing_date", "tenor", "guarantee", "instrument_distribution", "scale", "other"]),
    bps: figure, evidenceAnchor: id, methodologyVersion: id, independentEffectGroup: id})).max(32),
}).superRefine((v, ctx) => {
  if (v.pricingBasis === "same_indexer_quoted_spread" && v.ownIndexer !== v.peerIndexer)
    ctx.addIssue({code: "custom", message: "Different indexers require equivalent spreads on the same dated curve"});
  if (v.pricingBasis === "equivalent_spread_on_same_dated_curve" && !v.curveVersion)
    ctx.addIssue({code: "custom", message: "Equivalent spreads require their adopted curve version"});
  if (v.pricingBasis === "same_indexer_quoted_spread" && v.curveVersion !== null)
    ctx.addIssue({code: "custom", message: "A quoted spread bridge must not claim curve normalization"});
  for (const key of ["id", "family", "independentEffectGroup"] as const) {
    if (new Set(v.adjustments.map(a => a[key])).size !== v.adjustments.length)
      ctx.addIssue({code: "custom", message: `Duplicate or overlapping adjustment ${key}`});
  }
});

/** The bridge is arithmetic over separately evidenced, adopted adjustments. It does not
 * estimate market effects, confer comparability, explain causality or assign a credit rating. */
export function calculateRelativeDebtCostBridge(raw: z.infer<typeof relativeDebtCostBridgeInputSchema>) {
  const input = relativeDebtCostBridgeInputSchema.parse(raw);
  const gross = new Exact(input.ownSpreadBps).minus(input.peerSpreadBps);
  let remaining = gross;
  const steps = input.adjustments.map(a => {
    const before = fmt(remaining); remaining = remaining.minus(a.bps);
    return {...a, beforeBps: before, afterBps: fmt(remaining), formula: "remaining difference minus evidenced adjustment"};
  });
  const dateAdjustment = input.adjustments.find(a => a.family === "pricing_date");
  return {schemaVersion: "relative-debt-cost-bridge.v1" as const, version: relativeDebtCostVersion,
    operands: input, grossBps: fmt(gross), knownAdjustmentsBps: fmt(gross.minus(remaining)),
    afterPricingDateBps: dateAdjustment ? fmt(gross.minus(dateAdjustment.bps)) : null,
    unexplainedAfterKnownAdjustmentsBps: fmt(remaining),
    residualBps: input.coverage === "complete_scoped_bridge" ? fmt(remaining) : null,
    status: input.coverage === "complete_scoped_bridge" ? "scoped_bridge" as const : "limited_bridge" as const,
    steps, causalAttribution: false as const, creditRating: null,
    trace: {id: "relative_cost.bridge", formula: "gross = own - peer; residual = gross - sum of non-overlapping adopted adjustments",
      result: fmt(remaining)}};
}

export const debtCostActionInputSchema = z.strictObject({
  actionId: id, currency: z.string().regex(/^[A-Z]{3}$/),
  convention: z.enum(["marginal_spread_budget_estimate", "effective_rate_difference"]),
  currentSpreadBps: figure, proposedSpreadBps: figure,
  exposure: z.array(z.strictObject({id, startDate: date, endDate: date, affectedPrincipal: unsigned,
    yearFraction: unsigned, timeBasis: z.enum(["actual_365_fixed", "adopted_month_fraction"]),
    annualIndex: figure.nullable(), evidenceAnchor: id})).min(1).max(480),
  costs: z.array(z.strictObject({id, date, amount: unsigned, evidenceAnchor: id})).max(256),
  costCoverage: z.enum(["complete_for_stated_horizon", "incomplete"]),
}).superRefine((v, ctx) => {
  if (new Set(v.exposure.map(p => p.id)).size !== v.exposure.length || new Set(v.costs.map(c => c.id)).size !== v.costs.length)
    ctx.addIssue({code: "custom", message: "Duplicate exposure or cost"});
  v.exposure.forEach((p, n) => {
    if (p.endDate <= p.startDate || (n > 0 && p.startDate !== v.exposure[n - 1]!.endDate))
      ctx.addIssue({code: "custom", message: "Exposure must cover ordered contiguous intervals"});
    if (p.timeBasis === "actual_365_fixed") {
      const expected = new Exact(Date.parse(p.endDate) - Date.parse(p.startDate)).div(86400000).div(365);
      if (expected.minus(p.yearFraction).abs().gt("0.000000000000000001"))
        ctx.addIssue({code: "custom", message: "Year fraction does not match the civil calendar"});
    } else {
      const a = new Date(p.startDate), b = new Date(p.endDate);
      if (a.getUTCDate() !== b.getUTCDate()) ctx.addIssue({code: "custom", message: "Month fraction requires aligned day of month"});
      const months = (b.getUTCFullYear() - a.getUTCFullYear()) * 12 + b.getUTCMonth() - a.getUTCMonth();
      if (new Exact(months).div(12).minus(p.yearFraction).abs().gt("0.000000000000000001"))
        ctx.addIssue({code: "custom", message: "Year fraction does not match the adopted month interval"});
    }
    if (v.convention === "effective_rate_difference" ? p.annualIndex === null || new Exact(p.annualIndex).lte(-1) : p.annualIndex !== null)
      ctx.addIssue({code: "custom", message: "Index must be explicitly adopted for effective-rate comparison and absent for a marginal spread estimate"});
  });
  if (new Exact(v.currentSpreadBps).lte(-10000) || new Exact(v.proposedSpreadBps).lte(-10000))
    ctx.addIssue({code: "custom", message: "Spread factor must remain positive"});
  if (v.costs.some(c => c.date < v.exposure[0]!.startDate || c.date > v.exposure.at(-1)!.endDate))
    ctx.addIssue({code: "custom", message: "Cost is outside the stated benefit horizon"});
});

/** Nominal savings under an explicit exposure and accrual convention; never a debt NPV
 * or a promised repricing. No assumed tax, zero-cost waiver, whole-debt exposure or rollover. */
export function calculateDebtCostAction(raw: z.infer<typeof debtCostActionInputSchema>) {
  const input = debtCostActionInputSchema.parse(raw);
  const spreadDelta = new Exact(input.currentSpreadBps).minus(input.proposedSpreadBps).div(10000);
  let savings = new Exact(0);
  const rows = input.exposure.map(p => {
    const factor = input.convention === "effective_rate_difference" ? new Exact(p.annualIndex!).plus(1) : new Exact(1);
    const rateDelta = spreadDelta.times(factor);
    const accruedDifference = input.convention === "effective_rate_difference"
      ? factor.times(new Exact(input.currentSpreadBps).div(10000).plus(1)).pow(p.yearFraction)
        .minus(factor.times(new Exact(input.proposedSpreadBps).div(10000).plus(1)).pow(p.yearFraction))
      : rateDelta.times(p.yearFraction);
    const amount = new Exact(p.affectedPrincipal).times(accruedDifference);
    savings = savings.plus(amount);
    return {...p, annualRateDifference: fmt(rateDelta), accruedFactorDifference: fmt(accruedDifference), nominalSavings: fmt(amount)};
  });
  const knownCosts = input.costs.reduce((sum, c) => sum.plus(c.amount), new Exact(0));
  return {schemaVersion: "debt-cost-action.v1" as const, version: relativeDebtCostVersion, operands: input, rows,
    nominalSavings: fmt(savings), knownCosts: fmt(knownCosts),
    netNominalBenefit: input.costCoverage === "complete_for_stated_horizon" ? fmt(savings.minus(knownCosts)) : null,
    status: input.costCoverage === "complete_for_stated_horizon" ? "stated_horizon_estimate" as const : "missing_costs" as const,
    isDebtNpv: false as const, guaranteesRepricing: false as const,
    trace: {id: "relative_cost.action", formula: input.convention === "effective_rate_difference"
      ? "sum(principal * [(indexFactor * currentSpreadFactor)^t - (indexFactor * proposedSpreadFactor)^t]) minus known dated costs"
      : "sum(affected principal * marginal spread difference * stated exposure year fraction) minus known dated costs",
      result: input.costCoverage === "complete_for_stated_horizon" ? fmt(savings.minus(knownCosts)) : "cost coverage incomplete"}};
}

