const ZERO = new Decimal(0);
const ONE = new Decimal(1);
const DAYS_PER_MONTH = new Decimal(30);
const CALENDAR_DAYS_PER_YEAR = new Decimal(365);
const BUSINESS_DAYS_PER_YEAR = new Decimal(252);

