function amount(value: string, code = "projection_challenge_invalid_amount", signed = false) {
  if (typeof value !== "string" || !(signed ? /^-?\d{1,24}(?:\.\d{1,20})?$/ : /^\d{1,24}(?:\.\d{1,20})?$/).test(value)) throw new Error(code);
