      if (shortfall.gt(0) && firstKnownShortfallDate === null) firstKnownShortfallDate = date;
    }
    return {date, available, restricted, eventIds: day.map(event => event.id)};
  });
  return {
    schemaVersion: "liquidity-calendar.v1" as const, engineVersion: liquidityCalendarVersion,
    openingDate: input.openingDate, endDate: input.endDate, currency: input.currency,
    convention: input.convention, coverage: {...input.coverage}, opening: initial,
    status: gaps.length ? "partial" as const : "calculated" as const,
    identity: "closing = opening + inflows - outflows",
    amountConvention: "normalized_currency_units_exact_up_to_8_decimals" as const,
    rows, events, gaps, firstKnownShortfallDate, maximumKnownShortfall: maximumKnownShortfall?.toFixed() ?? null,
    /** Calculated describes supplied operands, not forecast certainty or financing approval. */
    closingAvailable: balances.available?.toFixed() ?? null, closingRestricted: balances.restricted?.toFixed() ?? null,
  };
}

packages/financial-core/src/figure-input.content:
import Decimal from "decimal.js";

/**
 * How every kernel of the materials, the desk and the price reference reads a figure it receives
 * (internal to the package). Decimal notation only: text in another notation (hexadecimal, binary,
 * `Infinity`, `NaN`) and a number that is not finite are not figures, and a kernel refuses them
 * instead of reading them as zero.
 */
const decimalText = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/** The figure as a decimal, or null when the value is not a finite decimal number. */
export function parseFigure(value: Decimal.Value): Decimal | null {
  if (typeof value === "string" && !decimalText.test(value)) return null;
  if (typeof value === "number" && !Number.isFinite(value)) return null;
  const parsed = new Decimal(value);
  return parsed.isFinite() ? parsed : null;
}

/** The figure as a decimal; refuses a value that is not a finite decimal number, naming it. */
export function finiteFigure(label: string, value: Decimal.Value): Decimal {
  const parsed = parseFigure(value);
  if (!parsed) throw new RangeError(`${label} must be a finite decimal number`);
  return parsed;
}

/** A decimal at full precision, without rounding: the figure a kernel hands on. */
export const fullFigure = (value: Decimal): string => value.toFixed();

packages/credit-playbook/src/sufficiency.content:
import type {DocumentKind} from "@offroad/credit-ontology";

import {archetype} from "./archetypes";
import type {
  ArchetypeId,
  Requirement,
  RequirementLevel,
  RequirementPurpose,
  RequirementResponse,
  RequirementStage,
} from "./types";

/**
 * Which declared responses close an item.
 *
 * A reasoned "does not apply" closes it: the desk asked for something this company does not
 * have, and leaving that permanently red teaches people to ignore the list. Without a reason
 * it closes nothing — an investor reading "not applicable" with no explanation learns only
 * that somebody wanted the red mark gone.
 *
 * "Partial" and "after the NDA" deliberately close nothing. They are the company telling us
 * where it stands, which is worth recording and is not the same as the item being met.
 */
const resolvedBy = (declared: {response: RequirementResponse; note?: string} | undefined): boolean =>
  declared?.response === "not_applicable" && Boolean(declared.note?.trim());

/**
 * What the desk still needs, computed rather than asked.
 *
 * A checklist a person ticks is a form. This is the same list answered by what the pipeline
 * actually read: a document is classified, and the requirements it discharges go green on
 * their own. The company sees its package fill in as it uploads, and the desk stops asking for
 * things it already has — which is most of what makes an intake feel professional instead of
 * bureaucratic.
 *
 * Two lines, not one score. **Minimum** is the refusal line: below it the case cannot be
 * opened, and saying so early is a kindness. **Ideal** is the pricing line: above it the
 * operation can be structured and defended to an investor. Collapsing both into a single
 * percentage would hide exactly the distinction that matters.
 *
 * Nothing here is a credit decision. A complete package is a package, not an approval.
 */

export type RequirementStatus = {
  requirement: Requirement;
  satisfied: boolean;
  /** Evidence that discharges it, by id. Document ids remain directly linkable by the UI. */
  satisfiedBy: string[];
  /** For information items: the answer the company gave, when it gave one. */
  answer?: string;
  /** When it is needed. Derived from `level` unless the requirement says otherwise. */
  stage: RequirementStage;
  /** What the company said about it, when a file was not the answer. */
  response?: RequirementResponse;
  /** Why it does not apply, or what part is still coming. Required for `not_applicable`. */
  note?: string;
};

/**
 * What the company said about an item it did not simply upload.
 *
 * Keyed by requirement id, the same key the answers use.
 */
export type RequirementResponses = Readonly<Record<string, {response: RequirementResponse; note?: string} | undefined>>;

/** An answer the company typed, keyed by requirement id. */
export type InformationAnswers = Readonly<Record<string, string | undefined>>;

/**
 * Evidence that resolves a requirement without asking the client for another file or answer.
 *
 * This is deliberately separate from `InformationAnswers`. A value derived from reconciled
 * facts or obtained from a registered public source is not something the company declared.
 * Keeping the two apart preserves IN-13 and IN-26: the system can stop asking while still
 * showing exactly where the answer came from.
 */
export type RequirementEvidence = Readonly<Record<string, {evidenceIds: readonly string[]} | undefined>>;

export type SufficiencyReport = {
  archetypeId: ArchetypeId;
  minimum: {satisfied: number; total: number; complete: boolean};
  ideal: {satisfied: number; total: number; complete: boolean};
  /** Grouped by when they are needed — the axis the company reads first. */
  byStage: Record<RequirementStage, RequirementStatus[]>;
  /** Everything, in playbook order — minimum first, then ideal. */
  requirements: RequirementStatus[];
  /** Not satisfied, minimum before ideal: the list to show as "what is still missing". */
  missing: RequirementStatus[];
  /** Documents that discharged no requirement. Not a complaint — the desk reads them anyway. */
  unmatchedDocuments: string[];
};

/** A document as the pipeline knows it once classified. */
export type ClassifiedDocument = {
  id: string;
  kind: DocumentKind;
};

const levelOrder: Record<RequirementLevel, number> = {minimum: 0, ideal: 1};

/**
 * When an item is needed, defaulting from how much it matters.
 *
 * The two axes usually agree — what the desk cannot open a case without is what it needs now —
 * so the default carries most items. True diligence and closing items are set explicitly and
 * remain outside the client's current request batch.
 */
export const stageOf = (requirement: Requirement): RequirementStage =>
  requirement.stage ?? (requirement.level === "minimum" ? "now" : "structuring");

/**
 * Answers the checklist from what was read.
 *
 * A requirement is discharged by any document of a kind it lists — several kinds per
 * requirement on purpose, because one company keeps a trial balance where another exports its
 * ERP and both answer the same question. A document can discharge more than one requirement:
 * audited statements carry both the history and the auditor's opinion, and pretending
 * otherwise would ask the company for a file it already sent.
 */
export function assessSufficiency(
  archetypeId: ArchetypeId,
  documents: readonly ClassifiedDocument[],
  answers: InformationAnswers = {},
  responses: RequirementResponses = {},
  requirementEvidence: RequirementEvidence = {},
): SufficiencyReport {
  const definition = archetype(archetypeId);
  const byKind = new Map<DocumentKind, string[]>();
  for (const document of documents) {
    byKind.set(document.kind, [...(byKind.get(document.kind) ?? []), document.id]);
  }

  const matched = new Set<string>();
  const requirements: RequirementStatus[] = [...definition.requirements]
    .sort((a, b) => levelOrder[a.level] - levelOrder[b.level])
    .map((requirement) => {
      const stage = stageOf(requirement);
      const declared = responses[requirement.id];
      const externallyResolvedBy = [...(requirementEvidence[requirement.id]?.evidenceIds ?? [])];
      for (const id of externallyResolvedBy) matched.add(id);

      // An information item is discharged by the company answering, not by a file. A blank or
      // whitespace answer is not an answer: the item stays open rather than looking closed.
      if (requirement.source === "information") {
        const answer = answers[requirement.id]?.trim();
        const answerIsComplete = Boolean(answer) && !["partial", "after_nda", "unavailable"].includes(declared?.response ?? "provided");
        return {
          requirement,
          stage,
          satisfied: answerIsComplete || resolvedBy(declared) || externallyResolvedBy.length > 0,
          satisfiedBy: externallyResolvedBy,
          ...(answer ? {answer} : {}),
          ...(declared ? {response: declared.response, ...(declared.note ? {note: declared.note} : {})} : {}),
        };
      }

      const satisfiedBy = [
        ...requirement.satisfiedBy.flatMap((kind) => byKind.get(kind) ?? []),
        ...externallyResolvedBy,
      ];
      for (const id of satisfiedBy) matched.add(id);
      return {
        requirement,
        stage,
        // A file closes it; so does a reasoned "does not apply". "Partial" and "after the NDA"
        // do not — they are the company telling us where it stands, not the item being met.
        satisfied: satisfiedBy.length > 0 || resolvedBy(declared),
        satisfiedBy,
        ...(declared ? {response: declared.response, ...(declared.note ? {note: declared.note} : {})} : {}),
      };
    });

  // Closing items are shown and never scored. The day one of them counts is the day this
  // request becomes the data room it promised not to be.
  const scored = requirements.filter((status) => status.stage !== "closing");

  const count = (level: RequirementLevel) => {
    const scoped = scored.filter((status) => status.requirement.level === level);
    const satisfied = scoped.filter((status) => status.satisfied).length;
    return {satisfied, total: scoped.length, complete: satisfied === scoped.length};
  };

  return {
    archetypeId,
    minimum: count("minimum"),
    ideal: count("ideal"),
    requirements,
    byStage: {
      now: requirements.filter((status) => status.stage === "now"),
      structuring: requirements.filter((status) => status.stage === "structuring"),
      diligence: requirements.filter((status) => status.stage === "diligence"),
      closing: requirements.filter((status) => status.stage === "closing"),
    },
    missing: scored.filter((status) => !status.satisfied),
    unmatchedDocuments: documents.filter((document) => !matched.has(document.id)).map((document) => document.id),
  };
}

/**
 * What to say next, in one line.
 *
 * The company should never have to read a table to know where it stands. Below the minimum
 * the desk names the single most important gap, because a list of eleven missing items reads
 * as "come back later" while one named document reads as a next step.
 */
/**
 * What is still missing, grouped by what it unblocks.
 *
 * A flat list of gaps tells a company how much work is left. This tells it what the work is
 * *for* — the numbers cannot be built without these, the investor will ask for those, the story
 * has no shape without the others. People close gaps far faster when they can see which part of
 * the outcome each one buys.
 */
export function missingByPurpose(report: SufficiencyReport): Record<RequirementPurpose, RequirementStatus[]> {
  const grouped: Record<RequirementPurpose, RequirementStatus[]> = {
    investor_case: [],
    financials: [],
    structure: [],
    storytelling: [],
  };
  for (const status of report.missing) {
    for (const purpose of status.requirement.purposes) grouped[purpose].push(status);
  }
  return grouped;
}

export function nextStep(report: SufficiencyReport, locale: "pt" | "en" = "pt"): {state: "blocked" | "openable" | "priceable"; message: string} {
  const firstMissing = report.missing[0];

  if (!report.minimum.complete && firstMissing) {
    return {
      state: "blocked",
      message:
        locale === "pt"
          ? `Faltam ${report.minimum.total - report.minimum.satisfied} de ${report.minimum.total} itens para abrir o caso. O próximo é: ${firstMissing.requirement.labels.pt}.`
          : `${report.minimum.total - report.minimum.satisfied} of ${report.minimum.total} items are still missing to open the case. Next: ${firstMissing.requirement.labels.en}.`,
    };
  }

  if (!report.ideal.complete && firstMissing) {
    return {
      state: "openable",
      message:
        locale === "pt"
          ? `O caso pode ser aberto. Para estruturar e levar ao mercado, o próximo item é: ${firstMissing.requirement.labels.pt}.`
          : `The case can be opened. To structure it and take it to market, the next item is: ${firstMissing.requirement.labels.en}.`,
    };
  }

  return {
    state: "priceable",
    message:
      locale === "pt"
        ? "Pacote completo: o desk tem o que precisa para estruturar a operação."
        : "Package complete: the desk has what it needs to structure the operation.",
  };
}

packages/credit-playbook/src/types.ts.content:
import {z} from "zod";
import type {DocumentKind} from "@offroad/credit-ontology";

/**
 * The desk's knowledge, as data.
 *
 * Everything a credit desk "just knows" about a kind of operation — what it refuses to look at
 * without, what it needs to price, what it reads first, what usually goes wrong, and what
 * shape the paper takes — lives here as versioned, reviewable structure rather than inside a
 * prompt. Three consequences, and all three are the point:
 *
 *   - It can be **argued with**. A credit professional can read this file and say "that tenor
 *     band is wrong for this sector", and the fix is a diff, not a re-prompt.
 *   - It can be **tested**. Requirements resolve to document kinds the ontology actually
 *     defines; a typo is a failing test, not a silently missing checklist item.
 *   - It **accumulates**. Every recurring correction becomes a requirement, a risk or a
 *     synonym here — which is what "the system learns" has to mean when the alternative is a
 *     model that forgets.
 *
 * What is deliberately NOT here: anything that decides an outcome. The playbook says what to
 * look at and what usually matters. Whether a specific deal works is arithmetic over verified
 * facts, done by `financial-core`, and the endpoint is a qualified introduction — never an
 * approval.
 */

export const archetypeIdSchema = z.enum([
  "working_capital",
  "growth_expansion",
  "acquisition",
  "refinance",
  "equipment_finance",
  "venture_debt",
  "other",
]);
export type ArchetypeId = z.infer<typeof archetypeIdSchema>;

export const requirementLevelSchema = z.enum(["minimum", "ideal"]);
export type RequirementLevel = z.infer<typeof requirementLevelSchema>;

/**
 * What an item is *for*. Four purposes, because a company deserves to know which part of the
 * work its effort unblocks — and because the four are genuinely different jobs.
 *
 *   - `investor_case` — an investor will ask for it, and its absence is a question mark on the
 *     first call.
 *   - `financials` — the spreads and the ratios cannot be built without it.
 *   - `structure` — it sizes the operation or defines the security package.
 *   - `storytelling` — it is what turns a set of numbers into a business a reader understands.
 *     Underrated and usually missing: two identical credit profiles raise different amounts
 *     depending on whether anyone can explain what the company does and why now.
 */
export const requirementPurposeSchema = z.enum(["investor_case", "financials", "structure", "storytelling"]);
export type RequirementPurpose = z.infer<typeof requirementPurposeSchema>;

/**
 * How an item gets satisfied.
 *
 * `document` items are discharged by a file the pipeline classifies. `information` items are
 * discharged by the company answering — a number, a date, a paragraph. A desk asks for both,
 * and a request that only asks for files leaves the qualitative half of the case unwritten:
 * nobody uploads a document that explains why now, who the customers are, or what happens if
 * the biggest one leaves.
 *
 * `notice` is neither. It is something the company should know is coming and must not be asked
 * to do — the corporate approvals, the registrations, the certificates dated at signing. Making
 * it a source rather than a test exemption means nothing can accidentally start requesting one:
 * a notice has no file to send and no question to answer, and the type says so.
 */
export const requirementSourceSchema = z.enum(["document", "information", "notice"]);
export type RequirementSource = z.infer<typeof requirementSourceSchema>;

export const answerFormatSchema = z.enum(["text", "number", "date", "list", "currency", "percentage"]);
export type AnswerFormat = z.infer<typeof answerFormatSchema>;

/**
 * When the desk needs it — which is a different question from how much it matters.
 *
 * A company opening a request sees a list and reads it as the price of admission. If that list
 * is everything a fund will ever want, the company closes the tab; if it is only what we need
 * today and says nothing about what comes next, the company is ambushed in diligence three
 * weeks later and blames us for the surprise. Both failures come from the same omission: a
 * request with no time axis.
 *
 * So every item carries one. `now` is the deliberately small set needed to understand the
 * company and open the case. `structuring` is requested progressively, only after the initial
 * base has been read, and supports the proposed alternatives and institutional materials.
 * `diligence` is what a fund may ask once it is interested; shown, explained, and **not
 * requested yet**. `closing` is what only exists if the operation happens — named so nobody
 * is surprised, never a task.
 *
 * The stages map onto the market's own P0/P1/P2 vocabulary, but they are not labelled that way
 * for the company. "P1" tells a banker when something is needed and tells a founder nothing.
 */
export const requirementStageSchema = z.enum(["now", "structuring", "diligence", "closing"]);
export type RequirementStage = z.infer<typeof requirementStageSchema>;

/**
 * How a company can close an item without a file.
 *
 * A checklist whose only two states are "sent" and "missing" makes a company look delinquent
 * for things that genuinely do not apply to it — a business with no receivables facility has
 * no receivables ageing, and marking that permanently red trains people to ignore the whole
 * list. It also has nowhere to put "I sent last year's, this year's is with the auditor",
 * which is the single most common real answer.
 *
 * `not_applicable` requires a reason. Without one it is a way to make the list go away, and
 * an investor reading "not applicable" with no explanation learns nothing except that somebody
 * wanted the red mark gone.
 */
export const requirementResponseSchema = z.enum(["provided", "partial", "not_applicable", "after_nda", "unavailable"]);
export type RequirementResponse = z.infer<typeof requirementResponseSchema>;

/**
 * One thing the desk needs to see.
 *
 * `minimum` is the refusal line: without it the case cannot be opened, because no amount of
 * analysis compensates for not knowing whether the company has audited numbers or what it
 * already owes. `ideal` is the pricing line: with it the operation can be structured and
 * defended to an investor instead of merely described.
 *
 * `satisfiedBy` lists the document kinds that discharge the requirement — several, because a
 * company may have a trial balance where another has an ERP export, and both answer the same
 * question. `rationale` is shown to whoever is assembling the package: a checklist that says
 * *why* is a desk explaining itself; one that only says *what* is a form.
 */
export type Requirement = {
  id: string;
  level: RequirementLevel;
  /** Empty for information items; the document kinds that discharge a document item. */
  satisfiedBy: readonly DocumentKind[];
  labels: {pt: string; en: string};
  rationale: {pt: string; en: string};
  /** True when one document of any listed kind is enough; false when the desk expects coverage of a period. */
  singleDocument: boolean;
  /** What this item unblocks. At least one; usually two. */
  purposes: readonly RequirementPurpose[];
  /** A file, or an answer from the company. Defaults to `document` when omitted. */
  source?: RequirementSource;
  /**
   * When it is needed. Omitted means derived from `level`: minimum is `now`, ideal is
   * `structuring`. Set explicitly for true diligence or closing items, which are shown as a
   * roadmap and not turned into a current task.
   */
  stage?: RequirementStage;
  /**
   * The period and granularity expected, in the company's words.
   *
   * "Demonstrações financeiras" is not a request; "demonstrações auditadas dos últimos três
   * exercícios" is. Without the period a company sends the most recent year and both sides
   * discover the gap a week later.
   */
  period?: {pt: string; en: string};
  /** For information items: the shape of the answer expected. */
  answerFormat?: AnswerFormat;
  /** For information items: the question, phrased the way a banker would ask it. */
  question?: {pt: string; en: string};
  /** For information items: what a good answer looks like, so nobody guesses the format. */
  example?: {pt: string; en: string};
  /**
   * For document items: **what file to actually send**, named the way the company calls it.
   *
   * A requirement labelled "Historical financial statements" is a category, and a company
   * staring at a category sends the wrong thing or nothing at all. What unblocks people is the
   * concrete artifact — "the audited PDF signed by the auditor, one per year", "the ERP export
   * in .xlsx with one tab per account", "the deck you already use with investors" — because
   * they know exactly which file on which drive that is.
   *
   * Each entry is one artifact, with its usual format in parentheses. Several because a company
   * may hold the same information in different shapes, and the desk takes whichever exists.
   */
  accepts?: readonly {pt: string; en: string}[];
};

/** What the desk reads first, and what it is reading for. */
export type AnalysisFocus = {
  id: string;
  labels: {pt: string; en: string};
  /** The question this focus exists to answer. */
  question: {pt: string; en: string};
  /** Field paths and calculations that carry the answer. Resolved against the ontology. */
  evidence: readonly string[];
};

/** A way this kind of operation usually goes wrong. Stated as a hypothesis to test, never as a verdict. */
export type ArchetypeRisk = {
  id: string;
  labels: {pt: string; en: string};
  /** What the desk looks at to confirm or dismiss it. */
  test: {pt: string; en: string};
  severity: "critical" | "high" | "medium";
};

/**
 * The shape the paper usually takes. Bands, not promises: they frame a conversation with an
 * investor and are never quoted to a company as terms.
 */
export type StructureMenu = {
  tenorMonths: {typical: [number, number]; outer: [number, number]};
  gracePeriodMonths: {typical: [number, number]};
  amortization: readonly string[];
  collateral: readonly string[];
  covenants: readonly string[];
  /**
   * What the market will carry for this kind of operation, as a decimal string.
   *
   * `leverageCeiling` is net debt / adjusted EBITDA at closing — the level above which this
   * paper stops finding buyers, not a covenant and not a target. `minimumDscr` is the coverage
   * a lender underwrites to. Both are the conservative end of what the desk has seen clear;
   * they size the operation, and they are the numbers a credit professional will argue with
   * first, which is why they are data rather than a constant buried in a function.
   */
  leverageCeiling: string;
  minimumDscr: string;
  notes: {pt: string; en: string};
};

/** A question the desk asks the company before it can go further. */
export type StandardQuestion = {
  id: string;
  labels: {pt: string; en: string};
  /** Which analysis focus it unblocks. */
  focusId: string;
  materiality: "material" | "supporting";
};

export type Archetype = {
  id: ArchetypeId;
  labels: {pt: string; en: string};
  description: {pt: string; en: string};
  requirements: readonly Requirement[];
  focus: readonly AnalysisFocus[];
  risks: readonly ArchetypeRisk[];
  structure: StructureMenu;
  questions: readonly StandardQuestion[];
};

packages/credit-playbook/src/archetypes..content:
import type {Archetype, Requirement} from "./types";
import {commonClosing} from "./closing";

/**
 * The five operations this desk originates, plus a fallback.
 *
 * Written for Brazilian private credit: the documents are the ones a company here actually
 * has, the collateral is the collateral that actually gets taken (alienação fiduciária,
 * cessão fiduciária de recebíveis, aval), and the risks are the ones that actually kill these
 * deals rather than the ones that read well in a textbook.
 *
 * Every line here is a claim a credit professional can disagree with, which is the point of
 * writing it down.
 */

/** Requirements almost every operation shares. Stated once so a change reaches all of them. */
const commonMinimum: readonly Requirement[] = [
  {
    id: "financials_historical",
    accepts: [
      {pt: "Demonstrações financeiras auditadas dos últimos 3 exercícios (PDF assinado pelo auditor, um por ano)", en: "Audited financial statements for the last 3 years (PDF signed by the auditor, one per year)"},
      {pt: "Se não houver auditoria: demonstrações gerenciais ou balanços de encerramento (PDF ou planilha)", en: "If unaudited: management accounts or year-end statements (PDF or spreadsheet)"},
    ],
    purposes: ["investor_case", "financials", "storytelling"],
    level: "minimum",
    satisfiedBy: ["audited_financial_statements", "reviewed_interim_statements", "management_accounts"],
    singleDocument: false,
    labels: {pt: "Demonstrações financeiras dos últimos exercícios", en: "Historical financial statements"},
    rationale: {
      pt: "Sem histórico não há tendência, e sem tendência qualquer projeção é opinião. Auditadas valem mais que gerenciais e mudam o preço.",
      en: "No history means no trend, and without a trend any projection is an opinion. Audited statements outrank management accounts and change the price.",
    },
  },
  {
    id: "financials_interim",
    accepts: [
      {pt: "Balancete mais recente, com no máximo 90 dias (PDF ou planilha)", en: "Most recent trial balance, no more than 90 days old (PDF or spreadsheet)"},
      {pt: "Export do ERP com o razão ou o plano de contas do período (.xlsx, .csv ou .txt)", en: "ERP export with the ledger or chart of accounts for the period (.xlsx, .csv or .txt)"},
    ],
    purposes: ["investor_case", "financials"],
    level: "minimum",
    satisfiedBy: ["trial_balance", "erp_export", "reviewed_interim_statements", "management_accounts"],
    singleDocument: false,
    labels: {pt: "Posição contábil recente (balancete ou export do ERP)", en: "Recent accounting position"},
    rationale: {
      pt: "O último exercício fechado pode ter meses. O investidor pergunta como a empresa está agora, e o intervalo entre o balanço e hoje é onde os problemas aparecem.",
      en: "The last closed year can be months old. The investor asks how the company is now, and the gap between balance sheet and today is where problems surface.",
    },
  },
  {
    id: "debt_schedule",
    accepts: [
      {pt: "Mapa de dívida em planilha: credor, saldo, taxa, vencimento, amortização, garantia e covenants por contrato (.xlsx)", en: "Debt schedule as a spreadsheet: lender, balance, rate, maturity, amortisation, collateral and covenants per facility (.xlsx)"},
      {pt: "Contratos, CCBs ou escrituras das operações vigentes (PDF)", en: "Agreements, promissory notes or indentures of the outstanding facilities (PDF)"},
    ],
