packages/credit-playbook/src/voice-filte.content:
/**
 * Deterministic voice filter compiled from two sources:
 *
 * - Source A: procedure section "N4. Voz e três níveis de afirmação", lines 207 to 219 of
 *   `knowledge/procedures/capital/prepare-capital-structure-decision.md`, plus the T1 sentence
 *   (line 227) that keeps the composition labels off the interface.
 * - Source B: the founder's banker filter, the list of constructions a banker never writes.
 *
 * It inspects strings that reach a reader and reports the patterns the house refuses. It never
 * rewrites a string and never judges the substance behind it: N4 and Q2 both say that a clean
 * lexical pass does not certify a good opinion. Every rule is data (what it matches, how severe
 * it is, which paragraph justifies it), so a reviewer can read the policy without reading code.
 *
 * The characters the rules ban are built from their code points on purpose: the house style
 * test walks every package for the literal, and the rule that names a character must not be an
 * offender.
 * The offending example words live in the test corpus, as N4 asks, not here.
 */

export const VOICE_FILTER_VERSION = "2026.09.24-v1";

export type VoiceChannel = "packet" | "screen" | "catalogue";
export type VoiceSeverity = "block" | "warn";
export type VoiceRuleId = `VF-${string}`;
/** The slice of a string a rule is tested against; also the unit a finding reports. */
export type VoiceScope = "text" | "line" | "sentence";
export type VoiceLevel = "fato" | "leitura" | "recomendacao" | "indeterminado";

export type VoiceString = {id: string; text: string};

export type VoiceRule = {
  id: VoiceRuleId;
  /** Stable snake_case code, in the style of the conduct policy findings. */
  code: string;
  severity: VoiceSeverity;
  /** The source paragraph that justifies the rule, quoting the phrase where the source names it. */
  origin: string;
  description: string;
  scope: VoiceScope;
  /** The unit fires when any pattern matches it; a string pattern is a case-sensitive literal. */
  patterns: readonly (RegExp | string)[];
  /** A unit that also matches this is exempt: the number that turns "não fecha" into a calculation. */
  unless?: RegExp;
  /** What the reader sees next to the finding, in pt-BR like the conduct policy messages. */
  message: string;
};

/**
 * Shaped after `ConductFinding` (ruleId, code, severity, message) so both audits can be listed
 * together. The severity vocabulary is the one the voice brief fixes, `block` or `warn`; a
 * consumer merging into a conduct audit maps `warn` to `review`.
 */
export type VoiceFinding = {
  ruleId: VoiceRuleId;
  code: string;
  severity: VoiceSeverity;
  message: string;
  channel: VoiceChannel;
  /** The id given with the string, or its index when the caller passed plain strings. */
  stringId: string;
  /** The matched text with a little context, so a reader can locate it without the rule. */
  excerpt: string;
};

const EM_DASH = String.fromCodePoint(0x2014);
const EN_DASH = String.fromCodePoint(0x2013);
const N4 = "prepare-capital-structure-decision.md, N4";
const T1 = "prepare-capital-structure-decision.md, T1";
const FOUNDER = "founder's banker filter";

/**
 * `\b` in a JavaScript regex only knows ASCII letters, so "ótimo" and "quê" never sit on a
 * word boundary. These lookarounds are the Unicode-aware equivalent.
 */
const NOT_WORD_BEFORE = "(?<![\\p{L}\\p{N}_])";
const NOT_WORD_AFTER = "(?![\\p{L}\\p{N}_])";

function words(source: string, flags: "u" | "iu" = "iu"): RegExp {
  return new RegExp(`${NOT_WORD_BEFORE}(?:${source})${NOT_WORD_AFTER}`, flags);
}

/** A digit anywhere in the unit: the account behind "não fecha" or behind a verdict. */
const HAS_NUMBER = /\d/u;

export const voiceRules: readonly VoiceRule[] = [
  {
    id: "VF-01",
    code: "em_dash",
    severity: "block",
    origin: `${N4} line 219: "travessões em qualquer texto entregue"; ${FOUNDER}: U+2014`,
    description: "The em dash (U+2014) anywhere in a delivered string.",
    scope: "text",
    patterns: [EM_DASH],
    message: "Travessão (U+2014) proibido em qualquer texto entregue.",
  },
  {
    id: "VF-02",
    code: "en_dash",
    severity: "block",
    origin: `${FOUNDER}: U+2013`,
    description: "The en dash (U+2013) anywhere in a delivered string.",
    scope: "text",
    patterns: [EN_DASH],
    message: "Meia-risca (U+2013) proibida em qualquer texto entregue.",
  },
  {
    id: "VF-03",
    code: "emoji",
    severity: "block",
    origin: `${N4} line 219: "emoji"; ${FOUNDER}: emoji`,
    description: "A character with default emoji presentation, or a pictograph forced into emoji presentation by U+FE0F.",
    scope: "text",
    patterns: [/\p{Emoji_Presentation}/u, /\p{Extended_Pictographic}\u{FE0F}/u],
    message: "Emoji proibido em texto entregue.",
  },
  {
    id: "VF-04",
    code: "ai_self_reference",
    severity: "block",
    origin: `${N4} line 219: "como IA"; ${FOUNDER}: "como IA", "como modelo de linguagem"`,
    description: "The system speaking as an AI or as a language model, in pt-BR or en-US. The acronym is matched case-sensitively so that the verb form \"como ia\" is left alone.",
    scope: "text",
    patterns: [
      words("[Cc]omo\\s+(?:uma\\s+)?IA", "u"),
      words("como\\s+(?:um\\s+)?modelo\\s+de\\s+linguagem"),
      words("[Aa]s\\s+an\\s+AI", "u"),
      words("as\\s+a\\s+language\\s+model"),
    ],
    message: "O texto fala como IA ou como modelo de linguagem.",
  },
  {
    id: "VF-05",
    code: "filler",
    severity: "block",
    origin: `${N4} line 219: "vale destacar", "ótima pergunta"; ${FOUNDER}: "vale destacar", "ótima pergunta"`,
    description: "Conversational filler the house refuses, with the en-US equivalent of the compliment.",
    scope: "text",
    patterns: [words("vale\\s+destacar|ótima\\s+pergunta|great\\s+question")],
    message: "Preenchimento de conversa proibido pela voz da casa.",
  },
  {
    id: "VF-06",
    code: "third_party_certainty",
    severity: "block",
    origin: `${N4} line 219: "certeza sobre o comportamento do banco", "Usar probabilidade para terceiros"; ${FOUNDER}: "o banco vai", "o investidor vai aceitar", "o mercado vai"`,
    description: "A bank, investor or market announced as certain to act (\"vai\" and its plural and future forms), in pt-BR or en-US. Possibility (\"pode\") and probability pass.",
    scope: "text",
    patterns: [
      words("(?:o|os)\\s+(?:bancos?|investidor(?:es)?|mercados?)\\s+(?:não\\s+)?(?:vai|vão|irá|irão)"),
      words("the\\s+(?:banks?|investors?|market)\\s+will"),
    ],
    message: "Certeza sobre o comportamento de terceiro; usar probabilidade.",
  },
  {
    id: "VF-07",
    code: "bad_faith_framing",
    severity: "block",
    origin: `${N4} line 219: "linguagem de ocultar restrições"; ${FOUNDER}: "antes que a diligência", "antes que descubram"`,
    description: "Framing that treats a restriction as something to hide from the counterparty.",
    scope: "text",
    patterns: [words("antes\\s+que\\s+(?:a\\s+diligência|descubram)")],
    message: "Enquadramento de má-fé: a restrição se declara, não se esconde.",
  },
  {
    id: "VF-08",
    code: "not_x_but_y",
    severity: "warn",
    origin: `${N4} line 219: a construção "não é X, é Y"; ${FOUNDER}: the construction "não é X, é Y"`,
    description: "The rhetorical contrast \"não é X, é Y\" inside one sentence, in pt-BR or en-US.",
    scope: "sentence",
    patterns: [
      /(?<![\p{L}\p{N}_])não\s+(?:é|são)\s+[^.;:!?\n]{1,80}?,\s*(?:é|são)\s+/iu,
      /(?:is\s+not|isn't|'s\s+not)\s+[^.;:!?\n]{1,80}?,\s*(?:it's|it\s+is)\s+/iu,
    ],
    message: "Construção \"não é X, é Y\" recusada pela voz da casa.",
  },
  {
    id: "VF-09",
    code: "does_not_close_without_number",
    severity: "warn",
    origin: `${N4} line 219: Não usar "não fecha" sem a conta; ${FOUNDER}: "não fecha" (or "não para em pé") without a number in the same sentence`,
    description: "\"Não fecha\" or \"não para em pé\" in a sentence that carries no number.",
    scope: "sentence",
    patterns: [words("não\\s+(?:fecha|fecham|para\\s+em\\s+pé|param\\s+em\\s+pé)")],
    unless: HAS_NUMBER,
    message: "\"Não fecha\" sem a conta na mesma frase.",
  },
  {
    id: "VF-10",
    code: "verdict_without_number",
    severity: "warn",
    origin: `${N4} line 219: "Não dar veredito aceitar/recusar por padrão; usá-lo quando a decisão solicitada exigir, com sustentação"; ${FOUNDER}: binary verdicts without the number behind them`,
    description: "A sentence that opens with the verdict, or recommends it, without a number behind it.",
    scope: "sentence",
    patterns: [
      /^[\s"'“”‘’(*•-]*(?:aceitar|recusar|aceite|recuse)(?![\p{L}\p{N}_])/iu,
      words("(?:recomend(?:o|amos)|convém|deve(?:m|ria|riam)?|vale)\\s+(?:aceitar|recusar)"),
    ],
    unless: HAS_NUMBER,
    message: "Veredito aceitar/recusar sem o número que o sustenta.",
  },
  {
    id: "VF-11",
    code: "superlative",
    severity: "warn",
    origin: `${FOUNDER}: "ótimo", "excelente", "perfeito", "incrível"; ${N4} line 219: "adjetivo sem fundamento", "número ou lógica no lugar de ênfase"`,
    description: "Superlatives as emphasis, with their en-US equivalents.",
    scope: "text",
    patterns: [words("ótim[oa]s?|excelentes?|perfeit[oa]s?|incrív(?:el|eis)|excellent|perfect|incredible|amazing")],
    message: "Superlativo no lugar de número ou lógica.",
  },
  {
    id: "VF-12",
    code: "exclamation",
    severity: "warn",
    origin: `${N4} line 219: "slogans, manchetes artificiais"; ${FOUNDER}: slogans and marketing metaphors`,
    description: "An exclamation mark, the lexical trace of a slogan or headline. The sources name no metaphor vocabulary, so competition and catastrophe metaphors stay with semantic review.",
    scope: "text",
    patterns: [/!(?!=)/u],
    message: "Ponto de exclamação: marca de slogan ou manchete.",
  },
  {
    id: "VF-13",
    code: "stamped_label",
    severity: "warn",
    origin: `${N4} line 217: "não precisam virar etiquetas em cada linha da tela"; ${T1} line 227: "esses rótulos não são estampados na interface"; ${FOUNDER}: "what matters", "why", "implication", "o que importa", "por quê", "implicação" used as labels`,
    description: "A line that consists only of a composition label and a colon.",
    scope: "line",
    patterns: [/^[\s#*_>-]*(?:what\s+matters|why|implication|o\s+que\s+importa|por\s+qu[eê]|implicação)[\s*_]*:[\s*_]*$/iu],
    message: "Rótulo de composição estampado na tela.",
  },
];

export type AuditVoiceOptions = {channel: VoiceChannel};

/**
 * Audits every string in order and returns the findings in order: by string, then by rule, then
 * by unit. Pure and deterministic: the same input always yields the same list.
 */
export function auditVoice(strings: readonly string[] | readonly VoiceString[], options: AuditVoiceOptions): VoiceFinding[] {
  const findings: VoiceFinding[] = [];
  strings.forEach((entry, index) => {
    const {id, text} = typeof entry === "string" ? {id: String(index), text: entry} : entry;
    for (const rule of voiceRules) {
      for (const unit of unitsOf(text, rule.scope)) {
        if (rule.unless?.test(unit)) continue;
        const match = firstMatch(rule.patterns, unit);
        if (!match) continue;
        findings.push({
          ruleId: rule.id,
          code: rule.code,
          severity: rule.severity,
          message: rule.message,
          channel: options.channel,
          stringId: id,
          excerpt: excerpt(unit, match),
        });
      }
    }
  });
  return findings;
}

const LEVEL_MARKERS: Readonly<Record<Exclude<VoiceLevel, "indeterminado">, readonly RegExp[]>> = {
  // The action verbs of a recommendation, plus the first-person conditional of the N4 example.
  recomendacao: [words("recomend(?:o|amos)|convém|deve(?:m|ria|riam)?|vale|tentaria")],
  // Interpretation with an owner, as in the N4 example "Minha leitura é que".
  leitura: [words("parece(?:m)?|sugere(?:m)?|indica(?:m)?|lê-se|(?:minha|nossa)\\s+leitura")],
  // Numbers, units and dates: the marks of a statement with an origin.
  fato: [HAS_NUMBER, /R\$|US\$|%/u, words("bps")],
};

/**
 * Lexical reading of the three N4 levels. Informational only: it never blocks, and a sentence
 * with markers of more than one level takes the most committed one, since the words of a
 * recommendation or of a reading are chosen while numbers are everywhere.
 */
export function classifyLevel(sentence: string): VoiceLevel {
  for (const level of ["recomendacao", "leitura", "fato"] as const) {
    if (LEVEL_MARKERS[level].some((pattern) => pattern.test(sentence))) return level;
  }
  return "indeterminado";
}

type Match = {index: number; length: number};

function unitsOf(text: string, scope: VoiceScope): string[] {
  if (scope === "text") return [text];
  const lines = text.split(/\r?\n/u);
  const units = scope === "line" ? lines : lines.flatMap((line) => line.split(/(?<=[.!?;])\s+/u));
  return units.filter((unit) => unit.trim().length > 0);
}

function firstMatch(patterns: readonly (RegExp | string)[], unit: string): Match | null {
  for (const pattern of patterns) {
    if (typeof pattern === "string") {
      const index = unit.indexOf(pattern);
      if (index >= 0) return {index, length: pattern.length};
      continue;
    }
    const found = pattern.exec(unit);
    if (found) return {index: found.index, length: found[0].length};
  }
  return null;
}

const CONTEXT = 40;

function excerpt(unit: string, match: Match): string {
  const start = Math.max(0, match.index - CONTEXT);
  const end = Math.min(unit.length, match.index + match.length + CONTEXT);
  const body = unit.slice(start, end).replace(/\s+/gu, " ").trim();
  return `${start > 0 ? "..." : ""}${body}${end < unit.length ? "..." : ""}`;
}

packages/credit-playbook/src/conduct-pol.content:
import {createHash} from "node:crypto";

/**
 * Deterministic controls compiled from House Playbook LC-01 to LC-13.
 *
 * This module does not decide whether a transaction is good credit. It only decides whether a
 * claim or communication is fit to leave its current gate. Semantic review may add findings, but
 * it cannot waive one of these controls.
 */

export const conductPolicyVersion = "2026.08.25-v1";
export const advisoryDisclaimerId = "offroad-dcm-advisory-boundary-2026-08-25";

export type ConductClaimKind = "fact" | "calculation" | "premise" | "judgment" | "market_reference";
export type ConductSeverity = "block" | "review";
export type ConductChannel = "internal_material" | "external_material" | "external_communication";

export type ConductClaim = {
  id: string;
  text: string;
  kind: ConductClaimKind;
  material: boolean;
  supportIds: readonly string[];
  /** Explicit basis for a qualitative adjective, separate from a generic citation. */
  qualifierBasis?: readonly string[];
  /** Human approval tied to this exact claim fingerprint when the claim is a judgment. */
  approvedFingerprint?: string;
};

export type BilingualStatement = {
  id: string;
  pt: string;
  en: string;
};

export type DiligenceSurprise = {
  id: string;
  description: string;
  responsibleProcedureId?: string;
  correctiveActionId?: string;
};

export type ConductAuditInput = {
  artifactId: string;
  channel: ConductChannel;
  claims: readonly ConductClaim[];
  bilingualStatements?: readonly BilingualStatement[];
  sourceOrganizationId: string;
  targetOrganizationId: string;
  sourceCaseId: string;
  targetCaseId: string;
  recipientAuthorized: boolean;
  disclaimerId?: string;
  conflictStatus: "clear" | "disclosed_accepted" | "unresolved";
  riskSectionPosition?: number;
  promotionalSectionPosition?: number;
  hasMaterialCommitment?: boolean;
  writtenRecordId?: string;
  knowledgeState?: "known" | "partially_known" | "unknown";
  resolutionDueOn?: string;
  diligenceSurprises?: readonly DiligenceSurprise[];
  /** Acronyms defined in the artifact or approved by the house glossary. */
  definedAcronyms?: readonly string[];
};

export type ConductFinding = {
  ruleId: `LC-${string}`;
  code: string;
  severity: ConductSeverity;
  message: string;
  claimId?: string;
  statementId?: string;
};

export type ConductAudit = {
  status: "pass" | "blocked" | "review";
  version: string;
  fingerprint: string;
  findings: ConductFinding[];
};

const MATERIAL_QUALIFIERS = [
  /\brobust[oa]s?\b/iu,
  /\bforte(?:s)?\b/iu,
  /\bsólid[oa]s?\b/iu,
  /\bresiliente(?:s)?\b/iu,
  /\batrativ[oa]s?\b/iu,
  /\blideran(?:ça|te(?:s)?)\b/iu,
  /\brobust\b/iu,
  /\bstrong\b/iu,
  /\bsolid\b/iu,
  /\bresilient\b/iu,
  /\battractive\b/iu,
  /\bleading\b/iu,
] as const;

const OUTCOME_PROMISES = [
  /\b(?:crédito|operação|financiamento)\s+(?:está\s+|foi\s+)?aprova(?:do|da)\b/iu,
  /\b(?:captação|financiamento|funding)\s+(?:está\s+|foi\s+)?garanti(?:do|da)\b/iu,
  /\ba\s+offroad\s+(?:aprova|garante|compromete\s+capital|recomenda\s+o\s+investimento)\b/iu,
  /\b(?:credit|transaction|financing)\s+(?:is\s+|was\s+)?approved\b/iu,
  /\b(?:funding|financing)\s+(?:is\s+|was\s+)?guaranteed\b/iu,
  /\boffroad\s+(?:approves|guarantees|commits\s+capital|recommends\s+the\s+investment)\b/iu,
] as const;

const FINAL_TERM_CLAIMS = [
  /\btermos?\s+finais?\b/iu,
  /\bpreço\s+fechado\b/iu,
  /\bfinal\s+terms?\b/iu,
  /\bcommitted\s+pricing\b/iu,
] as const;

const RELATIVE_DATES = [
  /\brecentemente\b/iu,
  /\bnos\s+últimos\s+tempos\b/iu,
  /\bem\s+breve\b/iu,
  /\brecently\b/iu,
  /\bsoon\b/iu,
  /\bin\s+recent\s+months\b/iu,
] as const;

const DEFAULT_ACRONYMS = new Set([
  "BRL", "USD", "EUR", "CDI", "IPCA", "CNPJ", "CPF", "EBITDA", "CFADS", "DSCR",
  "LTV", "FIDC", "CRI", "CRA", "CCB", "NCE", "ERP", "IFRS", "CPC", "DCM", "NDA",
  "M&A", "S.A.", "LTDA", "PT", "EN", "Q&A",
  "CSLL", "ITR", "CFO", "DSO", "DIO", "DPO",
]);

export function auditConduct(input: ConductAuditInput): ConductAudit {
  const findings: ConductFinding[] = [];

  for (const claim of input.claims) auditClaim(claim, findings);
  for (const statement of input.bilingualStatements ?? []) auditBilingual(statement, findings);

  if (input.channel !== "internal_material") {
    if (input.disclaimerId !== advisoryDisclaimerId) {
      findings.push(block("LC-06", "missing_advisory_disclaimer", "Material externo sem o disclaimer versionado da fronteira de assessoria."));
    }
    if (!input.recipientAuthorized) {
      findings.push(block("LC-08", "recipient_not_authorized", "Destinatário não autorizado para esta versão do material."));
    }
    if (input.sourceOrganizationId !== input.targetOrganizationId || input.sourceCaseId !== input.targetCaseId) {
      findings.push(block("LC-08", "cross_case_disclosure", "O contexto de destino não corresponde à organização e ao case de origem."));
    }
    if (input.conflictStatus === "unresolved") {
      findings.push(block("LC-09", "unresolved_conflict", "Conflito de interesse ainda não resolvido ou aceito pelas partes aplicáveis."));
    }
  }

  if (
    input.riskSectionPosition !== undefined &&
    input.promotionalSectionPosition !== undefined &&
    input.riskSectionPosition > input.promotionalSectionPosition
  ) {
    findings.push(review("LC-03", "risk_after_promotion", "Riscos aparecem depois da narrativa promocional; a ordem institucional deve nomear primeiro a restrição material."));
  }

  if (input.channel === "external_communication" && input.hasMaterialCommitment && !input.writtenRecordId?.trim()) {
    findings.push(block("LC-10", "material_commitment_not_recorded", "Compromisso material sem registro escrito e datado no case."));
  }

  if ((input.knowledgeState === "unknown" || input.knowledgeState === "partially_known") && !isIsoDate(input.resolutionDueOn)) {
    findings.push(review("LC-11", "unknown_without_due_date", "Resposta parcial ou desconhecida sem data absoluta para resolução."));
  }

  for (const surprise of input.diligenceSurprises ?? []) {
    if (!surprise.responsibleProcedureId || !surprise.correctiveActionId) {
      findings.push(review("LC-12", "unattributed_diligence_surprise", "Surpresa de diligência sem procedimento responsável e ação corretiva.", {claimId: surprise.id}));
    }
  }

  auditAcronyms(input, findings);

  const status = findings.some((finding) => finding.severity === "block")
    ? "blocked"
    : findings.length > 0
      ? "review"
      : "pass";
  return {
    status,
    version: conductPolicyVersion,
    fingerprint: sha256(stableJson({version: conductPolicyVersion, input, findings})),
    findings,
  };
}

function auditClaim(claim: ConductClaim, findings: ConductFinding[]) {
  const text = claim.text.trim();
  if (claim.material && claim.supportIds.length === 0) {
    findings.push(block("LC-01", "material_claim_without_support", "Afirmação material sem fonte ou calculation trace.", {claimId: claim.id}));
  }
  if (claim.kind === "judgment" && claim.material && !isSha256(claim.approvedFingerprint)) {
    findings.push(block("LC-01", "judgment_without_exact_approval", "Julgamento material sem aprovação vinculada ao fingerprint exato.", {claimId: claim.id}));
  }
  if (MATERIAL_QUALIFIERS.some((pattern) => pattern.test(text)) && (claim.qualifierBasis?.length ?? 0) === 0) {
    findings.push(review("LC-02", "unbased_material_qualifier", "Adjetivo material sem base explícita e verificável.", {claimId: claim.id}));
  }
  if (OUTCOME_PROMISES.some((pattern) => pattern.test(text))) {
    findings.push(block("LC-05", "outcome_promise", "Texto implica aprovação, compromisso de capital ou garantia de captação.", {claimId: claim.id}));
  }
  if (FINAL_TERM_CLAIMS.some((pattern) => pattern.test(text)) && !/indicativ|preliminar|non-binding|subject to/iu.test(text)) {
    findings.push(block("LC-04", "final_terms_claim", "Termo preliminar apresentado como final ou fechado.", {claimId: claim.id}));
  }
  if (text.includes("\u2014")) {
    findings.push(block("LC-13", "em_dash", "Travessão proibido pela forma da casa.", {claimId: claim.id}));
  }
  if (RELATIVE_DATES.some((pattern) => pattern.test(text))) {
    findings.push(review("LC-13", "relative_date", "Data relativa deve ser substituída por data absoluta.", {claimId: claim.id}));
  }
}

function auditBilingual(statement: BilingualStatement, findings: ConductFinding[]) {
  const pt = economicTokens(statement.pt);
  const en = economicTokens(statement.en);
  if (!sameMultiset(pt, en)) {
    findings.push(block("LC-07", "bilingual_economic_divergence", "As versões PT e EN não carregam os mesmos números, moedas, percentuais e múltiplos.", {statementId: statement.id}));
  }
  if (statement.pt.includes("\u2014") || statement.en.includes("\u2014")) {
    findings.push(block("LC-13", "em_dash", "Travessão proibido pela forma da casa.", {statementId: statement.id}));
  }
}

function auditAcronyms(input: ConductAuditInput, findings: ConductFinding[]) {
  const defined = new Set([...DEFAULT_ACRONYMS, ...(input.definedAcronyms ?? []).map((item) => item.toUpperCase())]);
  const text = [
    ...input.claims.map((claim) => claim.text),
    ...(input.bilingualStatements ?? []).flatMap((statement) => [statement.pt, statement.en]),
  ].join("\n");
  const acronyms = [...new Set(text.match(/\b[A-ZÁÉÍÓÚÇ][A-ZÁÉÍÓÚÇ0-9&]{2,}\b/gu) ?? [])];
  for (const acronym of acronyms) {
    if (!defined.has(acronym.toUpperCase())) {
      findings.push(review("LC-13", "undefined_acronym", `Sigla ${acronym} não foi aberta nem consta do glossário aprovado.`));
    }
  }
}

function economicTokens(text: string): string[] {
  const normalized = text
    .replace(/\b(?:dois\s+terços|two[-\s]thirds)\b/giu, " 2/3 ")
    .replace(/R\$/gu, " BRL ")
    .replace(/US\$/gu, " USD ")
    .replace(/\s+/gu, " ");
  const raw = normalized.match(/\b(?:BRL|USD|EUR)\b|\d{1,3}(?:[.,]\d{3})*(?:[.,]\d+)?\s*(?:%|x|bps)?/giu) ?? [];
  return raw.map(normalizeEconomicToken).sort();
}

function normalizeEconomicToken(token: string): string {
  const trimmed = token.trim().toUpperCase();
  if (/^(?:BRL|USD|EUR)$/u.test(trimmed)) return trimmed;
  const suffix = trimmed.match(/(?:%|X|BPS)$/u)?.[0] ?? "";
  const raw = trimmed.replace(/(?:%|X|BPS)$/u, "").trim();
  const lastDot = raw.lastIndexOf(".");
  const lastComma = raw.lastIndexOf(",");
  let decimal = raw;
  if (lastDot >= 0 && lastComma >= 0) {
    const decimalMark = lastDot > lastComma ? "." : ",";
    decimal = raw.replace(decimalMark === "." ? /,/gu : /\./gu, "").replace(decimalMark, ".");
  } else if (lastComma >= 0) {
    decimal = /,\d{3}$/u.test(raw) && !suffix ? raw.replace(/,/gu, "") : raw.replace(",", ".");
  } else if (lastDot >= 0 && /\.\d{3}$/u.test(raw) && !suffix) {
    decimal = raw.replace(/\./gu, "");
  }
  return `${Number(decimal)}${suffix}`;
}

function sameMultiset(left: readonly string[], right: readonly string[]) {
  return left.length === right.length && left.every((value, index) => value === right[index]);
}

function block(ruleId: `LC-${string}`, code: string, message: string, extra: Partial<ConductFinding> = {}): ConductFinding {
  return {ruleId, code, severity: "block", message, ...extra};
}

function review(ruleId: `LC-${string}`, code: string, message: string, extra: Partial<ConductFinding> = {}): ConductFinding {
  return {ruleId, code, severity: "review", message, ...extra};
}

function isSha256(value: string | undefined): boolean {
  return Boolean(value && /^[a-f0-9]{64}$/u.test(value));
}

function isIsoDate(value: string | undefined): boolean {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/u.test(value)) return false;
  return !Number.isNaN(Date.parse(`${value}T00:00:00Z`));
}

function sha256(value: string): string {
  return createHash("sha256").update(value).digest("hex");
}

function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${stableJson(record[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

packages/credit-playbook/src/client-requ.content:
import type {RequirementPurpose, RequirementStage} from "./types";
import type {RequirementStatus, SufficiencyReport} from "./sufficiency";

/**
 * A deliberately small client-facing batch selected from the complete desk playbook.
 *
 * The full playbook remains available to the system and the desk. The client sees only what is
 * material now. This prevents a professional information plan from degenerating into a giant
 * checklist that asks the company to perform the analysis before Offroad has read the room.
 */
export type ClientRequestPriority = "case_blocker" | "structure_driver" | "mandate_driver" | "material_quality";

export type ClientRequest = {
  status: RequirementStatus;
  priority: ClientRequestPriority;
  /** The decision or work product the answer unlocks. */
  unlocks: readonly RequirementPurpose[];
};

export type ClientRequestPlan = {
  current: ClientRequest[];
  resolved: RequirementStatus[];
  roadmap: Record<Extract<RequirementStage, "diligence" | "closing">, {open: number; total: number}>;
  hiddenOpenCount: number;
};

export type ClientRequestOptions = {
  /** Four is the product default. Five is the absolute operating ceiling. */
  batchSize?: number;
};

const purposeOrder: Record<RequirementPurpose, number> = {
  financials: 0,
  structure: 1,
  investor_case: 2,
  storytelling: 3,
};

const priorityOf = (status: RequirementStatus): ClientRequestPriority => {
  if (status.requirement.level === "minimum") return "case_blocker";
  if (status.requirement.purposes.includes("structure") || status.requirement.purposes.includes("financials")) return "structure_driver";
  if (status.requirement.purposes.includes("investor_case")) return "mandate_driver";
  return "material_quality";
};

const priorityOrder: Record<ClientRequestPriority, number> = {
  case_blocker: 0,
  structure_driver: 1,
  mandate_driver: 2,
  material_quality: 3,
};

/**
 * Selects the next best requests after the system has read everything currently available.
 *
 * Rules:
 *  - never ask for a satisfied item;
 *  - never surface diligence or closing as a current task;
 *  - prioritize blockers, then facts that change capacity/structure, then mandate fit;
 *  - cap the active batch at five, default four;
 *  - preserve playbook order as the final deterministic tie-breaker.
 */
export function planClientRequests(report: SufficiencyReport, options: ClientRequestOptions = {}): ClientRequestPlan {
  const requestedBatchSize = options.batchSize ?? 4;
  const batchSize = Math.max(1, Math.min(5, Math.trunc(requestedBatchSize)));
  const index = new Map(report.requirements.map((status, position) => [status.requirement.id, position]));
  const openNow = report.byStage.now.filter((status) => !status.satisfied);
  const openStructuring = report.byStage.structuring.filter((status) => !status.satisfied);
  const activeStage = openNow.length > 0 ? openNow : openStructuring;
  const prioritized = activeStage
    .sort((left, right) => {
      const priority = priorityOrder[priorityOf(left)] - priorityOrder[priorityOf(right)];
      if (priority !== 0) return priority;
      const leftPurpose = Math.min(...left.requirement.purposes.map((purpose) => purposeOrder[purpose]));
      const rightPurpose = Math.min(...right.requirement.purposes.map((purpose) => purposeOrder[purpose]));
      if (leftPurpose !== rightPurpose) return leftPurpose - rightPurpose;
      return (index.get(left.requirement.id) ?? 0) - (index.get(right.requirement.id) ?? 0);
    });

  return {
    current: prioritized.slice(0, batchSize).map((status) => ({
      status,
      priority: priorityOf(status),
      unlocks: [...status.requirement.purposes].sort((a, b) => purposeOrder[a] - purposeOrder[b]),
    })),
    resolved: report.requirements.filter((status) => status.satisfied),
    roadmap: {
      diligence: stageSummary(report, "diligence"),
      closing: stageSummary(report, "closing"),
    },
    hiddenOpenCount: Math.max(0, prioritized.length - batchSize),
  };
}

const stageSummary = (report: SufficiencyReport, stage: "diligence" | "closing") => ({
  open: report.byStage[stage].filter((status) => !status.satisfied).length,
  total: report.byStage[stage].length,
});

packages/credit-playbook/src/methodology.content:
import {financialDefinitionMap} from "@offroad/credit-ontology";
import {z} from "zod";

/**
 * Historical institutional authoring schema, not execution or publication authority.
 *
 * A bank, an asset manager and a credit fund analyse the same company differently: which EBITDA
 * they accept, which adjustments they allow, which thresholds screen a deal, how many scenarios a
 * memo needs, who reviews before whom, how a page is laid out. Knowing finance is not the same as
 * knowing how this house does finance. This object holds the second thing.
 *
 * It never decides what the work is. Intent commands the workflow; the methodology modifies the
 * criteria, the checks and the presentation. And it never holds capabilities: what the
 * institution is able to do lives in `institution_capability_profiles`, with an owner and an
 * origin, and this object only points at it.
 */
const decimalString = z.string().regex(/^-?\d+(\.\d+)?$/, "a decimal written as a string");

const knownDefinitionId = z.string().min(1).refine((id) => financialDefinitionMap.has(id), {
  message: "a financial definition id from packages/credit-ontology",
});

export const definitionAdoptionSchema = z.object({
  id: knownDefinitionId,
  /** Parameters the canonical formula accepts, never a different formula. */
  parameters: z.record(z.string().max(60), z.string().max(120)).default({}),
  note: z.string().max(300).optional(),
});

export const ebitdaAdjustmentPolicySchema = z.object({
  id: z.enum([
    "non_recurring_items",
    "ifrs16_leases",
    "stock_compensation",
    "pro_forma_acquisitions",
    "run_rate_synergies",
    "fx_translation",
    "discontinued_operations",
  ]),
  allowed: z.boolean(),
  capPercentOfEbitda: z.number().min(0).max(100).nullable(),
  requiresEvidence: z.boolean(),
});

export const comparatorSchema = z.enum(["<", "<=", ">", ">="]);

export const thresholdSchema = z.object({
  metric: knownDefinitionId,
  comparator: comparatorSchema,
  value: decimalString,
  scope: z.enum(["screening", "approval", "monitoring"]),
  note: z.string().max(300).optional(),
});

export const eligibilityRuleSchema = z.object({
  key: z.string().min(1).max(80),
  comparator: comparatorSchema,
  value: decimalString,
  unit: z.string().max(20).optional(),
  note: z.string().max(300).optional(),
});

export const scenarioRequirementSchema = z.object({
  id: z.enum(["base", "downside", "stress"]),
  required: z.boolean(),
  shocks: z.array(z.object({driver: z.string().min(1).max(80), change: z.string().min(1).max(80)})).max(20),
});

export const reviewStepSchema = z.object({
  order: z.number().int().min(1),
  responsibility: z.enum(["producer", "coordinator", "reviewer", "decision_maker"]),
  label: z.string().min(1).max(120),
});

export const presentationStandardSchema = z.object({
  language: z.enum(["pt-BR", "en-US"]),
  memoSections: z.array(z.string().min(1).max(120)).min(1).max(40),
  maxPagesByOutput: z.record(z.string().max(60), z.number().int().min(1).max(200)),
  numberLocale: z.enum(["pt-BR", "en-US"]),
});

export const decisionReferenceSchema = z.object({
  reference: z.string().min(1).max(200),
  summary: z.string().min(1).max(600),
  recordedAt: z.string().datetime({offset: true}),
  recordedBy: z.string().uuid(),
});

export const organizationMethodologySchema = z.object({
  schemaVersion: z.literal("organization-methodology.v1"),
  definitions: z.array(definitionAdoptionSchema).max(40),
  ebitdaAdjustments: z.array(ebitdaAdjustmentPolicySchema).max(20),
  thresholds: z.array(thresholdSchema).max(60),
  eligibility: z.array(eligibilityRuleSchema).max(60),
  mandateReferences: z.array(z.object({fundId: z.string().uuid(), label: z.string().max(120)})).max(40),
  presentation: presentationStandardSchema,
  reviewSequence: z.array(reviewStepSchema).max(10),
  minimumScenarios: z.array(scenarioRequirementSchema).max(3),
  mandatoryMetrics: z.array(knownDefinitionId).max(40),
  /** Capabilities are not stored here; the institution profile is the only place they live. */
  capabilitiesReference: z.literal("institution_capability_profiles"),
  priorDecisions: z.array(decisionReferenceSchema).max(500),
  corrections: z.array(decisionReferenceSchema).max(500),
}).superRefine((methodology, ctx) => {
  const orders = methodology.reviewSequence.map((step) => step.order);
  if (new Set(orders).size !== orders.length) {
    ctx.addIssue({code: z.ZodIssueCode.custom, message: "review steps carry distinct orders"});
  }
  const scenarioIds = methodology.minimumScenarios.map((scenario) => scenario.id);
  if (new Set(scenarioIds).size !== scenarioIds.length) {
    ctx.addIssue({code: z.ZodIssueCode.custom, message: "a scenario id appears once"});
  }
});
export type OrganizationMethodology = z.infer<typeof organizationMethodologySchema>;

packages/credit-playbook/src/review-reco.content:
import {z} from "zod";

/**
 * An independent review performed by a model, on record. Independent means separate from the
 * implementation: the reviewer goes back to the sources, recalculates the numbers, tests the
 * definitions and the exceptions, runs the adversarial mutations, checks consistency across runs
 * and, for outputs, the advantage over the generalist baseline. It carries reviewer, run,
 * evidence, fingerprint and result. It is never a human approval, and the schema says so.
 */
export const reviewSubjectKindSchema = z.enum(["answer_key", "method", "parameter", "executor", "output"]);
export const reviewEvidenceResultSchema = z.enum(["confirmed", "corrected", "unverifiable", "limitation"]);

export const aiIndependentReviewSchema = z.object({
  schemaVersion: z.literal("ai-independent-review.v1"),
  reviewId: z.string().regex(/^[a-z0-9][a-z0-9_.-]{2,120}$/),
  kind: z.literal("ai_independent_review"),
  humanApproval: z.literal(false),
  reviewer: z.object({
    provider: z.string().min(1),
    model: z.string().min(1),
    effort: z.string().min(1),
    tool: z.string().min(1),
  }).strict(),
  subject: z.object({
    kind: reviewSubjectKindSchema,
    id: z.string().min(1),
    version: z.string().min(1),
    /** sha256 of the exact bytes reviewed (subject plus the information base it was reviewed against). */
    fingerprint: z.string().regex(/^[a-f0-9]{64}$/),
  }).strict(),
  run: z.object({
    id: z.string().min(1),
    startedAt: z.string().datetime(),
    finishedAt: z.string().datetime(),
    commit: z.string().regex(/^[a-f0-9]{7,40}$/).optional(),
    costUsd: z.number().nonnegative().optional(),
  }).strict(),
  checks: z.object({
    sourcesRevisited: z.boolean(),
    numbersRecalculated: z.boolean(),
    definitionsTested: z.boolean(),
    exceptionsTested: z.boolean(),
    adversarialTested: z.boolean(),
    consistencyTested: z.boolean(),
    /** Null when the subject is not an output measured against a baseline. */
    baselineAdvantage: z.boolean().nullable(),
  }).strict(),
  evidence: z.array(z.object({
    claim: z.string().min(1).max(600),
    source: z.string().min(1).max(300),
    anchor: z.string().max(200).optional(),
    result: reviewEvidenceResultSchema,
    note: z.string().max(800).optional(),
  }).strict()).min(1),
  result: z.enum(["pass", "conditional", "fail"]),
  /** What stays conditioned when the result is conditional: legal questions without source, judgments that need an external specialist. */
  conditions: z.array(z.string().min(1).max(600)).default([]),
  notes: z.string().max(4000).default(""),
}).strict();
export type AiIndependentReview = z.infer<typeof aiIndependentReviewSchema>;

/** The verdict a rung can rely on. A failed review, or one that never revisited the sources, does not count. */
export function reviewCountsForPromotion(review: AiIndependentReview): boolean {
  return review.result !== "fail" && review.checks.sourcesRevisited && review.checks.numbersRecalculated;
}

/**
 * An independent review of an execution profile adapter, on record next to the method reviews.
 * The database binds a registered profile to this file by path and sha256 (review_evidence in
 * private.execution_method_profiles), so the record never moves and its bytes never change after
 * the registration. It reviews an adapter, not a method: the method library validates it and
 * leaves it out of the method review index.
 */
export const adapterReviewSchema = z.object({
  schemaVersion: z.literal("adapter-review.v1"),
  subject: z.object({
    adapter: z.string().min(1),
    platformReleaseId: z.string().min(1),
    artifactHash: z.string().regex(/^[a-f0-9]{64}$/),
    profileFingerprint: z.string().regex(/^[a-f0-9]{64}$/),
  }).strict(),
  subjectCommit: z.string().regex(/^[a-f0-9]{7,40}$/),
  reviewer: z.string().min(3).max(200),
  occurredAt: z.string().datetime(),
  result: z.enum(["approved", "conditional", "rejected"]),
  evidence: z.object({
    adapterBlob: z.string().min(1),
    adapterFileSha256: z.string().regex(/^[a-f0-9]{64}$/),
    serializationHelperCommit: z.string().regex(/^[a-f0-9]{7,40}$/),
    serializationHelperBlob: z.string().min(1),
    manifestHash: z.string().regex(/^[a-f0-9]{64}$/),
    manifestFileHash: z.string().regex(/^[a-f0-9]{64}$/),
    canonicalProfileTextSha256: z.string().regex(/^[a-f0-9]{64}$/),
    canonicalProfileTextBytes: z.number().int().positive(),
    reviewedWorktreeHead: z.string().regex(/^[a-f0-9]{7,40}$/),
    originMainHead: z.string().regex(/^[a-f0-9]{7,40}$/),
    checksPerformed: z.array(z.string().min(1).max(600)).min(1),
  }).strict(),
  findings: z.array(z.object({
    severity: z.enum(["importante", "menor"]),
    file: z.string().min(1).max(300),
    line: z.number().int().positive(),
    text: z.string().min(1).max(2000),
  }).strict()),
  verdictText: z.string().min(1).max(4000),
}).strict();
export type AdapterReview = z.infer<typeof adapterReviewSchema>;

packages/credit-playbook/src/workflow-re.content:
import {createHash} from "node:crypto";

import {z} from "zod";

const localizedTextSchema = z.object({pt: z.string().min(1), en: z.string().min(1)}).strict();

export const workflowRecipeStepSchema = z.object({
  taskId: z.string().regex(/^[A-Z][0-9]{2}$/),
  methodId: z.string().regex(/^[a-z][a-z0-9-]{2,79}$/),
  methodVersion: z.string().regex(/^\d{4}\.\d{2}\.\d{2}-v\d+$/),
  executorKey: z.string().min(1),
  /** Present for compiled compositions; historic recipes keep their original fingerprint. */
  manifestHash: z.string().regex(/^[a-f0-9]{64}$/).optional(),
  artifactType: z.string().regex(/^[a-z][a-z0-9_]*$/),
  label: localizedTextSchema,
  purpose: localizedTextSchema,
  decisionImpact: localizedTextSchema,
  dependencies: z.array(z.string().regex(/^[A-Z][0-9]{2}$/)),
  requiredObjects: z.array(z.string().regex(/^[a-z][a-z0-9_.-]*$/)),
  coverageKeys: z.array(z.string().regex(/^[a-z][a-z0-9_.-]*$/)).min(1),
  verification: z.array(z.string().regex(/^[a-z][a-z0-9_.-]*$/)).min(1),
  invalidationKeys: z.array(z.string().regex(/^[a-z][a-z0-9_.-]*$/)).min(1),
  executionClass: z.enum(["deterministic", "extraction", "research", "judgment", "compilation"]),
  stage: z.enum(["research", "analysis", "alternatives", "material"]),
  failurePolicy: z.enum(["block_descendants", "degrade_with_disclosed_gap", "retry_then_abstain"]),
  effect: z.enum(["none", "propose_state", "commit"]),
  costBudget: z.object({maxModelCalls: z.number().int().nonnegative().safe(), maxDurationMs: z.number().int().positive()}).strict(),
}).strict();
export type WorkflowRecipeStep = z.infer<typeof workflowRecipeStepSchema>;

export const workflowRecipeSchema = z.object({
  schemaVersion: z.literal("workflow-recipe.v1"),
  id: z.string().regex(/^[a-z][a-z0-9-]{2,79}$/),
  version: z.string().regex(/^\d{4}\.\d{2}\.\d{2}-v\d+$/),
  maturity: z.enum(["specified", "implemented", "tested", "production"]),
  economicSituations: z.array(z.string().regex(/^[a-z][a-z0-9_.-]*$/)).min(1),
  supportedOutcomes: z.record(z.string().regex(/^[a-z][a-z0-9_]*$/), z.array(z.string().regex(/^[A-Z][0-9]{2}$/)).min(1)),
  steps: z.array(workflowRecipeStepSchema).min(1),
}).superRefine((recipe, context) => {
  const taskIds = recipe.steps.map((step) => step.taskId);
  const known = new Set(taskIds);
  const taskIndex = new Map(taskIds.map((taskId, index) => [taskId, index]));
  if (known.size !== taskIds.length) context.addIssue({code: "custom", path: ["steps"], message: "task ids must be unique inside a workflow recipe"});
  for (const [index, step] of recipe.steps.entries()) {
    if (new Set(step.dependencies).size !== step.dependencies.length) context.addIssue({code: "custom", path: ["steps", index, "dependencies"], message: "dependencies must be unique inside a workflow step"});
    for (const dependency of step.dependencies) {
      if (!known.has(dependency)) context.addIssue({code: "custom", path: ["steps", index, "dependencies"], message: `unknown dependency ${dependency}`});
      if (dependency === step.taskId) context.addIssue({code: "custom", path: ["steps", index, "dependencies"], message: "a step cannot depend on itself"});
      if ((taskIndex.get(dependency) ?? -1) >= index) context.addIssue({code: "custom", path: ["steps", index, "dependencies"], message: `dependency ${dependency} must precede ${step.taskId}`});
    }
  }
  const reachable = new Set<string>();
  const dependenciesByTask = new Map(recipe.steps.map((step) => [step.taskId, step.dependencies]));
  const markReachable = (taskId: string) => {
    if (reachable.has(taskId) || !known.has(taskId)) return;
    reachable.add(taskId);
    for (const dependency of dependenciesByTask.get(taskId) ?? []) markReachable(dependency);
  };
  for (const [outcome, targets] of Object.entries(recipe.supportedOutcomes)) {
    if (new Set(targets).size !== targets.length) context.addIssue({code: "custom", path: ["supportedOutcomes", outcome], message: "targets must be unique inside an outcome"});
    for (const target of targets) {
      if (!known.has(target)) context.addIssue({code: "custom", path: ["supportedOutcomes", outcome], message: `unknown target ${target}`});
      markReachable(target);
    }
  }
  for (const [index, taskId] of taskIds.entries()) if (!reachable.has(taskId)) context.addIssue({code: "custom", path: ["steps", index], message: `orphan task ${taskId} is not reachable from any outcome`});
  if (hasCycle(recipe.steps)) context.addIssue({code: "custom", path: ["steps"], message: "workflow recipe contains a dependency cycle"});
