export type DepthPackDimension = "core" | "economic_situation" | "capital_objective" | "instrument" | "sector" | "analysis_domain" | "professional_function" | "jurisdiction" | "market_execution";
export type CoverageDomain = "company_and_business_model" | "sector_and_competitive_position" | "historical_financials" | "earnings_quality" | "cash_conversion_and_working_capital" | "liquidity_and_debt_schedule" | "leverage_and_debt_service" | "covenants" | "collateral_and_security" | "receivables_inventory_or_contracts" | "business_plan_and_sources_uses" | "downside_and_sensitivities" | "legal_tax_and_regulatory" | "capital_alternatives" | "structure_and_terms" | "market_pricing_and_precedents" | "capital_provider_fit" | "execution_timeline_and_contingency" | "materials_and_cross_consistency";
export type CoverageMateriality = "blocking" | "high" | "medium" | "low";

export type CoverageRequirementDefinition = {
  key: string;
  domain: CoverageDomain;
  label: string;
  questionAnswered: string;
  decisionImpacts: string[];
  acceptableEvidence: string[];
  materiality: CoverageMateriality;
};

/** Structural twin of the agent-contract manifest, kept dependency-free inside canonical knowledge. */
export type CanonicalDepthPack = {
  schemaVersion: "dcm-depth-pack.v1";
  id: string;
  version: string;
  owner: string;
  dimension: DepthPackDimension;
  activationKeys: string[];
  supportedJobs: string[];
  professionalFunctions: string[];
  requirements: CoverageRequirementDefinition[];
  procedureIds: string[];
  calculationPolicy: "required" | "conditional" | "not_applicable";
  calculationIds: string[];
  calculationRationale: string;
  structureTermKeys: string[];
  marketCriterionKeys: string[];
  disconfirmers: string[];
  qualityGateIds: string[];
  goldCaseIds: string[];
  adversarialCaseIds: string[];
  generalistBenchmarkIds: string[];
  dependsOn: string[];
  incompatibleWith: string[];
  maturity: "specified" | "implemented" | "tested" | "production";
  reviewedBy: string | null;
  reviewedAt: string | null;
};

/** Specifications for object-scoped composition, not executable methods or promoted depth packs.
 * No registry activation, financial constants or eligibility thresholds are implied here.
 * Intent/dimension strings deliberately avoid coupling this catalog to agent-contracts.
 */
export type SectorContextRequirement = {
  id: string;
  intents: readonly string[];
  evidenceNeeded: readonly string[];
  scenarioIds: readonly string[];
  methods: readonly {id: string; status: "specified"}[];
  marketCriteriaIds: readonly string[];
  outputSuggestions: readonly string[];
};
export type SectorContextModule = {
  id: string;
  version: string;
  labels: {pt: string; en: string};
  status: "specified";
  /** Every predicate must match on the same object and a compatible economic period.
   * The compositor owns evidence-state and period handling; there are no global exclusions.
   */
  applicability: readonly {dimension: string; value: string}[];
  /** Specific signal needed before requesting missing companion predicates. */
  activationDiscriminator: {dimension: string; value: string};
  requirements: readonly SectorContextRequirement[];
};
const version = "sector-context-catalog.2026-09-08.v1";
function module(id: string, pt: string, en: string, applicability: SectorContextModule["applicability"], evidence: readonly string[], scenarios: readonly string[], method: string, criteria: readonly string[], output: string): SectorContextModule {
  return {
    id, version, labels: {pt, en}, status: "specified", applicability,
    activationDiscriminator: applicability[applicability.length - 1]!,
